-- MySQL dump 10.13  Distrib 5.7.35, for Linux (x86_64)---- Host: localhost    Database: ninegate-- -------------------------------------------------------- Server version	5.7.35-0ubuntu0.18.04.1/*!40101 SET @OLD_CHARACTER_SET_CLIENT=@@CHARACTER_SET_CLIENT */;/*!40101 SET @OLD_CHARACTER_SET_RESULTS=@@CHARACTER_SET_RESULTS */;/*!40101 SET @OLD_COLLATION_CONNECTION=@@COLLATION_CONNECTION */;/*!40101 SET NAMES utf8 */;/*!40103 SET @OLD_TIME_ZONE=@@TIME_ZONE */;/*!40103 SET TIME_ZONE='+00:00' */;/*!40014 SET @OLD_UNIQUE_CHECKS=@@UNIQUE_CHECKS, UNIQUE_CHECKS=0 */;/*!40014 SET @OLD_FOREIGN_KEY_CHECKS=@@FOREIGN_KEY_CHECKS, FOREIGN_KEY_CHECKS=0 */;/*!40101 SET @OLD_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_AUTO_VALUE_ON_ZERO' */;/*!40111 SET @OLD_SQL_NOTES=@@SQL_NOTES, SQL_NOTES=0 */;---- Current Database: `ninegate`--CREATE DATABASE /*!32312 IF NOT EXISTS*/ `ninegate` /*!40100 DEFAULT CHARACTER SET utf8 */;USE `ninegate`;---- Table structure for table `alert`--DROP TABLE IF EXISTS `alert`;/*!40101 SET @saved_cs_client     = @@character_set_client */;/*!40101 SET character_set_client = utf8 */;CREATE TABLE `alert` (  `id` int(11) NOT NULL AUTO_INCREMENT,  `category` int(11) NOT NULL,  `title` varchar(100) COLLATE utf8_unicode_ci NOT NULL,  `content` longtext COLLATE utf8_unicode_ci,  `rowOrder` int(11) DEFAULT NULL,  `publishedat` date NOT NULL,  `unpublishedat` date DEFAULT NULL,  `fghideable` tinyint(1) NOT NULL,  `roles` longtext COLLATE utf8_unicode_ci COMMENT '(DC2Type:array)',  PRIMARY KEY (`id`),  KEY `IDX_17FD46C164C19C1` (`category`),  CONSTRAINT `FK_17FD46C164C19C1` FOREIGN KEY (`category`) REFERENCES `alertcategory` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;/*!40101 SET character_set_client = @saved_cs_client */;---- Dumping data for table `alert`--LOCK TABLES `alert` WRITE;/*!40000 ALTER TABLE `alert` DISABLE KEYS */;/*!40000 ALTER TABLE `alert` ENABLE KEYS */;UNLOCK TABLES;---- Table structure for table `alertcategory`--DROP TABLE IF EXISTS `alertcategory`;/*!40101 SET @saved_cs_client     = @@character_set_client */;/*!40101 SET character_set_client = utf8 */;CREATE TABLE `alertcategory` (  `id` int(11) NOT NULL AUTO_INCREMENT,  `icon_id` int(11) DEFAULT NULL,  `label` varchar(100) COLLATE utf8_unicode_ci NOT NULL,  `color` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL,  PRIMARY KEY (`id`),  KEY `IDX_EC575F7E54B9D732` (`icon_id`),  CONSTRAINT `FK_EC575F7E54B9D732` FOREIGN KEY (`icon_id`) REFERENCES `icon` (`id`) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;/*!40101 SET character_set_client = @saved_cs_client */;---- Dumping data for table `alertcategory`--LOCK TABLES `alertcategory` WRITE;/*!40000 ALTER TABLE `alertcategory` DISABLE KEYS */;INSERT INTO `alertcategory` VALUES (-100,431,'Annonces','00a996');/*!40000 ALTER TABLE `alertcategory` ENABLE KEYS */;UNLOCK TABLES;---- Table structure for table `alertgroupe`--DROP TABLE IF EXISTS `alertgroupe`;/*!40101 SET @saved_cs_client     = @@character_set_client */;/*!40101 SET character_set_client = utf8 */;CREATE TABLE `alertgroupe` (  `alert` int(11) NOT NULL,  `groupe` int(11) NOT NULL,  PRIMARY KEY (`alert`,`groupe`),  KEY `IDX_64DB975617FD46C1` (`alert`),  KEY `IDX_64DB97564B98C21` (`groupe`),  CONSTRAINT `FK_64DB975617FD46C1` FOREIGN KEY (`alert`) REFERENCES `alert` (`id`),  CONSTRAINT `FK_64DB97564B98C21` FOREIGN KEY (`groupe`) REFERENCES `groupe` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;/*!40101 SET character_set_client = @saved_cs_client */;---- Dumping data for table `alertgroupe`--LOCK TABLES `alertgroupe` WRITE;/*!40000 ALTER TABLE `alertgroupe` DISABLE KEYS */;/*!40000 ALTER TABLE `alertgroupe` ENABLE KEYS */;UNLOCK TABLES;---- Table structure for table `alertitem`--DROP TABLE IF EXISTS `alertitem`;/*!40101 SET @saved_cs_client     = @@character_set_client */;/*!40101 SET character_set_client = utf8 */;CREATE TABLE `alertitem` (  `alert` int(11) NOT NULL,  `item` int(11) NOT NULL,  PRIMARY KEY (`alert`,`item`),  KEY `IDX_873C473817FD46C1` (`alert`),  KEY `IDX_873C47381F1B251E` (`item`),  CONSTRAINT `FK_873C473817FD46C1` FOREIGN KEY (`alert`) REFERENCES `alert` (`id`),  CONSTRAINT `FK_873C47381F1B251E` FOREIGN KEY (`item`) REFERENCES `item` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;/*!40101 SET character_set_client = @saved_cs_client */;---- Dumping data for table `alertitem`--LOCK TABLES `alertitem` WRITE;/*!40000 ALTER TABLE `alertitem` DISABLE KEYS */;/*!40000 ALTER TABLE `alertitem` ENABLE KEYS */;UNLOCK TABLES;---- Table structure for table `alertniveau01`--DROP TABLE IF EXISTS `alertniveau01`;/*!40101 SET @saved_cs_client     = @@character_set_client */;/*!40101 SET character_set_client = utf8 */;CREATE TABLE `alertniveau01` (  `alert` int(11) NOT NULL,  `niveau01` int(11) NOT NULL,  PRIMARY KEY (`alert`,`niveau01`),  KEY `IDX_87E7389C17FD46C1` (`alert`),  KEY `IDX_87E7389C6DFC7E23` (`niveau01`),  CONSTRAINT `FK_87E7389C17FD46C1` FOREIGN KEY (`alert`) REFERENCES `alert` (`id`),  CONSTRAINT `FK_87E7389C6DFC7E23` FOREIGN KEY (`niveau01`) REFERENCES `niveau01` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;/*!40101 SET character_set_client = @saved_cs_client */;---- Dumping data for table `alertniveau01`--LOCK TABLES `alertniveau01` WRITE;/*!40000 ALTER TABLE `alertniveau01` DISABLE KEYS */;/*!40000 ALTER TABLE `alertniveau01` ENABLE KEYS */;UNLOCK TABLES;---- Table structure for table `alertuserread`--DROP TABLE IF EXISTS `alertuserread`;/*!40101 SET @saved_cs_client     = @@character_set_client */;/*!40101 SET character_set_client = utf8 */;CREATE TABLE `alertuserread` (  `alert` int(11) NOT NULL,  `user` int(11) NOT NULL,  PRIMARY KEY (`alert`,`user`),  KEY `IDX_D4317FA917FD46C1` (`alert`),  KEY `IDX_D4317FA98D93D649` (`user`),  CONSTRAINT `FK_D4317FA917FD46C1` FOREIGN KEY (`alert`) REFERENCES `alert` (`id`),  CONSTRAINT `FK_D4317FA98D93D649` FOREIGN KEY (`user`) REFERENCES `user` (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;/*!40101 SET character_set_client = @saved_cs_client */;---- Dumping data for table `alertuserread`--LOCK TABLES `alertuserread` WRITE;/*!40000 ALTER TABLE `alertuserread` DISABLE KEYS */;/*!40000 ALTER TABLE `alertuserread` ENABLE KEYS */;UNLOCK TABLES;---- Table structure for table `appexternal`--DROP TABLE IF EXISTS `appexternal`;/*!40101 SET @saved_cs_client     = @@character_set_client */;/*!40101 SET character_set_client = utf8 */;CREATE TABLE `appexternal` (  `id` int(11) NOT NULL AUTO_INCREMENT,  `name` varchar(100) COLLATE utf8_unicode_ci NOT NULL,  PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;/*!40101 SET character_set_client = @saved_cs_client */;---- Dumping data for table `appexternal`--LOCK TABLES `appexternal` WRITE;/*!40000 ALTER TABLE `appexternal` DISABLE KEYS */;/*!40000 ALTER TABLE `appexternal` ENABLE KEYS */;UNLOCK TABLES;---- Table structure for table `blog`--DROP TABLE IF EXISTS `blog`;/*!40101 SET @saved_cs_client     = @@character_set_client */;/*!40101 SET character_set_client = utf8 */;CREATE TABLE `blog` (  `id` int(11) NOT NULL AUTO_INCREMENT,  `user_id` int(11) DEFAULT NULL,  `name` varchar(100) COLLATE utf8_unicode_ci NOT NULL,  `roles` longtext COLLATE utf8_unicode_ci COMMENT '(DC2Type:array)',  PRIMARY KEY (`id`),  KEY `IDX_C0155143A76ED395` (`user_id`),  CONSTRAINT `FK_C0155143A76ED395` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`)) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;/*!40101 SET character_set_client = @saved_cs_client */;---- Dumping data for table `blog`--LOCK TABLES `blog` WRITE;/*!40000 ALTER TABLE `blog` DISABLE KEYS */;INSERT INTO `blog` VALUES (3,NULL,'Interne','a:0:{}'),(4,NULL,'Projets','a:0:{}'),(5,NULL,'Cadoles','a:0:{}'),(6,NULL,'Pôles','a:0:{}'),(8,8,'Formation','N;'),(9,6,'Mon Groupe 01','N;');/*!40000 ALTER TABLE `blog` ENABLE KEYS */;UNLOCK TABLES;---- Table structure for table `blogarticle`--DROP TABLE IF EXISTS `blogarticle`;/*!40101 SET @saved_cs_client     = @@character_set_client */;/*!40101 SET character_set_client = utf8 */;CREATE TABLE `blogarticle` (  `id` int(11) NOT NULL AUTO_INCREMENT,  `user_id` int(11) DEFAULT NULL,  `blog_id` int(11) NOT NULL,  `name` varchar(100) COLLATE utf8_unicode_ci NOT NULL,  `description` longtext COLLATE utf8_unicode_ci,  `submit` datetime NOT NULL,  `fgdraft` tinyint(1) NOT NULL,  `fgcomment` tinyint(1) NOT NULL,  `image` varchar(100) COLLATE utf8_unicode_ci DEFAULT NULL,  PRIMARY KEY (`id`),  KEY `IDX_6E464C24A76ED395` (`user_id`),  KEY `IDX_6E464C24DAE07E97` (`blog_id`),  CONSTRAINT `FK_6E464C24A76ED395` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`),  CONSTRAINT `FK_6E464C24DAE07E97` FOREIGN KEY (`blog_id`) REFERENCES `blog` (`id`)) ENGINE=InnoDB AUTO_INCREMENT=105 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;/*!40101 SET character_set_client = @saved_cs_client */;---- Dumping data for table `blogarticle`--LOCK TABLES `blogarticle` WRITE;/*!40000 ALTER TABLE `blogarticle` DISABLE KEYS */;INSERT INTO `blogarticle` VALUES (1,6,3,'CR de l\'assemblée collective du 16/04/19','<p>Notre premi&egrave;re assembl&eacute;e collective s&#39;est d&eacute;roul&eacute;e mardi dernier. Voici le compte rendu des d&eacute;cisions et discussions qui s&#39;y sont tenues.</p>\r\n\r\n<p>Ce compte rendu a &eacute;t&eacute; r&eacute;alis&eacute; &agrave; partir de mes notes et de celles qu&#39;on m&#39;a fait parvenir (merci d&#39;ailleurs aux personnes en question). Si vous voyez des &eacute;l&eacute;ments manquants ou des erreurs, n&#39;h&eacute;sitez pas &agrave; le faire savoir par retour de courriel.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2>Compte rendu pr&eacute;liminaire de l&#39;audit social</h2>\r\n\r\n<p>La premi&egrave;re journ&eacute;e d&#39;audit s&#39;est d&eacute;roul&eacute;e le mardi 09/04. Il manque quelques documents (principalement comptables) pour le finaliser.</p>\r\n\r\n<p>Quelques petites erreurs ont d&eacute;j&agrave; &eacute;t&eacute; relev&eacute;es qui devraient donner lieu &agrave; la cr&eacute;ation d&#39;avenants aux contrats des salari&eacute;s.</p>\r\n\r\n<p>La prochaine r&eacute;union avec le cabinet Mazars &agrave; ce sujet aura lieu le jeudi 02/05. Les r&eacute;sultats finaux de l&#39;audit devraient &ecirc;tre disponible dans la/les semaine(s) suivante(s).</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2>Changement de comptable</h2>\r\n\r\n<p>La r&eacute;siliation du contrat avec Exco est faite (accus&eacute; de r&eacute;ception au 29/03 de notre lettre de r&eacute;siliation). Aucune r&eacute;action de leur part depuis.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2>Dossiers d&#39;aide &agrave; la d&eacute;cision</h2>\r\n\r\n<p>Plusieurs DADs ont &eacute;t&eacute; pr&eacute;sent&eacute;s lors de cette assembl&eacute; collective. Pour rappel:</p>\r\n\r\n<p>- DAD-190402095000-teletravail-V1<br />\r\n&nbsp; &nbsp; - Porteur: Teddy<br />\r\n&nbsp; &nbsp; - Sujet: Amor&ccedil;age de la r&eacute;flexion autour de la mise en place du t&eacute;l&eacute;travail &agrave; Cadoles</p>\r\n\r\n<p>- DAD-190402181818-modele-1<br />\r\n&nbsp; &nbsp; - Porteur: Emmanuel<br />\r\n&nbsp; &nbsp; - Sujet: Pr&eacute;cision de la d&eacute;finition de &quot;cog&eacute;rance&quot; dans le mod&egrave;le d&eacute;cisionnel</p>\r\n\r\n<p>- DAD-190402183030-modele-1<br />\r\n&nbsp; &nbsp; - Porteur: Emmanuel<br />\r\n&nbsp; &nbsp; - Sujet: &Eacute;volution de la d&eacute;finition d&#39;une &quot;action&quot; dans le mod&egrave;le d&eacute;cisionnel</p>\r\n\r\n<p>- DAD-190402190500-DataDock<br />\r\n&nbsp; &nbsp; - Porteur: William<br />\r\n&nbsp; &nbsp; - Sujet: D&eacute;blocage de temps pour finaliser le dossier DataDock (agr&eacute;ment pour l&#39;activit&eacute; de formation) 2019</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Voici les d&eacute;cisions r&eacute;sultantes:</p>\r\n\r\n<h3>DAD-190402095000-teletravail-V1</h3>\r\n\r\n<p>Ce dossier ne portait pas &agrave; d&eacute;cision imm&eacute;diate. Un groupe de travail s&#39;est form&eacute; pour identifier dans les prochaines semaines les modalit&eacute;s de la mise en place de t&eacute;l&eacute;travail &agrave; Cadoles. Le sujet sera d&eacute;coup&eacute; en 2 parties: aspect l&eacute;gal et aspect op&eacute;rationnel. L&#39;aspect l&eacute;gal devrait &ecirc;tre trait&eacute; en premier.&nbsp;</p>\r\n\r\n<p>L&#39;objectif est de pr&eacute;senter un premier DAD &agrave; la prochaine assembl&eacute;e collective.</p>\r\n\r\n<p>Le groupe de travail est constitu&eacute; de Teddy, L&aelig;titia et Ludwig.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>DAD-190402181818-modele-1</h3>\r\n\r\n<p>L&#39;amendement au mod&egrave;le d&eacute;cisionnel est adopt&eacute; &agrave; l&#39;unanimit&eacute;. La PR associ&eacute;e sera accept&eacute;e dans les prochains jours pour mat&eacute;rialiser cette d&eacute;cision.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>DAD-190402183030-modele-1</h3>\r\n\r\n<p>L&#39;amendement au mod&egrave;le d&eacute;cisionnel est adopt&eacute; &agrave; l&#39;unanimit&eacute;. La PR associ&eacute;e sera accept&eacute;e dans les prochains jours pour mat&eacute;rialiser cette d&eacute;cision.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>DAD-190402190500-DataDock</h3>\r\n\r\n<p>La proposition de d&eacute;bloquer du temps pour compl&eacute;ter le dossier DataDock est adopt&eacute;. Un budget temps initial de 2 jours est allou&eacute; &agrave; Emmanuel pour compl&eacute;ter les 2 indicateurs manquants &agrave; notre agr&eacute;ment.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2>Discussions libres</h2>\r\n\r\n<p>De nombreux sujets ont &eacute;t&eacute; abord&eacute;s durant la phase de discussion libre. Ces discussions ont donn&eacute; lieu &agrave; la formation de plusieurs groupes de travail. Voici les principaux sujets not&eacute;s.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>Demande d&#39;accompagnement sur les missions administratives</h3>\r\n\r\n<p>L&aelig;titia a fait part de son besoin d&#39;&ecirc;tre accompagn&eacute;e dans une partie de ses missions afin de pouvoir se consacrer &agrave; des t&acirc;ches d&#39;un int&eacute;r&ecirc;t plus important pour Cadoles.</p>\r\n\r\n<p>Suite &agrave; discussion, un groupe de travail est constitu&eacute; afin d&#39;&eacute;valuer au mieux les missions en question et le volume horaire associ&eacute;. Ce groupe de travail comprend L&aelig;titia, Ludwig et William.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>Gestion des cong&eacute;s</h3>\r\n\r\n<p>Il a &eacute;t&eacute; fait remarqu&eacute; que la gestion des cong&eacute;s &eacute;tait aujourd&#39;hui dans un &eacute;tat de flou qui devenait dommageable pour les clients et la soci&eacute;t&eacute;.</p>\r\n\r\n<p>Il faudrait repr&eacute;ciser les r&egrave;gles de gestion des cong&eacute;s, notamment sur les d&eacute;lais, afin d&#39;&eacute;viter les probl&egrave;mes futurs.</p>\r\n\r\n<p>Aucun groupe de travail ne s&#39;est pour le moment empar&eacute; du sujet.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>Suivi client p&ocirc;le &quot;CSS/Int&eacute;gration EOLE&quot;</h3>\r\n\r\n<p>Il a &eacute;t&eacute; remont&eacute; que l&#39;absence de gestion client &quot;identifi&eacute;e&quot; sur les travaux de type int&eacute;gration/syst&egrave;me devenait particuli&egrave;rement dommageable au bon fonctionnement de la soci&eacute;t&eacute; et au bien &ecirc;tre des salari&eacute;s.</p>\r\n\r\n<p>Ce point semble entrer dans une question plus g&eacute;n&eacute;rale et strat&eacute;gique de la gestion client &agrave; Cadoles et du futur de la relation entre Cadoles et le p&ocirc;le Logiciels Libres.&nbsp;</p>\r\n\r\n<p>Il a &eacute;t&eacute; mentionn&eacute; que Luc &eacute;tait en passe de basculer &agrave; 50% sur le projet EOLE pour se consacrer au projet &quot;Alphabet&quot; (aucun lien avec Google...), un catalogue de services h&eacute;berg&eacute;s &agrave; la mode &quot;Envole&quot;.</p>\r\n\r\n<p>Cette question semble centraliser beaucoup d&#39;attentes/craintes de la part des salari&eacute;s.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>R&eacute;organisation du bureau</h3>\r\n\r\n<p>La r&eacute;organisation du bureau a &eacute;galement &eacute;t&eacute; abord&eacute;e lors de cette r&eacute;union. Les conditions de travail ne paraissent plus optimales pour les salari&eacute;s s&eacute;dentaires ou pr&eacute;sents r&eacute;guli&egrave;rement dans les locaux de Cadoles.</p>\r\n\r\n<p>Un groupe de travail s&#39;est form&eacute; afin de proposer des solutions pour am&eacute;liorer cet espace commun. Ce groupe est constitu&eacute; de Benjamin, Vincent et Teddy.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>Achat de &quot;petit mat&eacute;riel&quot;</h3>\r\n\r\n<p>Un groupe de travail constitu&eacute; de Benjamin et Vincent s&#39;est &eacute;galement constitu&eacute; pour r&eacute;fl&eacute;chir aux modalit&eacute;s de commandes de &quot;petit mat&eacute;riel&quot; par les salari&eacute;s afin de faciliter/clarifier le processus.</p>\r\n\r\n<p>Les questions du budget et de la gestion individuelle des commandes semblent centrales dans la r&eacute;flexion engag&eacute;e.</p>\r\n\r\n<p>### Institution d&#39;un quorum pour l&#39;assembl&eacute;e collective</p>\r\n\r\n<p>La notion de quorum n&#39;appara&icirc;t pas actuellement dans le mod&egrave;le d&eacute;cisionnel. Les salari&eacute;s pr&eacute;sents lors de cette assembl&eacute;e semblaient favorables &agrave; la mat&eacute;rialisation de cette notion afin d&#39;&eacute;viter des prises de d&eacute;cision par un groupe trop restreint.</p>\r\n\r\n<p>Une proposition d&#39;amendement sera apport&eacute;e par Teddy prochainement.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h3>Certification ANSSI</h3>\r\n\r\n<p>Via un contact avec Guillaume Boulaton (Toolib), il semblerait que l&#39;ANSSI soit en recherche de soci&eacute;t&eacute;s &quot;certifi&eacute;es&quot; en Bourgogne/Franche Comt&eacute;.</p>\r\n\r\n<p>La certification ANSSI peut &agrave; priori s&#39;obtenir en formant/validant les comp&eacute;tences d&#39;un minimum de 2 salari&eacute;s. Cette certification permettrait potentiellement &agrave; Cadoles d&#39;op&eacute;rer de v&eacute;ritables audits de s&eacute;curit&eacute; et par effet de bord d&#39;augmenter ses tarifs commerciaux sur ce type de prestation.&nbsp;</p>\r\n\r\n<p>La SMAB (groupement d&#39;assurance pour lequel Cadoles va effectuer un audit de code source sur une application web) est d&eacute;j&agrave; demandeur pour ce type de comp&eacute;tence et de validation. L&#39;EFS a &eacute;galement exprim&eacute; son int&eacute;r&ecirc;t sur ce sujet pour la suite des travaux sur Quid ou d&#39;autres projets.&nbsp;</p>\r\n\r\n<p>Un groupe de travail &agrave; ce sujet est port&eacute; par William.</p>\r\n\r\n<h3>Formations</h3>\r\n\r\n<p>Plusieurs salari&eacute;s ont exprim&eacute; leur envie de participer &agrave; des formations afin de pouvoir &eacute;voluer dans leurs missions.</p>\r\n\r\n<p>Un groupe de travail compos&eacute; pour l&#39;instant d&#39;Arnaud s&#39;est mont&eacute; pour faire un inventaire des attentes des salari&eacute;s afin de pouvoir ensuite identifier des solutions pour la mise en place concr&egrave;te de ces formations.&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2>Prochaine r&eacute;union</h2>\r\n\r\n<p>La prochaine assembl&eacute;e collective est programm&eacute;e pour le mardi 14/05.</p>\r\n\r\n<p>La date de publication pr&eacute;liminaire des futurs DADs est donc le 30/04 et la date de gel de ceux ci le 07/04.</p>\r\n\r\n<p>Merci &agrave; tous pour votre participation et votre bonne humeur.</p>','2019-04-25 14:11:53',1,0,'uploads/blogarticle/5cc1a645c2249.jpg'),(2,6,3,'CR de l\'assemblée collective du 18/05/19','<p>Sylvain a propos&eacute; une CR&Ecirc;PE PARTIE le vendredi 5 juillet &agrave; midi - accept&eacute; &agrave; l&#39;unanimit&eacute; - Ceux qui ont donc une cr&ecirc;pe partie peuvent la ramener, sinon on ne pourra pas faire les cr&ecirc;pes</p>\r\n\r\n<h2>Point sur l&#39;avanc&eacute;e des groupes de travail</h2>\r\n\r\n<ul>\r\n	<li><strong>Finalisation de l&#39;audit social</strong> - Laetitia : toujours en cours - Exco Socodec ayant fait de la r&eacute;tention de document par non communication. Cela devrait se d&eacute;canter cette semaine avec une prise de RDV avec le cabinet Mazars d&egrave;s la semaine prochaine</li>\r\n	<li><strong>Dossier DataDock</strong> - Emmanuel : le dossier est accept&eacute;, il faut maintenant revenir vers les clients en attente et proposer des dates de formation</li>\r\n	<li><strong>Demande d&#39;accompagnement sur les missions administratives</strong> (Laetita, Ludwig et William) : toujours en cours - Laetitia fait de la r&eacute;tention d&#39;information - ne prend pas le temps</li>\r\n	<li><strong>R&eacute;organisation du bureau</strong> - Benjamin et Vincent : &nbsp;des devis ont &eacute;t&eacute; demand&eacute;s &agrave; 2 autres entreprises qui n&#39;ont pas donn&eacute; de r&eacute;ponse. Une relance ainsi que la recherche de nouveaux potentiels prestataires va &ecirc;tre effectu&eacute;e.</li>\r\n	<li><strong>Institution d&#39;un quorum pour l&#39;assembl&eacute;e collective</strong> - Teddy : un syst&egrave;me de pourcentage devrait &ecirc;tre propos&eacute; (PR &agrave; discuter)</li>\r\n	<li><strong>Certification ANSSI</strong> - William : RDV pris le 11 juillet - y participera qui veut</li>\r\n	<li><strong>Formations</strong> - Arnaud et Matthieu : pr&eacute;cisions selon strat&eacute;gie mais beaucoup de personnes y ont r&eacute;pondu et un CR sera bient&ocirc;t donn&eacute; &agrave; tous</li>\r\n	<li><strong>Fiches de mission</strong> - Arnaud et Matthieu : une vue d&#39;ensemble a &eacute;t&eacute; envoy&eacute;e par tendance, avec 25 postes potentiels*missions&nbsp;</li>\r\n	<li><strong>Petit mat&eacute;riel</strong> : Vincent a envoy&eacute; une fiche &agrave; remplir (le cadre sera &agrave; pr&eacute;ciser) dans interne pour plus de rapidit&eacute; et d&#39;efficacit&eacute;</li>\r\n	<li><strong>T&eacute;latravail</strong> - Ludwig et Teddy : toujours en cours d&#39;avancement</li>\r\n</ul>\r\n\r\n<h2>&nbsp;<br />\r\nPrise de parole des porteurs des DADs puis vote</h2>\r\n\r\n<ul>\r\n	<li>DAD-190602000000-Decompte_horaire.pdf\r\n	<ul>\r\n		<li>Porteur: Sylvain</li>\r\n		<li>Sujet: D&eacute;compte du temps pass&eacute; par les salari&eacute;s par projet et temps annexes au projet</li>\r\n		<li>D&Eacute;CISION : ont &eacute;t&eacute; vot&eacute; &agrave; la majorit&eacute;&nbsp;\r\n		<ul>\r\n			<li>1/ le principe de d&eacute;compte pr&eacute;cis du temps pass&eacute;</li>\r\n			<li>2/ d&eacute;blocage de temps pour &eacute;tablir un groupe de travail pour &eacute;valuer les solutions techniques&nbsp;</li>\r\n		</ul>\r\n		</li>\r\n		<li>GROUPE DE TRAVAIL : Sylvain (pilote), Benjamin Bohard, Arnaud, Philippe</li>\r\n	</ul>\r\n	</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li>DAD-190603000000-Vote_non_coop&eacute;rateur.pdf\r\n	<ul>\r\n		<li>Porteur: Sylvain</li>\r\n		<li>Sujet: Les salari&eacute;s non coop&eacute;rateurs pourraient prendre part aux votes</li>\r\n		<li>D&Eacute;CISION : a &eacute;t&eacute; vot&eacute; &agrave; la majorit&eacute; le fait que tout salari&eacute; a le droit de vote lors des missions collectives sans laps de temps d&eacute;j&agrave; effectu&eacute; chez Cadoles</li>\r\n		<li>PROPOSITION D&#39;UN GROUPE DE TRAVAIL\r\n		<ul>\r\n			<li>Porteurs: Emmanuel, Ludwig, Philippe, Vincent</li>\r\n			<li>Sujet : S&rsquo;interroger sur l&#39;opportunit&eacute; ou non de r&eacute;pondre au march&eacute; EOLE si celui-ci est publi&eacute;.&nbsp;</li>\r\n			<li>Identifier les cons&eacute;quences (humaines, de moyen, opportunit&eacute; ...) des diff&eacute;rents choix qui s&#39;offrent &agrave; Cadoles. Un DAD sera r&eacute;dig&eacute; pour d&eacute;cider si nous chercherons &agrave; r&eacute;pondre &agrave; ce march&eacute;.</li>\r\n		</ul>\r\n		</li>\r\n		<li>D&Eacute;CISION: un groupe de travail a &eacute;t&eacute; mis en place pour travailler sur ce sujet strat&eacute;gique : Emmanuel (pilote), Benjamin Bohard, Philippe, Ludwig, G&eacute;rald (optionnel) et Matthieu (optionnel)</li>\r\n	</ul>\r\n	</li>\r\n</ul>\r\n\r\n<h2>Prise de parole libre</h2>\r\n\r\n<ul>\r\n	<li>R&Eacute;PONSE &Agrave; L&#39;OFFRE D&#39;EMBAUCHE : une personne a r&eacute;pondu a une de nos offres d&#39;emploi. Benjamin Bohard va y r&eacute;pondre.</li>\r\n	<li>Catalogue de services &agrave; revoir dans Dolibarr, avec un nettoyage n&eacute;cessaire.</li>\r\n	<li>Ghislain a annonc&eacute; son d&eacute;part de Cadoles au 1er octobre 2019, avec des implications diverses:\r\n	<ul>\r\n		<li>Il faudra nommer un 3&egrave;me cog&eacute;rant d&#39;ici l&agrave;</li>\r\n		<li>Ghislain continuera de travailler pour le client Toolib</li>\r\n		<li>Cadoles continuera de travailler pour le client Toolib sur divers points</li>\r\n	</ul>\r\n	</li>\r\n	<li>La question a ainsi &eacute;t&eacute; discut&eacute;e concernant les comp&eacute;tences Ruby de Ghislain, qu&#39;il est le seul &agrave; avoir aujourd&#39;hui chez Cadoles. Concernant celles-ci, &ccedil;a risque de poser un probl&egrave;me pour le site web de Cadoles ainsi que le client Co-voiturage (qui ne s&#39;est pas manifest&eacute; depuis longtemps maintenant). Il va falloir donc r&eacute;fl&eacute;chir &agrave; l&#39;impact des comp&eacute;tences uniques, qui sont &agrave; &eacute;viter. C&#39;est donc une question strat&eacute;gique que Cadoles se pose : 2 comp&eacute;tences en &quot;bin&ocirc;me&quot; au minimum sur chaque client.<br />\r\n	&nbsp;</li>\r\n</ul>','2019-06-19 09:12:56',1,0,'uploads/blogarticle/5d09e0738a6bc.jpg'),(3,18,3,'CR de l\'assemblée collective du 16/07/19','<p>Bonjour &agrave; tous,</p>\r\n\r\n<p>Voici le compte rendu de l&#39;assembl&eacute;e collective aui s&#39;est tenue le mardi 16 juillet 2019.</p>\r\n\r\n<p>## Audit social :<br />\r\n&nbsp;&nbsp;&nbsp; Projet en cours<br />\r\n&nbsp;&nbsp;&nbsp; Proc&eacute;dure au ralenti car quelques difficult&eacute;s &agrave; recueillir des informations &agrave; cause de la r&eacute;tentions d&#39;information de la part d&#39;Exco<br />\r\n&nbsp;&nbsp;&nbsp; En attente du deuxi&egrave;me jour d&#39;audit pr&eacute;vu le 18/07/19</p>\r\n\r\n<p>## ANSSI :<br />\r\n&nbsp;&nbsp;&nbsp; Proc&eacute;dure pouvant prendre 2 &agrave; 3 ans<br />\r\n&nbsp;&nbsp;&nbsp; Besoin de # personnes qualifi&eacute; minimum pour assurer le maintien de la certification<br />\r\n&nbsp;&nbsp;&nbsp; En attente des informations sur les couts des d&eacute;marches</p>\r\n\r\n<p>## R&eacute;organisation des bureaux :<br />\r\n&nbsp;&nbsp;&nbsp; Premi&egrave;re propisition non convaincante de la part d&#39;Aprim<br />\r\n&nbsp;&nbsp;&nbsp; En attentes des r&eacute;ponse des diff&eacute;rents prestataires.<br />\r\n&nbsp;&nbsp;&nbsp; Prise de rendez-vous avec la soci&eacute;t&eacute; Olivenoire par BGAUDE</p>\r\n\r\n<p>## Strat&eacute;gie EOLE :<br />\r\n&nbsp;&nbsp;&nbsp; En cours de travail. En attente du erendez-vous avec Luc Bourdot le 19/07/19 pour avoir avoir une ;eilleure vision de la suite sur le march&eacute; EOLE.<br />\r\n&nbsp;&nbsp;&nbsp; Le groupe de travail &eacute;labore un plan d&#39;impact financier et technique dans l&#39;&eacute;ventualit&eacute; de l&#39;arret du march&eacute;</p>\r\n\r\n<p>## T&eacute;l&eacute;travail :<br />\r\n&nbsp;&nbsp;&nbsp; Document r&eacute;dig&eacute; et couvrant toutes les &eacute;ventualit&eacute;s<br />\r\n&nbsp;&nbsp;&nbsp; Besoin d&#39;une relecture commune et ratification/avenant si besoin<br />\r\n&nbsp;&nbsp;&nbsp; <strong>Pr&eacute;voir une date de relecture g&eacute;n&eacute;rale</strong><br />\r\n&nbsp;&nbsp;&nbsp; Besoin d&#39;un vote collectif rapide pour valider la mission</p>\r\n\r\n<p>## D&eacute;compte horaire<br />\r\n&nbsp;&nbsp;&nbsp; Travail en cours.<br />\r\n&nbsp;&nbsp;&nbsp; Premier travail sur le d&eacute;compte des cong&eacute;s par p&eacute;riode<br />\r\n&nbsp;&nbsp;&nbsp; Ticket sur la cr&eacute;ation d&#39;un &eacute;cran de saisie, d&#39;un &eacute;cran de r&eacute;capitulation par salari&eacute;/projet<br />\r\n&nbsp;&nbsp;&nbsp; Implique que tout le monde saisisse ses temps de travail pour avoir des indicateurs pertinent.<br />\r\n&nbsp;&nbsp;&nbsp; Attention aux d&eacute;rives et/ou &agrave; ce que &ccedil;a implique l&eacute;galement.<br />\r\n&nbsp;&nbsp;&nbsp; Besoin que tout le monde r&eacute;gule mensuellement ses heures.<br />\r\n&nbsp;&nbsp;&nbsp; Test pendant un trimestre<br />\r\n&nbsp;&nbsp;&nbsp; Estimation de 5 jours de d&eacute;veloppement pour int&eacute;grer &agrave; schedule.<br />\r\n&nbsp;&nbsp;&nbsp; Voir si un outil open source existe d&eacute;j&agrave; avant de lancer le d&eacute;veloppement en aout.</p>\r\n\r\n<p>## Missions :<br />\r\n&nbsp;&nbsp;&nbsp; Diffusion des prmi&eacute;res fiches de missions individuelles<br />\r\n&nbsp;&nbsp;&nbsp; Soumis &agrave; critiques</p>\r\n\r\n<p>## Sujets libres :<br />\r\n&nbsp;&nbsp;&nbsp; # BGAUDE :<br />\r\n&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; Volont&eacute; de revenir &agrave; temps plein en septembre.<br />\r\n&nbsp;&nbsp;&nbsp;<br />\r\n&nbsp;&nbsp;&nbsp; # Probl&eacute;matique de R&eacute;gie :<br />\r\n&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; A d&eacute;battre : Nos salari&eacute;s ne doivent plus &ecirc;tre 5j par semaine chez le client<br />\r\n<br />\r\n&nbsp;&nbsp;&nbsp; # Renouvellement du contrat de MLAMALLE :<br />\r\n&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; Accept&eacute; &agrave; l&#39;unanimit&eacute;<br />\r\n<br />\r\n&nbsp;&nbsp;&nbsp; # Passer LSEYS et SELIADE au groupe interne :<br />\r\n&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; Accept&eacute; &agrave; l&#39;unanimit&eacute;<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<br />\r\n&nbsp;&nbsp;&nbsp; # Indexation des salaires sur le co&ucirc;t de la vie :<br />\r\n&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; Cr&eacute;ation d&#39;un groupe de travail : wpetit, seliade, vfebvre<br />\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<br />\r\n&nbsp;&nbsp;&nbsp; # D&eacute;part des salari&eacute;s et condition de la rupture conventionnelle :<br />\r\n&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; Constitution d&#39;un groupe de travail afin de d&eacute;finir un cadre et les conditions sur les d&eacute;parts : wpetit, egarette, mlamalle, bgaude</p>\r\n\r\n<p>&nbsp;&nbsp;&nbsp; # Rupture conventionnelle&nbsp;:<br />\r\n&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; En l&#39;absence de cadre d&eacute;fini demand&eacute; par la cog&eacute;rance:<br />\r\n&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; - Organiser un entretien.<br />\r\n&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; - Soumettre les n&eacute;gociations au vote lors d&#39;une r&eacute;union<br />\r\n<br />\r\n&nbsp;&nbsp;&nbsp; # Election d&#39;un CSE :<br />\r\n&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; Les salari&eacute;s souhaitant se pr&eacute;sent&eacute;s sont inviti&eacute;s &agrave; se manifester</p>\r\n\r\n<p>&nbsp;</p>','2019-07-17 10:30:15',1,0,'uploads/blogarticle/5daec55285fff.jpeg'),(4,18,3,'CR de l\'assemblée collective du 17/09/19','<p>Bonjour &agrave; tous,</p>\r\n\r\n<p>Voici le compte rendu de l&#39;assembl&eacute;e collective qui s&#39;est tenue le mardi 17 septembre 2019.</p>\r\n\r\n<p><strong>Formations :</strong><br />\r\nLes formations demand&eacute;es on bien &eacute;t&eacute; identifi&eacute;es. Toutefois, suite aux exp&eacute;riences pr&eacute;c&eacute;dentes il a &eacute;t&eacute; convenu que dans un premier temps il fallait proposer une formation de d&eacute;veloppement (Go) et une formation Syst&egrave;me (S&eacute;curit&eacute;)&nbsp;(seliade)</p>\r\n\r\n<p><strong>Indexation des salaires :</strong><br />\r\nSuite au travail du groupe, une premi&egrave;re proposition sera soumise dans&nbsp;un mois (wpetit, vfebvre, bgaude, seliade)</p>\r\n\r\n<p><strong>Fiches de mission :</strong><br />\r\nEn attente de la mise &agrave;&nbsp;jour des fiches de poste de collaborateur. (mlamalle)</p>\r\n\r\n<p><strong>Certification ANSSI :</strong><br />\r\nPas de nouvelles depouis la r&eacute;union.&nbsp;Relancer l&#39;ANSSI (wpetit)</p>\r\n\r\n<p><strong>R&eacute;organisation des bureaux :</strong><br />\r\nOublie de soumission du DAD. Apr&egrave;s r&eacute;ception des diff&eacute;rents devis / propositions, le choix du prestataire s&#39;oriente vers THA&Iuml;S. Pr&eacute;paration du prochain DAD et vote (bgaude, vfebvre, tcornaut)&nbsp;</p>\r\n\r\n<p><strong>March&eacute; EOLE :</strong><br />\r\nPour rappel, nous nous sommes engag&eacute; aupr&egrave;s d&#39;EOLE de faire uniquement du MCO, et ce dans nos bureaux jusqu&#39;&agrave; la fin du march&egrave;.<br />\r\nR&eacute;union pr&eacute;vue le jeudi 19 et vendredi 20 septembre pour discuter du projet Alphabet (wpetit, mlamalle)&nbsp;</p>\r\n\r\n<p><strong>Accompagnement administratif :</strong><br />\r\nL&#39;arriv&eacute; de Mazars apporte un plus.<br />\r\nOn retarde un peu le sujet pour voir l&#39;impact r&eacute;el que ce changement de comptable apporte (lfornerot)</p>\r\n\r\n<p><strong>Suivi du temps de travail :</strong><br />\r\nPlanifier 5 jours pour Sylvain pour d&eacute;velopper en interne un outil. (mlamalle, seliade)</p>\r\n\r\n<p><strong>Conditions de rupture :</strong><br />\r\nProposition &agrave; la prochaine AC</p>\r\n\r\n<p><strong>Chorum et g&eacute;rance :</strong><br />\r\nDAD en attente (tcornaud)</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Autres sujets :</p>\r\n\r\n<p>- La rupture conventionnelle de gloaec a &eacute;t&eacute; accept&eacute;e par la cog&eacute;rance.</p>\r\n\r\n<p>- Possible et th&eacute;orique retour d&#39;Arnaud au bureau&nbsp;si d&eacute;m&eacute;nagement des bureaux EOLE/Envole</p>\r\n\r\n<p>- Groupe de travail : Refonte Infra Interne (egarette, pcaseiro, vfebvre)</p>\r\n\r\n<p>- Groupe de travail : R&egrave;glement int&eacute;rieur (mlamalle, et autres bienvenus)</p>\r\n\r\n<p>- Groupe de travail : D&eacute;finition du r&ocirc;le du Co-G&eacute;rant (en attente de consultation Mazars)</p>\r\n\r\n<p>&nbsp;</p>','2019-09-18 15:36:57',1,0,'uploads/blogarticle/5daec55cca429.jpeg'),(5,18,3,'CR de l\'assemblée collective du 22/10/19','<p>Bonjour &agrave; tous,</p>\r\n\r\n<p>Voici le compte rendu de l&#39;assembl&eacute;e collective qui s&#39;est tenue le mardi 22 octobre 2019.</p>\r\n\r\n<h3><strong>Discussions :</strong></h3>\r\n\r\n<p><strong>R&eacute;&eacute;valuation des salaires :</strong><br />\r\nLe travail est en cours. Le groupe de travail &eacute;tudie la possibilit&eacute; de passer le calcul du salaire unique sur le brute mensuel.</p>\r\n\r\n<p><strong>Gestion des fins de contrats et d&eacute;parts des salari&eacute;s :</strong><br />\r\nPas d&#39;avancement sur le groupe de travail. Ce dernier n&#39;a pas pris le temps de travailler sur le sujet.</p>\r\n\r\n<p><strong>Fiches de missions :</strong><br />\r\nPR &agrave; pr&eacute;voir suite au prochain atelier collectif sur le mod&egrave;le organisationnel<br />\r\n<br />\r\n<strong>Quorum:</strong><br />\r\nPR &agrave; refaire suite &agrave; la perte de la forge</p>\r\n\r\n<p><strong>ANSSI :&nbsp;</strong><br />\r\nPas d&#39;avancement sur le groupe de travail. Besoin de pr&eacute;voir du temps de travail. Lfornerot rejoins le groupe de travail.</p>\r\n\r\n<p><strong>Formation :</strong><br />\r\n- formation GO : Dossier FAFIEC en cours. On attend des propositions de date en accord avec les plannings<br />\r\n- formation S&eacute;curit&eacute; syst&egrave;me : Pas de formations int&eacute;ressante pour le moment.</p>\r\n\r\n<p><strong>March&eacute; EOLE :</strong><br />\r\nOn continu de travailler sur les sprints, mais nous n&#39;entretenons plus vraiment de liens, eux non plus. Nous pensons que le march&eacute; ne sera pas reconduit, tout du moins pas sous cette forme. Suite au retour de l&#39;&eacute;quipe &agrave; Cadoles, une nouvelle &eacute;quipe CSS s&#39;est contitu&eacute;. Dissolution du groupe de travail</p>\r\n\r\n<p><strong>Accompagnement sur les missions administratives :</strong><br />\r\n<span style=\"font-family:Liberation Sans,sans-serif\">Mazars viens au bout de sa mission et souhaiterai la constitution d&rsquo;une fiche de mission pour pouvoir continuer &agrave; &ecirc;tre sollicit&eacute; occasionnellement sur des questions sociales, &eacute;conomique, etc &hellip; </span></p>\r\n\r\n<p><strong>Divers :</strong><br />\r\n<span style=\"font-family:Liberation Sans,sans-serif\">- Anticiper les r&eacute;formes qui vont survenir en 2020 sur les attributions d&rsquo;agr&eacute;ment de formations.<br />\r\n- Benjamin Gaud&eacute; souhaite rentrer au capital. La proposition&nbsp;sera mise&nbsp;&agrave; l&rsquo;ordre du jour &agrave; la prochaine AG.</span><br />\r\n<span style=\"font-family:Liberation Sans,sans-serif\">- Il faut qu&#39;on prenne&nbsp;l&rsquo;habitude de d&eacute;finir des budgets pour les groupes de travail et les DAD.</span><br />\r\n<span style=\"font-family:Liberation Sans,sans-serif\">- L&rsquo;&eacute;quipe CSS exp&eacute;rimente une nouvelle organisation. La premi&egrave;re heure de travail de la journ&eacute;e permettrait de faire des m&eacute;l&eacute;es et de r&eacute;aliser les missions coop&eacute;rateur. Exp&eacute;rimentation pendant 1 mois et retour aupr&egrave;s de l&rsquo;assembl&eacute;e collective</span></p>\r\n\r\n<h3>D&eacute;cisions :</h3>\r\n\r\n<p><strong>Am&eacute;nagement des bureaux : Passer commande de la prestation de Thais</strong><br />\r\nAdopt&eacute; &agrave; l&#39;unanimit&eacute;</p>\r\n\r\n<p><strong>R&eacute;mun&eacute;ration de Gwen quant aux formations : Marge pour Cadoles de 25%</strong><br />\r\nAdopt&eacute; &agrave; 7 voix pour, 4 voix autres</p>\r\n\r\n<p><strong>Financement des formations internes : d&eacute;cision libre du groupe de travail sous contr&ocirc;le du responsable administratif et financier</strong><br />\r\nD&eacute;finir dans un futur proche un seuil budg&eacute;taire&nbsp;</p>\r\n\r\n<h3>Groupes de travail :</h3>\r\n\r\n<p><strong>Accompagnement administratif : lfornerot, lseys, wpetit</strong><br />\r\n- Organiser un r&eacute;union avec Mazars et leur d&eacute;finir une feuille de route<br />\r\n- budget : 3 jours hommes</p>\r\n\r\n<p><strong>Strat&eacute;gie CSS : &eacute;quipe CSS</strong><br />\r\n- Renommer CSS<br />\r\n- Faire un retour prochain sur l&#39;exp&eacute;rimentation d&#39;organisation</p>\r\n\r\n<p><strong>Atelier Collectif : D&eacute;finir les diff&eacute;rentes missions au sein de Cadoles d&#39;un point de vu l&eacute;gal et social</strong><br />\r\nConstitution de 3 groupes de travail :</p>\r\n\r\n<ol>\r\n	<li>Gestion organisationnelle : afornerot, mlamalle, vfebvre, wpetit</li>\r\n	<li>Mesure d&#39;urgence : bgaude, bbohard, tcornaut, egarette</li>\r\n	<li>Missions l&eacute;gales : lfornerot, pcaseiro, lseys</li>\r\n</ol>\r\n\r\n<p>Premier retour &agrave; faire dans 15 jours, restitution dans un mois &agrave; la prochaine AC</p>','2019-10-23 09:28:35',1,0,'uploads/blogarticle/5db002b5d99bc.jpg'),(6,18,3,'CR de l\'assemblée collective du 19/11/19','<p>Bonjour &agrave; tous,</p>\r\n\r\n<p>Voici le compte rendu de l&#39;assembl&eacute;e collective qui s&#39;est tenue le mardi 19 novembre&nbsp;2019.</p>\r\n\r\n<h2>Discussions :</h2>\r\n\r\n<p>- Deux DADs ont &eacute;t&eacute; soumis par lfornerot. Il a &eacute;t&eacute; d&eacute;cid&eacute;&nbsp;de passer en mesure exceptionnelle le DAD &quot;Cadeau de fin d&#39;ann&eacute;e&quot;.<br />\r\nS&eacute;paration du DAD en 2 :<br />\r\n&nbsp; &nbsp; <strong>DAD Cadeau de fin d&#39;ann&eacute;e</strong> :<br />\r\n&nbsp; &nbsp; &nbsp; &nbsp; 1. Rien : 0<br />\r\n&nbsp; &nbsp; &nbsp; &nbsp; 2. Cadhoc salari&eacute; : 3<br />\r\n&nbsp; &nbsp; &nbsp; &nbsp; 3. Cadhoc salari&eacute;s et enfants : 2<br />\r\n&nbsp; &nbsp; &nbsp; &nbsp; 4. Ch&egrave;que cadeau divers : 4<br />\r\n&nbsp; &nbsp; &nbsp; &nbsp; 5. Abstention : 1<br />\r\n&nbsp; &nbsp; &nbsp; &nbsp; Vfebvre s&#39;occupe de centraliser les demandes</p>\r\n\r\n<p>&nbsp; &nbsp;<strong> DAD Prime exceptionnelle de fin d&#39;ann&eacute;e</strong> :<br />\r\n&nbsp; &nbsp; &nbsp; &nbsp; 1. Rien : 0<br />\r\n&nbsp; &nbsp; &nbsp; &nbsp; 2. Prime : 9<br />\r\n&nbsp; &nbsp; &nbsp; &nbsp; 3. Abstention : 1<br />\r\n&nbsp; &nbsp; &nbsp; &nbsp; Montant entre 1&euro; et 1000&euro; :&nbsp;<br />\r\n&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 1. 500&euro; : 0<br />\r\n&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 2. 750&euro; : 0<br />\r\n&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 3. 1000&euro; : 8<br />\r\n&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 4. Abstention : 2</p>\r\n\r\n<p>- Retour sur l&#39;exp&eacute;rimentation organisationnelle de l&#39;activit&eacute; Syst&egrave;me sur l&#39;allocation d&#39;une heure de temps coop&eacute;rateur et de r&eacute;union.&nbsp;<br />\r\nCela fonctionne bien, mais un autre probl&egrave;me &eacute;merge du fait de la quantit&eacute; de travail devant &ecirc;tre assum&eacute;.<br />\r\nTravail sur un DAD pour pallier &agrave; ce probl&egrave;me organisationnel.<br />\r\n&nbsp;</p>\r\n\r\n<h2>Groupes de travail :&nbsp;</h2>\r\n\r\n<p>Pas d&#39;avancer sur les autres sujets.</p>\r\n\r\n<p><strong>1. Gestion organisationnelle</strong><br />\r\n&nbsp; &nbsp; afornerot, mlamalle, vfebvre, wpetit<br />\r\n&nbsp; &nbsp; Relecture et d&eacute;bat.</p>\r\n\r\n<p><strong>2. Mesures d&#39;urgence</strong><br />\r\n&nbsp; &nbsp; bgaude, bbohard,egarette&nbsp;<br />\r\n&nbsp;&nbsp; &nbsp;Relecture et d&eacute;bat.<br />\r\n&nbsp;&nbsp; &nbsp;Plusieurs FIXME &agrave; corriger.<br />\r\n&nbsp;&nbsp; &nbsp;Soumis &agrave; relecture collective.</p>\r\n\r\n<p><strong>3. Missions l&eacute;gales</strong><br />\r\n&nbsp; &nbsp; seliade, lfornerot, pcaseiro, lseys<br />\r\n&nbsp;&nbsp; &nbsp;Relecture et d&eacute;bat.<br />\r\n&nbsp;&nbsp; &nbsp;Aujourd&#39;hui rien n&#39;existe. Volont&eacute; de merger la PR afin de combler le vide dans un premier temps.<br />\r\n&nbsp;&nbsp; &nbsp;Vote pour int&eacute;grer la proposition imm&eacute;diate, modulo modifications d&eacute;battues.<br />\r\n&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;Pour : 8<br />\r\n&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; &nbsp;Abstention : 1<br />\r\n&nbsp;<br />\r\nLes trois ateliers ont fourni un travail suffisant pour pouvoir &ecirc;tre soumis &agrave; une relecture g&eacute;n&eacute;rale, puis mise au vote la prochaine AC.</p>\r\n\r\n<h2>D&eacute;cisions :</h2>\r\n\r\n<p><strong>- Cadeaux de fin d&#39;ann&eacute;e : </strong>a &eacute;t&eacute; vot&eacute; des ch&egrave;ques cadeaux seront fait pour l&#39;ensemble des salari&eacute;s, dans les enseignes de leurs choix. Vfebvre r&eacute;coltera les souhaits de chacun.<br />\r\n-&nbsp;<strong>Prime exceptionnelle de fin d&#39;ann&eacute;e</strong> : a &eacute;t&eacute; vot&eacute; une prime de fin d&#39;ann&eacute;e de 1000&euro; pour l&#39;ensemble des salari&eacute;s, profitant de la d&eacute;fiscalisation.<br />\r\n-&nbsp;<strong>Missions l&eacute;gales : </strong>a &eacute;t&eacute; vot&eacute; la fusion de la PR pour combler le vide actuel, sous r&eacute;serve des modifications relev&eacute;s.</p>\r\n\r\n<p><br />\r\n&nbsp;</p>','2019-11-20 11:40:40',1,0,'uploads/blogarticle/5dd51822d627b.jpg'),(7,18,3,'CR de l\'assemblée collective du 20/12/19','<p>Bonjour &agrave; tous,</p>\r\n\r\n<p>Voici le compte rendu de l&#39;assembl&eacute;e collective qui s&#39;est tenue le vendredi&nbsp;20&nbsp;d&eacute;cembre&nbsp;2019.</p>\r\n\r\n<h2>Discussions :</h2>\r\n\r\n<ul>\r\n	<li>Tha&iuml;s repasse en janvier pour faire un devis des travaux. Elle proposera &eacute;galement un co&ucirc;t estimatif par poste de travail. Nous souhaitons metttre la pression sur les d&eacute;lais afin d&#39;avoir un am&eacute;nagement fin mars. Un catalogue de mobilier est mis &agrave; disposition.</li>\r\n	<li>Mettragre des locaux de TEMMII r&eacute;alis&eacute;s : 158m&sup2; pour la partie entrepot (comprenant un deuxi&egrave;me niveau).</li>\r\n	<li>Polynum : Il nous faut trouver un moyen de nous d&eacute;sengager du projet. A rediscuter ) la prochaine AC.</li>\r\n	<li>Contribution au logiciel libre : il&nbsp;faudra d&eacute;finir un montant maximum lors d&rsquo;un nouveau DAD. Traditionellement Cadoles fait des dons&nbsp;chaque ann&eacute;e &agrave; l&rsquo;April, Wikip&eacute;dia et Framasoft. Envisager d&rsquo;acheter du support en guise de participation financi&egrave;re.</li>\r\n	<li>Mesure d&#39;urgence et missions l&eacute;gales : Il reste des points &agrave; traiter et a compl&eacute;ter.</li>\r\n	<li>Mutuelle : aujourd&#39;hui les mutuelles propos&eacute;s ne sont pas de vraie arganisme de mutuelle. Nous ne faisons pas confiance &agrave; ces organismes qui trainent des casseroles et souhaiterions nous orienter vers une vraie mutuelle plus Humaniste.</li>\r\n	<li>Forfait annuel d&#39;assistance administrative, sociale et juridique : Aupr&egrave;s de notre cabinet comptable. 1200&euro;/mois</li>\r\n</ul>\r\n\r\n<h2>D&eacute;cisions :</h2>\r\n\r\n<ul>\r\n	<li><strong>Repas de fin d&#39;ann&eacute;e - Traiteur et location de salle pour les salari&eacute;s et leur famille<br />\r\n	Adopt&eacute;</strong> &agrave; 10 voix contre 2<br />\r\n	Date &agrave; d&eacute;finir pour le d&eacute;but d&#39;ann&eacute;e 2020</li>\r\n	<li><strong>Contribution financi&egrave;re au logiciel libre -&nbsp;Participer financi&egrave;rement &agrave; un ou plusieurs projet de logiciel libre s&eacute;lectionn&eacute;s de mani&egrave;re collective<br />\r\n	Adopt&eacute;</strong> &agrave;&nbsp; l&rsquo;unanimit&eacute;.</li>\r\n	<li><strong>Gestion organisationnelle - fusion de la PR<br />\r\n	Adopt&eacute;</strong>&nbsp;&agrave; l&#39;unanimit&eacute;</li>\r\n	<li><strong>Mesure d&#39;urgence : fusion de la PR</strong><br />\r\n	Adopt&eacute; &agrave; 11 voix contre 1</li>\r\n	<li><strong>Missions l&eacute;gales :&nbsp;&nbsp;fusion de la PR<br />\r\n	Adopt&eacute;</strong> &agrave; 10 voix contre 2</li>\r\n	<li><strong>Mutuelle - Garder la mutuelle actuelle<br />\r\n	Adopt&eacute;</strong> &agrave; 9 voix contre 3</li>\r\n	<li><strong>Forfait annuel d&#39;assistance administrative, sociale et juridique&nbsp;<br />\r\n	Adopt&eacute;</strong> &agrave; l&#39;unanimit&eacute;</li>\r\n	<li><strong>Rupture conventionnelle de Sylvain Eliade - Accepter la rupture conventionnelle, refuser la proposition actuelle, et demander une nouvelle n&eacute;gociation&nbsp;<br />\r\n	Adopt&eacute;</strong> &agrave; 5 voix contre 1 abstention, et 3 autres choix</li>\r\n	<li><strong>Valorisation des d&eacute;placements des salari&eacute;s -&nbsp;Compter les heures, valoriser en repos compensatoire et verser une prime de d&eacute;placement par jour.<br />\r\n	Adopt&eacute;</strong> &agrave; 10 voix contre 2</li>\r\n	<li><strong>D&eacute;finir de fa&ccedil;on pr&eacute;dictive le jour de l&#39;assembl&eacute;e collective -&nbsp;mardi apr&egrave;s-midi de la semaine du 15 du mois en cours.</strong><br />\r\n	<strong>Adopt&eacute;</strong> &agrave; l&rsquo;unanimit&eacute;, PR merg&eacute;e</li>\r\n</ul>\r\n\r\n<h2>Groupes de travail :</h2>\r\n\r\n<ul>\r\n	<li>Repas de fin d&#39;ann&eacute;e : wpetit, contacte la p&eacute;niche cancale. Une journ&eacute;e pr&eacute;vue.</li>\r\n	<li>Mesure d&#39;urgence : bgaude, r&eacute;aliser des issues et amender. Une demi journ&eacute;e pr&eacute;vue.</li>\r\n	<li>Missions l&eacute;gales&nbsp;: wpetit, pcaseiro et egarette, r&eacute;aliser des issues et amender. Une demi journ&eacute;e pr&eacute;vue par personne.</li>\r\n	<li>Trouver une nouvelle vraie mutuelle : lfornerot. Pas de budget estimable</li>\r\n	<li>Forfait annuel d&#39;assistance administrative, sociale et juridique : Cog&eacute;rance, v&eacute;iller au bon d&eacute;roulement&nbsp;</li>\r\n	<li>Ruptutre conventionnelle de Sylvain&nbsp;Eliade : Cog&eacute;rance, second rendez-vous de n&eacute;gociation.</li>\r\n	<li>Valorisation des d&eacute;placements des salari&eacute;s : Cog&eacute;rance, pilotage du bon d&eacute;roulement.</li>\r\n</ul>\r\n\r\n<ul>\r\n</ul>','2019-12-26 09:53:19',1,0,'uploads/blogarticle/5e04762260478.jpg'),(8,18,3,'CR de l\'assemblée collective du 14/01/20','<p>Bonjour &agrave; tous,</p>\r\n\r\n<p>Voici le compte rendu de l&#39;assembl&eacute;e collective qui s&#39;est tenue le mardi 14 janvier 2020.</p>\r\n\r\n<p>Discussions :</p>\r\n\r\n<ul>\r\n	<li>Organisation et am&eacute;nagement des bureaux :&nbsp;mal-&ecirc;tre exprim&eacute; par afornerot et support&eacute; par pcaseiro, sur l&#39;&eacute;tat actuel du bureaux et le rangement n&eacute;cessaire. Dans l&#39;attente de la restitution du travail par Tha&iuml;s, il est n&eacute;cessaire de faire quelque chose et de ranger.</li>\r\n	<li>D&eacute;part de Sylvain : Un courrier a &eacute;t&eacute; envoy&eacute; &agrave; seliade, sous conseil du cabinet Mazar. Nous sommes dans l&#39;attente d&#39;une r&eacute;ponse pour la suite.</li>\r\n</ul>\r\n\r\n<p>D&eacute;cisions :</p>\r\n\r\n<ul>\r\n	<li><strong>Gestion des recrutements</strong><br />\r\n	Cr&eacute;ation d&#39;un projet &quot;Recrutement&quot; et de sa structure, formalisation du proc&eacute;ssus d&#39;embauche<br />\r\n	<a href=\"https://forge.cadoles.com/Cadoles/scop-cadoles/src/branch/master/src/organisation/fiche-projet/recrutement.md\" target=\"_blank\">Fiche projet : Recrutement</a><br />\r\n	<strong>Adopt&eacute;</strong> &agrave; l&#39;unanimit&eacute;<br />\r\n	R&eacute;f&eacute;rent projet&nbsp;: afornerot<br />\r\n	R&eacute;f&eacute;rents techniques&nbsp;: wpetit, pcaseiro</li>\r\n	<li><strong>Organiser les journ&eacute;es LE</strong><br />\r\n	R&eacute;servation d&#39;une salle, s&eacute;lection d&#39;h&ocirc;tel &agrave; proposer aux participants, logitique<br />\r\n	Suite &agrave; un vote pond&eacute;r&eacute; : <strong>Organisation du weekend les 19 20 21</strong></li>\r\n</ul>\r\n\r\n<p>Groupes de travail :</p>\r\n\r\n<ul>\r\n	<li>Atelier LE : groupe collectif : D&eacute;finir ensemble ce qu&#39;il y a &agrave; faire.</li>\r\n	<li>Recrutement : afornerot, wpetit, mlamalle et tcornau : Mise en forme des offres d&#39;emploi, d&eacute;finition du processus d&#39;embauche et des &eacute;preuves soumises aux candidats.</li>\r\n	<li>Am&eacute;nagement des bureaux : collectif : Rangement des bureaux, r&eacute;organisation de l&#39;espace de travail pour une meilleure ergonomie et utilisabilit&eacute;.</li>\r\n</ul>','2020-01-15 10:20:30',1,0,'uploads/blogarticle/5e1ed6054838f.jpg'),(9,18,3,'CR de l\'assemblée collective du 11/02/20','<p>Bonjour &agrave; tous,</p>\r\n\r\n<p>Voici le compte rendu de l&#39;assembl&eacute;e collective qui s&#39;est tenue le mardi 11 f&eacute;vrier&nbsp;2020.</p>\r\n\r\n<p>Discussions :</p>\r\n\r\n<p>Concernant les ch&egrave;que d&eacute;jeuner et notament l&#39;ind&eacute;xation, il faudrait voir ci cette indexation ne pourrait pas &ecirc;tre plus globale (ch&egrave;que d&eacute;jeuners, salaires, etc)<br />\r\n&nbsp;</p>\r\n\r\n<p>D&eacute;cisions :</p>\r\n\r\n<ul>\r\n	<li><strong>Cybers&eacute;curit&eacute;</strong><br />\r\n	Participer au groupe de travail cybers&eacute;curit&eacute;<br />\r\n	<strong>Adopt&eacute; </strong>&agrave; 10 voix pour, 1 voix contre<br />\r\n	Groupe de travail&nbsp;: wpetit, bbohard, 0,5 jours par mois par personne</li>\r\n	<li>\r\n	<p>Ch&egrave;que d&eacute;jeuner<br />\r\n	Ajourner le DAD pour compl&eacute;ter/reformuler les options&nbsp;:<br />\r\n	7 pours, 1 voix contre, 1 abstention<br />\r\n	Voir s&rsquo;il est possible de cumuler cartes et tickets restau</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Destructeur de document</strong><br />\r\n	Achat d&rsquo;un destructeur de document norme DIN P-4<br />\r\n	<strong>Adopt&eacute; </strong>&agrave; l&rsquo;unanimit&eacute;</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Achats et am&eacute;nagement de bureaux</strong><br />\r\n	- Engager la proc&eacute;dure de signature de compromis du Major.<br />\r\n	<strong>Adopt&eacute; </strong>&agrave; l&rsquo;unanimit&eacute;<br />\r\n	- Non poursuite des travaux de Tha&iuml;s, mais compl&eacute;t&eacute; son offre<br />\r\n	<strong>Adopt&eacute; </strong>&agrave; l&rsquo;unanimit&eacute;</p>\r\n	</li>\r\n</ul>\r\n\r\n<p>Groupes de travail :</p>\r\n\r\n<ul>\r\n	<li>Cybers&eacute;curit&eacute; :&nbsp; wpetit, bbohard, 0,5 jours par mois par personne pour participer aux r&eacute;unions</li>\r\n	<li>Destructeur de document :&nbsp; bbohard, lseys, vfebvre pour choisir un mod&egrave;le</li>\r\n	<li>Organisation week end LE&nbsp;: bbohard s&rsquo;occupe de r&eacute;server la salle</li>\r\n	<li>Repas Cadoles&nbsp;: En cours, en attente de la synth&egrave;se de wpetit</li>\r\n	<li>D&eacute;velopper un outil de suivi interne&nbsp;: mlamalle, tcornaut.</li>\r\n</ul>','2020-02-12 10:00:58',1,0,'uploads/blogarticle/5e68b3e10cc46.jpg'),(10,18,3,'CR de l\'assemblée collective du 10/03/20','<p>Bonjour &agrave; tous,</p>\r\n\r\n<p>Voici le compte rendu de l&#39;assembl&eacute;e collective qui s&#39;est tenue le mardi 10 mars&nbsp;2020.</p>\r\n\r\n<p><strong>D&eacute;cisions :</strong></p>\r\n\r\n<ul>\r\n	<li><strong>Tickets Restaurant</strong><br />\r\n	Augmentation &agrave; 9 euros<br />\r\n	<strong>Adopt&eacute;&nbsp;</strong>&agrave; 8 voix pour, 1 voix contre, 1 abstention<br />\r\n	Refaire une DAD en septembre pour s&#39;adapter &agrave; la situation des nouveaux locaux<br />\r\n	&nbsp;</li>\r\n	<li>\r\n	<p><strong>Choix outil de documentation</strong><br />\r\n	<strong>Adopt&eacute;</strong> &agrave; l&rsquo;unanimit&eacute;<br />\r\n	Groupe de travail&nbsp;: mlamalle, lseys, tcornaut, egarette<br />\r\n	0,5 j par personne pour une r&eacute;union</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Machine &agrave; caf&eacute;</strong><br />\r\n	Achat d&rsquo;une nouvelle machine &agrave; caf&eacute;<br />\r\n	<strong>Adopt&eacute;</strong> &agrave; 9 voix pour, 2 abstention<br />\r\n	Groupe de travail pour choisir un mod&egrave;le&nbsp;: vfebvre, pcaseiro, tcornaut<br />\r\n	0,5 j par personne</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Trier et mettre &agrave; jour de la documentation interne<br />\r\n	Ajourn&eacute;e</strong>, sera trait&eacute; une fois la m&eacute;thodologie d&eacute;finie</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>DAD en ligne</strong><br />\r\n	Etudier la possibilit&eacute; de DAD en ligne<br />\r\n	<strong>Adopt&eacute;</strong> &agrave; l&rsquo;unanilmit&eacute;<br />\r\n	Groupe de travail&nbsp;: mlamalle, afornerot, bgaude</p>\r\n	</li>\r\n	<li>\r\n	<p>Non &agrave; l&rsquo;ordre du jour :<strong>&nbsp;D&eacute;cision sur l&rsquo;achat du nouveau local</strong><br />\r\n	<strong>Adopt&eacute;</strong> &agrave; l&rsquo;unanimit&eacute;</p>\r\n	</li>\r\n	<li>\r\n	<p>Non &agrave; l&rsquo;ordre du jour :&nbsp;<strong>Week end LE</strong><br />\r\n	Financer les repas du d&eacute;jeuner &agrave; hauteur de 20&euro; par personne<br />\r\n	<strong>Adopt&eacute;</strong> &agrave; l&#39;unanimit&eacute;</p>\r\n\r\n	<p>&nbsp;</p>\r\n	</li>\r\n</ul>\r\n\r\n<p><strong>Groupes de travail :</strong></p>\r\n\r\n<ul>\r\n	<li><strong>Choix outil de documentation</strong> :&nbsp;mlamalle, lseys, tcornaut, egarette</li>\r\n	<li><strong>Machine &agrave; caf&eacute; </strong>:&nbsp;vfebvre, pcaseiro, tcornaut</li>\r\n	<li><strong>DAD en ligne</strong> :&nbsp;mlamalle, afornerot, bgaude</li>\r\n	<li><strong>Am&eacute;nagement et recherche de local&nbsp;</strong>:&nbsp; signature promesse de vente vendredi 13 mars 2020, d&eacute;cision &agrave; prendre sur la vente du local actuel.</li>\r\n	<li>I<strong>ndexation des salaires&nbsp;</strong>: envoi pr&eacute;vu des simulations au salari&eacute;s. Proposition en plusieurs &eacute;tapes :\r\n	<ul>\r\n		<li>passage &agrave; un brut horaire identique pour tout le monde sur la base de 3333,44 &euro; mensuel temps plein (brut le plus haut &agrave; Cadoles aujourd&rsquo;hui)</li>\r\n		<li>augmentation du brut &agrave; 3400 &euro; pour tout le monde sur la base d&rsquo;un temps plein.</li>\r\n	</ul>\r\n	</li>\r\n	<li><strong>Embauches</strong>&nbsp;: plusieurs candidatures en cours du c&ocirc;t&eacute; dev, en attente de r&eacute;ponses de candidats. Du c&ocirc;t&eacute; sys, nouvelle offre publi&eacute; orient&eacute; assistante de direction, beaucoup de candidature, passages des entretiens.</li>\r\n	<li><strong>ANSSI</strong>&nbsp;: clos</li>\r\n	<li><strong>Outil de suivi</strong>&nbsp;: bgaude, afornerot rejoin le groupe. D&eacute;finir tu temps pour d&eacute;velopp&eacute; l&rsquo;outil int&eacute;gr&eacute; &agrave; schedule. Pr&eacute;voir une r&eacute;union d&rsquo;estimation, 0,5 j par personne.</li>\r\n	<li><strong>Infra cadoles</strong>&nbsp;: pr&eacute;vu au mois d&rsquo;avril</li>\r\n	<li><strong>Accompagnement administratif</strong>&nbsp;: Compl&eacute;ter le tableau des t&acirc;ches</li>\r\n	<li><strong>Repas Cadoles</strong>&nbsp;: en stagnation. mlamalle&nbsp; rejoignent le groupe de travail</li>\r\n	<li><strong>Organisation LE</strong>&nbsp;: en cours, risque d&rsquo;annulation pour cause de coronavirus, possibilit&eacute; d&rsquo;organiser &agrave; Cadoles. Accord de principe sur la participation de Cadoles au frais de bouche du midi des deux jours pour les participants, &agrave; hauteur de 20 &euro; par repas.</li>\r\n	<li><strong>Destructeur de document</strong>&nbsp;: en cours</li>\r\n</ul>','2020-03-11 10:29:36',1,0,'uploads/blogarticle/5e68b4932aa01.jpg'),(11,2,3,'CR de l’Assemblée Collective exceptionnelle du 23/03/2020','<h1>Compte-rendu de l&rsquo;Assembl&eacute;e Collective exceptionnelle du lundi 23 mars 2020</h1>\r\n\r\n<p>Cette assembl&eacute;e collective exceptionnelle a &eacute;t&eacute; convoqu&eacute;e pour statuer sur les processus d&rsquo;embauche en cours : volont&eacute; de proposer une offre d&rsquo;embauche &agrave; C&eacute;line Rappeneau pour le poste d&rsquo;assistant&middot;e de direction, coordinateur&middot;trice technique d&rsquo;une part, pr&eacute;sentation des profils retenus et du profil privil&eacute;gi&eacute; pour le poste de d&eacute;veloppeur&middot;se.<br />\r\nLa question du financement de l&rsquo;achat du local rue Jean Jaur&egrave;s a &eacute;t&eacute; abord&eacute;e.<br />\r\nLes effets du confinement sur les personnes et l&rsquo;activit&eacute; ont &eacute;galement &eacute;t&eacute; abord&eacute;s, ainsi que l&rsquo;&eacute;tat de la proc&eacute;dure de recouvrement des cr&eacute;ances de Toolib.</p>\r\n\r\n<p>Cette assembl&eacute;e collective s&rsquo;est d&eacute;roul&eacute;e &agrave; distance, uniquement &agrave; l&rsquo;oral et l&rsquo;&eacute;crit, via l&rsquo;application Mumble dont une instance a &eacute;t&eacute; install&eacute;e sur l&rsquo;infrastructure de la soci&eacute;t&eacute;.</p>\r\n\r\n<p>Cette assembl&eacute;e collective a rassembl&eacute; Arnaud Fornerot, Benjamin Bohard, Benjamin Gaud&eacute;, Emmanuel Garette, Laetitia Fornerot, Philippe Caseiro, Teddy Cornaut, Vincent Fevbre et William Petit.</p>\r\n\r\n<p>&Agrave; noter que Teddy Cornaut a particip&eacute; &agrave; l&rsquo;&eacute;crit seulement &eacute;tant donn&eacute; que son client mumble &eacute;tait mal configur&eacute;.<br />\r\n&Agrave; noter &eacute;galement la connexion inattendue de Sylvain &Eacute;liade sous un pseudonyme qui n&rsquo;a pas permis de le reconna&icirc;tre et a motiv&eacute; le bannissement du canal faute d&rsquo;avoir pu l&rsquo;identifier.</p>\r\n\r\n<h2>Offre de contrat de travail pour C&eacute;line Rappeneau</h2>\r\n\r\n<p>Le profil fait l&rsquo;unanimit&eacute; aupr&egrave;s des personnes qui ont men&eacute; l&rsquo;entretien, tant au niveau du savoir-faire (comp&eacute;tences acquises) que du savoir-&ecirc;tre.<br />\r\nApr&egrave;s tour de table, les remarques compl&eacute;mentaires appuient cet avis.<br />\r\nTous les participants se rangent &agrave; l&rsquo;avis des personnes ayant pass&eacute; l&rsquo;entretien pour justifier l&rsquo;offre de contrat de travail.<br />\r\nL&rsquo;offre d&rsquo;embauche valid&eacute;e &agrave; l&rsquo;unanimit&eacute; en assembl&eacute;e collective est la suivante : embauche &agrave; temps partiel &agrave; 80% &agrave; partir du 1er juin 2020 de C&eacute;line Rappeneau.</p>\r\n\r\n<h2>Poursuite du processus d&rsquo;embauche pour le poste de d&eacute;veloppeur&middot;se</h2>\r\n\r\n<p>Le premier choix se porte sur Charles Maxime qui se d&eacute;marque des deux autres profils retenus par ses comp&eacute;tences.<br />\r\nLa d&eacute;cision valid&eacute;e en assembl&eacute;e collective &agrave; l&rsquo;unanimit&eacute; est celle de faire passer un second entretien &agrave; Charles Maxime pour s&rsquo;assurer de son int&eacute;r&ecirc;t et, le cas &eacute;ch&eacute;ant, lui soumettre une offre d&rsquo;embauche &agrave; temps plein au salaire junior prenant effet dans deux mois.</p>\r\n\r\n<h2>Financement de l&rsquo;achat du local rue Jean Jaur&egrave;s</h2>\r\n\r\n<p>Apr&egrave;s rappel de la date de signature de la promesse d&rsquo;achat, il a &eacute;t&eacute; port&eacute; &agrave; connaissance des pr&eacute;sents les d&eacute;marches de demandes de pr&ecirc;ts effectu&eacute;es aupr&egrave;s de la banque h&eacute;bergeant les comptes de la soci&eacute;t&eacute;.<br />\r\nLa proposition de la banque est un pr&ecirc;t sur une partie de la somme due avec int&eacute;r&ecirc;t de 0,85 sur 15 ans.<br />\r\nLe pr&ecirc;t couvre l&rsquo;achat, les travaux, les frais d&rsquo;agences, les frais de dossier.<br />\r\nLe reste de la somme non couvert par le pr&ecirc;t est de l&rsquo;ordre de 27&nbsp;000 &euro;, dont 17&nbsp;000 &euro; d&eacute;j&agrave; mis en d&eacute;p&ocirc;t aupr&egrave;s du notaire.<br />\r\nAucune assurance n&rsquo;est envisag&eacute;e, celle-ci couvrant personnellement les dirigeants des entreprises dans le cadre des assurances d&rsquo;entreprise et n&rsquo;&eacute;tant pas obligatoire.<br />\r\nLa d&eacute;cision valid&eacute;e en assembl&eacute;e collective &agrave; l&rsquo;unanimit&eacute; est d&rsquo;accepter cette offre sans chercher &agrave; obtenir d&rsquo;autres offres aupr&egrave;s d&rsquo;autres &eacute;tablissements bancaires.</p>\r\n\r\n<h2>Effets du confinement</h2>\r\n\r\n<p>Le besoin d&rsquo;&eacute;quipement se r&eacute;sume aux fauteuils.<br />\r\nUn probl&egrave;me de locaux pour certains qui ne disposent pas d&rsquo;un espace d&eacute;di&eacute; dans lequel ils peuvent s&rsquo;isoler (Laetitia a &eacute;t&eacute; oblig&eacute; de quitter l&rsquo;assembl&eacute;e &agrave; ce moment en cons&eacute;quence de ce probl&egrave;me).<br />\r\nUn probl&egrave;me de bande passante &eacute;galement avec la multiplication des usages.<br />\r\nIl n&rsquo;est pas envisag&eacute; d&rsquo;obliger les salari&eacute;s &agrave; poser des cong&egrave;s durant la p&eacute;riode de confinement.</p>\r\n\r\n<p>En terme de commande, seul le projet &agrave; venir de l&rsquo;EFS sera sans doute report&eacute; en fin d&rsquo;ann&eacute;e, ce qui n&rsquo;est pas probl&eacute;matique pour l&rsquo;activit&eacute; actuelle.<br />\r\nOn ne pr&eacute;voit pas de baisse d&rsquo;activit&eacute; pour les clients comme le CROUS, le MEN, le MTES.<br />\r\n&Agrave; noter que pour le MSE, une partie de l&rsquo;activit&eacute; d&eacute;pend &eacute;galement d&rsquo;autres intervenants, ce qui fait peser une incertitude sur une partie de l&rsquo;activit&eacute; tout de m&ecirc;me.<br />\r\nPour Envole, le besoin accru d&rsquo;ENT actuel pourrait changer la crainte de l&rsquo;arr&ecirc;t en red&eacute;marrage.<br />\r\nPour Mistral, aucune nouvelle n&rsquo;est alors [1] disponible et fait craindre un arr&ecirc;t du support.<br />\r\nLe projet du CD41 suit son cours en prenant en compte l&rsquo;&eacute;ventuel retard li&eacute; aux probl&egrave;mes de contexte.<br />\r\nLe projet de la Province Sud est moins bien engag&eacute;.<br />\r\nLes formations EOLE sont toutes annul&eacute;es pour l&rsquo;instant.</p>\r\n\r\n<h2>Points divers</h2>\r\n\r\n<h3>Le recouvrement de Toolib</h3>\r\n\r\n<p>Pas de nouvelle de la direction de Toolib.<br />\r\nLe dossier &agrave; transmettre &agrave; la soci&eacute;t&eacute; de recouvrement est en cours de constitution par Benjamin Gaud&eacute;.</p>\r\n\r\n<p><br />\r\n[1] Le support a depuis &eacute;t&eacute; renouvel&eacute;</p>','2020-03-25 12:29:35',1,0,'uploads/blogarticle/5e9d4b53639d3.jpg'),(12,18,3,'CR de l\'assemblée collective du 14/04/20','<h2>D&eacute;cisions</h2>\r\n\r\n<p><strong>Licenciement de Sylvain Eliad pour faute grave :<br />\r\nAdopt&eacute;</strong> &agrave; 9 voix pour, 1 abstention<br />\r\n<br />\r\n<strong>Tableau de bord :</strong><br />\r\nIdentifier les indicateurs pertinents<br />\r\n<strong>Adopt&eacute;</strong> &agrave;&nbsp;l&#39;nunanimit&eacute;<br />\r\nOrganiser une r&eacute;union, Temps allou&eacute; 1/2 journ&eacute;e de pr&eacute;paration entre associ&eacute;s + 1/2 journ&eacute;e avec Mazars par membre du GdT<br />\r\ngroupe de travail: egarette, lfornerot, vfebvre, (pcaseiro)</p>\r\n\r\n<h2><br />\r\nGroupes de travail en cours</h2>\r\n\r\n<p><strong>Choix outil de documentation</strong><br />\r\n- Pas d&#39;avanc&eacute;e particuli&egrave;re.&nbsp;<br />\r\n- Pas d&#39;urgence<br />\r\n- &Agrave; reprendre lors de la prochaine AC</p>\r\n\r\n<p><strong>Machine &agrave; caf&eacute;</strong><br />\r\n- Standby&nbsp;suite au confinement.&nbsp;<br />\r\n-&nbsp;Un mod&egrave;le a &eacute;t&eacute; trouv&eacute;.&nbsp;<br />\r\n-&nbsp;La commande&nbsp;sera trait&eacute;e post-confinement.</p>\r\n\r\n<p><strong>DAD en ligne</strong><br />\r\n-&nbsp;D&eacute;veloppement interne, strat&eacute;gie en 2 temps:&nbsp;<br />\r\n&nbsp; &nbsp; &nbsp;1.&nbsp;UI&nbsp;sp&eacute;cialis&eacute;e&nbsp;avec backend classique<br />\r\n&nbsp; &nbsp; &nbsp;2. D&eacute;veloppement d&#39;un backend utilisant les concepts/m&eacute;caniques de Bloodchain<br />\r\n-&nbsp;Avis favorable pour phase 1&nbsp;(sans de mise au voix)<br />\r\n- Une estimation plus concr&egrave;te doit &ecirc;tre r&eacute;alis&eacute;e pour un r&eacute;el d&eacute;blocage de temps<br />\r\n- Note: si temps disponible, v&eacute;rifier l&#39;&eacute;tat des commandes Envole, il y a du&nbsp;taF<br />\r\n- Addendum: Recontacter l&#39;EFS pour prendre la temp&eacute;rature du projet Bloodchain</p>\r\n\r\n<p><strong>Am&eacute;nagement et recherche de local</strong><br />\r\n-&nbsp;Plusieurs devis en cours de r&eacute;alisation pour alimenter le dossier bancaire.<br />\r\n-&nbsp;Difficile d&#39;obtenir des informations dans les conditions actuelles du confinement.<br />\r\n- &quot;Standby&quot;&nbsp;pour l&#39;instant.<br />\r\n-&nbsp;Devis ferme pour la refection des sols et la peinture<br />\r\n-&nbsp;Devis pour la climatisation dans boite interne<br />\r\n-&nbsp;Budget travaux 90k&euro;&nbsp;estim&eacute;,&nbsp;actuellement le cumul des devis re&ccedil;us incluant le mobiler est&nbsp;bien en dessous, ce qui laisse de la marge pour les travaux des sanitaires</p>\r\n\r\n<p><strong>Indexation des salaires</strong><br />\r\n-&nbsp;Vote exceptionnel &agrave; organiser par le GdT ou &agrave; la prochaine AC, avec donn&eacute;es du pr&eacute;visionnel<br />\r\n-&nbsp;Pr&eacute;visionnel&nbsp;&agrave;&nbsp;r&eacute;aliser&nbsp;par lfornerot pour vendredi 17/04</p>\r\n\r\n<p><strong>Embauche</strong><br />\r\n-&nbsp;Deux nouvelles personnes: C&eacute;line et Charles-Maxime<br />\r\n-&nbsp;Deux promesses d&#39;embauche envoy&eacute;es<br />\r\n-&nbsp;Arriv&eacute;e au 1er juin</p>\r\n\r\n<p><strong>Outil de suivi</strong><br />\r\n-&nbsp;Migration sur Symfony 4 en cours pour remettre le code au propre et permettre aux d&eacute;veloppeur de pouvoir participer</p>\r\n\r\n<p><strong>Infra&nbsp;Cadoles</strong><br />\r\n- Pr&eacute;vu&nbsp;initialement&nbsp;au mois d&rsquo;avril<br />\r\n-&nbsp;Objectif mi-mai si possibilit&eacute; de se d&eacute;placer une semaine &agrave; Cadoles la mise en place&nbsp;du&nbsp;mat&eacute;riel<br />\r\n- R&eacute;partition projet de fond Risotto/Factory:<br />\r\n&nbsp; &nbsp; &nbsp;-&nbsp;Risotto: Benjamin/Emmanuel<br />\r\n&nbsp; &nbsp; &nbsp;- Factory: Vincent/Philippe<br />\r\n-&nbsp;Niveau d&#39;avancement&nbsp;estim&eacute;:<br />\r\n&nbsp;&nbsp;&nbsp; - Infra Cadoles: ~30%<br />\r\n&nbsp;&nbsp;&nbsp; - Ensemble Risotto/Factory: ~10%</p>\r\n\r\n<p><strong>Accompagnement administratif</strong><br />\r\n-&nbsp;Arriv&eacute;e de C&eacute;line<br />\r\n-&nbsp;Accompagnement de Mazars<br />\r\n- Cl&ocirc;ture du sujet</p>\r\n\r\n<p><strong>Repas Cadoles</strong><br />\r\n-&nbsp;Standby, attente du d&eacute;confinement<br />\r\n-&nbsp;Proposition after work en visio&nbsp;les&nbsp;vendredi apr&egrave;s midi</p>\r\n\r\n<p><strong>Destructeur de document</strong><br />\r\n-&nbsp;Standby, attente du d&eacute;confinement</p>\r\n\r\n<p><strong>Financement contribution logiciel libre</strong><br />\r\n- Pas de solution identifi&eacute;e &agrave; ce jour&nbsp;r&eacute;pondant au cahier des charges (possibilit&eacute; pour chacun de s&eacute;lectioner des logiciels libres &agrave; supporter)<br />\r\n-&nbsp;Ajouter ce DAD au sujet de l&#39;ordre du jour prochaine AC</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2>Question diverses</h2>\r\n\r\n<p><strong>Quid des tickets restau&nbsp;pendant la p&eacute;riode de d&eacute;confinement&nbsp;?</strong><br />\r\n-&nbsp;Soit envoi par courrier&nbsp;A/R&nbsp;soit attente de la fin du d&eacute;confinement<br />\r\n-&nbsp;Envoi d&#39;un courriel dans interne&nbsp;de Laetitia &agrave; chacun&nbsp;pour demande d&#39;envoi ou attestation d&#39;attente du d&eacute;confinement</p>\r\n\r\n<p><strong>Quid du suivi du temps de travail / baisse de productivit&eacute;</strong><br />\r\n-&nbsp;selon les textes, quand les entreprises permettent le t&eacute;l&eacute;travail, alors l&#39;arr&ecirc;t de travail pour garde d&#39;enfant (&nbsp;<a href=\"https://eazybymazars.zendesk.com/hc/fr/articles/360012582340--COVID-19-RH-PAIE-Ecoles-et-cr%C3%A8ches-ferm%C3%A9es-des-salari%C3%A9s-contraints-de-rester-chez-eux-)\">https://eazybymazars.zendesk.com/hc/fr/articles/360012582340--COVID-19-RH-PAIE-Ecoles-et-cr%C3%A8ches-ferm%C3%A9es-des-salari%C3%A9s-contraints-de-rester-chez-eux-)</a>&nbsp; n&#39;est pas plausible et il est demand&eacute; &agrave; chaque partie (salari&eacute;/entreprise) de faire au mieux dans les r&egrave;gles du t&eacute;l&eacute;travail.</p>\r\n\r\n<p><strong>Comment g&eacute;rer le delta entre le temps de travail effectif / comptabilis&eacute;&nbsp;?</strong><br />\r\n- Tenue d&#39;un compte temps &agrave; rattraper &quot;plus tard&quot;&nbsp;, privil&eacute;gier le best effort, autre solution?<br />\r\n-&nbsp;Point vendredi&nbsp;17/04&nbsp;14h&nbsp;sur Mumble&nbsp;et best effort d&#39;ici l&agrave;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>','2020-04-17 11:28:53',1,0,'uploads/blogarticle/5e9d4b0eaaf7f.jpg'),(13,18,3,'CR de l\'assemblée collective du 12/05/20','<h2>D&eacute;cisions</h2>\r\n\r\n<p><strong>Financement Logiciel Libre</strong><br />\r\nBesoin de temps pour continuer le travail et permettre &agrave; chacun de proposer un projet<br />\r\n<strong>Attribution d&rsquo;une journ&eacute;e de travail </strong>pour avancer sur le sujet &agrave; bbohard</p>\r\n\r\n<p><strong>Indexation des salaires&nbsp;:</strong><br />\r\nHarmoniser les salaires sur le brut horaire avec prise d&rsquo;effet au plus t&ocirc;t<br />\r\n<strong>Adopt&eacute;</strong> &agrave; 8 voix pour, 2 voix contre</p>\r\n\r\n<h2>Groupes de Travail</h2>\r\n\r\n<p><strong>Tableau de bord&nbsp;:</strong><br />\r\nPas d&rsquo;avanc&eacute; pour l&rsquo;instant.<br />\r\nBesoin d&rsquo;organiser une r&eacute;union</p>\r\n\r\n<p><strong>Outils de documentation&nbsp;:</strong><br />\r\nPas d&rsquo;avanc&eacute; pour l&rsquo;instant<br />\r\nBesoin de monter de version de Dokuwiki<br />\r\nafornerot rejoint le groupe de travail<br />\r\nOrganisation d&rsquo;une r&eacute;union</p>\r\n\r\n<p><strong>Dad en ligne&nbsp;:</strong><br />\r\nProjet cr&eacute;&eacute;<br />\r\nPas d&rsquo;avanc&eacute; par manque de temps<br />\r\nEn attente de l&rsquo;arriv&eacute; de Charles pour suivre le d&eacute;veloppement</p>\r\n\r\n<p><strong>Embauches&nbsp;:</strong><br />\r\nArriv&eacute; de C&eacute;line et Maxime le 1er juin<br />\r\nBesoin de d&eacute;signer un coordinateur de l&rsquo;accueil pour les int&eacute;grer &agrave; l&rsquo;entreprise, leur remettre leur poste de travail.<br />\r\nChaque &eacute;quipe doit d&eacute;signer un parrain/coordinateur pour chaque nouveau venu<br />\r\nPrivili&eacute;gier le t&eacute;l&eacute;travail, mais possibilit&eacute; de travailler au bureau sous r&eacute;serve de respecter les r&egrave;gles sanitaires.</p>\r\n\r\n<p><strong>Journ&eacute;e de solidarit&eacute; du 1er juin&nbsp;:</strong><br />\r\nTraditionnellement chacun d&eacute;cide s&rsquo;il d&eacute;cide de travailler ou non, et s&rsquo;il travail, ce n&rsquo;est pas sur du factur&eacute;. Sous forme de Hackaton, chacun peut proposer un sujet de travail.<br />\r\nAccueil des nouveaux arrivant le lendemain, 2 juin<br />\r\nProposition &agrave; envoyer&nbsp;&agrave; wpetit<br />\r\nPropositions actuelle&nbsp;:<br />\r\n- Dad en ligne<br />\r\n- Pr&eacute;sentation de la nouvelle infrastructure</p>\r\n\r\n<p><strong>Outil de suivi&nbsp;:</strong><br />\r\nMigration en cours de Schedule vers Symfony4<br />\r\nBesoin de Php 7.2, donc pour la nouvelle infra</p>\r\n\r\n<p><strong>Risotto/Factory&nbsp;:</strong><br />\r\nEn cours<br />\r\nPr&eacute;sentation au Hackaton</p>\r\n\r\n<p><strong>Nouvelle Infra&nbsp;:</strong><br />\r\nBesoin d&rsquo;acc&egrave;s aux machines physiques</p>\r\n\r\n<p><strong>Repas Cadoles&nbsp;:</strong><br />\r\nEn attente de la reprise de l&rsquo;activit&eacute; normale des restaurants</p>\r\n\r\n<p><strong>Destructeur de Document&nbsp;:</strong><br />\r\nStand by</p>\r\n\r\n<h2>Discussions diverse</h2>\r\n\r\n<p>- Tcornaut a pris son billet de retour &agrave; la m&egrave;re patrie. Retour pr&eacute;vue France le 19 Ao&ucirc;t.</p>\r\n\r\n<p>- Retour au bureau de Philippe et Laetitia de fa&ccedil;on occasionnel.</p>\r\n\r\n<p>- Signature le 15 juin pour le nouveau local. Besoin de devis pour les travaux. Il est necessaire de d&eacute;finir un budget et de d&eacute;signer un groupe de travail.</p>','2020-05-13 09:00:14',1,0,'uploads/blogarticle/5ebb9af9e9f59.jpeg'),(14,18,3,'CR de l\'assemblée collective du 16/06/20','<h1>D&eacute;cisions</h1>\r\n\r\n<p><strong>Financement logiciel libre&nbsp;:</strong><br />\r\nDes propositions ont &eacute;t&eacute; faites. En cours de constitution du DAD.</p>\r\n\r\n<p><strong>D&eacute;finition du budget pour les travaux des nouveau locaux&nbsp;:</strong><br />\r\nPilotage des travaux indispensables par un groupe de travail en suivant un budget de 70000 &euro;, et 20000&euro; pour travaux en accord avec le syndic.<br />\r\n<strong>Adopt&eacute;</strong> &agrave; l&rsquo;unanimit&eacute;<br />\r\nConstitution par la suite d&rsquo;un groupe de travail pour l&rsquo;am&eacute;nagement et la d&eacute;coration des locaux.</p>\r\n\r\n<h1>Groupes de travail</h1>\r\n\r\n<p><strong>Tableau de bord&nbsp;:</strong><br />\r\nBesoin d&rsquo;indicateur (co&ucirc;t journalier par salari&eacute;, le chiffre d&rsquo;affaire r&eacute;parti et l&rsquo;EBE) et d&rsquo;un pr&eacute;visionnel. Deux propositions ont &eacute;t&eacute; faites par Mazars (cf mail Contact du 16 juin&nbsp;14:14)<br />\r\nLa mise en place de la premi&egrave;re proposition devra &ecirc;tre mise en place, sous r&eacute;serve de donner les informations demand&eacute;s.</p>\r\n\r\n<p><strong>Outils de documentation&nbsp;:</strong><br />\r\nProposition d&rsquo;une organisation documentaire par type et par outil pour une meilleure gestion documentaire. <a href=\"https://pad.cadol.es/p/outil_documentation\">https://pad.cadol.es/p/outil_documentation</a><br />\r\nUn DAD sera pr&eacute;sent&eacute; par la suite pour valider la proposition et la mise en place des actions.</p>\r\n\r\n<p><strong>Daddy&nbsp;:</strong><br />\r\nLa structure du projet est en place. D&eacute;marrage du d&eacute;veloppement.</p>\r\n\r\n<p><strong>Outil de suivi&nbsp;:</strong><br />\r\nMigration de schedule vers symfony4 termin&eacute; et testable. Mlamalle rejoins le groupe de travail.</p>\r\n\r\n<p><strong>Risotto Factory&nbsp;:</strong><br />\r\nPr&eacute;sentation r&eacute;alis&eacute; au dernier hackathon. Besoin de d&eacute;terminer l&rsquo;objectif strat&eacute;gique de ce projet.</p>\r\n\r\n<p><strong>Nouvelle Infra&nbsp;:</strong><br />\r\nL&rsquo;avancement a &eacute;t&eacute; retard&eacute; &agrave; cause du confinement. Bonne avanc&eacute;e du projet. 5 services disponibles. Mise en place pr&eacute;vue pour l&rsquo;&eacute;t&eacute;.</p>\r\n\r\n<p><strong>Repas Cadoles&nbsp;:</strong><br />\r\nTransformation en inauguration des nouveaux locaux.</p>\r\n\r\n<h1>Discussions diverses</h1>\r\n\r\n<p>Nous sommes officiellement propri&eacute;taire des nouveau locaux Le Major.<br />\r\nIl serait possible d&rsquo;investir une partie des nouveaux bureaux afin de respecter les normes d&rsquo;hygi&egrave;ne et de s&eacute;curit&eacute;. Organisation d&rsquo;une visiste pour r&eacute;partition. Philippe propose sa camionette pour d&eacute;m&eacute;nager quelques meubles.<br />\r\n&nbsp;</p>\r\n\r\n<p>Le march&eacute; Eole arrive &agrave; sa fin. La r&eacute;ponse sera &agrave; faire courant de l&rsquo;&eacute;t&eacute; (mi-juillet). M&ecirc;me march&eacute; que le pr&eacute;c&eacute;dant avec possibilit&eacute; de travailler depuis nos locaux.</p>\r\n\r\n<p>Constitution d&rsquo;un groupe de travail pour &eacute;tudier le projet sur Arcad/Location de bornes.</p>\r\n\r\n<p>Le projet Envole reste toujours dans l&rsquo;incertitude.<br />\r\n<br />\r\n&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>','2020-06-17 09:36:39',1,0,'uploads/blogarticle/5ee9c8058b992.jpg'),(15,6,5,'Blog Cadoles','<p>Pour parler de Cadoles voici un blog o&ugrave; tout le monde peut s&#39;exprimer et parler de la pluie et du beau temps.</p>\r\n\r\n<p>Vous souhaitez vous exprimer, rien de plus simple, ajouter un article sur ce blog et il sera diffus&eacute; &agrave; tout le monde.</p>','2020-07-08 10:09:24',1,0,'uploads/blogarticle/5f057f2edea4b.jpg'),(16,18,3,'CR de l\'assemblée collective du 09/07/20','<h1>D&eacute;cisions</h1>\r\n\r\n<p><strong>R&eacute;partition dans les bureaux</strong><br />\r\nComme convenu lors de la visite g&eacute;n&eacute;rale des locaux<br />\r\nAccept&eacute; &agrave; l&rsquo;unanimit&eacute;</p>\r\n\r\n<p><strong>Fermeture de la cuisine</strong><br />\r\nCloison avec des stores et ajout d&rsquo;une porte vitr&eacute; fum&eacute;e, afin de pouvoir garder une certaine discr&eacute;tion.<br />\r\nAdopt&eacute; &agrave; 12 voix pour et 1 abstention.<br />\r\n<br />\r\n<strong>Changement d&#39;&eacute;clairage</strong><br />\r\nDemander un devis &agrave; l&#39;&eacute;lectricien un devis compl&eacute;mentaire pour changer l&#39;&eacute;clairage n&eacute;on.</p>\r\n\r\n<h1>Discussions diverses</h1>\r\n\r\n<p><strong>Cloison de l&rsquo;entr&eacute;e.</strong><br />\r\nUne id&eacute;e &agrave; &eacute;t&eacute; &eacute;mise de supprimer la cloison et la porte du palier afin d&rsquo;ouvrir l&rsquo;espace de l&rsquo;entr&eacute;e.<br />\r\nAjouter une grille afin de s&eacute;curiser l&rsquo;entr&eacute;e.</p>\r\n\r\n<p><strong>Eclairage.</strong><br />\r\nProposition de changement de l&rsquo;&eacute;clairage par des n&eacute;ons.<br />\r\nApr&egrave;s consultation, d&eacute;cision de demander un devis compl&eacute;mentaire &agrave; l&rsquo;&eacute;lectricien.</p>\r\n\r\n<p><strong>R&eacute;prise progressive de l&rsquo;activit&eacute; au bureau.</strong><br />\r\nUne reprise progressive de l&rsquo;activit&eacute; de travail au bureau r&eacute;partie entre les deux bureaux serait envisageable. Le t&eacute;l&eacute;travail devrait &ecirc;tre r&eacute;duit et devenir minoritaire. La proc&eacute;dure d&rsquo;inscription &agrave; la pr&eacute;sence dans les bureaux est maintenu, mais pourra &ecirc;tre all&eacute;g&eacute;e &agrave; l&rsquo;avenir avec la pratique.</p>','2020-07-09 11:10:20',1,0,'uploads/blogarticle/5f06df97b430f.jpg'),(17,18,4,'Compte-rendu du projet Mallette pédagogique MJC de Chenôve','<h2>R&eacute;f&eacute;rence du projet</h2>\r\n\r\n<p>Le projet ne dispose pas d&rsquo;une r&eacute;f&eacute;rence unique et transverse. Le code client dans Dolibarr est le MJCCH000100220, la proposition commerciale le PR2002-0786.</p>\r\n\r\n<h2>Objectifs</h2>\r\n\r\n<h3>Objectifs commerciaux</h3>\r\n\r\n<p>La MJC de Chen&ocirc;ve souhaite disposer d&rsquo;un ensemble d&rsquo;&eacute;quipements num&eacute;riques permettant des s&eacute;ances de travail bas&eacute;es sur le partage de ressources et les applications en r&eacute;seau local (jeux notamment). On distingue un &eacute;quipement d&eacute;di&eacute; &agrave; l&rsquo;animateur des s&eacute;ances.</p>\r\n\r\n<h3>Objectifs internes</h3>\r\n\r\n<p>Le projet met en &oelig;uvre de la gestion d&rsquo;identit&eacute; et de permissions, de la maintenance et du partage de ressources centralis&eacute;es. Il se pr&ecirc;te bien &agrave; l&rsquo;&eacute;valuation de la solution&nbsp;<em>freeipa</em>, notamment de la mise en pratique des solutions de&nbsp;<em>SSO</em>.</p>\r\n\r\n<h2>Pr&eacute;visionnel</h2>\r\n\r\n<h3>Calendrier</h3>\r\n\r\n<p>La date d&rsquo;&eacute;ch&eacute;ance est fix&eacute;e &agrave; la mi-mai. Le devis est &eacute;tabli pour 7,5 jours d&rsquo;ing&eacute;nieur syst&egrave;me et 3 jours de d&eacute;veloppement standard.</p>\r\n\r\n<h3>Intervenants</h3>\r\n\r\n<p>Les intervenants pr&eacute;vus sont Matthieu Lamalle, pour le d&eacute;veloppement, et Benjamin Bohard, pour l&rsquo;ing&eacute;nierie syst&egrave;me.</p>\r\n\r\n<h2>Ex&eacute;cution</h2>\r\n\r\n<h3>Calendrier</h3>\r\n\r\n<p><a href=\"https://schedule.cadoles.com/schedule/index.php?app=schedule&amp;view=schedule/report.php&amp;service=&amp;user=all&amp;project=92&amp;month=3\" rel=\"nofollow\">https://schedule.cadoles.com/schedule/index.php?app=schedule&amp;view=schedule/report.php&amp;service=&amp;user=all&amp;project=92&amp;month=3</a>&nbsp;Le projet a donn&eacute; lieu &agrave; un d&eacute;passement important : 29 jours au lieu de 10,5. Le d&eacute;passement &eacute;tait attendu du fait du souhait de profiter de ce projet pour une mont&eacute;e en comp&eacute;tence sur la solution&nbsp;<em>freeipa</em>. Son ampleur n&rsquo;est cependant pas raisonnable.</p>\r\n\r\n<h3>Intervenants</h3>\r\n\r\n<p>En plus des intervenants pr&eacute;vus, Philippe Caseiro est intervenu pour l&rsquo;installation des postes t&eacute;moins, la proc&eacute;dure d&rsquo;installation et l&rsquo;int&eacute;gration de&nbsp;<em>freeipa</em>.</p>\r\n\r\n<h3>Journal</h3>\r\n\r\n<p>Ce journal est &eacute;crit a posteriori et, en l&rsquo;absence de notes prises sur le moment, seulement indicatif. La premi&egrave;re &eacute;tape a port&eacute; sur le d&eacute;veloppement pr&eacute;liminaire de l&rsquo;application de gestion des utilisateurs et groupes, ainsi que sur l&rsquo;int&eacute;gration initiale de&nbsp;<em>freeipa</em>&nbsp;sur Ubuntu 20.04 La seconde &eacute;tape &agrave; consist&eacute; a mettre en place les services (partage de ressources sous la forme de partages NFS et d&rsquo;un wiki). Les principales difficult&eacute;s et sources de d&eacute;passement ont &eacute;t&eacute; :</p>\r\n\r\n<ul>\r\n	<li>l&rsquo;int&eacute;gration de&nbsp;<em>freeipa</em>&nbsp;sur Ubuntu 20.04, la solution ne pouvant pas &ecirc;tre install&eacute;e directement (la solution retenue d&rsquo;un conteneur docker n&rsquo;&eacute;tait pas celle envisag&eacute;e au d&eacute;part)&nbsp;;</li>\r\n	<li>le travail confin&eacute; sur des maquettes individuelles, sur les m&ecirc;mes sujets (avec des r&eacute;sultats et conclusions diff&eacute;rents qui plus est)&nbsp;;</li>\r\n	<li>la ma&icirc;trise tr&egrave;s partielle des m&eacute;canismes de&nbsp;<em>SSO</em>&nbsp;avec _kerberos_&nbsp;;</li>\r\n</ul>\r\n\r\n<p>les revirements de choix d&rsquo;impl&eacute;mentation des partages et r&eacute;pertoires personnels.</p>\r\n\r\n<h2>Bilan</h2>\r\n\r\n<h3>Bilan commercial</h3>\r\n\r\n<h4>Recette</h4>\r\n\r\n<p>Le client s&rsquo;est montr&eacute; satisfait de ce qui lui a &eacute;t&eacute; pr&eacute;sent&eacute;, &eacute;tant donn&eacute; que seul l&rsquo;usage de la solution lui permettra de se forger un avis plus d&eacute;finitif.</p>\r\n\r\n<h4>Bilan comptable</h4>\r\n\r\n<p>Avec un d&eacute;passement de presque 200 %, le bilan comptable de ce projet est mauvais.</p>\r\n\r\n<h3>Bilan interne</h3>\r\n\r\n<p>L&rsquo;objectif principal de prise en main de&nbsp;<em>freeipa</em>&nbsp;est mitig&eacute;. D&rsquo;un c&ocirc;t&eacute;, nous avons pu constater que la solution est compl&egrave;te pour la mise en place d&rsquo;une infrastructure client serveur avec l&rsquo;&eacute;l&eacute;ment cl&eacute; d&rsquo;authentification centralis&eacute;e utilisable pour une grande vari&eacute;t&eacute; de services :</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>ouverture de session</p>\r\n	</li>\r\n	<li>\r\n	<p>connexion aux applications</p>\r\n	</li>\r\n	<li>\r\n	<p>montage de ressources du r&eacute;seau</p>\r\n	</li>\r\n</ul>\r\n\r\n<p>Nous ne ma&icirc;trisons pas la connexion aux applications web. L&rsquo;essai sur&nbsp;<em>dokuwiki</em>&nbsp;n&rsquo;est pas concluant pour la mise en place du&nbsp;<em>SSO</em>, quoique l&rsquo;application&nbsp;<em>freeipa</em>&nbsp;elle-m&ecirc;me prouve que le concept est fonctionnel.</p>\r\n\r\n<p>Sur le plan de l&rsquo;industrialisation, celle-ci n&rsquo;a pas pu &ecirc;tre compl&eacute;t&eacute;e, tous les probl&egrave;mes &agrave; r&eacute;soudre n&rsquo;ayant pas &eacute;t&eacute; identifi&eacute;s suffisamment t&ocirc;t.</p>\r\n\r\n<blockquote>\r\n<p>[name=bbohard] a posteriori, je pense que l&rsquo;industrialisation a &eacute;t&eacute; envisag&eacute;e trop t&ocirc;t alors qu&rsquo;elle n&rsquo;&eacute;tait pas prioritaire tant dans les objectifs du client (deux postes seulement dans cette premi&egrave;re it&eacute;ration du projet) que dans les objectifs internes. Par ailleurs, une mauvaise utilisation de la forge pour les t&acirc;ches (visibilit&eacute; sur les objectifs et le reste &agrave; faire) et la mauvaise coordination (travail en parall&egrave;le sur les m&ecirc;mes sujets) ont &eacute;t&eacute; pr&eacute;judiciable &agrave; la tenue des d&eacute;lais.</p>\r\n</blockquote>\r\n\r\n<h2>Annexes</h2>\r\n\r\n<p>Le d&eacute;p&ocirc;t du projet contient les informations techniques dans le fichier README.md plac&eacute; &agrave; la racine.</p>','2020-07-09 11:15:45',1,1,'uploads/blogarticle/5f06e03d1ee11.jpeg'),(18,18,3,'CR de l\'assemblée collective du 21/07/20','<p>Procuration de Benjamin pour le vote d&rsquo;Emmanuel</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h1>D&eacute;cisions</h1>\r\n\r\n<p><strong>Processus de recrutement</strong><br />\r\nR&eacute;sultat de travail fourni par le groupe de travail<br />\r\nFusion de la PR <a href=\"https://forge.cadoles.com/Cadoles/scop-cadoles/pulls/14\">https://forge.cadoles.com/Cadoles/scop-cadoles/pulls/14</a><br />\r\n<strong>Adopt&eacute;</strong> &agrave; l&rsquo;unanimit&eacute;</p>\r\n\r\n<p><strong>Tableau de bord</strong><br />\r\nTableau de bord avec actualisation trimestriel.<br />\r\n<strong>Adopt&eacute;</strong> &agrave; 10 voix pour et 2 abstentions</p>\r\n\r\n<p><strong>Outil documentation</strong><br />\r\nNouvelle organisation des ressources documentaires<br />\r\n<strong>Adopt&eacute;</strong> &agrave; 11 voix pour et 1 abstention<br />\r\nContinuit&eacute; des actions par de travail.</p>\r\n\r\n<h1>Groupes de travail</h1>\r\n\r\n<p><strong>Outil documentation&nbsp;:</strong> Continuit&eacute; des actions. Migration du dokuwiki vers un nouveau wiki &agrave; pr&eacute;voir pour la suite</p>\r\n\r\n<p><strong>T&eacute;l&eacute;travail</strong>&nbsp;: Reprise du groupe du travail pour remettre &agrave; plat la PR et finaliser le travail.</p>\r\n\r\n<p><strong>Am&eacute;nagement des bureaux&nbsp;:</strong> Travaux en cours, remplacement des &eacute;clairages par des &eacute;clairages leds. En attente d&rsquo;un deuxi&egrave;me devis pour les cloisons.</p>\r\n\r\n<p><strong>Daddy</strong>&nbsp;: D&eacute;veloppement en cours. Pas de fonctionnalit&eacute;s majeures &agrave; pr&eacute;senter pour le moment.</p>\r\n\r\n<p><strong>Outil de suivi</strong>&nbsp;: En attente de la nouvelle infra pour d&eacute;ployer la nouvelle version. Nouvelle infra disponible au mieux d&eacute;but septembre.</p>\r\n\r\n<p><strong>Risotto/Factory</strong>&nbsp;: Plus qu&#39;un&nbsp;seul projet Risotto. D&eacute;veloppement toujours en cours.</p>\r\n\r\n<p><strong>Repas de fin d&rsquo;ann&eacute;e</strong>&nbsp;: Sondage en cours pour trouver une date. Poursuite prochaine pour organiser l&rsquo;&eacute;v&eacute;nement notamment avec le traiteur.</p>\r\n\r\n<p><strong>Inauguration</strong>&nbsp;: Pr&eacute;voir une inauguration avec nos clients courant 2020. Sujet &agrave; reprendre plus tard quand la situation le permettra.</p>\r\n\r\n<p><strong>Financement logiciel libre</strong>&nbsp;: Pas d&rsquo;avanc&eacute; sur le sujet</p>\r\n\r\n<p><strong>Arcad/location</strong>&nbsp;: en stand by</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h1>Discussion diverses</h1>\r\n\r\n<p>Le groupe de travail cybers&eacute;curit&eacute; organise sa prochaine r&eacute;union en septembre. Pas de repr&eacute;sentation assur&eacute;e pour les deux pr&eacute;c&eacute;dentes r&eacute;union qui se sont tenues &agrave; distance via l&rsquo;outil Microsoft Teams.</p>\r\n\r\n<p>Retour au bureau&nbsp;: Les bureaux sont ouverts, pr&ecirc;t &agrave;&nbsp;accueillir les collaborateurs. N&eacute;cessit&eacute; de s&rsquo;inscrire au pr&eacute;alable</p>\r\n\r\n<p>Toolib&nbsp;: R&eacute;ception d&rsquo;un mail de toolib. Pas de position ferme de l&rsquo;&eacute;quipe sur la suite &agrave; donner. Attente d&rsquo;une r&eacute;union de l&rsquo;&eacute;quipe de d&eacute;veloppement.</p>\r\n\r\n<p>Besoin d&rsquo;int&eacute;grer au suivi de temps la comptabilisation des astreintes actives et des d&eacute;placements.</p>\r\n\r\n<p>C&eacute;line et Benjamin B. commencent le travail sur Qualiopi.</p>\r\n\r\n<p>Teddy s&rsquo;est vu accord&eacute; 4 semaines de cong&eacute;s cons&eacute;cutives suite &agrave; la situation exectionnelle.</p>','2020-07-22 09:26:23',1,0,'uploads/blogarticle/5f1ecd196e8a6.jpg'),(19,41,3,'CR de l’Assemblée Collective du 15/09/20','<p><span style=\"font-size:12px\">Excus&eacute;e&nbsp;: Laetitia (pouvoir C&eacute;line pour les 2 DAD)</span></p>\r\n\r\n<p><span style=\"font-size:12px\">Pr&eacute;sents&nbsp;: tous les autres + Yohan Recchia de chez Mazars</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h1><span style=\"font-size:16px\"><span style=\"color:#078eb5\"><strong>DAD pr&eacute;sent&eacute;s :</strong></span></span></h1>\r\n\r\n<h2><span style=\"font-size:14px\"><span style=\"color:#078eb5\"><strong>DAD Achat de terminaux pour le d&eacute;veloppement port&eacute; par William</strong></span></span></h2>\r\n\r\n<p><span style=\"font-size:12px\">Achat de 2 terminaux (android + apple mini) = adopt&eacute; &agrave; l&rsquo;unanimit&eacute;</span></p>\r\n\r\n<p><span style=\"font-size:12px\">Plus globalement il serait int&eacute;ressant de cr&eacute;er un groupe de r&eacute;flexion sur la gestion des ressources chez Cadoles = groupe non constitu&eacute; en s&eacute;ance.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><span style=\"font-size:14px\"><span style=\"color:#078eb5\"><strong>DAD Qualiopi port&eacute; par BB et CR</strong></span></span></h2>\r\n\r\n<p><strong><span style=\"font-size:12px\">Propositions &eacute;cart&eacute;es&nbsp;:</span></strong></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:12px\">Se faire certifier sur T4/2020 pour b&eacute;n&eacute;ficier d&rsquo;une valid&eacute; de 4ans de la 1er certif = ne semble pas r&eacute;aliste = NON &agrave; l&rsquo;unanimit&eacute;</span></li>\r\n	<li><span style=\"font-size:12px\">Certif sans accompagnement&nbsp;: semble trop complexe &agrave; mettre en place sans accompagnement</span></li>\r\n</ul>\r\n\r\n<p><strong><span style=\"font-size:12px\">Proposition &agrave; soumettre &agrave; la prochaine AC&nbsp;:</span></strong></p>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:12px\">Mise en place co-traitance&nbsp;: il est demand&eacute; aux porteurs du projet d&rsquo;&eacute;valuer la possibilit&eacute; de mise en place d&rsquo;une co-traitance pour les formations</span></li>\r\n	<li><span style=\"font-size:12px\">Certification avec accompagnement sur 2021</span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:12px\">PC/VF et EG sont volontaire pour aider CR et BB sur le sujet de la co-traitance.</span></p>\r\n\r\n<h1><span style=\"font-size:16px\"><span style=\"color:#078eb5\"><strong>Groupes de travail&nbsp;: </strong></span></span></h1>\r\n\r\n<h2><span style=\"font-size:14px\"><span style=\"color:#078eb5\"><strong>Am&eacute;nagement des bureaux&nbsp;:</strong></span></span></h2>\r\n\r\n<p><span style=\"font-size:12px\"><strong>Point sur l&rsquo;avancement des travaux (PC)&nbsp;:</strong></span></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><span style=\"font-size:12px\">&eacute;lectricit&eacute; = termin&eacute; (sauf baie de brassage apr&egrave;s peinture)</span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-size:12px\">Clim = termin&eacute;</span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-size:12px\">Peintures = en cours</span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-size:12px\">Sol = livraison des mat&eacute;riaux le 16/09, d&eacute;but de la pose ds la foul&eacute;e</span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-size:12px\">Fermeture cuisine = en cours</span></p>\r\n	</li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:12px\">TC a r&eacute;ceptionn&eacute; les travaux de la Clim, l&rsquo;utilisation est assez simple. Un devis pour un contrat annuel de maintenance de la clim est &agrave; venir. L&rsquo;installateur a d&eacute;tect&eacute; une anomalie sur le tableau &eacute;lectrique = &agrave; voir avec l&rsquo;&eacute;lectricien.</span></p>\r\n\r\n<p><span style=\"font-size:12px\">Les travaux entrepris devraient &ecirc;tre termin&eacute;s derni&egrave;re semaine de septembre.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:12px\"><strong>Point budget (TC)</strong></span></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><span style=\"font-size:12px\">enveloppe travaux + mobilier = 70 000&euro;, avec le devis du mobilier &agrave; 19 000&euro;, il reste entre 2 000 et 3000 &euro; pour la d&eacute;co et le petit &eacute;quipement</span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-size:12px\">enveloppe compl&eacute;mentaire (travaux demandant l&rsquo;accord de la copro) = 20 000&euro;&nbsp;: non engag&eacute;e</span></p>\r\n	</li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:12px\">Le suivi des d&eacute;penses est disponible ici&nbsp;: <a href=\"https://owncloud.cadoles.com/owncloud/index.php/apps/files//?dir=%2FAm%C3%A9nagement_Bureau_Major\" style=\"color:#000080; text-decoration:underline\" target=\"_blank\">https://owncloud.cadoles.com/owncloud/index.php/apps/files//?dir=/Am&eacute;nagement_Bureau_Major</a></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:12px\"><strong>Mobilier de bureau&nbsp;:</strong></span></p>\r\n\r\n<p><span style=\"font-size:12px\">La soci&eacute;t&eacute; APRIME nous a fait une proposition, ce sont les seuls qui ont r&eacute;pondu &agrave; nos sollicitations. TC a compar&eacute; les tarifs avec les prix publics trouv&eacute;s sur internet, les tarifs sont coh&eacute;rents avec la qualit&eacute; et sont m&ecirc;me plus avantageux sur plusieurs r&eacute;f&eacute;rences.</span></p>\r\n\r\n<p><span style=\"font-size:12px\">Le choix s&rsquo;est port&eacute; sur des bureaux avec pi&eacute;tement m&eacute;tallique et plateau bois. (devis et catalogue dans la bo&icirc;te interne)</span></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><span style=\"font-size:12px\">Hauteur standard&nbsp;: AF, BG, CMS, ML, PC, TC</span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-size:12px\">Hauteur r&eacute;glable assis/debout (+30&euro; env.)&nbsp;: BB, CR (L=180), EG, LS, VF, WP, LF (L=180)</span></p>\r\n	</li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:12px\">Am&eacute;nagement&nbsp;: <a href=\"https://owncloud.cadoles.com/owncloud/public.php?service=files&amp;t=6a3c146472159b2fe49f9bc23cd74289\" style=\"color:#000080; text-decoration:underline\" target=\"_blank\">https://owncloud.cadoles.com/owncloud/public.php?service=files&amp;t=6a3c146472159b2fe49f9bc23cd74289</a></span></p>\r\n\r\n<p><span style=\"font-size:12px\">Au vue des d&eacute;lais pour le mobilier,<strong> un emm&eacute;nagement au 15/10 semble envisageable</strong>.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:12px\"><strong>Cloison d&rsquo;entr&eacute;e = remplacement par une grille&nbsp;?</strong></span></p>\r\n\r\n<p><span style=\"font-size:12px\">Pour (si ds le budget)&nbsp;: AF, CR, CMS, ML, PC, VF, TC = 7</span></p>\r\n\r\n<p><span style=\"font-size:12px\">Contre&nbsp;: BB, BG, EG = 3</span></p>\r\n\r\n<p><span style=\"font-size:12px\">Abstention&nbsp;: LF, LS, WP = 3</span></p>\r\n\r\n<p><span style=\"font-size:12px\">Afin d&rsquo;&eacute;viter que la porte des sanitaire ne reste ouverte, il sera &agrave; &eacute;tudier la possibilit&eacute; de mettre un groom. (acc&egrave;s handicap&eacute;?).</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><span style=\"font-size:14px\"><span style=\"color:#078eb5\"><strong>Outils documentation</strong></span></span></h2>\r\n\r\n<p><span style=\"font-size:12px\">Monter un 2&egrave;me wiki en parall&egrave;le pour migrer les donn&eacute;es de l&rsquo;un &agrave; l&rsquo;autre.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><span style=\"font-size:14px\"><span style=\"color:#078eb5\"><strong>T&eacute;l&eacute;travail </strong></span>(TC, LS, LF)&nbsp;:</span></h2>\r\n\r\n<p><span style=\"font-size:12px\">TC&nbsp;: Le groupe n&rsquo;a pas avanc&eacute; sur le sujet</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><span style=\"font-size:14px\"><span style=\"color:#078eb5\"><strong>Daddy</strong></span></span></h2>\r\n\r\n<p><span style=\"font-size:12px\">WP&nbsp;: Tout le monde a acc&egrave;s &agrave; une instance de tests que certains ont d&eacute;j&agrave; commenc&eacute; de tester.</span></p>\r\n\r\n<p><span style=\"font-size:12px\">Le lancement officiel devrait pouvoir avoir lieu &agrave; la prochaine AC.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><span style=\"font-size:14px\"><span style=\"color:#078eb5\"><strong>Nouvelle Infra</strong></span></span></h2>\r\n\r\n<p><span style=\"font-size:12px\">Elle est install&eacute;e et fonctionnelle depuis 2 semaines.</span></p>\r\n\r\n<p><span style=\"font-size:12px\">PC et VF installent les diff&eacute;rents services au fur et &agrave; mesure.</span></p>\r\n\r\n<p><span style=\"font-size:12px\">La mise en place d&eacute;finitive aura lieu d&egrave;s que tout sera suffisamment stable</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#078eb5\">Machines d&eacute;commissionn&eacute;es&nbsp;?</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\">BB souhaite r&eacute;cup&eacute;rer une machine pour effectuer des tests et maquettes.</span></p>\r\n\r\n<p><span style=\"font-size:12px\">PC&nbsp;: cela sera possible, au &ndash; 2 machines seront disponibles</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><span style=\"font-size:14px\"><span style=\"color:#078eb5\"><strong>Schedule </strong></span></span></h2>\r\n\r\n<p><span style=\"font-size:12px\">En attente de la nouvelle infra</span></p>\r\n\r\n<p><span style=\"font-size:12px\">Tests &agrave; faire en double utilisation pendant 1 semaine voire 1 mois.</span></p>\r\n\r\n<p><span style=\"font-size:12px\">AF&nbsp;: Une instance sera mise &agrave; dispo prochainement pour tests.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><span style=\"font-size:14px\"><span style=\"color:#078eb5\"><strong>Projet Risotto</strong></span></span></h2>\r\n\r\n<p><span style=\"font-size:12px\">Travail en cours sur le lien entre Risotto et Factory.</span></p>\r\n\r\n<p><span style=\"font-size:12px\">L&rsquo;equipe CSS se r&eacute;serve du temps chaque semaine pour travailler sur le sujet. (0,5j/pers/sem selon autres projets)</span></p>\r\n\r\n<p><span style=\"font-size:12px\">Vis &agrave; vis d&rsquo;EOLE = pas d&rsquo;int&eacute;r&ecirc;t manifest&eacute; de leur c&ocirc;t&eacute;, peu d&rsquo;espoir de les int&eacute;resser. Cel&agrave; pourrait &ecirc;tre propos&eacute; &agrave; d&rsquo;autres clients comme le CD41.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><span style=\"font-size:14px\"><span style=\"color:#078eb5\"><strong>Repas de fin d&rsquo;ann&eacute;e</strong></span></span></h2>\r\n\r\n<p><span style=\"font-size:12px\">ML va se remettre sur le sujet</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><span style=\"font-size:14px\"><span style=\"color:#078eb5\"><strong>Financement LL</strong></span></span></h2>\r\n\r\n<p><span style=\"font-size:12px\">BB n&rsquo;a pas avanc&eacute;</span></p>\r\n\r\n<p><span style=\"font-size:12px\">CR va caler 1/2j de travail avec BB et PC</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><span style=\"font-size:14px\"><span style=\"color:#078eb5\"><strong>Indicateurs mensuels</strong></span></span></h2>\r\n\r\n<p><span style=\"font-size:12px\">RDV lundi 21/09 avec MAZARS</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h2><span style=\"font-size:14px\"><span style=\"color:#078eb5\"><strong>TOOLIB</strong></span></span></h2>\r\n\r\n<p><span style=\"font-size:12px\">AF et ML les ont rencontr&eacute;s derni&egrave;rement (cf CR dans boite interne)</span></p>\r\n\r\n<p><span style=\"font-size:12px\">AF estime que le CA minimum sur le dernier trimestre 2020 pourrait &ecirc;tre de 12 000&euro; (15j).</span></p>\r\n\r\n<p><span style=\"font-size:12px\"><strong>Continuer la relation avec eux&nbsp;?</strong></span></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><span style=\"font-size:12px\">Pour&nbsp;: WP, TC, ML, LS, CMS, AF, CR, EG = 8</span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-size:12px\">Contre&nbsp;: PC, VF, BG = 3</span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-size:12px\">Abstention&nbsp;: BB, LF = 2</span></p>\r\n	</li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:12px\"><strong>Montant de p&eacute;nalit&eacute; exig&eacute;</strong></span></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><span style=\"font-size:12px\">Exiger la totalit&eacute; (env. 30000&euro;)&nbsp;: BG, CMS, LS, PC, VF, TC, WP = 7</span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-size:12px\">N&eacute;gociation &agrave; la baisse&nbsp;: AF, CR, EG = 3</span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-size:12px\">Abstention&nbsp;: BB, LF, ML = 3</span></p>\r\n	</li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:12px\">L&rsquo;AC donne pouvoir &agrave; ML et AF pour continuer les &eacute;changes avec Toolib et leur faire par de nos d&eacute;cisions.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<h1><span style=\"font-size:16px\"><span style=\"color:#078eb5\"><strong>Questions diverses&nbsp;:</strong></span></span></h1>\r\n\r\n<ul>\r\n	<li>\r\n	<p><span style=\"font-size:12px\"><strong>VF =besoin d&rsquo;une ligne t&eacute;l&eacute;phonique pour CR</strong></span></p>\r\n	</li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:12px\">Pour &agrave; l&rsquo;unanimit&eacute;</span></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><span style=\"font-size:12px\"><strong>CR = Quid des locaux de l&rsquo;Arquebuse &agrave; l&rsquo;avenir&nbsp;?</strong></span></p>\r\n	</li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:12px\">Il est d&eacute;cider la cr&eacute;ation d&rsquo;un groupe de travail afin d&rsquo;&eacute;tudier les diff&eacute;rentes options&nbsp;: vente ou location.</span></p>\r\n\r\n<p><span style=\"font-size:12px\">Groupe constitu&eacute; = PC/CR/VF/Yohan</span></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><span style=\"font-size:12px\"><strong>BB&nbsp;: CR mensuel LE</strong></span></p>\r\n	</li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:12px\">CR va se charger de sa r&eacute;daction et le soumettra qq jours avant les AC mensuelles pour validation en s&eacute;ance.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p style=\"text-align:center\"><span style=\"color:#078eb5\"><span style=\"font-size:large\"><strong>Prochaine AC le 13 octobre.</strong></span></span></p>','2020-09-17 10:55:33',1,0,'uploads/blogarticle/5f632780007fc.jpg'),(20,41,3,'CR de l’Assemblée Collective du 13/10/20','<p>Pr&eacute;sents&nbsp;: tous + Yohan Recchia de chez Mazars</p>\r\n\r\n<p>Excus&eacute;&nbsp;: Teddy (pouvoir donn&eacute; &agrave; William)</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><span style=\"font-size:large\"><strong>DAD</strong></span></span></p>\r\n\r\n<p><span style=\"color:#000000\">Aucun DAD soumis au vote ce jour</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong><span style=\"font-size:large\">Groupes de travail&nbsp;:</span> </strong></span></p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>Daddy&nbsp;: (WP)</strong></span></p>\r\n\r\n<p><span style=\"color:#000000\">William&nbsp;: Une newsletter sera &eacute;mise depuis Daddy tous les lundi &agrave; 9h avec un r&eacute;sum&eacute; de l&rsquo;activit&eacute; sur daddy</span></p>\r\n\r\n<p><span style=\"color:#000000\">Un onglet &laquo;&nbsp;Prendre la d&eacute;cision sera bient&ocirc;t ajout&eacute;&nbsp;&raquo; afin d&rsquo;y consigner le r&eacute;sultat des votes.</span></p>\r\n\r\n<p><span style=\"color:#000000\">Un ticket est ouvert pour la gestion des amendements qui sont parfois faits sur le DAD lors du vote (aujourd&rsquo;hui un DAD soumis au vote est en lecture seule)</span></p>\r\n\r\n<p><span style=\"color:#000000\">Attention un groupe clos ne peut &ecirc;tre r&eacute;ouvert facilement (voir avec William si besoin)</span></p>\r\n\r\n<p><span style=\"color:#000000\">L&rsquo;ajout de PJ sera ajout&eacute; prochainement ainsi que des notifications par e-mail.</span></p>\r\n\r\n<p><span style=\"color:#000000\">La partie &laquo;&nbsp;Conf&eacute;rence&nbsp;&raquo; vient d&rsquo;&ecirc;tre ajout&eacute;e, elle n&rsquo;est pas encore au point mais pourrait &ecirc;tre exploit&eacute;e pour les votes et la prise de parole lors de r&eacute;unions mumble.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>Outils documentation (LS, VF, WP, ML, BG, TC)</strong></span></p>\r\n\r\n<p><span style=\"color:#000000\">Ludwig&nbsp;: Un 2&egrave;me wiki a &eacute;t&eacute; cr&eacute;&eacute; afin de cr&eacute;er l&rsquo;arborescence et de trier les documents/infos.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>Qualiopi (BB, CR, PC)</strong></span></p>\r\n\r\n<p><span style=\"color:#000000\">Le groupe de travail n&rsquo;a pas avanc&eacute;.</span></p>\r\n\r\n<p><span style=\"color:#000000\">Philippe a potentiellement des contacts int&eacute;ress&eacute;s par un partenariat.</span></p>\r\n\r\n<p><span style=\"color:#000000\">=&gt; une r&eacute;union sera organis&eacute;e prochainement entre les membres du groupe pour avancer</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>T&eacute;l&eacute;travail (TC, LS, LF)&nbsp;:</strong></span></p>\r\n\r\n<p><span style=\"color:#000000\">Pas d&rsquo;avanc&eacute;e sur le sujet.</span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>Am&eacute;nagement des bureaux&nbsp;:</strong></span></p>\r\n\r\n<p>PC&nbsp;: Les travaux sont quasiment termin&eacute;s. Il reste une intervention sur la clim (fuite) qui doit &ecirc;tre programm&eacute;e rapidement.</p>\r\n\r\n<p>La d&eacute;coration de chaque bureau sera &agrave; discuter au sein de chaque bureau. (une bande de peinture color&eacute;e par exemple)</p>\r\n\r\n<p>Le mobilier de base (bureaux + am&eacute;nagement salle de r&eacute;union) doivent &ecirc;tre livr&eacute;s le 15/10. (au moins en partie)</p>\r\n\r\n<p>Quelques meubles d&rsquo;appoint ont &eacute;t&eacute; achet&eacute;s. (&eacute;tag&egrave;re table basse pour l&rsquo;entr&eacute;e)</p>\r\n\r\n<p>Fibre&nbsp;: apr&egrave;s incompr&eacute;hensions et al&eacute;as avec Bouygues, le pb semble r&eacute;gl&eacute; (acc&egrave;s &agrave; la config du routeur)</p>\r\n\r\n<p>Les baies de brassage n&rsquo;ont pas encore &eacute;t&eacute; achet&eacute;es.</p>\r\n\r\n<p>Le remplacement de la cloison de l&rsquo;entr&eacute;e par une grille ou autre n&rsquo;a &agrave; ce jour pas &eacute;t&eacute; chiffr&eacute;.</p>\r\n\r\n<p>&Eacute;galement nous attendons un devis pour la modification des sanitaires afin de pouvoir le pr&eacute;senter lors de la prochaine assembl&eacute;e de la COPRO.</p>\r\n\r\n<p>=&gt; relance ERB ou autre prestataire si pas de r&eacute;ponse</p>\r\n\r\n<p>Le suivi des d&eacute;penses est disponible ici&nbsp;:</p>\r\n\r\n<p><a href=\"https://owncloud.cadoles.com/owncloud/index.php/apps/files//?dir=%2FAm%C3%A9nagement_Bureau_Major\" style=\"color:#000080; text-decoration:underline\" target=\"_blank\">https://owncloud.cadoles.com/owncloud/index.php/apps/files//?dir=/Am&eacute;nagement_Bureau_Major</a></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>Nouvelle Infra</strong></span></p>\r\n\r\n<p>Elle est install&eacute;e et fonctionnelle, PC et VF installent les diff&eacute;rents services au fur et &agrave; mesure.</p>\r\n\r\n<p>La mise en place d&eacute;finitive aura lieu d&egrave;s que tout sera suffisamment stable</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>Schedule </strong></span></p>\r\n\r\n<p>La double saisie a permis d&rsquo;effectuer qq corrections. La mise en production devrait pouvoir avoir lieu d&rsquo;ici 10-15jours. Les donn&eacute;es de V1 seront r&eacute;pliqu&eacute;es sur une nouvelle instance de V2. (RAZ de V2)</p>\r\n\r\n<p>Les totaux des rapports sont &agrave; corriger avant la mise en prod.</p>\r\n\r\n<p>=&gt; pr&eacute;voir 0,5j avec PC ou VF + AF ou ML pour mise en prod</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>Projet Risotto</strong></span></p>\r\n\r\n<p>Travail en cours sur le lien entre Risotto et Factory = la m&eacute;thode a &eacute;t&eacute; d&eacute;finie</p>\r\n\r\n<p>Bitwarden sera utilis&eacute; pour la gestion des mots de passe</p>\r\n\r\n<p>Actuellement le projet est financ&eacute; avec les points en extra du projet EOLE</p>\r\n\r\n<p>Avec les commandes EOLE arriv&eacute;es r&eacute;cemment, il sera sans dout difficile d&rsquo;avancer sur le projet sur la fin de l&rsquo;ann&eacute;e</p>\r\n\r\n<p>AF&nbsp;: Faut il s&rsquo;attendre &agrave; des changements sur la m&eacute;thode d&rsquo;industrialisation&nbsp;?</p>\r\n\r\n<p>=&gt; Oui il y a qq diff&eacute;rences, mais l&rsquo;id&eacute;e est d&rsquo;avoir un service par machine virtuelle, simplifier l&rsquo;industrialisation (par rapport &agrave; EOLE)</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>Repas de fin d&rsquo;ann&eacute;e</strong></span></p>\r\n\r\n<p>ML&nbsp;: Les conditions COVID risquent de remettre en cause ce projet</p>\r\n\r\n<p>Contact de la papaye verte pour avoir un devis de prestation.</p>\r\n\r\n<p>Mise en place d&rsquo;un sondage pour avoir un d&eacute;compte des participants.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>Financement LL (BB, PC)</strong></span></p>\r\n\r\n<p>Suite &agrave; une r&eacute;union BB/PC, une nouvelle branche a &eacute;t&eacute; cr&eacute;&eacute;e dans Scoop Cadoles&nbsp;:</p>\r\n\r\n<p>Le lien sur la forge: <a href=\"https://forge.cadoles.com/Cadoles/scop-cadoles/src/branch/feature/DAD-191121093500_retribution_logiciel_libre\" style=\"color:#000080; text-decoration:underline\" target=\"_blank\">https://forge.cadoles.com/Cadoles/scop-cadoles/src/branch/feature/DAD-191121093500_retribution_logiciel_libre</a></p>\r\n\r\n<p>Modifications propos&eacute;es par Benjamin Bohard <a href=\"https://forge.cadoles.com/Cadoles/scop-cadoles/commit/9b5f6fe87458f4ab5e4edb466e346e1c57a85323\" style=\"color:#000080; text-decoration:underline\" target=\"_blank\">https://forge.cadoles.com/Cadoles/scop-cadoles/commit/9b5f6fe87458f4ab5e4edb466e346e1c57a85323</a></p>\r\n\r\n<p>=&gt; Un DAD sera soumis lors de la prochaine AC</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>TOOLIB</strong></span></p>\r\n\r\n<p>Nous n&rsquo;avons eu aucun retour de la part du client depuis le dernier e-mail dans lequel nous mettions comme condition le paiement des indemnit&eacute;s pour continuer le partenariat.</p>\r\n\r\n<p>=&gt; cl&ocirc;ture du groupe, Toolib n&rsquo;est plus consid&eacute;r&eacute; comme un client de Cadoles</p>\r\n\r\n<p>=&gt; poursuite de la proc&eacute;dure de recouvrement (LF + Mazars)</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>Locaux Arquebuse</strong></span></p>\r\n\r\n<p>Le voisin semble tr&egrave;s int&eacute;ress&eacute; par le rachat de nos bureaux.</p>\r\n\r\n<p>=&gt; les membres du groupe vont prendre RDV avec lui pour voir ce qu&rsquo;il propose (valid&eacute; par tour de table)</p>\r\n\r\n<p>L&rsquo;objectif est d&rsquo;avoir un DAD &agrave; soumettre le mois prochain</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>Indicateurs mensuels</strong></span></p>\r\n\r\n<p>La finalisation du bilan est un pr&eacute;alable &agrave; la mise en place des indicateurs.</p>\r\n\r\n<p>Notre comptable se d&eacute;placera ds nos locaux tous les mois.</p>\r\n\r\n<p>Ratio facturable/non facturable &agrave; d&eacute;terminer et &agrave; transmettre &agrave; Mazars =&gt; le groupe de travail doit en rediscuter.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><span style=\"font-size:large\"><strong>Questions diverses&nbsp;:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Destructeur de documents&nbsp;</strong></p>\r\n	</li>\r\n</ul>\r\n\r\n<p>Tous comme la machine &agrave; caf&eacute;, cet achat sera effectu&eacute; dans le cadre de l&rsquo;am&eacute;nagement des bureaux</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Retour au bureau/t&eacute;l&eacute;travail/COVID</strong></p>\r\n	</li>\r\n</ul>\r\n\r\n<p>Un e-mail de la co-g&eacute;rance va &ecirc;tre envoy&eacute; ce jour.</p>\r\n\r\n<p>Au vue de la situation sanitaire, le t&eacute;l&eacute;travail est encourag&eacute;. Il est cependant possible de se rendre dans les bureaux (Arquebuse et Jaures) pour ceux qui le souhaitent.</p>\r\n\r\n<p>Les conditions d&rsquo;inscription et les recommandations sanitaires sont d&eacute;crites dans le courriel.</p>\r\n\r\n<p>Concernant les cl&eacute;s&nbsp;: d&eacute;bat sur l&rsquo;attribution syst&eacute;matique de cl&eacute;s des nouveaux locaux &agrave; tous</p>\r\n\r\n<p>Probl&eacute;matique&nbsp;: il est imp&eacute;ratif de s&eacute;curiser nos donn&eacute;es et notamment notre infra et les infra h&eacute;berg&eacute;es chez nous. Doit-on tous poss&eacute;der les cl&eacute; des bureaux&nbsp;? Faut il uniquement s&eacute;curiser la salle serveur et autres zones sensibles&nbsp;? (norme ANSII)</p>\r\n\r\n<p>=&gt;Ce sujet devra &ecirc;tre abord&eacute; lors de la prochaine AC.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>R&eacute;sultat du Bilan</strong></p>\r\n	</li>\r\n</ul>\r\n\r\n<p>PC alerte sur le fait que nous sommes mi-octobre et que nous n&rsquo;avons aucune id&eacute;e du r&eacute;sultat de l&rsquo;exercice pr&eacute;c&eacute;dent pourtant clos au 30/06/2020, ni aucune id&eacute;e de la situation actuelle.</p>\r\n\r\n<p>Une prise de conscience doit avoir lieu afin de mieux ma&icirc;triser notre orientation.</p>\r\n\r\n<p>Yohan&nbsp;: le Bilan est en cours de finalisation, une perte assez cons&eacute;quente est &agrave; pr&eacute;voir</p>\r\n\r\n<p>L&aelig;titia alerte sur le fait qu&rsquo;il y a eu assez peu de facturation sur les derniers mois.</p>\r\n\r\n<p>L&rsquo;annonce d&rsquo;un r&eacute;sultat n&eacute;gatif a surpris l&rsquo;ensemble des collaborateurs. Une prise de conscience a lieu sur un manque collectif de suivi. Il est n&eacute;cessaire de comprendre et d&rsquo;analyser ce r&eacute;sultat afin de corriger le tir rapidement.</p>\r\n\r\n<p>=&gt; Cr&eacute;ation d&rsquo;un groupe de travail sur l&rsquo;analyse des r&eacute;sultats du bilan (Vincent, William, Philippe, C&eacute;line et Laetitia)</p>\r\n\r\n<p>Emmanuel fait part de son incompr&eacute;hension vis &agrave; vis de ces r&eacute;sultats d&eacute;cevants et de son sentiment de d&eacute;couragement. Le projet EOLE occupe tout son temps (voire plus) et il a le sentiment de ne pas &ecirc;tre assez soutenu sur ce projet.</p>\r\n\r\n<p>=&gt; La co-g&eacute;rance va &eacute;changer avec Emmanuel rapidement</p>\r\n\r\n<p>=&gt; L&rsquo;organisation et la r&eacute;partition des t&acirc;ches au sein de l&rsquo;&eacute;quipe CSS est &agrave; revoir</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><em>Note du 15/10&nbsp;: suite &agrave; r&eacute;ception du bilan, une v&eacute;rification a &eacute;t&eacute; effectu&eacute;e, une partie des en-cours n&rsquo;a pas &eacute;t&eacute; int&eacute;gr&eacute;e dans le projet initial. Apr&egrave;s correction, le r&eacute;sultat sera l&eacute;g&egrave;rement positif.</em></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>CR mensuel LE</strong></p>\r\n	</li>\r\n</ul>\r\n\r\n<p>CR va se charger de sa r&eacute;daction et le soumettra qq jours avant les AC mensuelles pour validation en s&eacute;ance.</p>\r\n\r\n<p>=&gt; sujet non abord&eacute; en s&eacute;ance</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><span style=\"font-size:large\"><strong>Prochaine AC le 1</strong></span></span><span style=\"color:#078eb5\"><span style=\"font-size:large\"><strong>0</strong></span></span><span style=\"color:#078eb5\"><span style=\"font-size:large\"><strong> </strong></span></span><span style=\"color:#078eb5\"><span style=\"font-size:large\"><strong>novembre</strong></span></span><span style=\"color:#078eb5\"><span style=\"font-size:large\"><strong>.</strong></span></span></p>','2020-10-15 15:54:40',1,1,'uploads/blogarticle/5f88538088dc8.jpg'),(21,41,3,'CR de l\'Assemblée Collective du 10/11/2020','<p>Pr&eacute;sents&nbsp;: tous + C&eacute;line Recchia et Nicolas Bourgeois du Cabinet Mazars</p>\r\n\r\n<p>Excus&eacute;&nbsp;: Teddy et Benjamin G. (pas de pouvoir)</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><span style=\"font-size:large\"><strong>DAD</strong></span></span></p>\r\n\r\n<p><span style=\"color:#000000\">Ch&egrave;que cadeau pour Noel, DAD propos&eacute; par Laetitia</span></p>\r\n\r\n<p><span style=\"color:#000000\">Le montant maximum permettant du exon&eacute;ration de charges est de 171&euro; cette ann&eacute;e.</span></p>\r\n\r\n<ul>\r\n	<li>Pas de ch&egrave;que cette ann&eacute;e : X</li>\r\n	<li>Ch&egrave;que Cadhoc uniquement (171&euro;) : X</li>\r\n	<li>Ch&egrave;que Cadhoc d&#39;un autre montant : X</li>\r\n	<li>Ch&egrave;que Cadhoc ou autre enseigne pour 171&euro; : adopt&eacute; par tous les pr&eacute;sents + 2 abstentions pour les 2 absents</li>\r\n</ul>\r\n\r\n<p><strong>Votre choix est &agrave; communiquer &agrave; Laetitia et Vincent au plus t&ocirc;t.</strong></p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong><span style=\"font-size:large\">Pr&eacute;sentation du bilan :</span> </strong></span></p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>Pr&eacute;sentation par Nicolas du Cabinet Mazars (cf support envoy&eacute; par email) :</strong></span></p>\r\n\r\n<ul>\r\n	<li>CA 2019/2020 : 748 361&euro; soit -31% par arpport &agrave; l&#39;ann&eacute;e pr&eacute;c&eacute;dente</li>\r\n	<li>CA 2018/2019 : 1 088 631&euro;</li>\r\n</ul>\r\n\r\n<p>Le choix avait &eacute;t&eacute; fait de baisser l&#39;activit&eacute; sur cet exercice afin de baisser un peu le r&eacute;gime et de prendre du temps pour des projets internes.</p>\r\n\r\n<ul>\r\n	<li>R&eacute;sultat de l&#39;exercice 2019/2020 : 946&euro;</li>\r\n	<li>R&eacute;sultat de l&#39;exercice 2018/2019 : 258 920&euro;</li>\r\n</ul>\r\n\r\n<p>Le r&eacute;sultat de l&#39;exercice, bien que positif est faible.</p>\r\n\r\n<p>Le fond&nbsp; de roulement reste tr&egrave;s bon. La Tr&eacute;sorerie est importante - m&ecirc;me un peu sup&eacute;rieure &agrave; l&#39;ann&eacute;e pass&eacute;e - cel&agrave; est tr&egrave;s rassurant, surtout dans le contexte actuel.</p>\r\n\r\n<p>Les charges de personnel sont inf&eacute;rieure &agrave; l&#39;ann&eacute;e pass&eacute;e, mais cette baisse semble peu importante au regard des d&eacute;parts et de la p&eacute;riode COVID :</p>\r\n\r\n<ul>\r\n	<li>Le ch&ocirc;mage partiel ne repr&eacute;sente que tr&egrave;s peu : environ 800&euro; (a &eacute;t&eacute; refus&eacute; par l&#39;administration dans plusieurs cas, nous avons arr&ecirc;t&eacute; d&#39;en faire la demande dans la mesure au le t&eacute;l&eacute;travail &eacute;tait possible)</li>\r\n	<li>Les primes de rupture conventionnelles sont incluses.</li>\r\n	<li>Le cr&eacute;dit d&#39;imp&ocirc;t comp&eacute;titivit&eacute; emploi a &eacute;t&eacute; arr&ecirc;t&eacute;, sur l&#39;exercice pr&eacute;c&eacute;dent cel&agrave; repr&eacute;sentait 15 000&euro;</li>\r\n</ul>\r\n\r\n<p>Quels seraient les impacts de la vente du local d&#39;un point de vue fianncier ?</p>\r\n\r\n<ul>\r\n	<li>Augmentation de la Tr&eacute;sorerie</li>\r\n	<li>La plus value viendrait s&#39;ajouter comme op&eacute;ration excpetionnelle au r&eacute;sultat (valeur compatble 80 000&euro;, valeur estim&eacute;e par les agences 120 000&euro;)</li>\r\n	<li>Si on ne fait rien du local, le co&ucirc;t serait de 3 500&euro; &agrave; l&#39;ann&eacute;e</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong><span style=\"font-size:large\">Situation &agrave; fin Septembre :</span> </strong></span></p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>Tableau de bord Mazars (cf documents transmis par email) :</strong></span></p>\r\n\r\n<p>Pr&eacute;visionnel : le budget pr&eacute;visionnel a &eacute;t&eacute; construit de telle sorte qu&#39;un r&eacute;sultat de 100 000&euro; soit r&eacute;alis&eacute;. Pour se faire, le chiffre d&#39;affaires devra &ecirc;tre de 900 000&euro;.</p>\r\n\r\n<p>La facturation a &eacute;t&eacute; assez faible sur ce premier trimestre d&#39;exercice, mais cel&agrave; est coh&eacute;rent vis &agrave; vis du fait de la p&eacute;riode estivale.</p>\r\n\r\n<p>EBE = exc&eacute;dent brut d&#39;exploitation</p>\r\n\r\n<p>TDB Culul&eacute; : somme des r&eacute;sultats des diff&eacute;rents tableaux de bord mensuels</p>\r\n\r\n<p>Pr&eacute;vision aterrissage 30/06 selon budget : T1 r&eacute;alis&eacute; + T2, T3, T4 selon ce qui a &eacute;t&eacute; budg&eacute;tis&eacute;</p>\r\n\r\n<p>Pr&eacute;vision aterrissage 30/06 selon r&eacute;el N-1 : T1 r&eacute;alis&eacute; + T2, T3, T4 identiques &agrave; N-1</p>\r\n\r\n<p>d&ucirc; client : factures non r&eacute;gl&eacute;es par les clients</p>\r\n\r\n<p>Les indicateurs jours facturables/pay&eacute;s/taux d&#39;efficience/prix de vente mini et prix de revient ne sont pas disponibles pour le moment. <strong>Un travail en interne, avec la collaboration du Cabinet Mazars est n&eacute;cessaire afin de s&#39;accorder sur la m&eacute;thodologie et les objectifs.</strong></p>\r\n\r\n<p>L&#39;assembl&eacute;e demande au Cabinet Mazars de rajouter une colonne avec les totaux sur 3 mois (moyenne) de l&#39;ann&eacute;e pr&eacute;c&eacute;dente afin de faciliter la comparaison avec le r&eacute;alis&eacute; de cette ann&eacute;e.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>Tableau de suivi interne (cf doc envoy&eacute; par email)</strong></span></p>\r\n\r\n<p>Laetitia, C&eacute;line et Arnaud ont commenc&eacute; &agrave; travailler sur un tableau de suivi de l&#39;activit&eacute; commun. Cel&agrave; devrait permettre d&#39;uniformiser le suivi et de faciliter la r&eacute;colte des informations &agrave; donner au Cabinet Mazars chaque mois.</p>\r\n\r\n<p>Ce tableau est pour le moment stock&eacute; sur Owncloud, un outil de travail collaboratif sera mis en place d&egrave;s que la nouvelle infra sera disponible.</p>\r\n\r\n<p>Ce tableau de suivi sera fourni avant la prochaine AC afin de permettre &agrave; chacun d&#39;en prendre connaissance avant la r&eacute;union.</p>\r\n\r\n<p>Seules les factures d&eacute;j&agrave; r&eacute;alis&eacute;es et les commandes en cours ou quasi certaines ont &eacute;t&eacute; compabilis&eacute;es pour le moment.</p>\r\n\r\n<p>L&#39;objectif est d&#39;avoir une estimation pr&eacute;visionnelle (mensuelle) pour le mois prochain.</p>\r\n\r\n<p><br />\r\n<span style=\"color:#078eb5\"><strong><span style=\"font-size:large\">Coh&eacute;sion d&#39;&eacute;quipe :</span></strong></span><span style=\"color:#078eb5\"><strong> </strong></span></p>\r\n\r\n<p><span style=\"color:#000000\">La cog&eacute;rance souhaite porter une attention particuli&egrave;re sur l&#39;ambiance au travail, la coh&eacute;sion d&#39;&eacute;quipe, le bien-&ecirc;tre des salari&eacute;s et les &eacute;ventuelles difficult&eacute;es de communication pour pourraient subvenir pendant cette p&eacute;riode compliqu&eacute;e.</span></p>\r\n\r\n<p>Le t&eacute;l&eacute;travail ne facilite pas la communication et les &eacute;changes. Il ne faut pas que cel&agrave; nuise &agrave; la coh&eacute;sion des &eacute;quipes.</p>\r\n\r\n<p>La boite e-mail gerant@cadoles.com a &eacute;t&eacute; r&eacute;activ&eacute;e et doit &ecirc;tre utilis&eacute;e pour faire part &agrave; la co-g&eacute;rance de toute difficult&eacute;e.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong><span style=\"font-size:large\">Groupes de travail</span></strong></span></p>\r\n\r\n<p>Du fait du temps pris par la pr&eacute;sentation du bilan, il n&#39;est pas fait de tour d&#39;&eacute;tat des lieux d&eacute;taill&eacute; de l&#39;avanc&eacute;e de chaque groupe de travail.</p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>T&eacute;l&eacute;travail (TC, LS, LF)&nbsp;:</strong></span></p>\r\n\r\n<p><span style=\"color:#000000\">Ludwig a fait parvenir &agrave; chacun un questionnaire afin d&#39;avancer sur le sujet. Merci d&#39;y r&eacute;pondre afin qu&#39;une d&eacute;cision puisse &ecirc;tre prise le mois prochain.</span></p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>Am&eacute;nagement des bureaux&nbsp;:</strong></span></p>\r\n\r\n<p>Le mobilier a &eacute;t&eacute; livr&eacute;!</p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>Nouvelle Infra</strong></span></p>\r\n\r\n<p>La fin de l&#39;ann&eacute;e est charg&eacute;e, il va &ecirc;tre difficile d&#39;avancer aussi vite que voulu.</p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>Schedule </strong></span></p>\r\n\r\n<p>Les pbs majeurs ont &eacute;t&eacute; r&eacute;gl&eacute;s, le d&eacute;ploiement de la V2 peut &ecirc;tre planifi&eacute;.</p>\r\n\r\n<p><strong>Arnaud va proposer une date &agrave; Vincent et Philippe.</strong></p>\r\n\r\n<p><span style=\"color:#078eb5\"><strong>Locaux Arquebuse</strong></span></p>\r\n\r\n<p>Notre voisin a confirm&eacute; son int&eacute;r&ecirc;t pour l&#39;achat de notre local. Le RDV pr&eacute;vu n&#39;a pu avoir lieu, <strong>C&eacute;line va lui proposer une visio + une visite un jour ou Laetitia est au bureau</strong>.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><span style=\"font-size:large\"><strong>Questions diverses&nbsp;:</strong></span></span></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Retour au bureau/t&eacute;l&eacute;travail/COVID</strong></p>\r\n	</li>\r\n</ul>\r\n\r\n<p>Le t&eacute;l&eacute;travail doit &ecirc;tre prioris&eacute;. Si pour des besoins ponctuels et exceptionnels il est n&eacute;cessaire pour certains d&#39;aller au bureau, cel&agrave; reste possible sous r&eacute;serve de validation par la co-g&eacute;rance.</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Ressources c&ocirc;t&eacute; DEV</strong></p>\r\n	</li>\r\n</ul>\r\n\r\n<p>La situation est assez tendue c&ocirc;t&eacute; dev, 2 arr&ecirc;ts maladie en cours, il y a un risque de ne pas pouvoir assumer toutes les t&acirc;ches de fin d&#39;ann&eacute;e.</p>\r\n\r\n<p>Il est n&eacute;cessaire de mettre &agrave; plat les besoins en ressources des 2 &eacute;quipes afin de voir comment r&eacute;partir la charge au mieux.</p>\r\n\r\n<p><strong>C&eacute;line et Arnaud vont faire un pr&eacute;visionnel sur d&eacute;cembre/janvier.</strong></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>March&eacute; EOLE 2020</strong></p>\r\n	</li>\r\n</ul>\r\n\r\n<p>Le nouveau march&eacute; EOLE a &eacute;t&eacute; publi&eacute;, la r&eacute;ponse doit &ecirc;tre faite avant le 30/11.</p>\r\n\r\n<p>Emmanuel confirme qu&#39;il est assez similaire au pr&eacute;c&eacute;dent. Il y a cependant des comp&eacute;tences particuli&egrave;res qu&#39;il conviendra de voir avec l&#39;&eacute;quipe de Dev.</p>\r\n\r\n<ul>\r\n	<li><strong>Projets EFS</strong></li>\r\n</ul>\r\n\r\n<p>Les projets avec l&#39;EFS sont en bonne voie, mais nous ne connaissons pas leur vision en terme de planning et il est tr&egrave;s difficile de pr&eacute;voir les besoins en ressources qui risquent d&#39;&ecirc;tre importants avec des temps de mont&eacute;e en comp&eacute;tence non n&eacute;gligeables.</p>\r\n\r\n<p>Arnaud et son &eacute;quipe souhaitent un investissement global de Cadoles pour r&eacute;pondre &agrave; ce projet transverse.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#078eb5\"><span style=\"font-size:large\"><strong>Prochaine AC le </strong></span></span><span style=\"color:#078eb5\"><span style=\"font-size:large\"><strong>mardi 15 </strong></span></span><span style=\"color:#078eb5\"><span style=\"font-size:large\"><strong>d&eacute;cembre</strong></span></span><span style=\"color:#078eb5\"><span style=\"font-size:large\"><strong>.</strong></span></span></p>\r\n\r\n<p>&nbsp;</p>','2020-11-12 10:42:17',1,1,'uploads/blogarticle/5fad11607cb79.jpg'),(22,41,3,'CR de l\'Assemblée Collective du 15/12/2020','<p>Pr&eacute;sents&nbsp;: tous + C&eacute;line Recchia du Cabinet Mazars</p>\r\n\r\n<p>Excus&eacute;s&nbsp;: Ludwig et Benjamin G. (pas de pouvoir)</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>La co-g&eacute;rance propose que la sc&eacute;ance soit enregistr&eacute;e et soumet cette proposition au vote&nbsp;:</p>\r\n\r\n<p>&rarr; 1 refus, la s&eacute;ance ne sera donc pas enregistr&eacute;e.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Tableau de suivi interne</span></span></strong></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Pr&eacute;sent&eacute; par C&eacute;line R</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Deux documents pdf ont &eacute;t&eacute; transmis en fin de matin&eacute;e sur <a href=\"mailto:interne@cadoles.com\" style=\"color:#000080; text-decoration:underline\">interne@cadoles.com</a></span></span></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Total factur&eacute; &agrave; date&nbsp;: 486 375&euro; dont 68 820&euro; factur&eacute; d&rsquo;avance.</span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Commandes en cours &nbsp;: 72 800&euro;</span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Cumul devis &agrave; l&rsquo;&eacute;tude (pond&eacute;r&eacute;)&nbsp;: 328 067&euro;</span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Pr&eacute;visionnel fin exercice&nbsp;: 887 242&euro;</span></span></p>\r\n	</li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">On peut &eacute;galement esp&eacute;rer des commandes c&ocirc;t&eacute; CD41 et ENVOLE pour un montant optimiste de 59 600&euro;, ce qui porterait le pr&eacute;visionnel fin d&rsquo;exercice &agrave; 946 842&euro;.</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ, il est vou&eacute; &agrave; &eacute;voluer notamment du fait des incertitudes li&eacute;es &agrave; l&rsquo;AO EOLE et aux d&eacute;lais de prise de d&eacute;cisions de l&rsquo;EFS.</span></span></p>\r\n\r\n<p><br />\r\n<span style=\"font-size:12px\"><strong><span style=\"color:#000000\">Remarques suite &agrave; cette pr&eacute;sentation&nbsp;:</span></strong></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Il serait int&eacute;ressant d&rsquo;ajouter l&rsquo;objectif d&rsquo;&eacute;quilibre dans les tableaux.</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">&Eacute;galement une projection graphique dans le temps permettant de visualiser l&rsquo;atteinte du point d&rsquo;&eacute;quilibre pourrait &ecirc;tre int&eacute;ressante.</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Philippe pose la question de l&rsquo;utilit&eacute; du tableau de bord de Mazars au regard des informations fournies dans ces tableaux internes&nbsp;:</span></span></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><span style=\"font-size:12px\"><span style=\"color:#000000\">permet de confronter nos chiffres &agrave; la r&eacute;alit&eacute; comptable</span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-size:12px\"><span style=\"color:#000000\">les pr&eacute;visions du tableau de suivi interne sont des pr&eacute;visions commerciales, les pr&eacute;visions Mazars sont bas&eacute;es sur la r&eacute;alit&eacute; N-1.</span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-size:12px\"><span style=\"color:#000000\">La situation trimestrielle de Mazars permet de voir l&rsquo;&eacute;volution r&eacute;elle des charges</span></span></p>\r\n	</li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Nous nous sommes engag&eacute;s sur 12 mois, il serait utile de se reposer la question l&rsquo;issue de cet engagement, apr&egrave;s une ann&eacute;e de recul de suivi de nos indicateurs en interne et de la validation de leur fiabilit&eacute;. Un objectif de CA &agrave; 900 000&euro; a &eacute;t&eacute; consid&eacute;r&eacute; de mani&egrave;re arbitraire, il est &agrave; valider par tous. (&agrave; l&rsquo;odj de la prochaine AC.</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Selon la Charte SCOP Cadoles, c&rsquo;est &agrave; l&rsquo;AC de valider les budgets. Charge &agrave; un groupe de travail de faire des propositions.</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Beaucoup d&rsquo;entre nous pl&eacute;biscitent un objectif d&rsquo;&eacute;quilibre, incluant d&rsquo;&eacute;ventuels investissements comme un recrutement, une r&eacute;serve &laquo;&nbsp;au cas o&ugrave;&nbsp;&raquo;, et une participation pour les salari&eacute;s.</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Il est propos&eacute; que le groupe de travail sur les tableaux de bord (Philippe, C&eacute;line, Emmanuel, Laetitia et Vincent) soit en charge de faire des propositions d&rsquo;objectif et soumette un DAD &agrave; la prochaine AC&nbsp;:</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">&rarr; proposition valid&eacute;e &agrave; l&rsquo;unanimit&eacute;</span></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Tableau de bord </span></span></strong><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Mazars</span></span></strong></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">pr&eacute;sent&eacute; par C&eacute;line Recchia du Cabinet Mazars&nbsp;:</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Les pr&eacute;visions d&rsquo;atterrissage au 30/06 bas&eacute;es sur le budget ou sur N-1 pr&eacute;voient respectivement un r&eacute;sultat net de 82 310&euro; et de 51 826&euro;.</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Taux d&rsquo;efficience&nbsp;: non rempli, il s&rsquo;agit d&rsquo;oubli</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Jours facturables&nbsp;: changer la d&eacute;nomination par &laquo;&nbsp;jours projets client&nbsp;&raquo;, corresponds au nombre de jours affect&eacute;s sur des projets clients sur Schedule.</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Il serait utile de rajouter le nombre de jours factur&eacute;s. (&agrave; fournir par C&eacute;line, Arnaud, L&aelig;titia)</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Prix de vente mini d&rsquo;1j factur&eacute;e = charges /nb de jours facturables</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Prix de revient d&rsquo;1 jour travaill&eacute;e = Charges / nb de jours pay&eacute;s</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">L&#39;assembl&eacute;e demande au Cabinet Mazars de rajouter une colonne avec les totaux sur la m&ecirc;me p&eacute;riode (moyenne) de l&#39;ann&eacute;e pr&eacute;c&eacute;dente afin de faciliter la comparaison avec le r&eacute;alis&eacute; de cette ann&eacute;e.</span></span></p>\r\n\r\n<p><br />\r\n<strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">DAD</span></span></strong></p>\r\n\r\n<p><span style=\"color:#000000\">Le DAD t&eacute;l&eacute;travail a &eacute;t&eacute; soumis, mais en l&rsquo;absence de Ludwig pour le pr&eacute;senter, le vote est report&eacute;.</span></p>\r\n\r\n<p><span style=\"color:#000000\">Les autres membres du groupe pr&eacute;senteront ce DAD lors de la prochaine AC.</span></p>\r\n\r\n<p><br />\r\n<strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Groupes de travail</span></span></strong></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Pour beaucoup d&rsquo;entre nous, il est difficile de consacrer du temps aux groupes de travail. Une r&eacute;flexion est &agrave; mener pour permettre aux diff&eacute;rents groupes d&rsquo;avancer.</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Une piste int&eacute;ressante serait de r&eacute;duire le temps consacr&eacute; &agrave; l&rsquo;AC pour permettre aux groupes de consacrer une partie de la demi-journ&eacute;e d&rsquo;AC &agrave; ces travaux.</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Le suivi des avanc&eacute;es pourrait &eacute;galement &ecirc;tre centralis&eacute; sur Daddy afin que chaque sujet ne soit pas abord&eacute; syst&eacute;matiquement &agrave; l&rsquo;AC.</span></span></p>\r\n\r\n<p><strong><span style=\"color:#078eb5\">Outils de documentation&nbsp;:</span></strong></p>\r\n\r\n<p>Peu d&rsquo;avanc&eacute;es, Ludwig a travaill&eacute; sur le nouveau wiki, cela demande beaucoup de temps dont ne disposent pas les membres du groupe.</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\">Nouvelle Infra</span></strong></p>\r\n\r\n<p>Les litiges avec Bouygues sont bloquants, une nouvelle box SFR doit &ecirc;tre livr&eacute;e le 17/12.</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\">Daddy&nbsp;:</span></strong></p>\r\n\r\n<p>En stand-by</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\">Schedule </span></strong></p>\r\n\r\n<p>En attente du feu vert pour mise en prod (inh&eacute;rent aux pb de box)</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\">Risotto&nbsp;:</span></strong></p>\r\n\r\n<p>Pas de temps consacr&eacute; &agrave; ce projet en novembre / d&eacute;cembre</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\">Financement LL&nbsp;:</span></strong></p>\r\n\r\n<p>Pas avanc&eacute;, &agrave; r&eacute;int&eacute;grer dans le budget</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\">Locaux Arquebuse&nbsp;:</span></strong></p>\r\n\r\n<p>Apr&egrave;s une premi&egrave;re visite et une visio, Symetris est revenu en d&eacute;but de semaine avec un artisan pour &eacute;tablir des devis travaux. Une proposition d&rsquo;achat semble &ecirc;tre &agrave; venir.</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\">Indicateurs&nbsp;:</span></strong></p>\r\n\r\n<p>Le suivi mis en place est op&eacute;rationnel, permet d&rsquo;avoir une situation &agrave; l&rsquo;instant T (pas maintenu quotidiennement), meilleur suivi de la facturation.</p>\r\n\r\n<p>&rarr; groupe de travail &agrave; supprim&eacute;, op&eacute;rationnel</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\">Qualiopi</span></strong></p>\r\n\r\n<p>Recherche de partenaires en cours. Un premier contact avec 2i2l int&eacute;ressant&nbsp;: partage des valeurs, formations dans le LL, h&eacute;berg&eacute; par Code Lutin, mais demande 30&nbsp;%, ce qui semble &eacute;lev&eacute;.</p>\r\n\r\n<p>D&rsquo;autres propositions sont attendues, d&rsquo;autres demandes de contact vont &ecirc;tre faites.</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\">Am&eacute;nagement des bureaux&nbsp;:</span></strong></p>\r\n\r\n<p>L&rsquo;essentiel est en place, manque la d&eacute;co et les petits &eacute;quipements.</p>\r\n\r\n<p>Il est demand&eacute; &agrave; chacun de lister ses besoins et de les transmettre &agrave; Vincent qui va centraliser.</p>\r\n\r\n<p>Date limite&nbsp;: 23/12</p>\r\n\r\n<p>Dans le cadre du litige avec Bouygues, merci de signaler &agrave; Philippe tout dysfonctionnement m&ecirc;me minime.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Questions diverses&nbsp;:</span></span></strong></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Retour au bureau/t&eacute;l&eacute;travail/COVID</strong></p>\r\n	</li>\r\n</ul>\r\n\r\n<p>Le t&eacute;l&eacute;travail reste de mise. Toute demande de pr&eacute;sentiel dans les bureaux doit &ecirc;tre r&eacute;alis&eacute;e aupr&egrave;s de la co-g&eacute;rance qui s&rsquo;assurera que le nombre de personnes pr&eacute;sentes permet de r&eacute;pondre aux r&egrave;gles de distanciations.</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong><strong>March&eacute; EOLE 2020</strong></strong></p>\r\n	</li>\r\n</ul>\r\n\r\n<p>Nous sommes en attente de la r&eacute;ponse &agrave; l&rsquo;AO auquel nous avons r&eacute;pondu au plus tard en d&eacute;but d&rsquo;ann&eacute;e.</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Validation CR LE</strong></p>\r\n	</li>\r\n</ul>\r\n\r\n<p><strong>Un premier CR a &eacute;t&eacute; co-r&eacute;dig&eacute;, </strong><strong><strong>il sera publi&eacute; vendredi 18/12 &agrave; 14h.</strong></strong><strong> Vos contributions / corrections sont attendues avant cette date.</strong></p>\r\n\r\n<p><strong><a href=\"https://pad.cadol.es/p/CR_LE-octobre\" style=\"color:#000080; text-decoration:underline\">https://pad.cadol.es/p/CR_LE-octobre</a></strong></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong><strong>Ch&egrave;ques No&euml;l</strong></strong></p>\r\n	</li>\r\n</ul>\r\n\r\n<p>Le gouvernement a annonc&eacute; une augmentation du montant d&eacute;fiscalis&eacute; pour les ch&egrave;ques cadeau de fin d&rsquo;ann&eacute;e. Cette annonce ayant &eacute;t&eacute; faite apr&egrave;s la r&eacute;ception de nos ch&egrave;que, se pose la question d&rsquo;une nouvelle commande pour 172&euro; par personne, cette proposition est soumise au vote&nbsp;:</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p>Pour&nbsp;: 6 voix</p>\r\n	</li>\r\n	<li>\r\n	<p>Contre&nbsp;: 2 voix</p>\r\n	</li>\r\n	<li>\r\n	<p>Abstention&nbsp;: 3 voix</p>\r\n	</li>\r\n</ul>\r\n\r\n<p>Cette proposition est adopt&eacute;e, <strong>vos d&eacute;sid&eacute;ratas sont &agrave; adresser &agrave; L&aelig;titia avant le 18/12. </strong>(Cadhoc ou autre)</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Attestation pour l&rsquo;avocate dans le cadre du litige avec Sylvain Eliade</strong></p>\r\n	</li>\r\n</ul>\r\n\r\n<p>Une attestation a &eacute;t&eacute; r&eacute;alis&eacute;e, d&rsquo;autres volontaires&nbsp;? 2 personnes se proposent</p>\r\n\r\n<p><strong>Ces attestations sont &agrave; retourner &agrave; la co-g&eacute;rance au plus tard le 18/12,</strong> l&rsquo;avocate devant les transmettre avec ses conclusions au plus t&ocirc;t.</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>D&eacute;m&eacute;nagement/mobilier&nbsp;:</strong></p>\r\n	</li>\r\n</ul>\r\n\r\n<p>Selon les disponibilit&eacute;s de chacun. L&rsquo;assurance couvre le d&eacute;m&eacute;nagement de nos dossiers, postes de travail. (accident de travail)</p>\r\n\r\n<p>Le mobilier non utilis&eacute; restant &agrave; l&rsquo;Arquebuse pourra &ecirc;tre donn&eacute; aux salari&eacute;s qui le souhaitent.</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Prochaine AC le mardi 1</span></span></strong><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">2 janvier</span></span></strong></p>','2020-12-17 12:28:08',1,1,'uploads/blogarticle/5fdb40bea540f.jpg'),(23,41,3,'CR de l\'Assemblée Collective du 12/01/2021','<p>Pr&eacute;sents&nbsp;: tous + C&eacute;line Recchia et Nicolas Bourgeois du Cabinet Mazars</p>\r\n\r\n<p>Excus&eacute;s&nbsp;: Ludwig (pouvoir donn&eacute; &agrave; Laetitia) et Benjamin G. (pas de pouvoir)</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Tableau de suivi interne</span></span></strong></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Pr&eacute;sent&eacute; par C&eacute;line R</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Un document synth&eacute;tique au format pdf a &eacute;t&eacute; transmis le 05/01 sur <a href=\"mailto:interne@cadoles.com\" style=\"color:#000080; text-decoration:underline\">interne@cadoles.com</a></span></span></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Total factur&eacute; &agrave; date&nbsp;: 487 455&euro; dont &euro; factur&eacute; d&rsquo;avance.</span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Commandes en cours &nbsp;: 81 566&euro;</span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Cumul devis &agrave; l&rsquo;&eacute;tude (pond&eacute;r&eacute;)&nbsp;: 326 757&euro;</span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Pr&eacute;visionnel fin exercice&nbsp;: 895 779&euro;</span></span></p>\r\n	</li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ, il est vou&eacute; &agrave; &eacute;voluer notamment du fait des incertitudes li&eacute;es &agrave; l&rsquo;AO EOLE et aux d&eacute;lais de prise de d&eacute;cisions de l&rsquo;EFS.</span></span></p>\r\n\r\n<p><br />\r\n<span style=\"font-size:12px\"><strong><span style=\"color:#000000\">Remarques suite &agrave; cette pr&eacute;sentation&nbsp;:</span></strong></span></p>\r\n\r\n<p>Suite aux retours et suggestions d&#39;&eacute;volutions propos&eacute;es par diff&eacute;rents collaborateurs, la pr&eacute;sentation a &eacute;t&eacute; modifi&eacute;e pour plus de lisibilit&eacute;. Elle pourra encore &eacute;voluer selon vos retours et besoins.</p>\r\n\r\n<p>A noter, le CA d&#39;&eacute;quilibre a &eacute;t&eacute; positionn&eacute; &agrave; 830 000&euro; et le CA objectif &agrave; 893 000&euro;. (cf DAD soumis par le groupe indicateurs)</p>\r\n\r\n<p>[AF] : Nous avons des difficult&eacute;s avec Logomotion, avec des formations effectu&eacute;es avant le 1er confinement puis des formations qui ont d&ucirc; &ecirc;tre annul&eacute;e. Le dossier de financement est manquant et cel&agrave; complique la facturation. Risque de perte de qq jours. Ce client a encore des formations command&eacute;es, mais pour l&#39;instant il ne r&eacute;pond plus &agrave; nos solliciations.</p>\r\n\r\n<p>[AF] Il est pr&eacute;vu de rajouter un suivi des jours &quot;non facturables&quot; prochainement. (facilit&eacute; par la mise en prod de schedule V2)</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Tableau de bord </span></span></strong><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Mazars</span></span></strong></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">pr&eacute;sent&eacute; par C&eacute;line Recchia du Cabinet Mazars&nbsp;:</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">Le chiffre d&#39;affaires au 31/12 est de 482 726&euro;, il est sup&eacute;rieur aux estimations. (+29% par rapport &agrave; N-1, mais reste inf&eacute;rieur au niveau de N-2). Les charges sont pour le moment &eacute;quivalentes &agrave; cel</span></span><span style=\"font-size:12px\"><span style=\"color:#000000\">les de N-1. L&#39;activit&eacute; couvre les frais et permet une plus grande marge de manoeuvre que sur l&#39;exercice pr&eacute;c&eacute;dent.</span></span></p>\r\n\r\n<p><span style=\"font-size:12px\"><span style=\"color:#000000\">[EG] Serait il possible d&#39;avoir les documents Mazars au plus tard la veille de l&#39;AC afin d&#39;en prendre connaissance &agrave; l&#39;avance? -&gt; ok Mazars</span></span></p>\r\n\r\n<p><br />\r\n<strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">DAD</span></span></strong></p>\r\n\r\n<p><strong>DAD Financement Logiciels libres soumis par le groupe indicateurs</strong></p>\r\n\r\n<p>Inscription au budget pr&eacute;visionnel d&#39;une enveloppe de 6 500&euro; pour le financement des logiciels libres.</p>\r\n\r\n<ul>\r\n	<li><strong>Pour : 12</strong></li>\r\n	<li><strong>Contre : 0</strong></li>\r\n	<li><strong>Abstention : 0</strong></li>\r\n</ul>\r\n\r\n<p>Remarques :</p>\r\n\r\n<p>La d&eacute;fiscalisation est possible dans certains cas, selon le destinataire</p>\r\n\r\n<p>Il serait judicieux de d&eacute;finir une r&egrave;gle de calcul pur d&eacute;finir le montant de ce financement chaque ann&eacute;e. (% du CA par exemple)</p>\r\n\r\n<p>[EG] il sera important de communiquer sur ce financement</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>DAD Nouvelle Embauche soumis par le groupe indicateurs</strong></p>\r\n\r\n<p>Inscription au budget d&#39;une enveloppe pour le financement d&#39;une nouvelle embauche au 1er f&eacute;vrier 2021, au salaire s&eacute;nior soit un montant de 23 500&euro;</p>\r\n\r\n<ul>\r\n	<li><strong>Pour : 11</strong></li>\r\n	<li><strong>Contre : 0</strong></li>\r\n	<li><strong>Abstention : 1</strong></li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>DAD B&eacute;n&eacute;fice soumis par le groupe indicateurs</strong></p>\r\n\r\n<p>Inscription au budget pr&eacute;visionnel d&#39;un b&eacute;n&eacute;fice&nbsp;de 63 000 &euro; permettant de financer :</p>\r\n\r\n<ul>\r\n	<li>Participation (env. 28 500)</li>\r\n	<li>R&eacute;serve (env 28 500)</li>\r\n	<li>Interressement (env 6 000)</li>\r\n</ul>\r\n\r\n<p>Participation = r&eacute;serve et Participation + interressement = 1 mois de salaire net</p>\r\n\r\n<p>Cel&agrave; implique de devoir r&eacute;aliser un Chiffre d&#39;affaires minimum de 893 000&euro;. (charges pr&eacute;vues + participation + r&eacute;serve + interressement)</p>\r\n\r\n<ul>\r\n	<li><strong>Pour : 8</strong></li>\r\n	<li><strong>Contre : 2</strong></li>\r\n	<li><strong>Abstention : 2</strong></li>\r\n</ul>\r\n\r\n<p>Quelques remarques suite aux &eacute;changes :</p>\r\n\r\n<p>[BB] Quel est l&#39;objectif de constituer une r&eacute;serve? Pr&eacute;f&egrave;re un objectif de CA inf&eacute;rieur et travailler moins plut&ocirc;t que travailler plus avec une r&eacute;mun&eacute;ration suppl&eacute;mentaire.</p>\r\n\r\n<p>[EG] Pr&eacute;f&egrave;rerait travailler plus pour la communaut&eacute; du LL que de gagner plus, ce qui est plus gratifiant pour sa part.</p>\r\n\r\n<p>[PC] Il est indispensable de reconstituer une r&eacute;serve (utilis&eacute;e lors de l&#39;investissement dans les locaux de Jaures), souhaite que les collaborateurs soient gratifi&eacute;s pour leur implication.</p>\r\n\r\n<p>[WP] La reserve pr&eacute;c&eacute;dente a t elle &eacute;t&eacute; utilis&eacute;e lors de l&#39;achat de Jaures? -&gt; oui</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>DAD r&eacute;partition des groupes op&eacute;rationnels</strong></p>\r\n\r\n<p>R&eacute;partition des objectifs sur les 2 groupes op&eacute;rationnels existants au prorata des ETP dits facturables.</p>\r\n\r\n<ul>\r\n	<li><strong>Pour : 10</strong></li>\r\n	<li><strong>Contre : 0</strong></li>\r\n	<li><strong>Abstention : 2</strong></li>\r\n</ul>\r\n\r\n<p>Remarques et questions soulev&eacute;es :</p>\r\n\r\n<p>[WP] Pourrait on faire ressortir des ETP infra, co-g&eacute;rance, part C&eacute;line dans interne etc ?</p>\r\n\r\n<p>[AF] Dans la PR, pourrait on plut&ocirc;t mettre la r&egrave;gle de calcul au lieu d&#39;une valeur en euros bas&eacute;e sur un pr&eacute;visionnel? Le tableau de suivi interne pourra &eacute;voluer pour tenir compte de la mise en place des objectifs par groupe op&eacute;rationnels.</p>\r\n\r\n<p>Plusieurs collaborateurs notent un risque de mise en comp&eacute;tition entre les groupes op&eacute;rationnels qui pourrait s&#39;av&eacute;rer malsain. Quelles cons&eacute;quences si un groupe ne peut atteindre les objectifs fix&eacute;s?</p>\r\n\r\n<p>[CR] Risque de cloisonnement avec la formalisation de ces 2 groupes op&eacute;rationnels, risque de perte de transversalit&eacute; sur certains projets impliquant des membres des 2 groupes?</p>\r\n\r\n<p><strong>DAD indicateurs pr&eacute;sent&eacute; par le groupe indicateurs</strong></p>\r\n\r\n<p>Validation du mode de calcul des indicateurs suivants :</p>\r\n\r\n<ul>\r\n	<li><u>Co&ucirc;t de revient journalier d&#39;un salari&eacute; (CDR) </u>: Le but de cet indicateur est de calculer le co&ucirc;t de chaque salari&eacute; (facturable ou non). Mode de calcul : Montant des charges annuelles / Nombre de jours travaill&eacute;s par les salari&eacute;s.</li>\r\n	<li><u>Prix de vente minimum d&#39;une journ&eacute;e (PVM) </u>: Le but de cet indicateur est de savoir &agrave; partir de quelle montant une journ&eacute;e est rentable. On sait qu&#39;en dessous de ce tarif une journ&eacute;e est r&eacute;alis&eacute;e &agrave; perte. Mode de calcul : Montant des charges annuelles / Nombre de jours r&eacute;alisables par les salari&eacute;s dits facturables</li>\r\n	<li><u>CA moyen d&#39;une journ&eacute;e pour arriver &agrave; l&#39;objectif (CAM)</u> : Le but de cet indicateur est de connaitre le montant de la journ&eacute;e minimum pour arriver &agrave; l&#39;objectif. En dessous de ce montant, la journ&eacute;e ne permet pas d&#39;y arriver. Dans les conditions optimales, l&#39;ensemble des salari&eacute;s facturables seront factur&eacute;s, en moyenne, &agrave; ce montant chaque jour de travail. Mode de calcul : Chiffre d&#39;affaires souhait&eacute; / Nombre de jours r&eacute;alisables par les salari&eacute;s dits facturables.</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li><strong>Pour : 12</strong></li>\r\n	<li><strong>Contre : 0</strong></li>\r\n	<li><strong>Abstention : 0</strong></li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>DAD D&eacute;finition du temps collaborateur propos&eacute; par Emmanuel et Benjamin</strong></p>\r\n\r\n<p>Chaque salari&eacute; pourra et devra, chaque mois, participer &agrave; la vie de l&#39;entreprise. (cf PR)</p>\r\n\r\n<ul>\r\n	<li><strong>Pour : 7</strong></li>\r\n	<li><strong>Contre : 1</strong></li>\r\n	<li><strong>Abstention : 4</strong></li>\r\n</ul>\r\n\r\n<p>Remarques et questions soulev&eacute;es sur la PR :</p>\r\n\r\n<p><em>&quot;Le cog&eacute;rent peut profiter de son temps collaborateur pour r&eacute;aliser les actions li&eacute;es &agrave; cette mission.&quot;</em></p>\r\n\r\n<p>-&gt; le temps allou&eacute; &agrave; la co-g&eacute;rance est assimil&eacute; &agrave; du temps collaborateur</p>\r\n\r\n<p><em>&quot;Chaque collaborateur DOIT disposer et justifier, d&#39;au minimum, en moyenne, 1 jour 1/2 par mois de temps collaborateur.&quot;</em></p>\r\n\r\n<p>-&gt; la notion d&#39;obligation de justifier ce temps pose question &agrave; certains collaborateurs, quid si ce n&#39;est pas respect&eacute;? Sanctions?</p>\r\n\r\n<p>-&gt;ad&eacute;quation entre la r&eacute;alit&eacute; et l&#39;objectif de 1,5j / mois : suffisant, trop important, r&eacute;alisable, &agrave; partir de quand?</p>\r\n\r\n<p>Plusieurs collaborateurs demandent le report de cette d&eacute;cision afin de prendre le temps de r&eacute;pondre &agrave; ces diff&eacute;rents points</p>\r\n\r\n<p>-&gt;Proposition accept&eacute;e en l&#39;&eacute;tat, pas de report</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Groupes de travail</span></span></strong></p>\r\n\r\n<p><strong><span style=\"color:#078eb5\">Nouvelle Infra</span></strong></p>\r\n\r\n<p>Les prises r&eacute;seau murales &agrave; Jaures sont op&eacute;rationnelles. Un nouveau serveur de messagerie a &eacute;t&eacute; mis en place, de nouveaux services seront d&eacute;ploy&eacute;s prochainement. (cf email Vincent/Philippe)</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\">Daddy&nbsp;:</span></strong></p>\r\n\r\n<p>William pr&eacute;voit d&#39;interroger tous les utilisateurs afin de pr&eacute;parer une liste d&#39;&eacute;volutions pour faciliter encore plus la gestion des AC.</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\">Support :</span></strong></p>\r\n\r\n<p>Cr&eacute;ation d&#39;un groupe de travail</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Questions diverses&nbsp;:</span></span></strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Partenariat EFS</strong></p>\r\n	</li>\r\n</ul>\r\n\r\n<p>L&#39;EFS nous demande de nous positionner sur un nouveau type de march&eacute; ; march&eacute; d&#39;innovation.</p>\r\n\r\n<p>La mise en conccurence serait plus faible, le march&eacute; ne serait pas limit&eacute; &agrave; un seul sujet, permettrait d&#39;officialiser notre partenariat.</p>\r\n\r\n<p>En revanche, le principe it&eacute;ratif permet &agrave; l&#39;EFS de mettre un terme au march&eacute; si le projet n&#39;est pas concluant &agrave; tt moment.</p>\r\n\r\n<p>=&gt; une r&eacute;union strat&eacute;gique est planifi&eacute;e le lundi 18/01 &agrave; 11h entre les associ&eacute;s pour prise de d&eacute;cision rapide, dans le cas contraire une mesure d&#39;urgence sera prise par les co-g&eacute;rants.</p>\r\n\r\n<p><a class=\"moz-txt-link-freetext\" href=\"https://www.economie.gouv.fr/daj/partenariat-innovation-2019\">https://www.economie.gouv.fr/daj/partenariat-innovation-2019</a></p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong><strong>Tickets resto</strong></strong></p>\r\n	</li>\r\n</ul>\r\n\r\n<p>Avec le t&eacute;l&eacute;travail, la qt&eacute; de TR disponible est importante, malgr&eacute; les annonces de prolongation de leur validit&eacute;, il semblerait qu&#39;il soit difficile de les utiliser chez certains commer&ccedil;ants.</p>\r\n\r\n<p>-&gt; les co-g&eacute;rants vont prendre ce point et voir ce qu&#39;il est possible de faire</p>\r\n\r\n<ul>\r\n	<li>\r\n	<p><strong>Validation CR LE</strong></p>\r\n	</li>\r\n</ul>\r\n\r\n<p>Le CR LE de d&eacute;cembre sera envoy&eacute; le 15/01 &agrave; 14h.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Prochaine AC le mardi 1</span></span></strong><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">6 f&eacute;vrier</span></span></strong></p>\r\n\r\n<p>&nbsp;</p>','2021-01-15 10:02:55',1,1,'uploads/blogarticle/6001a88f49382.jpeg'),(24,6,6,'Pôle DEV = New letters du 05/02/2021','<h2>MSE</h2>\r\n\r\n<ul>\r\n	<li>Int&eacute;ration en cours compliqu&eacute;e car encore une t&acirc;che de Michel lanc&eacute;e dans la mare sans sp&eacute;cification</li>\r\n	<li>Faudrait un peu plus imput&eacute; de l&#39;UO03</li>\r\n	<li>Il faudrait r&eacute;organisation un peu l&#39;&eacute;quipe Cadoles en terme de r&ocirc;le</li>\r\n	<li>Facturation de Matthieu d&egrave;s la prochaine it&eacute;ration</li>\r\n	<li>Pr&eacute;sentaion &agrave; l&#39;&eacute;quipe du CROUS Toulouse &agrave; la prochaine m&eacute;l&eacute;e</li>\r\n</ul>\r\n\r\n<h2>Sheila</h2>\r\n\r\n<ul>\r\n	<li>Premi&egrave;re it&eacute;ration desgin r&eacute;alis&eacute;e</li>\r\n	<li>Seconde it&eacute;ration sur l&#39;int&eacute;gration de donn&eacute;es qui est le coeur du produit</li>\r\n	<li>Prochaine it&eacute;rations d&eacute;j&agrave; planifi&eacute;es tant au nvieau planning que du contenu</li>\r\n	<li>Client ultra content des avanc&eacute;es sur le projet</li>\r\n	<li>Revoir la politique d&#39;inscription des utilisateurs EFS n&eacute;cessaire : trop de personnes qui ne se connecte pas</li>\r\n	<li>au del&agrave; du POC si signature du contrat d&#39;innovation, repr&eacute;sentera 100000&euro;/an</li>\r\n	<li>Sinon sur le POC actuelle on pourra facturer 30% maintenant / 30% en milieu de projet / 40 % en fin de projet</li>\r\n</ul>\r\n\r\n<h2>Quid</h2>\r\n\r\n<ul>\r\n	<li>Retour de charge de Quid</li>\r\n	<li>Revue du schema d&#39;architecture</li>\r\n	<li>On revient &agrave; l&#39;architecture initiale</li>\r\n	<li>Devis &agrave; r&eacute;aliser</li>\r\n	<li>En attente de commande sur le devis sur Go-CaptivePortal &gt; PR2011-0852 = 5jr = 2550&euro;</li>\r\n</ul>\r\n\r\n<h2>Transnum</h2>\r\n\r\n<ul>\r\n	<li>Prochain Lot de dev</li>\r\n	<li>Migration du Nextcloud de envole 6 &agrave; envole 7 pour b&eacute;n&eacute;ficier de Nextcloud 19</li>\r\n	<li>Discution toujours en cours pour faire &eacute;voluer l&#39;infra de production</li>\r\n</ul>\r\n\r\n<h2>Envole</h2>\r\n\r\n<ul>\r\n	<li>Manque de commandes de Aix / Nice / Cr&eacute;teil</li>\r\n	<li>Avec les commandes actuelles le terme des jours disponibles viendra fin mai / d&eacute;but juin</li>\r\n	<li>Quid apr&egrave;s ...&nbsp;</li>\r\n	<li>Gros travail autour de l&#39;AD / de lemonLDAP / du LDAPS</li>\r\n	<li>A venir = test Envole 2.8 / packaging Jupyter</li>\r\n</ul>\r\n\r\n<h2>Mistral</h2>\r\n\r\n<ul>\r\n	<li>MEP r&eacute;alis&eacute; la semaine</li>\r\n	<li>Mistral n&#39;est pas pro</li>\r\n	<li>Les retours du clients sont multiples, sans coordination de leur part</li>\r\n	<li>Il faut faire une r&eacute;union avec eux pour mettre &agrave; plat les m&eacute;thodes de communication</li>\r\n	<li>Vu l&#39;ampleur il faut les pr&eacute;venir qu&#39;il faudrait plus d&#39;implication de leur part</li>\r\n</ul>\r\n\r\n<h2>Xibo</h2>\r\n\r\n<ul>\r\n	<li>Evolution du Discovery n&eacute;cessaire &agrave; r&eacute;aliser le 08/02</li>\r\n	<li>MEP le 17/02</li>\r\n	<li>Passage de flambeau n&eacute;cessaire de 5 jours avec Teddy et Matthieu</li>\r\n	<li>Le CROUS de Poitiers a un budget li&eacute; &agrave; XIBO : il devrait revenir vers nous pour faire &eacute;voluer la solution</li>\r\n	<li>Notamment sur l&#39;utilisation d&#39;un nouveau plugin permettant la diffusion de publicit&eacute;s : ils voudraient utiliser ce plugin afin de diffuser de la pub &eacute;tudiantes</li>\r\n</ul>\r\n\r\n<h2>Logomotion</h2>\r\n\r\n<ul>\r\n	<li>Pas de nouvelle de logomotion</li>\r\n	<li>Pas de convention de formation malgr&egrave;s des commandes du client</li>\r\n	<li>La commande a &eacute;t&eacute; partiellement r&eacute;alis&eacute;e</li>\r\n	<li>Relance du client pour soit finaliser la commande, soit r&eacute;gler partiellement la commande</li>\r\n	<li>Pas de nouvelle de lui</li>\r\n	<li>Derni&egrave;re nouvelle : il a eu un accident et qu&#39;il &eacute;tait &agrave; l&#39;arr&ecirc;t mais cela date de bien 2 mois</li>\r\n	<li>Lui t&eacute;l&eacute;phoner ?</li>\r\n</ul>\r\n\r\n<h2>BER</h2>\r\n\r\n<ul>\r\n	<li>Mise en oeuvre d&#39;un connecteur AD avec Ninegate en tant que pilote</li>\r\n	<li>Recette pr&eacute;vu le 15/02</li>\r\n	<li>MEP le 17/02</li>\r\n</ul>\r\n\r\n<h2>PYXIS</h2>\r\n\r\n<ul>\r\n	<li>on arrive en fin de dev</li>\r\n	<li>RAF la partie web</li>\r\n	<li>Retard de livraison du mat&eacute;riel ce qui nous permet de finaliser les travaux en phase avec la reception du mat&eacute;riel</li>\r\n</ul>\r\n\r\n<h2>ARCADE</h2>\r\n\r\n<ul>\r\n	<li>le projet perso de William devient important</li>\r\n	<li>mod&egrave;le &eacute;co via abonnement enviseag&eacute;</li>\r\n	<li>il faudrait que William pr&eacute;sente le projet &agrave; Cadoles et pofine un peu un dossier commercial</li>\r\n</ul>\r\n\r\n<h2>Daddy</h2>\r\n\r\n<ul>\r\n	<li>L&#39;outils commence a &ecirc;tre utilis&eacute;</li>\r\n	<li>N&eacute;cessit&eacute; de faire une estimation des retours</li>\r\n	<li>RAF\r\n	<ul>\r\n		<li>8jrs pour traiter le minimum pour une exploitation en production</li>\r\n		<li>8jrs de plus pour finaliser le produit mais qui viendrait &agrave; faire &eacute;voluer</li>\r\n		<li>8jrs en estimant qu&#39;il sera n&eacute;cessaire de doubler les comp&eacute;tences</li>\r\n		<li>A l&#39;avenir il faudrait penser qu&#39;une maintenance de 5jrs par an serait n&eacute;cessaire</li>\r\n	</ul>\r\n	</li>\r\n	<li>A terme\r\n	<ul>\r\n		<li>Il faudrait le diffuser &agrave; LE</li>\r\n		<li>Mais avant il faudrait l&#39;&eacute;prouver en interne</li>\r\n		<li>A voir quand m&ecirc;me car demandera un investissement de maintenance suppl&eacute;mentaire</li>\r\n		<li>Serait donc &agrave; d&eacute;cider en AC</li>\r\n	</ul>\r\n	</li>\r\n</ul>\r\n\r\n<h2>Gitkan</h2>\r\n\r\n<ul>\r\n	<li>Plus n&eacute;cessaire car le kanboard est directement impl&eacute;ment&eacute; dans la nouvelle version de git- ea</li>\r\n</ul>\r\n\r\n<h2>Schedule</h2>\r\n\r\n<ul>\r\n	<li>La version 2 est en production</li>\r\n	<li>Ne pas h&eacute;siter &agrave; remonter le moindre probl&egrave;me</li>\r\n</ul>\r\n\r\n<h2>Dialogue DEV &lt;&gt; CSS</h2>\r\n\r\n<ul>\r\n	<li>Du point de vue DEV il faudrait que l&#39;on remonte plus clairement les besoins syst&egrave;mes du DEV</li>\r\n	<li>Exemple\r\n	<ul>\r\n		<li>maintenance syst&egrave;me Mistral</li>\r\n		<li>difficult&eacute;s de suivi des taches infra MSE. Pr&eacute;sence de CSS lors de la r&eacute;union du vendredi matin m&ecirc;me pour 10mn souhait&eacute;. Demander &agrave; C&eacute;line &agrave; ce que le p&ocirc;le CSS participe syst&egrave;matiquement &agrave; la m&eacute;l&eacute;e MSE hebdomadaire.</li>\r\n	</ul>\r\n	</li>\r\n</ul>','2021-02-08 10:53:52',1,0,'uploads/blogarticle/60210a2ab35a0.jpg'),(25,6,3,'CR de l\'Assemblée Collective du 16/02/2021','<div id=\"magicdomid2\">Pr&eacute;sents : tous + C&eacute;line Recchia et Nicolas Bourgeois du Cabinet Mazars</div>\r\n\r\n<div id=\"magicdomid3\">Excus&eacute;s : Philippe (pouvoir donn&eacute; &agrave; Vincent)</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div id=\"magicdomid4\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Tableau de suivi interne</span></span></strong></div>\r\n\r\n<div id=\"magicdomid6\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div id=\"magicdomid7\">Un document synth&eacute;tique corrig&eacute; au format pdf a &eacute;t&eacute; transmis le 15/02 sur <u>interne@cadoles.com</u></div>\r\n\r\n<div id=\"magicdomid8\">Une erreur sur la valorisation des heures de DEV pr&eacute;visionnelles a fauss&eacute; la premi&egrave;re version du document (devis/&agrave;l&#39;&eacute;tude), celles-ci &eacute;taient valoris&eacute;es au prix de 600&euro; au lieu de 420&euro;. Apr&egrave;s correction :</div>\r\n\r\n<div id=\"magicdomid9\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 487 064&euro;.</li>\r\n	<li>Commandes en cours&nbsp; : 123 516&euro;</li>\r\n	<li>Cumul devis &agrave; l&rsquo;&eacute;tude (pond&eacute;r&eacute;) : 238 076&euro;</li>\r\n	<li>Pr&eacute;visionnel fin exercice : 837 029&euro;</li>\r\n</ul>\r\n</div>\r\n\r\n<div id=\"magicdomid13\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div id=\"magicdomid14\">A noter &eacute;galement la modification des pond&eacute;rations suivantes :</div>\r\n\r\n<ul>\r\n	<li>&nbsp;&nbsp;&nbsp; MSE : 90% &agrave; 95%</li>\r\n	<li>&nbsp;&nbsp;&nbsp; AO EOLE et MTES : 50% &agrave; 25%</li>\r\n</ul>\r\n\r\n<div id=\"magicdomid17\">&nbsp;</div>\r\n\r\n<div id=\"magicdomid18\"><strong>Remarques suite &agrave; cette pr&eacute;sentation :</strong></div>\r\n\r\n<div id=\"magicdomid19\">Pour m&eacute;moire, le CA d&#39;&eacute;quilibre a &eacute;t&eacute; positionn&eacute; &agrave; 830 000&euro; et le CA objectif &agrave; 893 000&euro;. (cf DAD soumis par le groupe indicateurs)</div>\r\n\r\n<div id=\"magicdomid20\">Ces chiffres devront &ecirc;tre mis &agrave; jour puisque l&#39;embauche &eacute;ventuelle avait &eacute;t&eacute; budg&eacute;t&eacute;e &agrave; partir du mois de f&eacute;vrier.</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1513\">A ce jour, rien n&#39;est pr&eacute;vu si nous n&#39;atteignons pas cet objectif, il faudra peut-&ecirc;tre en reparler d&#39;ici &agrave; la fin de l&#39;exercice.</div>\r\n\r\n<div id=\"magicdomid22\">&nbsp;</div>\r\n\r\n<div id=\"magicdomid23\">[AF] La facturation de Sheila sera effectu&eacute;e sur cet exercice ( en 3 fois).</div>\r\n\r\n<div>La publication du march&eacute; d&#39;innovation pour Sheila devrait intervenir vers la mi-mars, le d&eacute;lai de r&eacute;ponse sera tr&egrave;s court. (100K&euro;/an sur 4ans)</div>\r\n\r\n<div id=\"magicdomid24\">Arnaud est en contact avec Creteil pour Envole, ils devraient passer commande prochainement.</div>\r\n\r\n<div id=\"magicdomid25\">Certains jours MSE c&ocirc;t&eacute; dev m&eacute;riteraient d&#39;&ecirc;tre factur&eacute;s &agrave; 600&euro;, il faudrait &ecirc;tre vigilant sur ce point lors des prochaines facturations.</div>\r\n\r\n<div id=\"magicdomid26\">&nbsp;</div>\r\n\r\n<div id=\"magicdomid27\">&nbsp;</div>\r\n\r\n<div id=\"magicdomid28\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Tableau de bord </span></span></strong><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Mazars</span></span></strong></div>\r\n\r\n<div id=\"magicdomid29\">pr&eacute;sent&eacute; par C&eacute;line Recchia du Cabinet Mazars :</div>\r\n\r\n<div id=\"magicdomid30\">Le chiffre d&#39;affaires au 31/01 est de 509 274&euro;.&nbsp;</div>\r\n\r\n<div id=\"magicdomid31\">&nbsp;</div>\r\n\r\n<div id=\"magicdomid32\">&nbsp;</div>\r\n\r\n<div id=\"magicdomid33\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">DAD</span></span></strong></div>\r\n\r\n<div id=\"magicdomid34\"><strong>DAD Qualiopi soumis par le groupe Qualiopi (C&eacute;line et Benjamin)</strong></div>\r\n\r\n<div id=\"magicdomid35\">Se faire certifier Qualiopi</div>\r\n\r\n<div>\r\n<div id=\"magicdomid36\">\r\n<ul>\r\n	<li><strong>Pour : 0</strong></li>\r\n	<li><strong>Contre :&nbsp;</strong></li>\r\n	<li><strong>Abstention :&nbsp;</strong></li>\r\n</ul>\r\n</div>\r\n</div>\r\n\r\n<div>Ne pas se faire certifier Qualiopi</div>\r\n\r\n<div id=\"magicdomid36\">\r\n<ul>\r\n	<li><strong>Pour : 9</strong></li>\r\n	<li><strong>Contre : 0</strong></li>\r\n	<li><strong>Abstention : 3</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div id=\"magicdomid39\">&nbsp;</div>\r\n\r\n<div id=\"magicdomid40\">Remarques : ne pas se faire certifier Qualiopi implique soit de recourir &agrave; un portage, soit de ne pas r&eacute;pondre &agrave; l&#39;AO formation EOLE.</div>\r\n\r\n<div id=\"magicdomid41\">&nbsp;</div>\r\n\r\n<div id=\"magicdomid42\">Recourir au portage via la soci&eacute;t&eacute; 2i2l :</div>\r\n\r\n<div id=\"magicdomid43\">\r\n<ul>\r\n	<li><strong>Pour : 5</strong></li>\r\n	<li><strong>Contre :&nbsp;</strong></li>\r\n	<li><strong>Abstention :&nbsp;</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div id=\"magicdomid46\">&nbsp;</div>\r\n\r\n<div id=\"magicdomid47\">Recourir au portage via la CAE Bourgogne :&nbsp;&nbsp;&nbsp;&nbsp;</div>\r\n\r\n<div id=\"magicdomid48\">\r\n<ul>\r\n	<li><strong>Pour : 3</strong></li>\r\n	<li><strong>Contre :&nbsp;</strong></li>\r\n	<li><strong>Abstention :&nbsp;</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div id=\"magicdomid51\">&nbsp;</div>\r\n\r\n<div id=\"magicdomid52\">Recourir au portage via Go-on Formation :&nbsp;&nbsp;&nbsp;&nbsp;</div>\r\n\r\n<div id=\"magicdomid53\">\r\n<ul>\r\n	<li><strong>Pour : 7</strong></li>\r\n	<li><strong>Contre :&nbsp;</strong></li>\r\n	<li><strong>Abstention :&nbsp;</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div id=\"magicdomid56\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1818\">Il est donc d&eacute;cid&eacute; de prioriser le partenariat avec Go-on, sous r&eacute;serve de volontaires pour r&eacute;aliser la formation demand&eacute;e en &eacute;change, puis 2i2l en second choix. D&#39;autre part, la publication de l&#39;AO formation EOLE avec une date limite de r&eacute;ponse au 25/02 pose question. En effet, la certification Qualiopi sera n&eacute;cessaire &agrave; partir du 01/01/22. Le prestataire choisi sera il en mesure de r&eacute;pondre &agrave; l&#39;AO dans les temps?</div>\r\n\r\n<div id=\"magicdomid58\">&nbsp;</div>\r\n\r\n<div id=\"magicdomid59\">&nbsp;</div>\r\n\r\n<div id=\"magicdomid60\"><strong>DAD 1.Application du mod&egrave;le op&eacute;rationnel soumis par le groupe mod&egrave;le op&eacute;rationnel</strong></div>\r\n\r\n<div id=\"magicdomid61\">Proposition de tester une application du mod&egrave;le sur une granularit&eacute; plus pr&eacute;cise avec 5 projets op&eacute;rationnels de test repr&eacute;sentatifs :&nbsp;</div>\r\n\r\n<div id=\"magicdomid62\">\r\n<ul style=\"margin-left:40px\">\r\n	<li>EOLE</li>\r\n	<li>MSE</li>\r\n	<li>Support</li>\r\n	<li>EFS</li>\r\n	<li>Infra Cadoles</li>\r\n</ul>\r\n</div>\r\n\r\n<div id=\"magicdomid68\">\r\n<ul>\r\n	<li><strong>Pour : 9</strong></li>\r\n	<li><strong>Contre : 0&nbsp;</strong></li>\r\n	<li><strong>Abstention : 3&nbsp;</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div id=\"magicdomid71\">&nbsp;</div>\r\n\r\n<div id=\"magicdomid72\"><strong>DAD&nbsp; 2. Indicateurs des projets op&eacute;rationnels soumis par le groupe mod&egrave;le op&eacute;rationnel</strong></div>\r\n\r\n<div id=\"magicdomid73\">Les indicateurs propos&eacute;s sont :</div>\r\n\r\n<div id=\"magicdomid74\">\r\n<ul style=\"margin-left:40px\">\r\n	<li>Budget du projet</li>\r\n	<li>Progression sur l&#39;objectif (CA)</li>\r\n	<li>Progression sur le temps</li>\r\n</ul>\r\n</div>\r\n\r\n<div id=\"magicdomid78\">\r\n<ul>\r\n	<li><strong>Pour : 8</strong></li>\r\n	<li><strong>Contre : 0&nbsp;</strong></li>\r\n	<li><strong>Abstention : 5</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div id=\"magicdomid81\">&nbsp;&nbsp;&nbsp;&nbsp;</div>\r\n\r\n<div id=\"magicdomid82\"><strong>DAD 3.Execution du mod&egrave;le op&eacute;rationnel soumis par le groupe mod&egrave;le op&eacute;rationnel</strong></div>\r\n\r\n<div id=\"magicdomid83\">Proposition de temporalit&eacute; de mise en application : un mois sur les cinq projets de tests pr&eacute;sent&eacute;s dans le DAD pr&eacute;c&eacute;dent, puis il nous restera trois mois avant la fin de l&rsquo;exercice en cours pour tenter de d&eacute;finir tous les projets restants si le test est concluant.</div>\r\n\r\n<div id=\"magicdomid84\">\r\n<ul>\r\n	<li><strong>Pour : 9</strong></li>\r\n	<li><strong>Contre : 1&nbsp;</strong></li>\r\n	<li><strong>Abstention : 2&nbsp;</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div id=\"magicdomid87\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1824\">Remarques :</div>\r\n\r\n<div class=\"ace-line\">La soumission de ces 3 DAD a soulev&eacute; de nombreuses questions et interrogations. Notamment sur la disparition des p&ocirc;les CSS/DEV, le r&ocirc;le des coordinateurs, l&#39;&eacute;ventuel besoin de conserver une coordination globale des ressources etc.</div>\r\n\r\n<div id=\"magicdomid90\">Pour le groupe de travail, ces diff&eacute;rents points seront adress&eacute;s au fur et &agrave; mesure de la mise en application du mod&egrave;le.&nbsp;</div>\r\n\r\n<div id=\"magicdomid91\">&nbsp;</div>\r\n\r\n<div id=\"magicdomid92\">&nbsp;</div>\r\n\r\n<div id=\"magicdomid93\"><strong>DAD Vente du Local de l&#39;Arquebuse</strong></div>\r\n\r\n<div id=\"magicdomid94\">La Soci&eacute;t&eacute; Symetris nous a fait une offre d&#39;achat de 144 000&euro; pour le local. Peut on accepter cette offre ?</div>\r\n\r\n<div id=\"magicdomid95\">\r\n<ul>\r\n	<li><strong>Pour : 13</strong></li>\r\n	<li><strong>Contre : 0</strong></li>\r\n	<li><strong>Abstention : 0</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div id=\"magicdomid99\">Remarque : la vente du local sera int&eacute;gr&eacute;e au bilan comme un produit exceptionnel.</div>\r\n\r\n<div id=\"magicdomid100\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1793\"><strong>Les DADs suivants seront soumis au vote ult&eacute;rieurement faute de temps : Site internet, DADDY</strong></div>\r\n\r\n<div id=\"magicdomid103\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1369\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Groupes de travail</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1379\">\r\n<ul>\r\n	<li><strong>T&eacute;l&eacute;travail</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1356\">Les travaux de ce groupe sont &agrave; relancer afin de proposer un DAD lors de la prochaine AC.</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1381\">\r\n<ul>\r\n	<li><strong>Daddy : Fluidification des AC</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div id=\"magicdomid108\">William pr&eacute;voit 2 &eacute;tapes :</div>\r\n\r\n<div id=\"magicdomid109\">&nbsp;&nbsp;&nbsp;&nbsp; - 1 pool de 8j = fonctionalit&eacute;s / am&eacute;liorations</div>\r\n\r\n<div id=\"magicdomid110\">&nbsp;&nbsp;&nbsp;&nbsp; - 1 pool de 8j = aide &agrave; la publicit&eacute;, automatisation du vote</div>\r\n\r\n<div id=\"magicdomid111\">L&#39;Assembl&eacute;e &eacute;met un avis favorable.</div>\r\n\r\n<div>Ce groupe de travail a besoin de nouvelles recrues !</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1573\">\r\n<ul>\r\n	<li><strong>Financement Logiciels libres</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1574\">Le montant de la dotation a &eacute;t&eacute; valid&eacute; lors de la derni&egrave;re AC. Il est maintenant n&eacute;cessaire de d&eacute;finir les b&eacute;n&eacute;ficiares.</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1660\">BB sollicite de l&#39;aide sur ce groupe.</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1792\">\r\n<ul>\r\n	<li><strong>Activit&eacute; de support</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1787\">Le groupe a commenc&eacute; &agrave; travailler sur des proc&eacute;dures, disponibles sur un d&eacute;p&ocirc;t. Les avis sont les bienvenus.</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1789\"><a href=\"https://forge.cadoles.com/lseys/support/src/branch/split\">https://forge.cadoles.com/lseys/support/src/branch/split</a></div>\r\n\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid1334\">\r\n<ul>\r\n	<li><strong>Site internet</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1049\">Notre site internet n&#39;est plus maintenable et les informations qui y sont pr&eacute;sent&eacute;es sont en partie obsol&egrave;tes, il devient urgent d&#39;agir.</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1333\">VF pr&eacute;cise que tt est pr&ecirc;t c&ocirc;t&eacute; infra. ML a d&eacute;j&agrave; travaill&eacute; sur la refonte du site, l&#39;Assembl&eacute;e est d&#39;accord pour que ML et WP prennent le temps d&#39;&eacute;valuer la charge de travail n&eacute;cessaire.</div>\r\n</div>\r\n\r\n<div id=\"magicdomid114\">&nbsp;</div>\r\n\r\n<div id=\"magicdomid115\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Questions diverses&nbsp;:</span></span></strong></div>\r\n\r\n<div id=\"magicdomid116\">&nbsp;</div>\r\n\r\n<div id=\"magicdomid117\">\r\n<ul>\r\n	<li><strong>Mobilier du local de l&#39;Arquebuse</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div id=\"magicdomid118\">Plusieurs personnes ont &eacute;mis le souhait de r&eacute;cup&eacute;rer du mobilier dans les locaux de l&#39;Arquebuse.</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid487\">Celine Recchia nous alerte sur le fait que certains meubles, ont &eacute;t&eacute; immobilis&eacute;s lors de l&#39;achat des locaux.</div>\r\n\r\n<div class=\"ace-line\">D&#39;autre part, il est convenu que C&eacute;line et Arnaud fixent des dates de d&eacute;m&eacute;nagement dans les plannings.</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid497\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid529\"><em>[e-mail C. Recchia] Suite &agrave; l&rsquo;AC, voici ce qu&rsquo;il faut savoir sur la cession du local.</em></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid530\"><em>Le local au 30/06/2021 vaudra au bilan 101506 &euro; (immobilier et travaux r&eacute;alis&eacute;s)</em></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid531\"><em>Les &laquo; biens meubles &raquo; achet&eacute;s avec le local valent aussi 4750&euro; et les si&egrave;ges arrozzi 347.68 &euro;</em></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid532\"><em>Au total si vous &laquo; r&eacute;cup&eacute;rez &raquo; les meubles, la valeur comptable sera de 101506 + 4750 soit 106256 e et donc la plus value de 37 744 &euro; si vous consid&eacute;rez que les meubles font partie du prix de vente</em></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid533\"><em>Je n&rsquo;ai pas inclus les si&egrave;ges qui peuvent &ecirc;tre r&eacute;cup&eacute;r&eacute;s ou vendus par ailleurs et dont la valeur n&rsquo;est pas significative</em></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid545\"><em>&nbsp;Chaque meuble que vous vendrez viendra augmenter le &laquo; gain &raquo; r&eacute;sultant de la cession mais globalement il sera difficile de dire que ces meubles qui ont une valeur de 4750 e ont &eacute;t&eacute; &laquo; jet&eacute;s &raquo; par contre vous pouvez rajouter 5000&euro; au prix de vente ou indiquer (m&ecirc;me s&rsquo;il n&rsquo;y en a pas) que dans le prix de vente sont inclus pour 5000&euro; de meubles.</em></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid552\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid586\">\r\n<ul>\r\n	<li><strong>Formation SALT</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid709\">La formation SALT de 4 1/2j pour 5 personnes sera financ&eacute;e &agrave; hauteur de 4000&euro; par ATLAS, reste &agrave; charge Cadoles 800&euro;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid834\">L&#39;Assembl&eacute;e n&#39;&eacute;met aucune objection &agrave; cette d&eacute;pense qui rel&egrave;ve par ailleur d&#39;une obligation de l&#39;employeur.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div id=\"magicdomid127\">\r\n<ul>\r\n	<li><strong>Validation CR LE</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid485\">Le CR LE de janvier sera envoy&eacute; le 22/01 &agrave; 14h.</div>\r\n\r\n<div id=\"magicdomid129\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid551\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Prochaine AC le mardi 1</span></span></strong><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">6 mars</span></span></strong></div>\r\n\r\n<div id=\"magicdomid131\">&nbsp;</div>','2021-02-19 12:09:17',1,1,'uploads/blogarticle/602f9c58e9495.jpg'),(26,41,3,'CR de l\'Assemblée Collective du 16/03/2021','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous + C&eacute;line Recchia du Cabinet Mazars</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Ludwig, Vincent et William</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3089\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) et indicateurs Mazars : 15min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4847\">&nbsp;&nbsp;&nbsp; DAD : 60min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe : 1h30</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid11\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Tableau de suivi interne</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\">Situation au 28/02/2021 (&eacute;volution par rapport au mois pr&eacute;c&eacute;dent)</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 525 136&euro; (+38 072&euro;)</li>\r\n	<li>Commandes en cours&nbsp; : 128 422&euro; (+4 906&euro;)</li>\r\n	<li>Cumul devis &agrave; l&rsquo;&eacute;tude (pond&eacute;r&eacute;) : 261 308&euro; (+23 232&euro;)</li>\r\n	<li>Pr&eacute;visionnel fin exercice : 904 559&euro; (+67 530&euro;)</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid356\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid841\">A noter, sont inclus dans &quot;devis/&agrave; l&#39;&eacute;tude&quot; :\r\n<ul>\r\n	<li>AO EOLE/MTES : l&#39;ENT s&#39;engage sur 30 &agrave; 35 points par sprints jusqu&#39;en juin (soit environ 160points, le MTES sur au minimum 45pts, soit 85 075&euro; &agrave; r&eacute;aliser d&#39;ici &agrave; la fin de l&#39;exercice)</li>\r\n	<li>La pr&eacute;vision MSE s&#39;&eacute;l&egrave;ve &agrave; 125 628&euro; d&#39;ici &agrave; la fin de l&#39;exercice</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1035\">Soit 210 703&euro; de CA qui devrait &ecirc;tre assur&eacute; m&ecirc;me si pas consid&eacute;r&eacute; comme &eacute;tant command&eacute;. Le CA &eacute;quilibre devrait &ecirc;tre atteint &agrave; la fin de l&#39;exercice sans trop de difficult&eacute;s.</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid860\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid38\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Tableau de bord </span></span></strong><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Mazars</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid39\">pr&eacute;sent&eacute; par C&eacute;line Recchia du Cabinet Mazars :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1116\">La situation r&eacute;elle sera r&eacute;&eacute;valu&eacute;e au 30/03. (trimestrielle)</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1138\">Le chiffre d&#39;affaires au 28/02 est de 554 177&euro;.&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid41\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1139\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">DAD</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3057\">Aucun DAD n&#39;est soumis au vote pour cette s&eacute;ance.</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3058\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid5119\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Nouvelle organisation des Assembl&eacute;es Collectives</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid5127\">Les co-g&eacute;rants profitent du temps disponible pour proposer une nouvelle organisation des AC. L&#39;objectif est de raccourcir, de fluidifier et de redonner &agrave; cette assembl&eacute;e sa mission d&#39;origine, &agrave; savoir la prise de d&eacute;cision. Cette version n&#39;est pas grav&eacute;e dans le marbre et sera amen&eacute;e &agrave; &ecirc;tre modifi&eacute;e si elle ne correspond pas aux attentes. Un temps maximum sera donc donn&eacute; pour chaque &eacute;tape de l&#39;AC comme suit:&nbsp;</div>\r\n\r\n<div class=\"ace-line\">\r\n<ol>\r\n	<li><u>Pr&eacute;sentation des chiffres </u>(actuels + pr&eacute;visionnels) par Cadoles ainsi que par le cabinet Mazars = 15 minutes&nbsp;</li>\r\n	<li><u>Soumission des DAD</u>&nbsp; = 60 minutes</li>\r\n	<li><u>Questions diverses</u> = 15 minutes</li>\r\n	<li><u>Pr&eacute;sentation rapide de l&#39;avanc&eacute;e des groupes de travail </u>qui le d&eacute;sirent = 15 minutes</li>\r\n</ol>\r\n\r\n<p>L&#39;AC sera alors clause et laissera place, le reste de l&#39;apr&egrave;s-midi, au travail en groupes sur les sujets en cours.</p>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4803\">Cette organidation est pr&eacute;sent&eacute;e comme un DAD pour exemple, apr&egrave;s un tour de table, un vote informel est r&eacute;alis&eacute;.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\"><strong>Pr&eacute;sentation en d&eacute;tails :</strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4865\">L&#39;organisation propos&eacute;e&nbsp; pour les DAD est la suivante :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1553\">&nbsp;&nbsp;&nbsp; 1. Pr&eacute;sentation succinte du DAD par son ou ses auteurs</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4700\">&nbsp;&nbsp;&nbsp; 2.Possibilit&eacute; de poser 1 ou 2 questions succintes maximum aux auteurs du DAD, qui feront &eacute;galement une r&eacute;ponse rapide.</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid5082\">&nbsp;&nbsp;&nbsp; 3. Vote formel, qui sera automatiquement int&eacute;gr&eacute; sur le site daddy</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1712\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\"><strong>Remarques suite au tour de table :</strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4035\">Les questions r&eacute;currentes portent essentiellement sur la m&eacute;thodologie &agrave; employer pour d&eacute;battre des DAD puisque qu&#39;il est rappel&eacute; que l&#39;AC mensuelle n&#39;est pas le lieu appropri&eacute; :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid5095\">&nbsp;&nbsp;&nbsp; Quelle forme peuvent prendre les discussions et d&eacute;bats en amont?</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid2069\">&nbsp;&nbsp;&nbsp; Quand et o&ugrave; auront lieu des d&eacute;bats?</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid2165\">Egalement la m&eacute;thodologie et la forme du DAD sont abord&eacute;s.</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid2167\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid2186\">Quelques rappels :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4039\">&nbsp;&nbsp;&nbsp; D&eacute;finition du DAD : (Dossier d&#39;Aide &agrave; la D&eacute;cision)</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4040\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - Fruit du travail d&#39;une personne ou d&#39;un groupe de travail</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4042\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - Propose les diff&eacute;rentes options</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4049\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - Envoy&eacute; au moins 15jours avant l&#39;AC mensuelle</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid2476\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Chacun doit prendre le temps de le lire et de poser les questions n&eacute;cessaire en amont de l&#39;AC</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid2479\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid2625\">&nbsp; Autour de la question &quot;Quel est le bon lieu pour les d&eacute;bats&quot;, Philippe rappelle les possibilit&eacute;s suivantes :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4062\">&nbsp;&nbsp; &nbsp;&nbsp; - Organiser une r&eacute;unions strat&eacute;gique (associ&eacute;s)</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4063\">&nbsp; &nbsp; &nbsp; - Organiser un sondage aupr&egrave;s de tous avant de r&eacute;diger le DAD</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4867\">&nbsp; &nbsp; &nbsp; - D&eacute;clenclencher une AC exceptionnelle (tout le monde)</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4968\">&nbsp;&nbsp;&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid2509\"><strong>Vote informel :</strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4132\">Mettre en place cette nouvelle organisation :</div>\r\n\r\n<ul>\r\n	<li><strong>Pour : 8</strong></li>\r\n	<li><strong>Contre : 0&nbsp;</strong></li>\r\n	<li><strong>Abstention : 2</strong></li>\r\n</ul>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid132\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4164\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Questions diverses&nbsp;:</span></span></strong></div>\r\n\r\n<ul>\r\n	<li><strong>AG April</strong></li>\r\n</ul>\r\n\r\n<p>Quid du vote &agrave; l&#39;AG de l&#39;April ( 21 mars 2021), dont Cadoles est membre. Le vote par correspondance/d&eacute;mat&eacute;rialis&eacute;, au vu de la situation sanitaire, est limit&eacute; au jeudi 18 mars 2021. Procuration est donn&eacute;e &agrave; Benjamin Bonhard, comme chaque ann&eacute;e pour voter au nom de Cadoles, ainsi qu&#39;&agrave; Laetitia Fornerot.&nbsp;</p>\r\n\r\n<ul>\r\n	<li><strong>Proposition de Formation en communication</strong></li>\r\n</ul>\r\n\r\n<p>Formation pour l&#39;ensemble des collaborateurs Cadoles. C&eacute;line Rappeneau nous enverra dans les jours &agrave; venir, les devis re&ccedil;us suite &agrave; sa demande &agrave; divers organismes.</p>\r\n\r\n<ul>\r\n	<li><strong>Prime exceptionnelle pour le pouvoir d&#39;achat</strong></li>\r\n</ul>\r\n\r\n<p>C&eacute;line et Laetitia vont se renseigner pour savoir ce qu&#39;il en est de cette annonce &eacute;manant de notre gouvernement ce lundi 15 mars au soir.&nbsp;</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid151\">\r\n<ul>\r\n	<li><strong>Validation CR LE</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3596\">Le CR LE de f&eacute;vrier sera envoy&eacute; le 22/02 &agrave; 14h.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid4161\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Groupes de travail</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3248\">\r\n<ul>\r\n	<li><strong>Documentation AF/LS</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3282\">Un Docuwiki de dev a &eacute;t&eacute; cr&eacute;&eacute;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3342\">Le nouveau Dokuwiki de dev a &eacute;t&eacute; mis en place par Philippe.</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3471\">Arnaud propose de travailler les documents via un plug-in (tt en faisant un premier tri),</div>\r\n\r\n<div class=\"ace-line\">O&ugrave; devons nous faire se travail ? Directement en production ou sur la copie actuellement h&eacute;berg&eacute;e ici <a class=\"moz-txt-link-freetext\" href=\"https://dokuwiki.cadol.es/dokuwiki/doku.php\">https://dokuwiki.cadol.es/dokuwiki/doku.php</a> Il n&#39;y a pas v&eacute;ritablement d&#39;opinion sur la question. Seul Benjamin a demand&eacute; &agrave; ce que l&#39;on fasse plut&ocirc;t ce travail sur la copie.</div>\r\n\r\n<div class=\"ace-line\">Mais si oui il faudrait mettre la production en lecture seule. Philippe lui est plus partant pour le faire en production.</div>\r\n\r\n<div class=\"ace-line\">La d&eacute;cision n&#39;a pas &eacute;t&eacute; prise &agrave; ce jour.</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3461\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4007\">\r\n<ul>\r\n	<li><strong>Qualiopi</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3922\">Finalement nous avons r&eacute;pondu &agrave; l&#39;AO de formation EOLE. (mesure d&#39;urgence co-g&eacute;rance) La solution du portage n&#39;&eacute;tant pas possible l&eacute;galement. (sous-traitance sur la totalit&eacute; du march&eacute;)</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3892\">Nous avions malgr&eacute; tout contact&eacute; Go-On qui avait &eacute;t&eacute; tr&egrave;s r&eacute;actif et disponible. Quid de cette collaboration?</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4010\">\r\n<ul>\r\n	<li><strong>Daddy</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4133\">Des tickets ou demandes d&#39;&eacute;volutions sont &agrave; soumettre afin d&#39;avancer</div>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid153\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\"><strong>Prochaine AC le mardi 13 avril</strong></div>','2021-03-18 10:53:59',1,1,'uploads/blogarticle/60532330ccccd.jpg'),(27,41,3,'CR de l\'Assemblée Collective du 11/05/2021','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous + C&eacute;line Recchia et Nicolas Bourgeois du Cabinet Mazars</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Teddy (pv Arnaud), Benjamin G (pv William), Ludwig (pv Laetitia), Charles-Maxime</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3089\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) et indicateurs Mazars : 15min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4847\">&nbsp;&nbsp;&nbsp; DAD : 60min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe : 1h30</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid11\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">A noter : l&#39;AC du mois d&#39;avril a &eacute;t&eacute; annul&eacute;e. (migration des serveurs de l&#39;Arquebuse vers Jaur&egrave;s, indispo de Daddy)</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Tableau de suivi interne</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\">Situation au 30/04/2021 (&eacute;volution par rapport au mois pr&eacute;c&eacute;dent)</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 674 335&euro; (+95 468&euro;)</li>\r\n	<li>Commandes en cours planifi&eacute;es sur l&#39;exercice en cours : 140 867&euro; (-6 304&euro;)</li>\r\n	<li>Cumul devis &agrave; l&rsquo;&eacute;tude r&eacute;alisables sur l&#39;ex en cours (pond&eacute;r&eacute;) : 87 853&euro; (-67 679&euro;)</li>\r\n	<li>Pr&eacute;visionnel fin exercice : 903 056&euro; (+21 486&euro;)</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.&nbsp;</div>\r\n\r\n<p>Le CA &eacute;quilibre devrait &ecirc;tre atteint &agrave; la fin de l&#39;exercice sans trop de difficult&eacute;s, le CA objectif &eacute;galement en consid&eacute;rant des charges inf&eacute;rieures (embauche pr&eacute;vue non r&eacute;alis&eacute;e).</p>\r\n\r\n<p>Des stats avec des regroupements par projets op&eacute;rationnels sont &eacute;galement mise &agrave; disposition. Elles &eacute;volueront en fonction des projets op&eacute;rationnels qui doivent encore &ecirc;tre d&eacute;finis.</p>\r\n\r\n<p>Une premi&egrave;re version de stats hors projets op&eacute;rationnels (temps non facturables) est &eacute;galement disponible. Cette version &eacute;voluera en fonction des retours et des besoins formul&eacute;s par chacun.</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid860\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid38\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Tableau de bord </span></span></strong><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Mazars</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid39\">pr&eacute;sent&eacute; par C&eacute;line Recchia/Nicolas Bourgeois du Cabinet Mazars :</div>\r\n\r\n<p>Les r&eacute;sultats suite &agrave; l&#39;arr&ecirc;t&eacute; au 30/03 confirment que nos objectifs devraient &ecirc;tre atteints &agrave; la fin de l&#39;exercice.</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid41\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1139\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">DAD</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3057\"><strong>Fluidifier les AC gr&acirc;ce &agrave; Daddy : reprogrammer du temps de d&eacute;veloppement</strong></div>\r\n\r\n<div class=\"ace-line\">Il manque l&#39;estimation du temps de d&eacute;veloppement n&eacute;cessaire, le vote est ajourn&eacute;.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\"><strong>Participer &agrave; une formation Communication</strong></div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Pour : 11</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Contre : 1</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Abstention : 0</div>\r\n\r\n<div class=\"ace-line\">=&gt;Proposition adopt&eacute;e</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\"><strong>Choix d&#39;un prestataire pour la formation communication</strong></div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">GFC : 11</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Orsys : 0</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Abstention : 1</div>\r\n\r\n<div class=\"ace-line\">=&gt; GFC est retenu, C&eacute;line et Arnaud vont planifier cette formation avec GFC</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\"><strong>Proposition de d&eacute;finition de &quot;Coordinateur d&#39;activit&eacute;&quot;</strong></div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Pour : 12</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Contre : 0</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Abstention : 0</div>\r\n\r\n<div class=\"ace-line\">=&gt;Proposition adopt&eacute;e, PR &agrave; valider par Emmanuel</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\"><strong>Proposition de d&eacute;finition de &quot;R&eacute;f&eacute;rent commercial et financier&quot;</strong></div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Pour : 12</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Contre : 0</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Abstention : 0</div>\r\n\r\n<div class=\"ace-line\">=&gt;Proposition adopt&eacute;e, PR &agrave; valider par Emmanuel</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\"><strong>Proposition de d&eacute;finition de &quot;R&eacute;f&eacute;rent projet &amp; technique&quot;</strong></div>\r\n\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Pour : 12</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Contre : 0</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Abstention : 0</div>\r\n\r\n<div class=\"ace-line\">=&gt;Proposition adopt&eacute;e, PR &agrave; valider par Emmanuel</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\"><strong>Migration du serveur Sentry</strong></div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Solution externalis&eacute;e SAAS : 0</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Solution upgrade de l&#39;actuel : 11</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Solution internalis&eacute;e nelle infra : 0</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Ne rien faire : 0</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Abstention : 1</div>\r\n\r\n<div class=\"ace-line\">=&gt; Solution Solution upgrade de l&#39;actuel valid&eacute;e, cr&eacute;ation d&#39;un projet op&eacute;rationnel + budget</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Questions diverses&nbsp;:</span></span></strong></p>\r\n\r\n<ul>\r\n	<li><strong>Vaccination COVID, par Arnaud</strong></li>\r\n</ul>\r\n\r\n<p>Serait il possible, pour ceux qui le souhaitent et qui obtiennent un cr&eacute;neau en journ&eacute;e, de se faire vacciner sur son temps de travail ? (sans r&eacute;cup&eacute;ration)</p>\r\n\r\n<p>Un tour de table est effectu&eacute;, les avis sont soit favorables soit non prononc&eacute;s, pas d&#39;avis d&eacute;favorable.</p>\r\n\r\n<p>=&gt; La co-g&eacute;rance va consulter les aspects juridiques et faire un retour officiel.</p>\r\n\r\n<ul>\r\n	<li><strong>Budget 2021-2022</strong></li>\r\n</ul>\r\n\r\n<p>C&eacute;line et Laetitia ont sollicit&eacute; Celine RECCHIA du cabinet Mazars pour initier le budget de l&#39;exercice 2021-2022.</p>\r\n\r\n<p>=&gt; Cr&eacute;ation d&#39;un groupe de travail et appel &agrave; volontaires</p>\r\n\r\n<ul>\r\n	<li><strong>Finalisation d&eacute;m&eacute;nagement</strong></li>\r\n</ul>\r\n\r\n<p>Laetitia va retourner r&eacute;cup&eacute;rer le materiel restant le 12/05. Un dernier coup de m&eacute;nage rapide sera effectu&eacute; par l&#39;entretien dijonnais avant la vente.</p>\r\n\r\n<p>Merci de rapporter vos cl&eacute;s rapidement, la vente officielle avec remise des cl&eacute;s a lieu le 28/05.</p>\r\n\r\n<ul>\r\n	<li><strong>Fin du contrat de Ludwig le 15/06</strong></li>\r\n</ul>\r\n\r\n<p>Le contrat d&#39;alternance de Ludwig prend fin le 15/06. Il a &eacute;mis le souhait de poursuivre ses &eacute;tudes en alternance en septembre. Quid de la p&eacute;riode juin &agrave; septembre? R&eacute;-engagement avec un nouveau contrat d&#39;alternance?</p>\r\n\r\n<p>=&gt; une d&eacute;cision en urgence de la co-g&eacute;rance s&#39;impose, Emmanuel son tuteur y prendra part</p>\r\n\r\n<ul>\r\n	<li><strong>Contribution &agrave; verser aux logiciels libres</strong></li>\r\n</ul>\r\n\r\n<p>La d&eacute;finition des destinataires de notre contribution est &agrave; finaliser avant la fin de l&#39;exercice.</p>\r\n\r\n<p>=&gt; le groupe de travail doit travailler dessus &agrave; l&#39;issue de la s&eacute;ance</p>\r\n\r\n<ul>\r\n	<li><strong>Prime exceptionnelle pour le pouvoir d&#39;achat</strong></li>\r\n</ul>\r\n\r\n<p>Manque d&#39;infos pour le moment, ne concernera pas l&#39;exercice en cours.</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid151\">\r\n<ul>\r\n	<li><strong>Validation CR LE</strong></li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3596\">Le CR LE de mars/avril sera envoy&eacute; le 20/05 &agrave; 14h.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid153\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\"><strong>Prochaine AC le mardi 15 juin</strong></div>','2021-05-17 11:22:07',1,1,'uploads/blogarticle/60a2361e34c06.jpg'),(28,41,3,'CR de l\'Assemblée Collective du 15/06/2021','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous + C&eacute;line Recchia et Nicolas Bourgeois du Cabinet Mazars</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Ludwig</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3089\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) et indicateurs Mazars : 15min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4847\">&nbsp;&nbsp;&nbsp; DAD : 60min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe : 1h30</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid11\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Tableau de suivi interne</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\">Situation au 30/04/2021 (&eacute;volution par rapport au mois pr&eacute;c&eacute;dent)</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 752 816&euro; (+78 481&euro;)</li>\r\n	<li>Commandes en cours planifi&eacute;es sur l&#39;exercice en cours : 80 794&euro; (-60 073&euro;)</li>\r\n	<li>Cumul devis &agrave; l&rsquo;&eacute;tude r&eacute;alisables sur l&#39;ex en cours (pond&eacute;r&eacute;) : 0&euro; (-87 853&euro;)</li>\r\n	<li>Pr&eacute;visionnel fin exercice : 899 943&euro;</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.&nbsp;</div>\r\n\r\n<p>Le CA &eacute;quilibre devrait &ecirc;tre atteint &agrave; la fin de l&#39;exercice sans trop de difficult&eacute;s, le CA objectif &eacute;galement en consid&eacute;rant des charges inf&eacute;rieures (embauche pr&eacute;vue non r&eacute;alis&eacute;e).</p>\r\n\r\n<p>Des stats avec des regroupements par projets op&eacute;rationnels sont &eacute;galement mises &agrave; disposition. Elles &eacute;volueront en fonction des projets op&eacute;rationnels qui doivent encore &ecirc;tre d&eacute;finis.</p>\r\n\r\n<p>Une premi&egrave;re version de stats hors projets op&eacute;rationnels (temps non facturables) est &eacute;galement disponible. Cette version &eacute;voluera en fonction des retours et des besoins formul&eacute;s par chacun.</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid860\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid38\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Tableau de bord </span></span></strong><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Mazars</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid39\">pr&eacute;sent&eacute; par C&eacute;line Recchia/Nicolas Bourgeois du Cabinet Mazars :</div>\r\n\r\n<p>Les pr&eacute;visions de r&eacute;sultats net avant imp&ocirc;t &agrave; la fin de l&#39;exercice sont estim&eacute;s &agrave; +147 000&euro;.</p>\r\n\r\n<p>A noter :</p>\r\n\r\n<ul>\r\n	<li>le r&eacute;sultat net avant imp&ocirc;t ne fait pas &eacute;tat du r&eacute;sultat exceptionnel issu de la vente du local de l&#39;Arquebuse (+ 45 000&euro; environ)</li>\r\n	<li>Interressement : calcul&eacute; sur le r&eacute;sultat net avant imp&ocirc;t (25% du r&eacute;sultat soit environ 30 K&euro; &agrave; partager)</li>\r\n	<li>Participation : calcul&eacute;e sur le r&eacute;sultat net avant imp&ocirc;t + r&eacute;sultat exceptionnel (1/2 = participation / 1/2 = r&eacute;serves)</li>\r\n	<li>Le calcul les montants de la participation sera r&eacute;alis&eacute; au plus tard en octobre, apr&egrave;s la cl&ocirc;ture des comptes (d&eacute;p&ocirc;t pr&eacute;vu au plus tard le 15/10)</li>\r\n</ul>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid41\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1139\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">DAD</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3057\"><strong>Ludwig : Poursuite d&#39;&eacute;tude en alternance avec le CESI &agrave; Cadoles septembre 2021 &agrave; mars 2023</strong></div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Pour : 10</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Contre : 0</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Abstention : 0</div>\r\n\r\n<div class=\"ace-line\">=&gt;Proposition adopt&eacute;e</div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Groupes de travail :</span></span></strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li><strong>T&eacute;l&eacute;travail</strong></li>\r\n</ul>\r\n\r\n<p>RAS, le groupe va reprendre les travaux &agrave; l&#39;issue de l&#39;AC.</p>\r\n\r\n<ul>\r\n	<li><strong>Am&eacute;nagement des bureaux</strong></li>\r\n</ul>\r\n\r\n<p>Sujet d&eacute;co &agrave; relancer</p>\r\n\r\n<ul>\r\n	<li><strong>Nouvelle infra</strong></li>\r\n</ul>\r\n\r\n<p>Tout a &eacute;t&eacute; migr&eacute;</p>\r\n\r\n<ul>\r\n	<li><strong>Risotto</strong></li>\r\n</ul>\r\n\r\n<p>Pas de nouveaux travaux pour le moment, peut-&ecirc;tre cet &eacute;t&eacute;</p>\r\n\r\n<ul>\r\n	<li><strong>Budget 2021-2022</strong></li>\r\n</ul>\r\n\r\n<p>C&eacute;line et Laetitia ont sollicit&eacute; Celine RECCHIA du cabinet Mazars pour initier le budget de l&#39;exercice 2021-2022.</p>\r\n\r\n<p>Le groupe se r&eacute;unit &agrave; l&#39;issue de l&#39;AC pour travailler sur la partie &quot;charges&quot;</p>\r\n\r\n<ul>\r\n	<li><strong>Contribution &agrave; verser aux logiciels libres</strong></li>\r\n</ul>\r\n\r\n<p>Le d&eacute;pouillement du vote a eu lieu, curl et gitea seront les projets soutenus</p>\r\n\r\n<p>Le versement est &agrave; faire rapidement pour &ecirc;tre pris en compte sur l&#39;exercice.</p>\r\n\r\n<ul>\r\n	<li><strong>Site web</strong></li>\r\n</ul>\r\n\r\n<p>un groupe de travail a &eacute;t&eacute; cr&eacute;&eacute;</p>\r\n\r\n<ul>\r\n	<li><strong>Travail autour des activit&eacute;s Scop Cadoles</strong></li>\r\n</ul>\r\n\r\n<p>Logique d&eacute;finie, livraison schedule faite ce jour</p>\r\n\r\n<ul>\r\n	<li><strong>Validation CR LE</strong></li>\r\n</ul>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3596\">Le CR LE de mai sera envoy&eacute; le 24/06 &agrave; 14h.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid153\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\"><strong>Prochaine AC le mardi 13 juillet</strong></div>','2021-06-17 12:02:20',1,1,'uploads/blogarticle/60cb1e1905148.jpg'),(29,41,3,'CR de l\'Assemblée Collective du 13/07/2021','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous + C&eacute;line Recchia, Benjamin Ledter et Nicolas Bourgeois du Cabinet Mazars</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Benjamin B (pv Emmanuel), Vincent (pv Philippe)</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3089\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) et indicateurs Mazars : 15min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4847\">&nbsp;&nbsp;&nbsp; DAD : 60min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe : 1h30</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid11\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Tableau de suivi interne</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\">Situation au 30/06/2021 (fin d&#39;exercice)</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 816 332&euro;</li>\r\n	<li>Travaux r&eacute;alis&eacute;s sur l&#39;exercice, non factur&eacute;s au 30/06 : 86 213&euro;</li>\r\n	<li>Fin exercice : 902 545&euro;</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.&nbsp;</div>\r\n\r\n<p>Un &eacute;cart sur le CA entre ces chiffres et ceux de Mazars est expliqu&eacute; par une prise en compte diff&eacute;rente des en-cours de l&#39;exercice pr&eacute;c&eacute;dent (&eacute;cart connu). En dehors de cel&agrave;, le suivi interne est conforme aux tableaux de bords r&eacute;alis&eacute;s par notre comptable, ce qui confirme leur pertinence.</p>\r\n\r\n<p>Des stats avec des regroupements par projets op&eacute;rationnels sont &eacute;galement mises &agrave; disposition. Elles &eacute;volueront en fonction des projets op&eacute;rationnels qui doivent encore &ecirc;tre d&eacute;finis. L&#39;objectif &eacute;tant d&#39;avoir ce regroupement d&egrave;s le d&eacute;but de l&#39;exercice suivant.</p>\r\n\r\n<p>Une premi&egrave;re version de stats hors projets op&eacute;rationnels (temps non facturables) est &eacute;galement disponible. Cette version &eacute;voluera en fonction des retours et des besoins formul&eacute;s par chacun. L&#39;ajout d&#39;une statistique des jours clients / jours pr&eacute;sents (hors CP et maladie) est demand&eacute;.</p>\r\n\r\n<p>Une pr&eacute;sentation plus d&eacute;taill&eacute;e sera effectu&eacute;e &agrave; chaque fin de trimestre. (hors projets op&eacute;rationnels, d&eacute;tails)</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid860\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid38\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Tableau de bord </span></span></strong><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Mazars</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid39\">pr&eacute;sent&eacute; par C&eacute;line Recchia/Nicolas Bourgeois du Cabinet Mazars :</div>\r\n\r\n<p>Les pr&eacute;visions de r&eacute;sultats net avant imp&ocirc;t &agrave; la fin de l&#39;exercice sont estim&eacute;s &agrave; +78 937&euro;. (hors participation, prime d&#39;activit&eacute; &eacute;ventuelle et provision Eliade)</p>\r\n\r\n<p>A noter :</p>\r\n\r\n<ul>\r\n	<li>r&eacute;sultat exceptionnel issu de la vente du local de l&#39;Arquebuse (+ 37 105&euro;)</li>\r\n	<li>Prime d&#39;activit&eacute; : &agrave; priori nous pourrions verser 2 000&euro;/pers maxi (pas de charges, ni d&#39;imp&ocirc;t sur le revenu) : d&eacute;cision &agrave; prendre rapidement (prochaine AC)</li>\r\n	<li>Provision litige Eliade : nous devons estimer si nous devons provisionner une somme en pr&eacute;vision du proc&egrave;s et quel montant, info &agrave; communiquer &agrave; Mazars au plus tard mi-sept (prochaine AC le 15/09)</li>\r\n	<li>Le calcul les montants de la participation sera r&eacute;alis&eacute; au plus tard en octobre, apr&egrave;s la cl&ocirc;ture des comptes (d&eacute;p&ocirc;t pr&eacute;vu au plus tard le 15/10)</li>\r\n</ul>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid41\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">A l&#39;issue de l&#39;AC, un groupe de travail effectuera des simulations avec Mazars pour d&eacute;terminer diff&eacute;rents sc&eacute;narios possibles.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid1139\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">DAD</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3057\"><strong>Organisation d&#39;un s&eacute;minaire Scop Cadoles (port&eacute; par Benjamin G et Emmanuel)</strong></div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Pour : 13</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Contre : 0</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Abstention : 0</div>\r\n\r\n<div class=\"ace-line\">=&gt;Proposition adopt&eacute;e, groupe de travail &agrave; constituer</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3057\"><strong>Embauche ing&eacute;nieur syst&egrave;me (port&eacute; par Philippe)</strong></div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Pour : 13</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Contre : 0</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Abstention : 0</div>\r\n\r\n<div class=\"ace-line\">=&gt;Proposition adopt&eacute;e &agrave; la condition d&#39;un accord sur la mise &agrave; dispo de Philippe &agrave; 80% sur EOLE 3, sinon un nouveau DAD sera soumis</div>\r\n\r\n<div class=\"ace-line\">&nbsp;&nbsp;&nbsp;&nbsp; Cr&eacute;ation d&#39;un groupe de travail</div>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Groupes de travail :</span></span></strong></p>\r\n\r\n<ul>\r\n	<li><strong>Simulations d&eacute;cisions de fin d&#39;exercice avec Mazars</strong></li>\r\n</ul>\r\n\r\n<p>Objectif : r&eacute;aliser des simulations avec Prime d&#39;activit&eacute;/interressement/participation/provision litige Elliade pour prise de d&eacute;cision lors de la prochaine AC</p>\r\n\r\n<ul>\r\n	<li><strong>Embauche ing&eacute;nieur syst&egrave;me</strong></li>\r\n</ul>\r\n\r\n<p>Objectif : pr&eacute;parer l&#39;annonce &agrave; faire para&icirc;tre (profil, comp&eacute;tences...)</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3596\">\r\n<ul>\r\n	<li><strong>S&eacute;minaire Scop Cadoles</strong></li>\r\n</ul>\r\n\r\n<p>Objectif : organiser un s&eacute;minaire en sept ou oct</p>\r\n</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\"><strong>Prochaine AC le mercredi 15 septembre</strong></div>','2021-07-15 09:59:15',1,1,'uploads/blogarticle/60efeb6c8f127.jpg'),(30,41,3,'CR de l\'Assemblée Collective du 14/09/2021','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Ludwig S (&agrave; l&#39;&eacute;cole, pas de procuration)</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Benjamin Ledter et Nicolas Bourgeois du Cabinet Mazars ne sont pas pr&eacute;sents suite &agrave; une mauvaise communication. (visio/pr&eacute;sentiel)</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 25min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4847\">&nbsp;&nbsp;&nbsp; DAD : 60min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe : 1h30</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid11\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Tableau de suivi interne</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\">Situation au 31/08/2021</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 68 476&euro;</li>\r\n	<li>Travaux r&eacute;alis&eacute;s sur l&#39;exercice, non factur&eacute;s au 31/08 : 35 936&euro;</li>\r\n	<li>Reste &agrave; faire sur commandes : 30 703&euro;</li>\r\n	<li>Devis &agrave; l&#39;&eacute;tude pond&eacute;r&eacute;s : 673 931</li>\r\n	<li>Fin exercice estim&eacute; : 809 047&euro;</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">Le r&eacute;alis&eacute; &agrave; fin ao&ucirc;t est comparable &agrave; celui r&eacute;alis&eacute; &agrave; fin septembre sur N-1. &Agrave; ce jour les commandes et les devis r&eacute;alis&eacute;s ne permettent pas d&#39;atteindre l&#39;&eacute;quilibre, mais nous ne sommes pas encore &agrave; la fin du premier trimestre.</div>\r\n\r\n<div class=\"ace-line\">Les pr&eacute;visions r&eacute;alis&eacute;es par C&eacute;line et Arnaud en ce d&eacute;but d&#39;exercice sont positives, avec une nette augmentation pr&eacute;vue du budget MSE et l&#39;obtention du march&eacute; avec l&#39;EFS. Nous sommes tr&egrave;s confiants.</div>\r\n\r\n<div class=\"ace-line\">\r\n<p>Le budget de l&#39;exercice n&#39;&eacute;tant pas encore vot&eacute;, le CA objectif et le CA &eacute;quilibre seront &agrave; adapter</p>\r\n\r\n<p>La pr&eacute;sentation envoy&eacute;e avant l&#39;AC n&#39;est pas assez claire, les chiffres de celle-ci ne sont pas rassurants pour certains malgr&eacute;s les explications donn&eacute;es par Arnaud et C&eacute;line. Un travail de remise en forme des donn&eacute;es sera effectu&eacute; rapidement afin de permettre une meilleure lisibilit&eacute; pour tous.</p>\r\n</div>\r\n\r\n<p>Egalement, une pr&eacute;sentation plus d&eacute;taill&eacute;e sera effectu&eacute;e &agrave; chaque fin de trimestre. (hors projets op&eacute;rationnels, d&eacute;tails)</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid860\">&nbsp;</div>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">DAD</span></span></strong></p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3057\">\r\n<p><strong>D&eacute;cisions &agrave; prendre pour la fin de l&#39;exercice 20-21</strong></p>\r\n\r\n<p>Objectif : faire un choix concernant la provision d&#39;un montant en vue du proc&egrave;s Eliade et l&#39;&eacute;ventuel versement d&#39;une prime d&#39;activit&eacute;.</p>\r\n\r\n<ul>\r\n	<li>Proposition n&deg;1 (provision 3 500&euro;, prime activit&eacute; : 0&euro;) : 0 vote</li>\r\n	<li>Propositions n&deg;2 (provision 19 500&euro;, prime activit&eacute; : 0&euro;): 1 vote</li>\r\n	<li>Proposition n&deg;3 (provision 19 500&euro;, prime activit&eacute; : 26 000&euro; - soit 2 000&euro; par collaborateur): 11 votes</li>\r\n	<li>Proposition n&deg;4 (provision 3 500&euro;, prime activit&eacute; : 26 000&euro; - soit 2 000&euro; par collaborateur): 0 vote</li>\r\n</ul>\r\n\r\n<p>=&gt; La proposition n&deg; 3 est adopt&eacute;e, la prime d&#39;activit&eacute; sera vers&eacute;e rapidement, sans proratisation (m&ecirc;me somme pour tous).</p>\r\n\r\n<p><strong>Proposition de budget pour l&#39;exercice 2021-2022 : charges</strong></p>\r\n\r\n<p>Objectif : validation des diff&eacute;rents postes de charge pour l&#39;exercice 2021-2022</p>\r\n\r\n<p>Un d&eacute;bat autour de la l&eacute;gitimit&eacute; du vote des salari&eacute;s non associ&eacute;s pour le budget &eacute;tant soulev&eacute;e (crainte de non validit&eacute; du vote), il est demand&eacute; aux collaborateurs non-associ&eacute;s de sortir de la salle et de ne pas prendre part au vote. (C&eacute;line et Charles-Maxime)</p>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Pour : 9</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Contre : 0</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">Abstention : 0</div>\r\n\r\n<p>=&gt;Vote des associ&eacute;s seuls : budget valid&eacute; &agrave; l&#39;unanimit&eacute;</p>\r\n<strong>Cr&eacute;ation d&#39;un projet op&eacute;rationnel &quot;Atelier d&#39;&eacute;change D&eacute;veloppement&quot;</strong></div>\r\n\r\n<div class=\"ace-line\">Objectif : temps commun d&#39;&eacute;change et de transfert de comp&eacute;tence pour les dev.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">Ajournement du vote :</div>\r\n\r\n<div class=\"ace-line\">Pour : 8</div>\r\n\r\n<div class=\"ace-line\">Contre :1</div>\r\n\r\n<div class=\"ace-line\">Absention : 2</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">=&gt; Vote report&eacute; pour manque de visibilit&eacute; sur le temps disponible pour ce type de projets, sera probablement abord&eacute; lors du s&eacute;minaire. N&eacute;cessit&eacute; d&#39;&eacute;laborer un budget par domaine d&#39;activit&eacute; au pr&eacute;alable.</div>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Question diverses :</span></span></strong></p>\r\n\r\n<p>La co-g&eacute;rance rappelle la n&eacute;cessit&eacute; de maintenir les gestes &quot;barri&egrave;re&quot; : port du masque, a&eacute;ration r&eacute;guli&egrave;re des locaux, distanciation... et ce en d&eacute;pit de la vaccination.</p>\r\n\r\n<p>Le planning scolaire de Ludwig ne lui permettra pas en l&#39;&eacute;tat d&#39;assister aux prochaines AC : un DAD de modification des dates sera soumis par Ludwig prochainement.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Groupes de travail :</span></span></strong></p>\r\n\r\n<ul>\r\n	<li><strong>T&eacute;l&eacute;travail</strong></li>\r\n</ul>\r\n\r\n<p>Une grosse partie du travail sur ce sujet a d&eacute;j&agrave; &eacute;t&eacute; r&eacute;alis&eacute;e. Il devient tr&egrave;s urgent de le finaliser avec la sortie de l&#39;exception de t&eacute;l&eacute;travail pour raisons sanitaires.</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3596\">\r\n<ul>\r\n	<li><strong>S&eacute;minaire Scop Cadoles</strong></li>\r\n</ul>\r\n\r\n<p>La date du 6 octobre a &eacute;t&eacute; retenue. C&eacute;line et Laetitia devront changer leur jour d&#39;absence pour temps partiel. (remboursement de la garde d&#39;enfant envisageable)</p>\r\n\r\n<p>Le s&eacute;minaire sera co-anim&eacute; par Vincent Guilleminot, notre formateur en communication. Un repas avec traiteur est pr&eacute;vu et une soir&eacute;e anniversaire 10 ans Cadoles en prolongement.</p>\r\n\r\n<p>Pas de prise de d&eacute;cision ni de r&eacute;daction de DAD pendant le s&eacute;minaire.</p>\r\n</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\"><strong>Prochaine AC le mardi 12 octobre</strong></div>','2021-09-20 09:58:32',1,1,'uploads/blogarticle/61483bcf67197.jpg'),(31,6,6,'Newsletter DEV','<h1>PROSPECTS</h1>\r\n\r\n<h2>EDSSI</h2>\r\n\r\n<p><em>European Digital Student Service Infrastruture</em></p>\r\n\r\n<p><br />\r\nProjet AMOA sur la construction du besoin en f&eacute;d&eacute;ration d&#39;identit&eacute;<br />\r\nCompl&eacute;tude de l&#39;identit&eacute; venant de RENATER<br />\r\nConcentration des offres de logements en fonction de la destination des &eacute;tudiants<br />\r\nTr&egrave;s n&eacute;buleux<br />\r\nProposition orale de 2/3 jr d&#39;assistance &agrave; d&eacute;finition du besoin &agrave; 800<br />\r\nPour l&#39;instant j&#39;attend qu&#39;ils nous donnent leurs donn&eacute;es administratives pour r&eacute;daction de la proposition dans dolibarr</p>\r\n\r\n<h2>AUDENCIA</h2>\r\n\r\n<p><em>Ecole Nantaise</em><br />\r\nSouhaite mettre en place un Idp afin de rentrer dans la f&eacute;d&eacute;ration RENATER d&#39;ERASMUS<br />\r\nPropostion de 3 jours de prestation &agrave; 800 euros<br />\r\nEn attente de la commande</p>\r\n\r\n<h2>Accueil Paysan Bourgogne</h2>\r\n\r\n<p>Demande de devis pour recherche de fonds d&#39;investissement<br />\r\nDevis &agrave; rendre entre le 14/10 et le 29/10<br />\r\nRDV visio avec eux Lundi&nbsp;</p>\r\n\r\n<h1>CLIENTS / PROJETS</h1>\r\n\r\n<h2>Envole</h2>\r\n\r\n<p>Tr&egrave;s peu de commande &agrave; pr&eacute;voir pour l&#39;ann&eacute;e<br />\r\nEn mode ultra &eacute;conomie sur les jours consomm&eacute;s depuis le mois d&#39;Aout<br />\r\nEn attente de commande de Poitiers / Dijon / Eole / R&eacute;union</p>\r\n\r\n<h2>Mistral</h2>\r\n\r\n<p>Reste 3 jours de TMA pour aller jusqu&#39;&agrave; fin Mars<br />\r\nFaire attention &agrave; ne pas trop d&eacute;penser<br />\r\nAttendre l&#39;avanc&eacute; des travaux de maintenances syst&egrave;mes avant de les recontacter pour une potentielle rallonge</p>\r\n\r\n<h2>Transnum</h2>\r\n\r\n<p>Reste 13 jours de TMA &agrave; consommer dans l&#39;ann&eacute;e<br />\r\nLe Chef de Projet va changer en d&eacute;but d&#39;ann&eacute;e prochaine<br />\r\nSouhaitera surement d&eacute;penser son reste de jours<br />\r\nNormalement un projet de migration d&#39;infrastructure est dans en pr&eacute;vision depuis un moment avec le Rectorat de Dijon<br />\r\nMais cela ne bouge pas depuis plus d&#39;un an &agrave; pr&eacute;sent</p>\r\n\r\n<h2>Sympa</h2>\r\n\r\n<p>Prestation de 5 jours termin&eacute;s : upgrade syst&egrave;me + upgrade sympa + &eacute;l&eacute;ment de s&eacute;curit&eacute; + debug<br />\r\nRelance par 2 fois le CNOUS pour avoir la commande afin que l&#39;on puisse facturer<br />\r\nIls font le mort ... Relanc&eacute; pour une troisi&egrave;me fois le 07/10</p>\r\n\r\n<h2>Pyxis Orion</h2>\r\n\r\n<p>Prestation de 21 jours en cours de finalisation<br />\r\nQuelques bugs &eacute;taient en attentes. Ils&nbsp;ont pu &ecirc;tre r&eacute;solus cette semaine<br />\r\nR&eacute;union pr&eacute;vue le 12/10 avec Pyxis pour s&#39;accorder sur la fin de prestation</p>\r\n\r\n<h2>Xibo</h2>\r\n\r\n<p>Reste &agrave; 0.5j pour traiter un petit bug<br />\r\nA se d&eacute;barrasser car cela traine depuis trop longtemps</p>\r\n\r\n<h2>BFC Nature</h2>\r\n\r\n<p>Prestation de 14 jours en cours de finalisation<br />\r\nD&eacute;veloppement r&eacute;alis&eacute;<br />\r\nEn attente de l&#39;environnement client pour installation et recette<br />\r\nSurement quelques points seront &agrave; r&eacute;aliser durant la phase de recette<br />\r\nDevrait se finaliser nous l&#39;esp&eacute;rons d&eacute;but Novembre</p>\r\n\r\n<h2>Quid</h2>\r\n\r\n<p>Le projet rentre en phase de nationalisation<br />\r\nLa premi&egrave;re &eacute;tape &eacute;tant de d&eacute;ployer la solution en Bretagne et/ou Grand Est<br />\r\nProposition mat&eacute;riels et installation &eacute;mise<br />\r\nEn attente de signature de la proposition<br />\r\nOn peut s&#39;attendre &agrave; des demandes d&#39;&eacute;volution &quot;Quid App&quot; durant le premier semestre 2022</p>\r\n\r\n<h2>Sheila</h2>\r\n\r\n<p>Officiellement un budget de 100000 mais officieusement 170000<br />\r\nChangement du plan it&eacute;ratif demand&eacute; par le client pour commencer les points &quot;m&eacute;tiers&quot; avant les points &quot;permissions&quot;<br />\r\nD&eacute;mo du projet fin d&#39;ann&eacute;e &agrave; destination des d&eacute;cideurs EFS<br />\r\nVoir s&#39;il est possible d&#39;augmenter le nombre d&#39;ETP allou&eacute; au projet d&#39;ici la fin d&#39;ann&eacute;e&nbsp;<br />\r\nPour l&#39;instant pas de solution possible en tout cas pour l&#39;it&eacute;ration &agrave; venir</p>\r\n\r\n<h2>MSE</h2>\r\n\r\n<p>Sujets en cours<br />\r\n- It&eacute;ration INES 1<br />\r\n- S&eacute;paration de l&#39;identit&eacute;<br />\r\n- OpenID</p>\r\n\r\n<p>Fin Octobre d&eacute;cision sur le lancement des travaux sur l&#39;OPENID<br />\r\nMais quoi qu&#39;il arrive il faudra que les travaux OPENID puisse commencer en 2021</p>\r\n\r\n<p>Difficult&eacute; sur le projet<br />\r\n- Charge de travail constant jusqu&#39;&agrave; Aout 2022<br />\r\n- Sujet surprise en d&eacute;but d&#39;ann&eacute;e<br />\r\n- Rappeler au CROUS qu&#39;il ne faut pas chercher &agrave; parrall&eacute;liser les sujets<br />\r\n- Role de Benjamin CP + Dev pas tenable</p>\r\n\r\n<p>En r&eacute;union l&#39;&eacute;quipe semble dire que d&eacute;dier une ressource &agrave; la conduite serait peut-&ecirc;tre la solution.<br />\r\nVoir mettre Arnaud en full CP sur le projet<br />\r\nP&eacute;riode de transfert de comp&eacute;tence et donc du coup indispensable pour faire cette bascule.<br />\r\nMais voil&agrave; ajouter une ressource de CP ne permettra pas d&#39;augmenter les ETP d&eacute;di&eacute;s au projet car actuellement d&eacute;j&agrave; au taquet des possibilit&eacute;s financi&egrave;res du client</p>\r\n\r\n<p>Relancer le sujet de la r&eacute;union annuelle avec le client.<br />\r\nAfin de bien pr&eacute;parer l&#39;ann&eacute;e 2022 et potentiellement faire passer une augmentation des ETP</p>\r\n\r\n<p>Augmentation des ETP en vigueur depuis Septembre 2022<br />\r\nPassage de 45/50jr par mois &agrave; 90jr par mois<br />\r\nPeut-&ecirc;tre attendre un peu de voir si cette augmentation d&#39;effectif a eu un v&eacute;ritable impact sur le projet</p>\r\n\r\n<p><br />\r\n&nbsp;</p>','2021-10-07 15:14:55',1,1,'uploads/blogarticle/615ef0657849a.jpg'),(32,41,3,'CR de l\'Assemblée Collective du 12/10/2021','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous (Teddy en visio) + Nicolas Bourgeois du Cabinet Mazars</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Benjamin G, Charles-Maxime</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 25min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4847\">&nbsp;&nbsp;&nbsp; DAD : 60min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe : 1h30</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid11\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Tableau de suivi interne</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\">Situation au 30/10/2021</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 96 684&euro; (+28 216&euro;)</li>\r\n	<li>Travaux r&eacute;alis&eacute;s sur l&#39;exercice, non factur&eacute;s au 30/09 : 94 101&euro;</li>\r\n	<li>Reste &agrave; faire sur commandes : 43 920&euro;</li>\r\n	<li>Devis &agrave; l&#39;&eacute;tude pond&eacute;r&eacute;s : 673 931</li>\r\n	<li>Fin exercice estim&eacute; : 840 028&euro; (+30 981&euro;)</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&Agrave; ce jour les commandes et les devis r&eacute;alis&eacute;s ne permettent pas d&#39;atteindre l&#39;&eacute;quilibre, mais les perspectives annonc&eacute;es par nos clients sont bonnes et la situation devrait &eacute;voluer favorablement.</div>\r\n\r\n<div class=\"ace-line\">\r\n<p>Le budget de l&#39;exercice n&#39;&eacute;tant pas encore vot&eacute;, le CA objectif et le CA &eacute;quilibre seront &agrave; adapter</p>\r\n\r\n<p>Suite &agrave; la derni&egrave;re AC, la pr&eacute;sentation des indicateurs a &eacute;volu&eacute; pour permettre une meilleure lisibilit&eacute;.</p>\r\n\r\n<p>Les remarques et conseils apport&eacute;s par Nicolas Bourgeois et les remarques effectu&eacute;es en AC seront pris en comptes. Diverses pistes d&#39;am&eacute;liorations seront consid&eacute;r&eacute;es :</p>\r\n\r\n<ul>\r\n	<li>normaliser et am&eacute;liorer la saisie dans schedule (donn&eacute;es de base)</li>\r\n	<li>analyse de la rentabilit&eacute; (et pas du CA seulement)</li>\r\n	<li>CA mensuel compar&eacute; au CA mensuel N-1 (pas seulement cumul)</li>\r\n	<li>R&eacute;flexion autour d&#39;indicateurs non financiers : p&eacute;nibilit&eacute;, ambiance etc.</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid860\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Indicateurs Mazars</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">La situation &agrave; fin de trimestre sera pr&eacute;sent&eacute;e d&egrave;s la cl&ocirc;ture finale des comptes.</div>\r\n</div>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">DAD</span></span></strong></p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3057\">\r\n<p><strong>Pas de DAD soumis au vote.</strong></p>\r\n</div>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Question diverses :</span></span></strong></p>\r\n\r\n<ul>\r\n	<li><strong>Prestations Mazars</strong></li>\r\n</ul>\r\n\r\n<p>Nicolas Bourgeois fait un &eacute;tat des lieux sur les prestations. La prestation de conseil factur&eacute;e 1 200&euro;/mois a &eacute;t&eacute; tr&egrave;s utilis&eacute;e la premi&egrave;re ann&eacute;e, beaucoup moins sur l&#39;exercice &eacute;coul&eacute;. La tendance &eacute;tant &agrave; la baisse, Mazars propose de r&eacute;duire cette prestation &agrave; 600&euro;/mois.</p>\r\n\r\n<p>Les autres prestations restent pour le moment inchang&eacute;es. (compta, payes)</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>D&#39;autre part, Nicolas Bourgeois rappelle (suite &agrave; notre question lors de la derni&egrave;re AC) que les d&eacute;cisions prises en AC n&#39;ont pas de valeur juridique. Les co-g&eacute;rants ont officiellement tout pouvoir de d&eacute;cision. (statuts bas&eacute;s sur la SARL) Les co-g&eacute;rants s&#39;engagent moralement &agrave; suivre les avis vot&eacute;s en AC.</p>\r\n\r\n<p>La r&eacute;daction d&#39;un r&egrave;glement int&eacute;rieur d&eacute;finissant le fonctionnement des AC serait souhaitable, attention toutefois, ce fonctionnement ne peut &ecirc;tre contraire aux dispositions des statuts.</p>\r\n\r\n<p>Il est n&eacute;ammmoins possible de rajouter une clause de limitation des pouvoirs de la co-g&eacute;rance dans nos statuts. (au risque d&#39;alourdir les proc&eacute;dures de prise de d&eacute;cision)</p>\r\n\r\n<ul>\r\n	<li><strong>Internalisation de la saisie comptable</strong></li>\r\n</ul>\r\n\r\n<p>C&eacute;line a un projet personnel de formation comptable et a engag&eacute; une formation en vue d&#39;obtenir le DCG. (Dipl&ocirc;me de Comptabilit&eacute; et Gestion, financement CPF) Suite &agrave; discusssion avec la co-g&eacute;rance il est envisag&eacute; de saisir cette opportunit&eacute; pour internaliser une partie de la comptabilit&eacute; de Cadoles : tenue des comptes + d&eacute;clarations de TVA. Cette internalisation passerait d&#39;une part par l&#39;investissement personnel de C&eacute;line dans sa formation et par une formation n&eacute;cessaire au logiciel de CEGID auquel Mazars pourrait nous donner un acc&egrave;s en mode SAAS.</p>\r\n\r\n<p>Pour cela Mazars propose un accompagnement de 10jours, soit 7 500&euro; sur le second semestre de l&#39;exercice, &agrave; terme l&#39;&eacute;conomie serait de 2 000&euro; par an.</p>\r\n\r\n<p>Un DAD sera pr&eacute;sent&eacute; &agrave; la prochaine AC avec tous les &eacute;l&eacute;ments (participation possible de l&#39;OPCO, avantages etc.)</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Groupes de travail :</span></span></strong></p>\r\n\r\n<ul>\r\n	<li><strong>S&eacute;minaire Scop Cadoles</strong></li>\r\n</ul>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3596\">Suite au s&eacute;minaire : apr&egrave;s avoir s&eacute;lectionn&eacute; les probl&eacute;matiques &agrave; traiter en priorit&eacute;, 2 groupes de travail ont &eacute;t&eacute; form&eacute;s sur les th&eacute;matqiues suivantes :</div>\r\n\r\n<ul>\r\n	<li>Bien-&ecirc;tre au travail (Matthieu, Emmanuel, Ludwig, C&eacute;line, William, Teddy, Charles-Maxime)</li>\r\n	<li>Mod&egrave;le d&eacute;cisionnel ( Vincent, Philippe, Benjamin B, Benjamin G, Arnaud, Laetitia)</li>\r\n</ul>\r\n\r\n<div class=\"ace-line\">Les groupes formeront des sous-groupes afin de r&eacute;colter des propositions avant de les consolider en vue de pr&eacute;sentation &agrave; la prochaine AC.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\"><strong>Prochaine AC le mardi 16 novembre</strong></div>','2021-10-19 09:53:01',1,1,'uploads/blogarticle/616e86f50e472.jpg'),(33,41,3,'CR de l\'Assemblée Collective du 16/11/2021','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous&nbsp; + Nicolas Bourgeois du Cabinet Mazars</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Vincent, Ludwig, William</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 25min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4847\">&nbsp;&nbsp;&nbsp; DAD : 60min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe : 1h30</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid11\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Tableau de suivi interne</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\">Situation au 31/10/2021</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 321 115&euro; dont 91 507&euro; factur&eacute;s d&#39;avance (+224 431&euro;)</li>\r\n	<li>Travaux r&eacute;alis&eacute;s sur l&#39;exercice, non factur&eacute;s au 31/10 : 32 700&euro;</li>\r\n	<li>Reste &agrave; faire sur commandes : 71 383&euro;</li>\r\n	<li>Devis &agrave; l&#39;&eacute;tude pond&eacute;r&eacute;s : 673 931</li>\r\n	<li>Fin exercice estim&eacute; : 843 212&euro;&nbsp; (+3 184&euro;)</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&Agrave; ce jour les commandes et les devis r&eacute;alis&eacute;s ne permettent pas d&#39;atteindre l&#39;&eacute;quilibre, mais les perspectives annonc&eacute;es par nos clients sont bonnes et la situation devrait &eacute;voluer favorablement.</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\">\r\n<p>Le budget de l&#39;exercice n&#39;&eacute;tant pas encore vot&eacute;, le CA objectif et le CA &eacute;quilibre seront &agrave; adapter</p>\r\n\r\n<p>L&#39;embauche de Laurent est pr&eacute;vue d&eacute;but janvier, le budget pr&eacute;voyait de couvrir 9 mois de salaire : le CA &eacute;quilibre peut &ecirc;tre r&eacute;-&eacute;valu&eacute; &agrave; 855 300&euro;.</p>\r\n</div>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">DAD</span></span></strong></p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3057\">\r\n<ul>\r\n	<li><strong>Embauche Laurent Gourv&eacute;nec / r&eacute;gularisation de la mesure d&#39;urgence prise par la co-g&eacute;rance</strong></li>\r\n</ul>\r\n\r\n<p>Embauche en CDI &agrave; temps plein au salaire s&eacute;nior &agrave; partir du 03/01.</p>\r\n\r\n<ul>\r\n	<li><strong>Ch&egrave;ques No&euml;l 2021</strong></li>\r\n</ul>\r\n\r\n<p>Ch&egrave;ques Cadeau d&#39;un montant de 171&euro; / salari&eacute;s en ch&egrave;que Cadhoc ou autre enseigne :</p>\r\n\r\n<ul style=\"margin-left:80px\">\r\n	<li>pour : 7</li>\r\n	<li>contre : 2</li>\r\n	<li>abstention : 1</li>\r\n</ul>\r\n\r\n<p>Ch&egrave;ques Cadeau pour les enfants &agrave; charge&nbsp; :</p>\r\n\r\n<ul style=\"margin-left:80px\">\r\n	<li>pour : 1</li>\r\n	<li>contre : 5</li>\r\n	<li>abstention : 4</li>\r\n</ul>\r\n\r\n<p>-&gt; Merci de faire part &agrave; Laetitia de votre <strong>pr&eacute;f&eacute;rence Cadhoc ou autre enseigne avant le 23/11</strong>. (&agrave; d&eacute;faut, ce sera ch&egrave;que Cadhoc)</p>\r\n\r\n<ul>\r\n	<li><strong>Internalisation de la comptabilit&eacute; (saisie + d&eacute;claration de TVA) par C&eacute;line + formation Mazars n&eacute;cessaire</strong>\r\n\r\n	<ul style=\"margin-left:40px\">\r\n		<li>pour : 10</li>\r\n		<li>contre : 0</li>\r\n		<li>abstention : 0</li>\r\n	</ul>\r\n	</li>\r\n</ul>\r\n\r\n<p>-&gt;La convention de formation sera sign&eacute;e rapidement pour un d&eacute;but de formation en janvier.</p>\r\n</div>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Question diverses :</span></span></strong></p>\r\n\r\n<ul>\r\n	<li><strong>Scop Owlnext : organisation d&#39;un &eacute;change technique suivi d&#39;un afterwork</strong></li>\r\n</ul>\r\n\r\n<div class=\"body color-primary-font-color\" dir=\"auto\">Owlnext c&#39;est une SCOP bas&eacute;e &agrave; Qu&eacute;tigny. Ils font principalement du dev pour des startups, ils sont 6 (ou 7?).</div>\r\n\r\n<div class=\"body color-primary-font-color\" dir=\"auto\">Ils on l&#39;air en phase avec nos valeurs, ils ne sont pas libristes comme nous mais plut&ocirc;t bienveillants sur cet aspect des choses.</div>\r\n\r\n<p>Lors de cet &eacute;change, l&#39;id&eacute;e d&#39;organiser un &eacute;change technique entre les &eacute;quipes des deux SCOP a &eacute;t&eacute; &eacute;mise.</p>\r\n\r\n<p>Nous pourrions ainsi :</p>\r\n\r\n<ul>\r\n	<li>Partager et &eacute;changer sur nos pratiques de travail respectives</li>\r\n	<li>Identifier s&#39;ils peuvent &ecirc;tre des partenaires potentiels pour le futur, projet partag&eacute;/sous-traitance...</li>\r\n</ul>\r\n\r\n<div class=\"message-body-wrapper\">\r\n<div class=\"border-component-color color-info-font-color title\">&nbsp;</div>\r\n\r\n<div class=\"body color-primary-font-color\" dir=\"auto\">Le premier th&egrave;me pourrait tourner autour de php symphony, l&#39;&eacute;change serait sous la forme d&#39;un afterwork.</div>\r\n\r\n<div class=\"body color-primary-font-color\" dir=\"auto\">-&gt; plusieurs collaborateurs &eacute;tant interress&eacute;s, C&eacute;line va prendre contact avec Owlnext afin de d&eacute;terminer des dates possibles.</div>\r\n</div>\r\n\r\n<ul>\r\n	<li><strong>Demande de stage d&#39;observation 3&egrave;me de Nahoko MASSON (connaissance EG) du 6 au 10 d&eacute;cembre</strong></li>\r\n</ul>\r\n\r\n<p>Benjamin Gaud&eacute; se propose pour encadrer ce stage. C&eacute;line pourra &eacute;galement la prendra en charge certains jours.</p>\r\n\r\n<p>-&gt; Benjamin se charge de r&eacute;pondre &agrave; son email</p>\r\n\r\n<ul>\r\n	<li><strong>Demande de rupture conventionnelle de Teddy</strong></li>\r\n</ul>\r\n\r\n<p>Teddy nous a inform&eacute; de son souhait de quitter Cadoles en juin, id&eacute;alement par le biais d&#39;une rupture conventionnelle.</p>\r\n\r\n<p>-&gt; Une ACE est planifi&eacute;e le mardi 30/11 afin de statuer sur cette demande (DAD co-g&eacute;rance en cours)</p>\r\n\r\n<p>-&gt; l&#39;&eacute;quipe de dev va se r&eacute;unir afin de d&eacute;terminer le profil du recrutement &agrave; lancer et d&eacute;finir une strat&eacute;gie de transfert de comp&eacute;tences.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Groupes de travail :</span></span></strong></p>\r\n\r\n<ul>\r\n	<li><strong>S&eacute;minaire Scop Cadoles</strong></li>\r\n</ul>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3596\">Suite au s&eacute;minaire : apr&egrave;s avoir s&eacute;lectionn&eacute; les probl&eacute;matiques &agrave; traiter en priorit&eacute;, 2 groupes de travail ont &eacute;t&eacute; form&eacute;s sur les th&eacute;matiques suivantes :</div>\r\n\r\n<ul>\r\n	<li>Bien-&ecirc;tre au travail (Matthieu, Emmanuel, Ludwig, C&eacute;line, William, Teddy, Charles-Maxime)</li>\r\n	<li>Mod&egrave;le d&eacute;cisionnel ( Vincent, Philippe, Benjamin B, Benjamin G, Arnaud, Laetitia)</li>\r\n</ul>\r\n\r\n<p>Arnaud fait un CR de l&#39;avanc&eacute;e des travaux de son groupe :</p>\r\n\r\n<p>https://nextcloud.cadoles.com/nextcloud/index.php/apps/files/?dir=/Cadoles%20Commun/Tableaux%20de%20Bords&amp;view=-Cadoles%20Commun-Tableaux%20de%20Bords#mindmap</p>\r\n\r\n<p>Il souhaite que chacun puisse s&#39;exprimer sur la carte mentale propos&eacute;e : <strong>commentaires &agrave; faire par &eacute;crit &agrave; Arnaud avant le 26/11</strong></p>\r\n\r\n<div class=\"ace-line\" style=\"text-align:center\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" style=\"text-align:center\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" style=\"text-align:center\"><strong>ACE le mardi 30 novembre</strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\" style=\"text-align:center\"><strong>Prochaine AC le mardi 14 d&eacute;cembre</strong></div>','2021-11-18 17:32:41',1,1,'uploads/blogarticle/619763c0e7327.jpg'),(34,41,3,'CR de l\'Assemblée Collective Extraordinaire du 30/11/2021','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous&nbsp; sauf excus&eacute;s</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : William (procuration Laetitia), Benjamin G.( (procuration Matthieu), Ludwig, Teddy pour le vote du 1er DAD</div>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4847\">&nbsp;&nbsp;&nbsp; DAD : 60min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;</div>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">DAD</span></span></strong></p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3057\">\r\n<p><strong>Rupture conventionnelle Teddy selon conditions propos&eacute;es</strong></p>\r\n\r\n<ul>\r\n	<li>pour : 9</li>\r\n	<li>contre : 0</li>\r\n	<li>abstention : 2</li>\r\n</ul>\r\n\r\n<p><strong>Recrutement d&#39;un rempla&ccedil;ant</strong></p>\r\n\r\n<p>Il ne s&#39;agit pas d&#39;un remplacement poste pour poste, des transferts auront lieu en interne sur les sujets les plus complexes/sensibles.</p>\r\n\r\n<p>Profil D&eacute;veloppeur PHP/Simfony pour le projet MSE, profil junior + &agrave; interm&eacute;diaire, overloap avril/mai id&eacute;alement.</p>\r\n\r\n<ul>\r\n	<li>pour : 11</li>\r\n	<li>contre : 0</li>\r\n	<li>abstention : 0</li>\r\n</ul>\r\n\r\n<p>Pilotage du recrutement par l&#39;&eacute;quipe dev + C&eacute;line si besoin, publication des annonces d&egrave;s que possible.</p>\r\n\r\n<p>&Agrave; noter : le transfert de comp&eacute;tence en interne &agrave; organiser et &agrave; planifier : &eacute;quipe dev + C&eacute;line pour les transfert vers CSS.</p>\r\n</div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\" style=\"text-align:center\"><strong>Prochaine AC le mardi 14 d&eacute;cembre</strong></div>\r\n\r\n<p>&nbsp;</p>','2021-12-02 11:48:08',1,1,'uploads/blogarticle/61a8a4cdc4a8b.jpg'),(35,41,3,'CR de l\'Assemblée Collective du 11/01/2022','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous&nbsp; + Benjamin Ledter du Cabinet Mazars</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Benjamin G, Benjamin B (pouvoir donn&eacute; &agrave; Emmanuel)</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 20min&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp;&nbsp;&nbsp; CR COPIL : 15min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4847\">&nbsp;&nbsp;&nbsp; DAD : 60min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe : 1h30</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid11\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Tableau de suivi interne</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\">Situation au 31/10/2021</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 477 254&euro; dont 99 560&euro; factur&eacute;s d&#39;avance</li>\r\n	<li>Travaux r&eacute;alis&eacute;s sur l&#39;exercice, non factur&eacute;s au 31/12 : 43 745&euro;</li>\r\n	<li>Reste &agrave; faire sur commandes : 36 601&euro;</li>\r\n	<li>Devis &agrave; l&#39;&eacute;tude pond&eacute;r&eacute;s : 320 855&euro;</li>\r\n	<li>Fin exercice estim&eacute; : 878 455&euro;</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<p>Depuis la r&eacute;alisation de cet &eacute;tat, de nouveaux &eacute;l&eacute;ments sont apparus : L&#39;EFS peine &agrave; trouver le budget pour finaliser Sheila, notre pr&eacute;visionnel sera potentiellement &agrave; revoir &agrave; la baisse. (au pire -36K&euro;)</p>\r\n\r\n<p>D&#39;autre part, l&#39;impact du d&eacute;part annonc&eacute; par Emmanuel n&#39;est pas pris en compte.</p>\r\n\r\n<p>Le budget de l&#39;exercice n&#39;&eacute;tant pas encore vot&eacute;, le CA objectif et le CA &eacute;quilibre seront &agrave; adapter</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Situation comptable au 31/12</span></span></strong></p>\r\n\r\n<p>Benjamin Ledter, qui repr&eacute;sente le cabinet Mazars, nous fait une pr&eacute;sentation de la situation des comptes arr&ecirc;t&eacute;s au 31/12, soit &agrave; mi-exercice.</p>\r\n\r\n<p>La production de l&#39;exercice (Factur&eacute; - factur&eacute; d&#39;avance + en-cours) s&#39;&eacute;l&egrave;ve &agrave; 420 826&euro;. (le premier semestre inclue les mois d&#39;&eacute;t&eacute; relativement moins productifs)</p>\r\n\r\n<p>Les achats et charges externes sont stables par rapport &agrave; l&#39;ann&eacute;e derni&egrave;re. Les charges de personnel sont inf&eacute;rieures. (pour rappel, lors de l&#39;exercice pr&eacute;c&eacute;dent, nous avions b&eacute;n&eacute;fici&eacute; de la prime d&#39;activit&eacute; pour 26 000&euro;)</p>\r\n\r\n<p>&Agrave; ce stade, le r&eacute;sultat de l&#39;exercice est de 34 743&euro;, &agrave; nuancer toutefois car certaines charges interviendront sur la seconde partie de l&#39;exercice. (investissement renouvellement mat&eacute;riel info, charges li&eacute;es aux d&eacute;parts etc)</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">CR COPIL</span></span></strong></p>\r\n\r\n<p>Un Comit&eacute; de Pilotage hebdomadaire a &eacute;t&eacute; mis en place depuis S51-2021 par la Co-g&eacute;rance. Il est compos&eacute; de la co-g&eacute;rance et des deux coordinateurs d&#39;activit&eacute;, C&eacute;line et Arnaud. Ponctuellement, d&#39;autres personnes pourront y &ecirc;tre convi&eacute;es selon les sujets abord&eacute;s.</p>\r\n\r\n<p>L&#39;objectif est de suivre au plus pr&egrave;s les &eacute;v&egrave;nements op&eacute;rationnels de la vie de l&#39;Entreprise. (projets, finances, &eacute;quipes, prospections et opportunit&eacute;s)</p>\r\n\r\n<p>Dans un souci de transparence, des CR r&eacute;guliers seront faits &agrave; l&#39;ensemble des associ&eacute;s et salari&eacute;s.</p>\r\n\r\n<p>Le COPIL est encore en rodage, mais la co-g&eacute;rance s&#39;engage &agrave; clarifier par &eacute;crit son r&ocirc;le et ses pr&eacute;rogatives de fa&ccedil;on &agrave; les inclure dans SCOP CADOLES (sera soumis en AC). Egalement, un CR &eacute;crit sera produit r&eacute;guli&egrave;rement.</p>\r\n\r\n<p>D&#39;autre part, actuellement, Arnaud a le r&ocirc;le de surveillance de la co-g&eacute;rance : il faudra voir si ce r&ocirc;le est &agrave; modifier.</p>\r\n\r\n<p>En attendant plus de formalisme, Philippe expose les sujets abord&eacute;s lors des 2 derni&egrave;res sessions :</p>\r\n\r\n<ul>\r\n	<li><strong>&nbsp;Proposition de partenariat l&#39;entreprise Electroprotect</strong>, cette derni&egrave;re est le fournisseur de bornes wifi de l&#39;EFS. Ils souhaitent mettre en place un partenariat autour de la diffusion de la solution Quid.</li>\r\n</ul>\r\n\r\n<p>-&gt; une rencontre sera organis&eacute;e rapidement (AF)</p>\r\n\r\n<ul>\r\n	<li><strong>&nbsp;EFS</strong>\r\n\r\n	<ul>\r\n		<li>Sheila : incertitudes sur la suite du projet</li>\r\n		<li>Bloodchain, RDV le 19/01 : nouveau projet &agrave; venir, peut etre sur l&#39;exercice prochain par contre*</li>\r\n	</ul>\r\n	</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li><strong>Benjamin G :</strong> a sollicit&eacute; un entretien avec la co-g&eacute;rance, entretien qui n&#39;a pu avoir lieu du fait de son arr&ecirc;t maladie</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li><strong>Emmanuel </strong>a exprim&eacute; son souhait de quitter Cadoles au 30/04, deux options ont &eacute;t&eacute; &eacute;tudi&eacute;es lors d&#39;un entretien r&eacute;alis&eacute; avec la co-g&eacute;rance pendant lequel Emmanuel &eacute;tait repr&eacute;sent&eacute; par Teddy.\r\n\r\n	<ul>\r\n		<li>contrat d&#39;incubation : cr&eacute;ation d&#39;une activit&eacute; d&#39;Emmanuel, sous-traitance EOLE pendant une p&eacute;riode de transition, reprise de certains clients par Emmanuel</li>\r\n		<li>Rupture conventionnelle au 30/04</li>\r\n	</ul>\r\n	</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li><strong>Recrutements en cours :</strong>\r\n\r\n	<ul>\r\n		<li>D&eacute;veloppeur</li>\r\n		<li>Admin syst&egrave;me</li>\r\n	</ul>\r\n	</li>\r\n</ul>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">DAD</span></span></strong></p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3057\">\r\n<p>Vote &agrave; bulletins secrets.</p>\r\n\r\n<ul>\r\n	<li><strong>Droit de vote en AC - ADOPT&Eacute;</strong></li>\r\n</ul>\r\n\r\n<ul style=\"margin-left:80px\">\r\n	<li><strong>pour : 8</strong></li>\r\n	<li>contre : 1</li>\r\n	<li>abstention : 2</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li><strong>Construction des groupes de travail - REFUS&Eacute;</strong></li>\r\n</ul>\r\n\r\n<ul style=\"margin-left:80px\">\r\n	<li>pour : 2</li>\r\n	<li><strong>contre : 10</strong></li>\r\n	<li>abstention : 0</li>\r\n</ul>\r\n\r\n<p>L&#39;AC est lev&eacute;e. Une r&eacute;union sur les travaux effectu&eacute;s sur l&#39;organisation en Domaines est r&eacute;alis&eacute;e &agrave; la suite de l&#39;AC.</p>\r\n<strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Travaux sur les domaines / constitution budgets :</span></span></strong></div>\r\n\r\n<ul>\r\n	<li><strong>DAD Domaines : validation du principe de la carte des domaines</strong></li>\r\n</ul>\r\n\r\n<div class=\"body color-primary-font-color\" dir=\"auto\">\r\n<ul>\r\n</ul>\r\n\r\n<ul style=\"margin-left:80px\">\r\n	<li>pour : 11</li>\r\n	<li>contre : 0</li>\r\n	<li>abstention : 1</li>\r\n</ul>\r\n\r\n<p>Arnaud et C&eacute;line travaillent sur l&#39;&eacute;laboration d&#39;indicateurs par domaines.</p>\r\n</div>\r\n\r\n<ul>\r\n	<li><strong>DAD D&eacute;cider le niveau d&#39;implication de l&#39;AC dans le Mod&egrave;le Budg&eacute;taire - otion A</strong></li>\r\n</ul>\r\n\r\n<ul style=\"margin-left:80px\">\r\n	<li><strong>Option A : 7</strong></li>\r\n	<li>Option B : 1</li>\r\n	<li>Option C : 2</li>\r\n	<li>Nul : 1</li>\r\n	<li>Abstention : 2</li>\r\n	<li>Blanc : 1</li>\r\n</ul>\r\n\r\n<p><strong>Option A : </strong>Inscrire uniquement le principe dans Scop Cadoles et se r&eacute;f&eacute;rer &agrave; la Carte Mentale pour tout changement</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div class=\"ace-line\" style=\"text-align:center\">&nbsp;</div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div class=\"ace-line\" style=\"text-align:center\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" style=\"text-align:center\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\" style=\"text-align:center\"><strong>Prochaine AC le mardi 15 f&eacute;vrier</strong></div>','2022-01-14 09:55:19',1,1,'uploads/blogarticle/61e13cc20b456.jpg'),(36,41,3,'CR de l\'Assemblée Collective du 15/02/2022','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous&nbsp; + Benjamin Ledter du Cabinet Mazars</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Benjamin G, Benjamin B, Emmanuel, Vincent, Matthieu, Teddy</div>\r\n\r\n<div class=\"ace-line\">Pouvoirs : Vincent -&gt;Philippe ; Matthieu -&gt; William</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 20min&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp;&nbsp;&nbsp; CR COPIL : 45min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4847\">&nbsp;&nbsp;&nbsp; DAD :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid11\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\"><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">Tableau de suivi interne</span></span></strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\">Situation au 31/01/2022</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 524 094&euro; dont 71 730&euro; factur&eacute;s d&#39;avance</li>\r\n	<li>Travaux r&eacute;alis&eacute;s sur l&#39;exercice, non factur&eacute;s au 31/01 : 57 135&euro;</li>\r\n	<li>Reste &agrave; faire sur commandes : 78 350&euro;</li>\r\n	<li>Devis &agrave; l&#39;&eacute;tude pond&eacute;r&eacute;s : 224 335&euro;</li>\r\n	<li>Fin exercice estim&eacute; : 893 915&euro;</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<p>Pond&eacute;rations appliqu&eacute;es sur devis :</p>\r\n\r\n<ul>\r\n	<li>EFS Sheila : 0%</li>\r\n	<li>EOLE/MTES : 70%</li>\r\n	<li>MSE :75%</li>\r\n</ul>\r\n\r\n<p>Pour info, l&#39;ensemble du fichier est disponible sur Nexcloud. (&agrave; ouvrir en lecture seule!) Cadole commun/Tableaux de bord</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">CR COPIL</span></span></strong></p>\r\n\r\n<p>Les membres du COPIL font un CR de leurs travaux : explications un peu plus d&eacute;taill&eacute;es des infos contenues dans les CR envoy&eacute;s par email.</p>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">\r\n<div class=\"moz-forward-container\">\r\n<p><strong><span style=\"color:#167594\">Point sur les indicateurs CAM/CDR/PVM :</span></strong></p>\r\nCR est repartie des calculs effectu&eacute;s et valid&eacute;s l&#39;ann&eacute;e derni&egrave;re pour remettre &agrave; jour les indicateurs :</div>\r\n\r\n<ul>\r\n	<li>Co&ucirc;t de revient journalier d&#39;un salari&eacute; (CDR) = 334&euro; (ancien 305&euro;)</li>\r\n	<li>Prix de vente minimum d&#39;une journ&eacute;e (PVM) = 385&euro; (ancien 351&euro;)</li>\r\n	<li>CA moyen d&#39;une journ&eacute;e pour arriver &agrave; l&#39;objectif (CAM) = 404&euro; (ancien 383&euro;)</li>\r\n</ul>\r\n\r\n<p>Le chiffre d&#39;affaires cible a &eacute;t&eacute; d&eacute;fini par le COPIL afin de calculer le CAM. Il n&#39;a pas &eacute;t&eacute; valid&eacute; par les associ&eacute;s.</p>\r\n\r\n<p>CA cible = 920 850&euro; (CA &eacute;quilibre + 5%)</p>\r\nLe fichier de calculs est disponible sur Nexcloud pour ceux qui souhaiteraient aller plus loin dans l&#39;analyse. (merci toutefois de l&#39;ouvrir en lecture seule).</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">\r\n<p><span style=\"color:#167594\"><strong>Budgets par domaines</strong></span></p>\r\n\r\n<p>Pr&eacute;sentation des indicateurs de suivi par domaines. Les membres du COPIL sont &agrave; votre dispo si besoin d&#39;explications suppl&eacute;mentaires.</p>\r\n\r\n<p>https://nextcloud.cadoles.com/nextcloud/index.php/f/112368</p>\r\n</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">\r\n<div class=\"moz-forward-container\"><span style=\"color:#167594\"><strong>R&eacute;mun&eacute;ration</strong></span></div>\r\n\r\n<div class=\"moz-forward-container\"><br />\r\nAugmentation des salaires bas&eacute;e sur l&#39;IPC (indice des prix de la vie de l&#39;INSEE)\r\n<p>-&gt; l&#39;augmentation serait de 2,9%, soit environ 100&euro; bruts pour un senior &agrave; temps plein. Cela repr&eacute;sente une augmentation du budget &eacute;quilibre de 11 000&euro; environ pour le reste de l&#39;exercice. (de janv &agrave; juin)</p>\r\n\r\n<p><span style=\"color:#167594\"><strong>Badgeuse - Ninebadge</strong></span></p>\r\n\r\n<p>Obligation l&eacute;gale : effectuer un suivi des temps des salari&eacute;s = obligation de l&#39;employeur</p>\r\n\r\n<p>AF a d&eacute;velopp&eacute; un nouvel outil : ninebadge. Cet outil simple d&#39;utilisation permet d&#39;enregistrer des entr&eacute;es et des sorties, permet de rectifier apr&egrave;s coup et d&#39;avoir un rapport individuel et collectif.</p>\r\n</div>\r\n\r\n<div class=\"moz-forward-container\">Le suivi sera effectu&eacute; par la co-g&eacute;rance -&gt;LF. (responsabilit&eacute; de l&#39;employeur)</div>\r\n\r\n<div class=\"moz-forward-container\">&nbsp;</div>\r\n\r\n<div class=\"moz-forward-container\">Principe de base : pas d&#39;heures suppl&eacute;mentaires</div>\r\n\r\n<div class=\"moz-forward-container\">&nbsp;</div>\r\n\r\n<div class=\"moz-forward-container\">-&gt; la co-g&eacute;rance doit d&eacute;finir le cadre (souplesse, r&egrave;gles d&#39;utilisation etc.) -&gt;Co-g&eacute;rance</div>\r\n\r\n<div class=\"moz-forward-container\">-&gt; la mise en place se fera un lundi pour tt le monde, une note de service sera diffus&eacute;e prochainement -&gt;Co-g&eacute;rance\r\n<p><strong><span style=\"color:#167594\">Organisation des bureaux </span></strong></p>\r\n\r\n<p>Pr&eacute;sentation d&#39;une proposition de r&eacute;partition des bureaux. (plan joint au CR de COPIL)</p>\r\n\r\n<p>Divers objectifs :</p>\r\n\r\n<ul>\r\n	<li>Rapprocher Laetitia, C&eacute;line et Arnaud (administratif, coordination, planification)</li>\r\n	<li>Rapprocher Ludwig de Vincent/Philippe qui seront ses nouveaux tuteurs</li>\r\n	<li>Regrouper les dev MSE</li>\r\n	<li>Rapprocher Benjamin B de l&#39;&eacute;quipe CSS</li>\r\n</ul>\r\n\r\n<p>-&gt; en attente du retour des salari&eacute;s</p>\r\n\r\n<p><span style=\"color:#167594\"><strong>Plan de formation</strong></span></p>\r\n\r\n<p>Pr&eacute;paration du dossier de demande de financement en cours pour demande de financement globale du plan de formation : FNE Fond national de l&#39;emploi.</p>\r\n\r\n<p><span style=\"color:#167594\"><strong>Charte t&eacute;l&eacute;travail</strong></span></p>\r\n\r\n<p>La charte t&eacute;l&eacute;travail a &eacute;t&eacute; revue et corrig&eacute;e par le cabinet Mazars. Elle n&#39;est pas soumise &agrave; l&#39;approbation des salari&eacute;s. Cependant, elle ne sera mise en place qu&#39;apr&egrave;s relecture et &eacute;ventuels retours des salari&eacute;s. (d&eacute;lai : 15jours)</p>\r\n\r\n<p>Une note de service informera de validation d&eacute;finitive, elle ne sera applicable qu&#39;apr&egrave;s la lev&eacute;e des restrictions COVID / &eacute;tat d&#39;urgence sanitaire</p>\r\nhttps://nextcloud.cadoles.com/nextcloud/index.php/f/112520</div>\r\n&nbsp;\r\n\r\n<div class=\"moz-forward-container\"><span style=\"color:#167594\"><strong>Divers</strong></span></div>\r\n\r\n<div class=\"moz-forward-container\">&nbsp;</div>\r\n\r\n<div class=\"moz-forward-container\">-&gt; R&eacute;daction du contrat de partenariat avec Emmanuel : en cours</div>\r\n&nbsp;\r\n\r\n<div class=\"moz-forward-container\">-&gt; Partenariat avec Electrotech (suite au RDV du 09/02) : &eacute;change pas concluant, leur mod&egrave;le &eacute;conomique ne tient pas la route, rien de concret pour l&#39;instant.</div>\r\n\r\n<div class=\"moz-forward-container\">&nbsp;</div>\r\n\r\n<div class=\"moz-forward-container\">-&gt; Demande formul&eacute;e par William concernant la mise &agrave; dispo des locaux pour Hackathon ou autre : pas d&#39;objection, il faudra n&eacute;ammoins d&eacute;finir des r&egrave;gles. l&#39;&eacute;change avec Owlnext s&#39;inscrira dans la m&ecirc;me d&eacute;marche.</div>\r\n\r\n<div class=\"moz-forward-container\">William : faire un DAD pour prochaine AC</div>\r\n\r\n<div class=\"moz-forward-container\">&nbsp;</div>\r\n\r\n<div class=\"moz-forward-container\">&nbsp;\r\n<p><strong><span style=\"color:#167594\">Ordre du jour du prochain COPIL le 22/02 de 11h :</span></strong></p>\r\n\r\n<ul>\r\n	<li>Travaux sur la note de cadrage COPIL (missions etc.)</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li>Plan de formation : selon avanc&eacute;es</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li>D&eacute;part Emmanuel : point sur l&#39;avanc&eacute;e de la r&eacute;daction du contrat</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li>D&eacute;veloppement badgeuse : cadre &agrave; d&eacute;finir</li>\r\n</ul>\r\n</div>\r\n</div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong><span style=\"color:#078eb5\"><span style=\"font-size:x-large\">DAD</span></span></strong></p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3057\">RAS</div>\r\n\r\n<div class=\"ace-line\">Note : la cr&eacute;ation du COPIL n&#39;exclut pas la cr&eacute;ation de DAD !</div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\" style=\"text-align:center\"><strong>Prochaine AC le mardi 15 mars</strong></div>\r\n\r\n<p>&nbsp;</p>','2022-02-17 11:44:20',1,1,'uploads/blogarticle/620e27dcda01e.jpg'),(37,41,3,'CR de l\'AC du 15/03/2022','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous&nbsp; + Nicolas Bourgeois du Cabinet Mazars</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Benjamin B, Emmanuel</div>\r\n\r\n<div class=\"ace-line\">Pouvoirs : aucun</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 20min&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp;&nbsp;&nbsp; CR COPIL : 15min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4847\">&nbsp;&nbsp;&nbsp; DAD :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 45 min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid11\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Tableau de suivi interne</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\">Situation au 28/02/2022</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 562 764&euro; dont 41 082&euro; factur&eacute;s d&#39;avance</li>\r\n	<li>Travaux r&eacute;alis&eacute;s sur l&#39;exercice, non factur&eacute;s au 28/02 : 76 891&euro;</li>\r\n	<li>Reste &agrave; faire sur commandes : 92 584&euro;</li>\r\n	<li>Devis &agrave; l&#39;&eacute;tude pond&eacute;r&eacute;s : 182 567&euro;</li>\r\n	<li>Fin exercice estim&eacute; : 914 807&euro;</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<p>A noter :</p>\r\n\r\n<ul>\r\n	<li>EOLE : le Rectorat vient d&#39;obtenir ses budgets, ils vont &agrave; nouveau pouvoir passer des commandes, une mise en stand by du projet de 3 semaines a d&ucirc; &ecirc;tre effectu&eacute;e. (compens&eacute;e par une formation EOLE d&#39;une semaine et par quelques sc&eacute;narios MTES)</li>\r\n	<li>EFS : toujours pas de retour pour Sheila, le march&eacute; Bloodchain n&#39;arrivera sans doute pas avant l&#39;&eacute;t&eacute;.</li>\r\n	<li>MSE : le volume de commande du mois de mars est tr&egrave;s exceptionnel, nous avons tabl&eacute; sur des pr&eacute;visions plus classiques pour avril, mai et juin.</li>\r\n	<li>Pyxis : le projet pourra d&eacute;buter lorsque cela nous arrangera, cela permettra d&#39;avoir une variable d&#39;ajustement sur la charge dev</li>\r\n</ul>\r\n\r\n<p>D&#39;une&nbsp; mani&egrave;re g&eacute;n&eacute;rale les pond&eacute;rations appliqu&eacute;es sont plut&ocirc;t prudentes.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Note de Cadrage COPIL</strong></span></span></p>\r\n\r\n<p>Une note encadrant les activit&eacute;s du COPIL et son p&eacute;rim&egrave;tre d&#39;action a &eacute;t&eacute; envoy&eacute;e aux salari&eacute;s. Les associ&eacute;s sont appel&eacute;s &agrave; se prononcer sur cette note.</p>\r\n\r\n<p>Il est rappel&eacute; que le statut d&#39;observateur de la co-g&eacute;rance a &eacute;t&eacute; donn&eacute; &agrave; Arnaud en AG lors des derni&egrave;res &eacute;lections de la co-g&eacute;rance, ce qui le met en position de juge et partie. Pour changer cet &eacute;tat de fait il serait n&eacute;cessaire de faire une AG extraordinaire. L&#39;AC ne consid&egrave;re pas ce point comme bloquant dans l&#39;imm&eacute;diat.</p>\r\n\r\n<p>Vote des associ&eacute;s :</p>\r\n\r\n<ul>\r\n	<li>Pour : 9 voix</li>\r\n	<li>Contre : 0 voix</li>\r\n</ul>\r\n\r\n<p>=&gt; la note de cadrage est adopt&eacute;e et sera mise &agrave; disposition sur Nexcloud. (emplacement &agrave; d&eacute;finir)</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:22px\"><span style=\"color:#2980b9\"><strong>T&eacute;l&eacute;travail</strong></span></span></p>\r\n\r\n<p>Les dispositions extraordinaires li&eacute;es au t&eacute;l&eacute;travail du fait de la situation sanitaire ont &eacute;t&eacute; lev&eacute;es. Par cons&eacute;quent, la pr&eacute;sence au bureau redevient la norme. La charte t&eacute;l&eacute;travail s&#39;applique d&eacute;sormais, les personnes souhaitant t&eacute;l&eacute;travailler doivent en faire la demande &agrave; la co-g&eacute;rance. Si un avis favorable est &eacute;mis, un avenant au contrat de travail sera effectu&eacute;.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:22px\"><span style=\"color:#2980b9\"><strong>Poste vacant de Teddy</strong></span></span></p>\r\n\r\n<p>Lors de la phase de recrutement, de nombreuses candidatures ont &eacute;t&eacute; &eacute;tudi&eacute;es. Seules 3 personnes ont &eacute;t&eacute; retenues &agrave; l&#39;issue des tests techniques, et seules 2 ont pass&eacute; des entretiens convaincants.</p>\r\n\r\n<p>Rudy faisait partie de ces candidats, il a &eacute;t&eacute; embauch&eacute; pour pallier temporairement &agrave; l&#39;abscence de Benjamin G. Son int&eacute;gration au sein de l&#39;entreprise et son travail sugg&egrave;rent qu&#39;il a sa place au sein de Cadoles. L&#39;&eacute;quipe de dev est confiante sur ses capacit&eacute;s &agrave; progresser et &agrave; combler ses lacunes techniques.</p>\r\n\r\n<p>Les associ&eacute;s se prononcent sur son embauche en CDI au salaire junior :</p>\r\n\r\n<ul>\r\n	<li>Pour : 9 voix</li>\r\n	<li>Contre : 0 voix</li>\r\n</ul>\r\n\r\n<p>=&gt; Rudy a accept&eacute; le poste propos&eacute; &agrave; l&#39;issue du vote</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Organisation des bureaux </strong></span></span></p>\r\n\r\n<p>Suite &agrave; la proposition du COPIL, William avait fait une contre-proposition. Un d&eacute;bat sur le sujet &eacute;tait par cons&eacute;quent n&eacute;cessaire.</p>\r\n\r\n<p>L&#39;AC, apr&egrave;s &eacute;changes a d&eacute;cid&eacute; ce qui suit :</p>\r\n\r\n<ul>\r\n	<li>C&eacute;line, Arnaud et Laetitia se regroupent dans l&#39;actuel bureau d&#39;Arnaud et dans le petit bureau adjacent</li>\r\n	<li>Ludwig rejoint le bureau de Vincent/Philippe qui seront ses nouveaux tuteurs</li>\r\n	<li>L&#39;actuel bureau de Laetitia sera compos&eacute; de : Charles-Maxime, Rudy, Benjamin B et Matthieu (sous r&eacute;serve d&#39;un positionnement acceptable de 4 bureaux)</li>\r\n	<li>Les deux bureaux du fond seront r&eacute;serv&eacute;s aux personnes sur le d&eacute;part, les &quot;itin&eacute;rants&quot; (William) ou les invit&eacute;s (S&eacute;bastien).</li>\r\n	<li>Une &eacute;tude sur les possibilit&eacute;s d&#39;am&eacute;liorer les bureaux du fond sera &agrave; effectuer et &agrave; budg&eacute;tiser.</li>\r\n</ul>\r\n\r\n<p>Les mouvements peuvent &ecirc;tre faits d&egrave;s que possible &agrave; la convenances des personnes concern&eacute;es.</p>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">\r\n<div class=\"moz-forward-container\">&nbsp;\r\n<p><span style=\"font-size:22px\"><span style=\"color:#167594\"><strong>COPIL : &eacute;laboration d&#39;une proposition strat&eacute;gique pour Cadoles</strong></span></span></p>\r\n\r\n<p>Constats :</p>\r\n\r\n<p>Le projet EOLE2 est en perte de vitesse depuis plusieurs ann&eacute;es, le volume des commandes diminue d&#39;ann&eacute;es en ann&eacute;es. Son rempla&ccedil;ant, le projet EOLE3 ne d&eacute;colle pas et a du mal &agrave; se structurer.</p>\r\n\r\n<p>Le projet MSE&nbsp; occupe une place de plus en plus importante en terme de chiffre d&#39;affaire et d&#39;occcupation de nos ETP. Cela constitue un risque non n&eacute;gligeable.</p>\r\n\r\n<p>Cadoles a besoin de construire un plan strat&eacute;gique pour les ann&eacute;es &agrave; venir afin d&#39;anticiper des changements sur ses activit&eacute;s et de les diversifier pour diluer les risques.</p>\r\n\r\n<p>Le COPIL travaille actuellement sur une proposition bas&eacute;e sur trois axes principaux :</p>\r\n\r\n<p><span style=\"color:#2980b9\">&nbsp;1 - D&eacute;finir un socle technologique</span></p>\r\n\r\n<p>Coeur de l&#39;expertise de Cadoles, ce socle technologique servira de base &agrave; notre strat&eacute;gie. Elle constituera en outre une alternative &agrave; EOLE dans le futur.</p>\r\n\r\n<p><span style=\"color:#2980b9\"><span style=\"background-color:#ffffff\">2 - Construire une offre et se munir d&#39;une force commerciale</span></span></p>\r\n\r\n<p>Dans un premier temps il sera n&eacute;cessaire de red&eacute;finir un catalogue de services incluant des produits &agrave; forte valeur ajout&eacute;e (formations, conseil) en s&#39;appuyant sur des comp&eacute;tences commerciales internes ou externes. (recrutement, agent commercial...)</p>\r\n\r\n<p><span style=\"color:#2980b9\">3 - Re-contruire l&#39;image de Cadoles</span></p>\r\n\r\n<p>Notre communication est quasi inexistante, notre site internet ne refl&egrave;te pas nos r&eacute;alisations r&eacute;centes (ex : EFS). L&#39;objectif est d&#39;imposer Cadoles comme un acteur incontournable des technologies que nous auront cibl&eacute;es, de valoriser notre &eacute;quipe d&#39;experts et notre capacit&eacute; &agrave; apporter des solutions pertinentes. (site internet, &eacute;v&egrave;nements, hackatons, r&eacute;seaux sociaux, presse...)</p>\r\n</div>\r\n\r\n<p>Le COPIL travaille actuellement &agrave; la retranscription de ces 3 axes en plan d&#39;action, chiffr&eacute; et plannifi&eacute; afin de le proposer &agrave; la discussion.</p>\r\n\r\n<div class=\"moz-forward-container\">&nbsp;</div>\r\n\r\n<div class=\"moz-forward-container\"><span style=\"font-size:22px\"><span style=\"color:#167594\"><strong>Divers</strong></span></span></div>\r\n\r\n<div class=\"moz-forward-container\">&nbsp;</div>\r\n\r\n<div class=\"moz-forward-container\">-&gt; Cl&eacute;s : des trousseaux de cl&eacute;s sont &agrave; pr&eacute;voir pour Rudy et Laurent (C&eacute;line va s&#39;en charger)</div>\r\n\r\n<div class=\"moz-forward-container\">&nbsp;</div>\r\n-&gt; Journ&eacute;e de solidarit&eacute; : jour d&ucirc;, id&eacute;alement travaill&eacute; le lundi de Pentec&ocirc;te, le COPIL fera une proposition d&#39;organisation de cette journ&eacute;e (travail pour Cadoles, moment convivial...)\r\n\r\n<div class=\"moz-forward-container\">&nbsp;</div>\r\n\r\n<div class=\"moz-forward-container\">-&gt; Philippe pr&eacute;sente bri&egrave;vement le livre &quot;La citoyennet&eacute; &eacute;conomique peut-elle sauver l&#39;avenir&quot; &eacute;dit&eacute; par les Scop, le chapitre &eacute;crit par Laurence Ruffin, g&eacute;rante de la Scop ALMA propose des pistes interressantes en terme d&#39;organisation et de fonctionnement qu&#39;il invite chacun &agrave; lire.</div>\r\n\r\n<div class=\"moz-forward-container\">&nbsp;</div>\r\n</div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:22px\"><strong><span style=\"color:#078eb5\">DAD</span></strong></span></p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3057\">RAS</div>\r\n\r\n<div class=\"ace-line\">Note : la cr&eacute;ation du COPIL n&#39;exclut pas la cr&eacute;ation de DAD !</div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\" style=\"text-align:center\"><strong>Prochaine AC le mardi 12 avril</strong></div>\r\n\r\n<p>&nbsp;</p>','2022-03-16 10:47:30',1,1,'uploads/blogarticle/6231b4330c4b7.jpg'),(38,41,3,'CR de l\'AC du 12/04/2022','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous&nbsp; + Nicolas Bourgeois du Cabinet Mazars</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Benjamin G, Emmanuel, William, Vincent</div>\r\n\r\n<div class=\"ace-line\">Pouvoirs : aucun</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 20min&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp;&nbsp;&nbsp; CR COPIL : 15min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4847\">&nbsp;&nbsp;&nbsp; DAD : 15min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid11\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Tableau de suivi interne</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\">Situation au 31/03/2022</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 623 820&euro; dont 26 204&euro; factur&eacute;s d&#39;avance</li>\r\n	<li>Travaux r&eacute;alis&eacute;s sur l&#39;exercice, non factur&eacute;s au 31/03 : 103 995&euro;</li>\r\n	<li>Reste &agrave; faire sur commandes : 80 808&euro;</li>\r\n	<li>Devis &agrave; l&#39;&eacute;tude pond&eacute;r&eacute;s : 130 170&euro;</li>\r\n	<li>Fin exercice estim&eacute; : 934 421&euro;</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<p>A noter :</p>\r\n\r\n<ul>\r\n	<li>EFS : toujours pas de retour pour Sheila, le march&eacute; Bloodchain n&#39;arrivera sans doute pas avant l&#39;&eacute;t&eacute;.</li>\r\n</ul>\r\n\r\n<p>D&#39;une&nbsp; mani&egrave;re g&eacute;n&eacute;rale les pond&eacute;rations appliqu&eacute;es sont plut&ocirc;t prudentes.</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Situation comptable arr&ecirc;t&eacute;e au 31/03</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute;e par Nicolas Bourgeois du cabinet MAZARS</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">Le niveau d&#39;activit&eacute; est sup&eacute;rieur &agrave; celui de l&#39;ann&eacute;e derni&egrave;re &agrave; la m&ecirc;me date, les charges, elles, sont assez similaires.</div>\r\n\r\n<div class=\"ace-line\">La situation au 31/03, soit un trimestre avant la fin de l&#39;exercice d&eacute;gage un r&eacute;sultat de 82 192&euro;.</div>\r\n\r\n<div class=\"ace-line\">Si nous devons rester prudent car l&#39;exercice n&#39;est pas termin&eacute;, ce r&eacute;sultat est tr&egrave;s encourageant et, sauf accident, devrait permettre un r&eacute;sultat satisfaisant. Nous devrons r&eacute;fl&eacute;chir au pilotage de ce r&eacute;sultat avant la fin de l&#39;exercice : charges &agrave; affecter sur l&#39;exercice redistribution etc. afin d&#39;anticiper les d&eacute;cisions qui devront &ecirc;tre ent&eacute;rin&eacute;es lors de l&#39;Assembl&eacute;e G&eacute;n&eacute;rale.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">PC : Ce r&eacute;sultat encourageant est le fruit d&#39;un effort collectif : nous avons eu une meilleure gestion des ressources (pas ou peu d&#39;intercontrat), un bon niveau d&#39;activit&eacute; fourni par nos clients et une optimisation du temps factur&eacute;. Il ne semble pas que l&#39;activit&eacute; et la charge aient augment&eacute; pour les &eacute;quipes.</div>\r\n\r\n<div class=\"ace-line\">Nous ne devons toutefois pas nous r&eacute;jouir trop t&ocirc;t et attendre la fin de l&#39;exercice tout en maintenant nos efforts.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<p><span style=\"font-size:22px\"><span style=\"color:#2980b9\"><strong>DAD - Mise &agrave; disposition des locaux + charte</strong></span></span></p>\r\n\r\n<p>Les associ&eacute;s se prononcent sur la mise &agrave; disposition des locaux en dehors des horaires de bureaux pour l&#39;organisation d&#39;&eacute;v&egrave;nements priv&eacute;s encadr&eacute;s par une charte &agrave; &eacute;laborer :</p>\r\n\r\n<ul>\r\n	<li>Pour : 6 voix</li>\r\n	<li>Contre : 0 voix</li>\r\n	<li>Abstention : 1 voix</li>\r\n</ul>\r\n\r\n<p>=&gt; Proposition accept&eacute;e, la charte est &agrave; r&eacute;diger par le groupe de travail (William?) pour validation ult&eacute;rieure</p>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">\r\n<div class=\"moz-forward-container\">&nbsp;\r\n<p><span style=\"font-size:22px\"><span style=\"color:#167594\"><strong>Point COPIL</strong></span></span></p>\r\n\r\n<p>Visio Cooptech le 19/04 : pr&eacute;sence de Owlnext et de D&eacute;butant-e Accept&eacute;-e</p>\r\n</div>\r\nJourn&eacute;e de solidarit&eacute; / lundi de Pentec&ocirc;te : aucun retour des salari&eacute;s, le COPIL fera des propositions<br />\r\n&nbsp;</div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\" style=\"text-align:center\"><strong>Prochaine AC le mardi 10 mai</strong></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>','2022-04-15 09:27:13',1,1,'uploads/blogarticle/62591ee51ccfb.jpg'),(39,41,3,'CR de l\'AC du 10/05/2022','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous&nbsp; + Nicolas Bourgeois du Cabinet Mazars</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Benjamin G, Emmanuel, Benjamin B, Ludwig</div>\r\n\r\n<div class=\"ace-line\">Pouvoirs : aucun</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 20min&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp;&nbsp;&nbsp; CR COPIL : 15min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4847\">&nbsp;&nbsp;&nbsp; DAD : 15min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid11\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Tableau de suivi interne</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\">Situation au 30/04/2022</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 698 006&euro; dont 35 466.,20&euro; factur&eacute;s d&#39;avance</li>\r\n	<li>Travaux r&eacute;alis&eacute;s sur l&#39;exercice, non factur&eacute;s au 30/04 : 121 660&euro;</li>\r\n	<li>Reste &agrave; faire sur commandes : 69 797&euro;</li>\r\n	<li>Devis &agrave; l&#39;&eacute;tude pond&eacute;r&eacute;s : 79 024,50&euro;</li>\r\n	<li>Fin exercice estim&eacute; : 958 925,64&euro; (&agrave; d&eacute;duire 26 336,20&euro; de travaux factur&eacute;s qui ne seront probablement pas r&eacute;alis&eacute;s &agrave; fin d&#39;exercice)</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<p>A noter :</p>\r\n\r\n<p>D&#39;une&nbsp; mani&egrave;re g&eacute;n&eacute;rale les pond&eacute;rations appliqu&eacute;es sont plut&ocirc;t prudentes.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:22px\"><span style=\"color:#2980b9\"><strong>DAD - Recrutement junior pour Rectorat / EOLE 3</strong></span></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Les associ&eacute;s se prononcent sur le lancement d&#39;un recrutement pour un int&eacute;grateur syst&egrave;me junior pour le projet EOLE3 (CDD 18mois, junior) :</p>\r\n\r\n<ul>\r\n	<li>Pour : 7 voix</li>\r\n	<li>Contre : 0 voix</li>\r\n	<li>Abstention : 1 voix</li>\r\n</ul>\r\n\r\n<p>=&gt; Proposition accept&eacute;e, l&#39;annonce sera publi&eacute;e rapidement par LF / CR</p>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">\r\n<div class=\"moz-forward-container\">&nbsp;\r\n<p><span style=\"font-size:22px\"><span style=\"color:#167594\"><strong>Point COPIL</strong></span></span></p>\r\n\r\n<p><strong>Ateliers strat&eacute;giques</strong> les 17 et 19 mai : Brainstormings collectifs sur Commercial, Marketing et Communication</p>\r\n\r\n<p>Programme &agrave; venir : le COPIL viendra vous voir pour vous int&eacute;grer &agrave; ces ateliers en fonction des affinit&eacute;s / comp&eacute;tences / temps dispo</p>\r\n\r\n<p><strong>Ateliers techniques MSE</strong> : le travail r&eacute;alis&eacute; en workshop sera pr&eacute;sent&eacute; au client le 11/05 pour validation = nouveau socle technique Cadoles</p>\r\n\r\n<p><strong>Dossier formation</strong>, subvention FNE</p>\r\n\r\n<p>Limit&eacute; &agrave; 35K&euro; pour les formations d&eacute;but&eacute;es en&nbsp; 2022, notre dossier est en bonne voie, nous allons devoir prioriser (tout ne sera pas financ&eacute; cette ann&eacute;e)</p>\r\n\r\n<p><strong>Lundi de Pentec&ocirc;te 06/06</strong></p>\r\n\r\n<p>Pensez &agrave; apporter une ou plusieurs photos de vous enfant, nous ferons aussi de nouvelles photos</p>\r\n</div>\r\n\r\n<p>Programme (cf CR COPIL du 10/05)</p>\r\n\r\n<p><strong>Hacking health 02/06</strong></p>\r\n\r\n<p>William, Philippe et Arnaud repr&eacute;senteront Cadoles au c&ocirc;t&eacute; de l&#39;EFS &agrave; Besan&ccedil;on</p>\r\n</div>\r\n\r\n<p><strong>Pot de d&eacute;part de Teddy</strong></p>\r\n\r\n<p>Pr&eacute;vu le vendredi 03/06 en fin d&#39;apr&egrave;s-midi</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\" style=\"text-align:center\"><strong>Prochaine AC le mardi 14 juin</strong></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>','2022-05-12 15:42:40',1,0,'uploads/blogarticle/627d17e46d2be.jpg'),(40,41,3,'CR de l\'AC du 14/06/22','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous&nbsp; + Nicolas Bourgeois et L&eacute;a Jean-Michel du Cabinet Mazars</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Benjamin G, Emmanuel, Ludwig</div>\r\n\r\n<div class=\"ace-line\">Pouvoirs : aucun</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 10min&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp; &nbsp; DAD : 15min</div>\r\n\r\n<div class=\"ace-line\">&nbsp;&nbsp;&nbsp; CR COPIL : 15min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid11\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Tableau de suivi interne</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\">Situation au 31/05/2022</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 858 527&euro; dont 25 091&euro; factur&eacute;s d&#39;avance</li>\r\n	<li>Travaux r&eacute;alis&eacute;s sur l&#39;exercice, non factur&eacute;s au 31/05 : 43 500&euro;</li>\r\n	<li>Reste &agrave; faire sur commandes : 76 636&euro; sur l&#39;exercice (+30 300&euro; sur l&#39;exercice suivant)</li>\r\n	<li>Devis &agrave; l&#39;&eacute;tude pond&eacute;r&eacute;s : 4 992&euro; sur l&#39;exercice (+ 11 912 sur l&#39;exercice suivant)</li>\r\n	<li>Fin exercice estim&eacute; : 983 656&euro; - 25 091&euro; (travaux factur&eacute;s mais non r&eacute;alis&eacute;s estim&eacute;s en fin d&#39;exercice) = 958 565&euro;</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<p>A noter :</p>\r\n\r\n<p>D&#39;une&nbsp; mani&egrave;re g&eacute;n&eacute;rale les pond&eacute;rations appliqu&eacute;es sont plut&ocirc;t prudentes.</p>\r\n\r\n<p>Un r&eacute;sultat d&#39;environ 70 000&euro; est envisag&eacute;, en se basant sur le CA &eacute;quilibre estim&eacute; en d&eacute;but d&#39;exercice.</p>\r\n\r\n<p>L&#39;ann&eacute;e derni&egrave;re nous avions p&ucirc; profiter de la prime d&#39;activit&eacute;. Cette prime a &eacute;t&eacute; annonc&eacute;e comme maintenue mais le d&eacute;cret n&#39;a, &agrave; ce jour, pas &eacute;t&eacute; publi&eacute;. Pour que nous puissions la verser sur cet exercice, la publication doit intervenir avant le 30/06/22.</p>\r\n\r\n<p>Dans le cas o&ugrave; elle le serait, la co-g&eacute;rance demande &agrave; l&#39;AC si elle est favorable au versement de cette prime : avis majoritairement favorable de l&#39;AC.</p>\r\n\r\n<p>Dans le cas contraire, les m&eacute;canismes habituels s&#39;appliqueront : interressement + participation.</p>\r\n\r\n<p><span style=\"font-size:22px\"><span style=\"color:#2980b9\"><strong>DAD - Am&eacute;nagement bureaux du fond</strong></span></span></p>\r\n\r\n<p>Les associ&eacute;s se prononcent sur les devis pour les travaux permettant de r&eacute;unir les 2 bureaux du fond et de r&eacute;cup&eacute;rer l&#39;espace perdu dans le couloir. Deux devis ont &eacute;t&eacute; pr&eacute;sent&eacute;s.</p>\r\n\r\n<p>Travaux r&eacute;alis&eacute;s sur devis A2P:</p>\r\n\r\n<ul>\r\n	<li>Pour : 0 voix</li>\r\n	<li>Contre : 9 voix</li>\r\n	<li>Abstention : 0 voix</li>\r\n</ul>\r\n\r\n<p>Travaux r&eacute;alis&eacute;s sur devis S. Estivalet :</p>\r\n\r\n<ul>\r\n	<li>Pour : 8 voix</li>\r\n	<li>Contre : 1 voix</li>\r\n	<li>Abstention : 0 voix</li>\r\n</ul>\r\n\r\n<p>Ne rien faire :</p>\r\n\r\n<ul>\r\n	<li>Pour : 1 voix</li>\r\n	<li>Contre : 8 voix</li>\r\n	<li>Abstention : 0 voix</li>\r\n</ul>\r\n\r\n<p>=&gt; Proposition S. Estivalet accept&eacute;e, travaux &agrave; planifier d&egrave;s que possible.</p>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">\r\n<div class=\"moz-forward-container\">\r\n<p><span style=\"font-size:22px\"><span style=\"color:#2980b9\"><strong>DAD - Budget formation</strong></span></span></p>\r\n\r\n<p>Les associ&eacute;s se prononcent sur le budget formation.</p>\r\n\r\n<p>Budget 20 600&euro; (Formations avec financement FNE, frais formation Ludwig)</p>\r\n\r\n<ul>\r\n	<li>Pour : 0 voix</li>\r\n	<li>Contre : 9 voix</li>\r\n	<li>Abstention : 0 voix</li>\r\n</ul>\r\n\r\n<p>Budget 25 600&euro; (Formations avec financement FNE, frais formation Ludwig + budget pour financer formation alternant dev)</p>\r\n\r\n<ul>\r\n	<li>Pour : 9 voix</li>\r\n	<li>Contre : 0 voix</li>\r\n	<li>Abstention : 0 voix</li>\r\n</ul>\r\n\r\n<p>=&gt; Proposition n&deg;2 accept&eacute;e (avec possibilit&eacute; de financer la formation d&#39;un alternant dev)</p>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">\r\n<div class=\"moz-forward-container\">\r\n<p><span style=\"font-size:22px\"><span style=\"color:#167594\"><strong>Divers</strong></span></span></p>\r\n\r\n<p><strong>Participation aux logiciels libres</strong> : 6 500&euro; avaient &eacute;t&eacute; budget&eacute;s pour l&#39;exercice, mais nous n&#39;avaons &agrave; ce jour fait aucune d&eacute;marche.</p>\r\n\r\n<p>Si nous n&#39;arrivons pas &agrave; le faire avant la fin de l&#39;exercice ce budget pourrait &ecirc;tre report&eacute; sur l&#39;exercice suivant.</p>\r\n\r\n<p><strong>Cabinet Mazars :</strong> Nicolas Bourgeois nous pr&eacute;sente L&eacute;a Jean-Michel qui remplacera Marine Perrin sur les questions sociales.</p>\r\n</div>\r\n</div>\r\n\r\n<p><span style=\"font-size:22px\"><span style=\"color:#167594\"><strong>Point COPIL</strong></span></span></p>\r\n<strong>Plan strat&eacute;gique :</strong> Le dernier COPIL a eu lieu le 13/06 et &eacute;tait d&eacute;di&eacute; aux travaux sur le plan strat&eacute;gique. (pas de livrable pour le moment)\r\n\r\n<p><strong>Prud&#39;Homme / litige Eliade</strong> : l&#39;audience a eu lieu le 09/06. Notre avocate a fait du tr&egrave;s bon travail et a prouv&eacute; que les dires de notre adversaire &eacute;taient mensongers. Elle a demand&eacute; des dommages et int&eacute;r&ecirc;ts pour &eacute;tayer sa strat&eacute;gie. A l&#39;issue de l&#39;audience elle &eacute;tait plut&ocirc;t confiante. Il faut toutefois rester prudents en attendant le d&eacute;lib&eacute;r&eacute; qui est pr&eacute;vu pour le 15/09.</p>\r\n<strong>Journ&eacute;es de l&#39;innovation au CHU de Besan&ccedil;on le 02/06</strong></div>\r\n\r\n<p>William, Philippe et Arnaud : retour tr&egrave;s positif, deux contacts potentiels parmis les autres exposants, dont 1 RDV pr&eacute;vu en septembre.</p>\r\n\r\n<p>Une journaliste des Echos a demand&eacute; &agrave; avoir nos coordon&eacute;es, &agrave; suivre.</p>\r\n\r\n<p><strong>Hacking Health du 14 au 16 octobre 2022 &agrave; Besan&ccedil;on</strong></p>\r\n\r\n<p>Cadoles vous encourage &agrave; participer, la participation ne peut &ecirc;tre qu&#39;individuelle.</p>\r\n\r\n<p>https://hacking-health.org/fr/event/5e-marathon-dinnovation-ouverte-en-sante-hacking-health-besancon/</p>\r\n</div>\r\n\r\n<p>Cadoles a re&ccedil;u des propositions de sponsoring, &agrave; diff&eacute;rents niveaux selon le budget, &agrave; &eacute;tudier.</p>\r\n\r\n<p><strong>Ev&egrave;nement Cr&eacute;er Demain 30/11 et 01/12 organis&eacute; par l&#39;AER BFC</strong></p>\r\n\r\n<p>Candidature &agrave; envoyer avant le 1er juillet, Matthieu prend en charge ce sujet.</p>\r\n\r\n<p>https://creerdemain.aer-bfc.com/</p>\r\n\r\n<p><strong>Evennement Framework or not Framework</strong> dans les locaux de Cpage le 30/06 de 16h &agrave; 18h</p>\r\n\r\n<p>ML, RD et PC y participeront, inscription &agrave; faire.</p>\r\n\r\n<p>https://bfcnumerique.fr/evenement/conference-collaborative-sur-le-theme-web-framework-or-not/</p>\r\n\r\n<p><strong>T&eacute;l&eacute;travail</strong></p>\r\n\r\n<p>Pour rappel, nous avons mis en place un accord d&#39;entreprise portant sur le t&eacute;l&eacute;travail. Ceux qui souhaitent en b&eacute;n&eacute;ficier doivent demander un avenant &agrave; leur contrat de travail &agrave; la cog&eacute;rance.</p>\r\n\r\n<p>En l&#39;absence d&#39;avenant, le t&eacute;l&eacute;travail n&#39;est possible que de fa&ccedil;on ponctuelle et sur demande &agrave; la co-g&eacute;rance.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\" style=\"text-align:center\"><strong>Prochaine AC le mardi 12 juillet</strong></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>','2022-06-16 11:05:55',1,1,'uploads/blogarticle/62aaf2e95cb72.jpg'),(41,41,3,'CR de l\'AC du 12/07/2022','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous&nbsp; + Nicolas Bourgeois du Cabinet Mazars</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Benjamin G, Emmanuel, William, Rudy</div>\r\n\r\n<div class=\"ace-line\">Pouvoirs : aucun</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 20min&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp; &nbsp; DAD : 10min</div>\r\n\r\n<div class=\"ace-line\">&nbsp;&nbsp;&nbsp; CR COPIL : 15min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid11\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Tableau de suivi interne</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\">Situation au 30/06/2022 : fin d&#39;exercice</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 899 035,56&euro;</li>\r\n	<li>Travaux r&eacute;alis&eacute;s sur l&#39;exercice, non factur&eacute;s au 30/06 : 70 897,50&euro;</li>\r\n	<li>Reste &agrave; faire sur commandes : 0&euro; sur l&#39;exercice (+30 877&euro; sur l&#39;exercice suivant)</li>\r\n	<li>Devis &agrave; l&#39;&eacute;tude pond&eacute;r&eacute;s : 0&euro; sur l&#39;exercice (+ 11 912 sur l&#39;exercice suivant)</li>\r\n	<li>Fin exercice estim&eacute; : 969 933</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<p>A noter :</p>\r\n\r\n<p>D&#39;une&nbsp; mani&egrave;re g&eacute;n&eacute;rale les pond&eacute;rations appliqu&eacute;es sont plut&ocirc;t prudentes.</p>\r\n\r\n<p>Dans la mesure du possible, la prime d&#39;activit&eacute; sera reconduite sur cet exercice. (montant et modalit&eacute;s &agrave; d&eacute;finir)</p>\r\n\r\n<p>Dans le cas contraire, les m&eacute;canismes habituels s&#39;appliqueront : interressement + participation.</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Situation comptable au 30/06</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par Nicolas Bourgeois, Cabinet Mazars</div>\r\n\r\n<div class=\"ace-line\">L&#39;exercice se cl&ocirc;ture avec une belle progression de la marge brute (+93K&euro;), le r&eacute;sultat de l&#39;exercice sera autour de 100K&euro;.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">Les travaux de cl&ocirc;ture d&#39;exercice d&eacute;buteront en septembre. Nous devrions en savoir plus sur la provision &agrave; maintenir ou &agrave; modifier dans le cadre du litige Elliade.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Pr&eacute;visionnel 2022-2023</strong></span></span></div>\r\n\r\n<div class=\"ace-line\">C&eacute;line et Arnaud ont pr&eacute;par&eacute; un pr&eacute;visionnel de ventes :</div>\r\n\r\n<div class=\"ace-line\">CA non pond&eacute;r&eacute; = 1 290K&euro;</div>\r\n\r\n<div class=\"ace-line\">CA pond&eacute;r&eacute; =&nbsp; 1 013K&euro;</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">Ce pr&eacute;visionnel fait appara&icirc;tre un manque de ressources, notemment c&ocirc;t&eacute; dev si les projets de l&#39;EFS se concr&eacute;tisent selon le timing pr&eacute;vu. (Bloodchain et Shela). De la sous-traitance est envisag&eacute;e pour pallier temporairement &agrave; ce besoin sur le dernier trimestre 2022. Le poste poura &ecirc;tre p&eacute;rennis&eacute; par la suite si les conditions sont favorables.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">Par ailleurs l&#39;inflation actuelle n&eacute;cessitera que nous rediscutions rapidement d&#39;une revalorisation des salaires.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<p><span style=\"font-size:22px\"><span style=\"color:#2980b9\"><strong>DAD - Sponsoring Hacking Health</strong></span></span></p>\r\n\r\n<p>Les associ&eacute;s se prononcent sur le sponsoring de l&#39;&eacute;vennement Hacking Health de Besan&ccedil;on.</p>\r\n\r\n<p>Formule argent &agrave; 3 000&euro; HT</p>\r\n\r\n<ul>\r\n	<li>Pour : 9 voix</li>\r\n	<li>Contre : 0 voix</li>\r\n	<li>Abstention : 0 voix</li>\r\n</ul>\r\n\r\n<p>Proposition adopt&eacute;e, AF se charge de passer la commande aupr&egrave;s des organisateurs.</p>\r\n\r\n<p><span style=\"font-size:22px\"><span style=\"color:#2980b9\"><strong>Alternant Dev&nbsp; : Arnold ARDOUIN</strong></span></span></p>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">\r\n<div class=\"moz-forward-container\">\r\n<p>Suite au process de recrutement, Arnold ARDOUIN a &eacute;t&eacute; selectionn&eacute; pour un contrat de 2ans</p>\r\n\r\n<p>Sa formation est enti&egrave;rement prise en charge par l&#39;OPCO.</p>\r\n\r\n<p>Achat de mat&eacute;riel &agrave; pr&eacute;voir. (Poste de travail -&gt; VF)</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:22px\"><span style=\"color:#167594\"><strong>Point COPIL</strong></span></span></p>\r\n\r\n<p><strong>Projet vid&eacute;o :</strong> Plusieurs devis ont &eacute;t&eacute; re&ccedil;us pour des prestations &eacute;quivalentes.</p>\r\n\r\n<p>L&#39;AC valide le devis de Visual Record (et celui de Caf&eacute; Gourmand en second choix) sous r&eacute;serve que Cadoles obtienne les droits sur la vid&eacute;o.</p>\r\n\r\n<p>Le tournage sera planifi&eacute; la premi&egrave;re semaine de septembre.</p>\r\n\r\n<p><strong>Strat&eacute;gie Cadoles</strong> : le COPIL souhaite soumettre le plan strat&eacute;gique en septembre</p>\r\n<strong>Emmanuel :</strong> Emmanuel ne s&#39;est pas pr&eacute;sent&eacute; &agrave; son poste de travail depuis le 01/07. La co-g&eacute;rance lui a demand&eacute; des explications.</div>\r\n\r\n<p><strong>Formation : </strong>Laetitia va planifier les formations pr&eacute;vues au plan de formation rapidement.</p>\r\n\r\n<p>La formation RH de Laetitia d&eacute;bute le 21/07</p>\r\n</div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\" style=\"text-align:center\"><strong>Prochaine AC le mardi 13 septembre</strong></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>','2022-07-21 15:50:03',1,1,'uploads/blogarticle/62d959d698fd3.jpg'),(42,41,3,'CR de l\'AC du 16/09/2022','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous&nbsp; + Nicolas Bourgeois du Cabinet Mazars</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Benjamin G</div>\r\n\r\n<div class=\"ace-line\">Pouvoirs : aucun</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 20min&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp; &nbsp; DAD : 10min</div>\r\n\r\n<div class=\"ace-line\">&nbsp;&nbsp;&nbsp; CR COPIL : 15min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe :</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid11\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Prime de partage de la valeur (PPV)</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">Appel&eacute;e pr&eacute;c&eacute;demment &quot;Prime Macron&quot;, nous avions convenu de profiter de cette opportunit&eacute; sur l&#39;exercice 2021-2022. Cette derni&egrave;re sera vers&eacute;e sur le salaire de septembre et sera calcul&eacute;e comme suit :</div>\r\n\r\n<ul>\r\n	<li>Somme &agrave; partager env. 50 000&euro; (r&eacute;pr&eacute;sente 1/2 du r&eacute;sultat de l&#39;exercice si on ne la versait pas, la somme exacte sera connue dans les prochains jours avec les travaux de cl&ocirc;ture de l&#39;exercice qui sont en cours)</li>\r\n	<li>Au prorata du temps de travail (prise en compte de la date d&#39;arriv&eacute;e dans l&#39;entreprise et des temps partiels)</li>\r\n	<li>Tous les salari&eacute;s pr&eacute;sents sur cet exercice pourront en b&eacute;n&eacute;ficier</li>\r\n</ul>\r\n\r\n<p>Pour rappel, cette prime est exon&eacute;r&eacute;e de charges et d&#39;IS. Le r&eacute;sultat de l&#39;exercice restant sera partag&eacute; selon les r&egrave;gles habituelles.(int&eacute;ressement, participation et r&eacute;serves)</p>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Budget et Pr&eacute;visionnel de ventes exercice 2022-2023</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R et Arnaud F</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">Le <a href=\"https://nextcloud.cadoles.com/nextcloud/index.php/f/125601\" target=\"_blank\">pr&eacute;visionnel des ventes</a> pour l&#39;exercice est pr&eacute;sent&eacute; &agrave; l&#39;Assembl&eacute;e :</div>\r\n\r\n<ul>\r\n	<li>CA pr&eacute;visionnel pond&eacute;r&eacute; = .1 073 255&euro; (pond&eacute;ration moyenne 82%)</li>\r\n	<li>CA pr&eacute;visionnel non pond&eacute;r&eacute; = 1 305 555&euro;</li>\r\n</ul>\r\n\r\n<p>Ce pr&eacute;visionnel est &eacute;tabli avec les informations dont nous disposons &agrave; l&#39;instant T.</p>\r\n\r\n<p>Deux <a href=\"https://nextcloud.cadoles.com/nextcloud/index.php/f/131228\" target=\"_blank\">budgets pr&eacute;visionnels </a>(charges) sont pr&eacute;sent&eacute;s &agrave; l&#39;Assembl&eacute;e et soumis au vote des associ&eacute;s.</p>\r\n\r\n<p><strong>Version A : 1 067 753&euro;</strong></p>\r\n\r\n<ul>\r\n	<li>Recrutements : 1 syst&egrave;me (6mois) + 1 d&eacute;veloppeur (7 mois)</li>\r\n	<li>Charges bas&eacute;es sur celles de l&#39;exercice pr&eacute;c&eacute;dente en tenant compte des hausses de tarifs g&eacute;n&eacute;rales</li>\r\n	<li>Hausse des salaires de 4% &agrave; compter du 01/09/2022 (hausse li&eacute;e &agrave; l&#39;inflation)</li>\r\n	<li>Revalorisation des salaires bruts li&eacute;e &agrave; l&#39;anciennet&eacute; &agrave; compter du 01/07/2022\r\n	<ul>\r\n		<li>+5% si 5 ans d&#39;anciennet&eacute;</li>\r\n		<li>+10% si 10 ans d&#39;anciennet&eacute;</li>\r\n	</ul>\r\n	</li>\r\n</ul>\r\n\r\n<p><strong>Version B : 1 028 724&euro;</strong></p>\r\n\r\n<ul>\r\n	<li>Recrutements : 1 syst&egrave;me (6mois) + 1 d&eacute;veloppeur (7 mois)</li>\r\n	<li>Charges bas&eacute;es sur celles de l&#39;exercice pr&eacute;c&eacute;dente en tenant compte des hausses de tarifs g&eacute;n&eacute;rales</li>\r\n	<li>Hausse des salaires de 4% &agrave; compter du 01/09/2022 (hausse li&eacute;e &agrave; l&#39;inflation)</li>\r\n</ul>\r\n\r\n<p><strong>R&eacute;sultat du vote :</strong></p>\r\n\r\n<ul>\r\n	<li>Budget A : 8 voix (adopt&eacute;)</li>\r\n	<li>Budget B :&nbsp; 1 voix</li>\r\n</ul>\r\n\r\n<p>A noter : la p&eacute;rennisation de l&#39;augmentation li&eacute;e &agrave; l&#39;anciennet&eacute; <strong>devra faire l&#39;objet d&#39;un DAD.</strong></p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Projet strat&eacute;gique</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par les membres du COPIL</div>\r\n\r\n<div class=\"ace-line\">Un document de pr&eacute;sentation est disponible <a href=\"https://nextcloud.cadoles.com/nextcloud/index.php/s/SLZFWTWPmY7JEDX\" target=\"_blank\">ici</a></div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">\r\n<div class=\"moz-forward-container\">&nbsp;\r\n<p><span style=\"font-size:22px\"><span style=\"color:#167594\"><strong>Point COPIL / Divers</strong></span></span></p>\r\n\r\n<p><strong>Mandats co-g&eacute;rance :</strong> les mandats des actuels co-g&eacute;rants arrivent &agrave; &eacute;ch&eacute;ance en 2023, le premier &eacute;tant celui de Laetitia en mars. Il faudra se poser la question d&#39;une &eacute;ventuelle harmonisation des dates de sortie lors d&#39;une prochaine AC.</p>\r\n\r\n<p><strong>Projet vid&eacute;o :</strong> Sont volontaires pour les interview : Arnaud, William, Philippe et C&eacute;line. Date de tournage &agrave; d&eacute;terminer selon les plannings. (CR/AF)</p>\r\n<strong>Emmanuel :</strong> Emmanuel a &eacute;t&eacute; officiellement licenci&eacute; le 26/08/2022. Emmanuel est en cours de cr&eacute;ation de son entreprise. Un contrat de partenariat a &eacute;t&eacute; r&eacute;dig&eacute; avec notre avocate.</div>\r\n</div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\" style=\"text-align:center\"><strong>Prochaine AC le mardi 11 octobre</strong></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>','2022-09-16 20:04:35',1,1,'uploads/blogarticle/63281ae50501a.jpg'),(43,41,3,'CR de l\'AC du 11/10/2022','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous&nbsp; + Anthony AZEVEDO du Cabinet Mazars</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Benjamin G</div>\r\n\r\n<div class=\"ace-line\">Pouvoirs : aucun</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 20min&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp; &nbsp; DAD : 10min</div>\r\n\r\n<div class=\"ace-line\">&nbsp;&nbsp;&nbsp; CR COPIL : 15min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe :</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"moz-forward-container\">\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Indicateurs internes MAJ au 30/09/22</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\">Situation au 30/09/2022 : (T1)</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 162 639&euro; (dont 38 318&euro; factur&eacute;s d&#39;avance)</li>\r\n	<li>Travaux r&eacute;alis&eacute;s sur l&#39;exercice, non factur&eacute;s au 30/09 : 79 045&euro;</li>\r\n	<li>Reste &agrave; faire sur commandes : 228 215&euro; sur l&#39;exercice</li>\r\n	<li>Devis &agrave; l&#39;&eacute;tude pond&eacute;r&eacute;s : 506 693&euro; sur l&#39;exercice</li>\r\n	<li>Fin exercice estim&eacute; : 976 592&euro; (Rappel &eacute;quilibre d&#39;apr&egrave;s budget pr&eacute;visionnel : 1 067 733&euro;)</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<p>A noter :</p>\r\n\r\n<ul>\r\n	<li>D&#39;une&nbsp; mani&egrave;re g&eacute;n&eacute;rale les pond&eacute;rations appliqu&eacute;es sont plut&ocirc;t prudentes.</li>\r\n	<li>MSE : quasi 70% de notre CA, refonte de l&#39;infra cette ann&eacute;e, le volume sera r&eacute;duit par la suite.</li>\r\n	<li>Toujours pas mal d&#39;incertitudes sur les projets EFS, surtouts sur la temporalit&eacute;. La premi&egrave;re commande de 5 bornes est laborieuse du fait de la rupture d&#39;appro des bornes linksys nous obligeant &agrave; changer de mat&eacute;riel)</li>\r\n	<li>March&eacute; EOLE : un volume de commande a &eacute;t&eacute; garanti popur couvrir l&#39;&eacute;quivalent de 1.5ETP sur EOLE 2 et 1 ETP sur EOLE3 jusqu&#39;en mars 2023. Pas d&#39;engagement de volume au-del&agrave;.</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n</div>\r\n\r\n<p><span style=\"font-size:22px\"><span style=\"color:#167594\"><strong>Point COPIL / Divers</strong></span></span></p>\r\n\r\n<p>CR du COPIL du 07/10 : &agrave; venir</p>\r\n\r\n<ul>\r\n	<li><strong>Sylvain ELIADE </strong>: a &eacute;t&eacute; debout&eacute; en premi&egrave;re instance mais a fait appel, un nouveau proc&egrave;s va donc avoir lieu devant des magistrats professionnels (convocation d&eacute;but novembre). De nouveaux frais sont donc &agrave; pr&eacute;voir, la provision a &eacute;t&eacute; maintenue au cas o&ugrave;. (15 000&euro;)</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li><strong>Document unique sur les risques pro</strong> : LF a mis &agrave; jour ce document, appel &agrave; salari&eacute;s volontaires pour la relecture</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li><strong>Speed Techning / Developers Group Dijon :</strong>\r\n\r\n	<ul>\r\n		<li>ML a particip&eacute; &agrave; la derni&egrave;re session</li>\r\n		<li>retour tr&egrave;s positif, techniquement tr&egrave;s interressant, pr&eacute;sence essentiellement de d&eacute;veloppeurs senior</li>\r\n		<li>Cadoles n&#39;a pas &agrave; rougir de ses comp&eacute;tences</li>\r\n	</ul>\r\n	</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li><strong>KubeCon de la Linux fondation &agrave; Amterdam en avril 2023</strong>: ML souhaiterait y participer, un DAD sera r&eacute;dig&eacute; en ce sens avec demande de budget. (https://events.linuxfoundation.org/kubecon-cloudnativecon-europe/)</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li><strong>Colloque SECnum :</strong> LS nous fait un retour positif sur ce colloque, interventions interressantes de la DGFIP, l&#39;ANSI et l&#39;AFNOR. (de l&#39;int&eacute;r&ecirc;t pour les entreprises &agrave; s&#39;impliquer dans la construction des r&egrave;gles iso)</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li><strong>Hacking Health &agrave; Besan&ccedil;on</strong> : c&#39;est ce week-end !</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li><strong>Formation Kubernetes : </strong>\r\n\r\n	<ul>\r\n		<li>retours tr&egrave;s positifs de la formation suivie par les dev, le formateur sera le m&ecirc;me pour la formation Sys,</li>\r\n		<li>voir qui veut passer les certifications apr&egrave;s la prochaine session</li>\r\n	</ul>\r\n	</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li><strong>Petits Dej de l&#39;innovation :</strong> WP rappelle que cette id&eacute;e avait &eacute;t&eacute; soumise et qu&#39;il serait souhaitable de la mettre en oeuvre</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li><strong>Cartes de visites </strong>: nous n&#39;avons plus de cartes de visite &agrave; jour :\r\n\r\n	<ul>\r\n		<li>-&gt; dans un premier temps, voir pour en r&eacute;imprimer une version &agrave; jour sans nom (petite quantit&eacute;)</li>\r\n		<li>-&gt; la cr&eacute;ation d&#39;un groupe de travail &quot;Communication&quot; serait utile pour r&eacute;fl&eacute;chir plus largement</li>\r\n	</ul>\r\n	</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li><strong>&nbsp;Intervention d&#39;un Ergonome</strong> au bureau dans le cadre de la pr&eacute;vention des TMS : le lundi 5 d&eacute;cembre, pr&eacute;sence au bureau indispensable</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li><strong>AG CADOLES :</strong> le mardi 6 d&eacute;cembre 2022 &agrave; 16h (hors temps de travail)</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li><strong>AG URSCOP le 20/10 </strong>: ceux qui souhaitent y participer doivent s&#39;inscrire au plus vite</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li><strong>Avenant accord de participation :</strong>\r\n\r\n	<ul>\r\n		<li>signature lors de l&#39;AC, d&eacute;blocage anticip&eacute; de la participation</li>\r\n		<li>LF tient &agrave; dispo la somme d&eacute;tenue par chacun</li>\r\n		<li>exon&eacute;ration fiscale,</li>\r\n		<li>maxi 10 000&euro; sur les participations acquises au 01/01/2022,</li>\r\n		<li>simple demande &agrave; faire &agrave; la co-g&eacute;rance,</li>\r\n		<li>chaque contribuable doit garder les justificatifs d&#39;achats de biens ou de prestations r&eacute;alis&eacute;s avec cette somme.</li>\r\n	</ul>\r\n	</li>\r\n</ul>\r\n\r\n<ul>\r\n	<li><strong>Charge de travail : </strong>\r\n\r\n	<ul>\r\n		<li>l&#39;&eacute;quipe Dev remonte une charge de travail importante depuis la rentr&eacute;e : reprise de tous les projets en m&ecirc;me temps, absence de Benjamin G. malgr&eacute; des tentatives d&#39;anticipation. (arriv&eacute;e de Valentin de Atol). La d&eacute;sorganisation du client MSE complique la situation.</li>\r\n		<li>M&ecirc;me constat c&ocirc;t&eacute; sys, le retour d&#39;EG en sous-traitance devrait stabiliser la situation c&ocirc;t&eacute; EOLE.</li>\r\n	</ul>\r\n	</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid11\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Projet strat&eacute;gique</strong></span></span></div>\r\n\r\n<div class=\"ace-line\">Un document de pr&eacute;sentation est disponible <a href=\"https://nextcloud.cadoles.com/nextcloud/index.php/s/SLZFWTWPmY7JEDX\" target=\"_blank\">ici</a></div>\r\n\r\n<div class=\"ace-line\">Nous avons sollicit&eacute; et re&ccedil;u une offre de service de la Junior entreprise de la BSB pour une premi&egrave;re &eacute;tude de march&eacute; autour du produit qui sera issu des travaux sur Quid / Arcade.</div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\" style=\"text-align:center\"><strong>Prochaine AC le mardi 22 novembre</strong></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>','2022-10-13 10:56:55',1,1,'uploads/blogarticle/6347d7162ee60.jpg'),(44,41,3,'CR de l\'AC du 22/11/2022','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Benjamin G, Anthony AZEVEDO (Mazars)</div>\r\n\r\n<div class=\"ace-line\">Pouvoirs : aucun</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 20min&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp; &nbsp; DAD : 10min</div>\r\n\r\n<div class=\"ace-line\">&nbsp;&nbsp;&nbsp; CR COPIL : 15min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe :</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"moz-forward-container\">\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Indicateurs internes MAJ au 31/10/22</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\">Situation au 31/10/2022 :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 287 379&euro; (dont 58 738&euro; factur&eacute;s d&#39;avance)</li>\r\n	<li>Travaux r&eacute;alis&eacute;s sur l&#39;exercice, non factur&eacute;s au 31/10 : 83 490&euro;</li>\r\n	<li>Reste &agrave; faire sur commandes : 239 889&euro; sur l&#39;exercice</li>\r\n	<li>Devis &agrave; l&#39;&eacute;tude pond&eacute;r&eacute;s : 446 437&euro; sur l&#39;exercice</li>\r\n	<li>Fin exercice estim&eacute; : 1 057 197&euro; (Rappel &eacute;quilibre d&#39;apr&egrave;s budget pr&eacute;visionnel : 1 067 733&euro;)</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<p>A noter :</p>\r\n\r\n<ul>\r\n	<li>D&#39;une&nbsp; mani&egrave;re g&eacute;n&eacute;rale les pond&eacute;rations appliqu&eacute;es sont plut&ocirc;t prudentes.</li>\r\n	<li>MSE : quasi 70% de notre CA, refonte de l&#39;infra cette ann&eacute;e, le volume sera r&eacute;duit par la suite.</li>\r\n	<li>Toujours pas mal d&#39;incertitudes sur les projets EFS, surtouts sur la temporalit&eacute;. La premi&egrave;re commande de 5 bornes est laborieuse du fait de la rupture d&#39;appro des bornes linksys nous obligeant &agrave; changer de mat&eacute;riel)</li>\r\n	<li>March&eacute; EOLE : un volume de commande a &eacute;t&eacute; garanti popur couvrir l&#39;&eacute;quivalent de 1.5ETP sur EOLE 2 et 1 ETP sur EOLE3 jusqu&#39;en mars 2023. Pas d&#39;engagement de volume au-del&agrave;.</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">Pr&eacute;sentation des indicateurs trimestriels permettant :</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;- une analyse de l&#39;exercice &eacute;coul&eacute;</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;- un suivi analytique par domaines d&#39;activit&eacute;s</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;- un suivi du budget vot&eacute; vs r&eacute;&eacute;l</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">C&eacute;line est &agrave; votre disposition pour une pr&eacute;sentation plus d&eacute;taill&eacute;e.</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;</div>\r\n</div>\r\n</div>\r\n\r\n<p><span style=\"font-size:22px\"><span style=\"color:#167594\"><strong>Point COPIL / Divers</strong></span></span></p>\r\n\r\n<div><strong>Libre Entreprise :</strong> Souhaite t on continuer &agrave; faire partie du mouvement LE, doublon avec Cooptech? (de nombreux membres de LE font partie de Cooptech), Si oui, il faudra un r&eacute;f&eacute;rent LE chez Cadoles.</div>\r\n\r\n<div>-&gt; D&eacute;cision &agrave; prendre lors de la prochaine AC</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>Petits Dej de l&#39;innovation :</strong> c&#39;&eacute;tait ce matin ! Nous avons tous manqu&eacute; ce RDV, aucune proposition de pitch n&#39;a &eacute;t&eacute; formul&eacute;e.</div>\r\n\r\n<div>Prochaine &eacute;dition le 06/12, pitch &agrave; soumettre avant le 02/12.</div>\r\n\r\n<div>Pr&eacute;voir la pr&eacute;sence des alternants (d&eacute;rogation &eacute;cole &agrave; demander)</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<p><strong>Article Hackathon</strong> : &agrave; relire, puis publication</p>\r\n\r\n<p><strong>Vid&eacute;o Cadoles </strong>: &agrave; mettre sur Nexcloud en interne, et &agrave; diffuser (site internet Cadoles, Linkedin...)</p>\r\n\r\n<p><strong>Formation Kubernetes : </strong></p>\r\n\r\n<ul>\r\n	<li>retours tr&egrave;s positifs sur ces formations : des &eacute;changes en interne vont avoir lieu pour faire le point sur les 3 projets impact&eacute;s par cette techno (EOLE 3 , EFS, MSE)</li>\r\n	<li>Certification : Cadoles prendra en charge la certification de ceux qui le souhaitent, il semblerait judicieux de manipuler avant, une session de bachotage commune pourrait &ecirc;tre organis&eacute;e fin 2023/ d&eacute;but 2024.</li>\r\n</ul>\r\n\r\n<ul>\r\n</ul>\r\n\r\n<p><strong>KubeCon de la Linux fondation &agrave; Amterdam en avril 2023</strong>:</p>\r\n\r\n<div>Souhaitent s&#39;y rendre : VF, PC, RM, CMS, ML, LS, WP</div>\r\n\r\n<div>Pr&eacute;paration du d&eacute;placement : Rudy se propose pour r&eacute;unir les infos et co&ucirc;ts de ce d&eacute;placement pour vote lors de la prochaine AC (DAD)</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>Point sur le temps de travail et les plages dites obligatoires</strong> -&gt; plages recommand&eacute;es :</div>\r\n\r\n<div>LF fera une note de service &agrave; ce sujet la semaine prochaine.</div>\r\n\r\n<div>V&eacute;rifier la coh&eacute;rence avec les contrats de travail</div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Ch&egrave;ques Cadhoc</strong> : distribu&eacute;s d&eacute;but d&eacute;cembre, pas d&#39;autre type de carte cadeau par soucis de simplicit&eacute;</p>\r\n\r\n<p><strong>R&eacute;mun&eacute;ration de la co-g&eacute;rance </strong>: les co-g&eacute;rants expriment leur souhait d&#39;allouer une r&eacute;mun&eacute;ration compl&eacute;mentaire aux co-g&eacute;rants de l&#39;ordre de 1 000&euro; par co-g&eacute;rant par exercice. Ce sujet sera soumis au vote des associ&eacute;s lors de l&#39;AG.</p>\r\n\r\n<p><strong>Fin de mandats des co-g&eacute;rants actuels</strong></p>\r\n\r\n<ul>\r\n	<li>LF en mars</li>\r\n	<li>PC en octobre</li>\r\n	<li>VF en d&eacute;cembre</li>\r\n</ul>\r\n\r\n<div>Doit on aligner les 3 mandats pour qu&#39;ils se terminent en m&ecirc;me temps lors de l&#39;AG de d&eacute;cembre 2023 ?</div>\r\n\r\n<div>Tour de table : nombreux salari&eacute;s seraient favorable &agrave; des fins de mandat &eacute;tal&eacute;e afin d&#39;assurer la continuit&eacute; de la co-g&eacute;rance</div>\r\n\r\n<div>Ce sujet sera remis sur la table de l&#39;AG</div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Participation :</strong> pour rappel un d&eacute;blocage exceptionnel est possible sur la participation aquise au 01/01/2022, dans la limite de 10 000&euro; dans le but d&#39;effectuer des achats de biens ou de prestation. Demandes &agrave; effectuer aupr&egrave;s de LF ou de CR.</p>\r\n\r\n<p><strong>Interressement :</strong> l&#39;interressement calcul&eacute; au titre de l&#39;exercice clos au 30/06/2022 sera vers&eacute; sur les payes de novembre.</p>\r\n\r\n<p><strong>AG CADOLES :</strong> le mardi 6 d&eacute;cembre 2022 &agrave; 16h (hors temps de travail)</p>\r\n</div>\r\n\r\n<p><span style=\"color:#3498db\"><strong><span style=\"font-size:22px\">Questions diverses :</span></strong></span></p>\r\n\r\n<div><strong>Financement du Logiciel Libre</strong></div>\r\n\r\n<div>Code Lutin et de Nereide proposent d&#39;institutionaliser et de communiquer sur notre financement du logiciel libre via le site <a class=\"moz-txt-link-freetext\" href=\"https://copiepublique.fr/\">https://copiepublique.fr</a></div>\r\n\r\n<div>C&#39;est &eacute;galement d&#39;occasion de d&eacute;finir une r&egrave;gle de calcul pour le montant &agrave; allouer chaque ann&eacute;e.</div>\r\n\r\n<div>Nous avons besoin d&#39;un r&eacute;f&eacute;rent chez Cadoles pour g&eacute;rer cet aspect, des volontaires?</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>Actions en faveur de la hausse du co&ucirc;t du transport</strong> : que peut mettre en place Cadoles pour aider les salari&eacute;s ?</div>\r\n\r\n<div>R&eacute;flexion en cours, nous attendons vos propositions</div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\" style=\"text-align:center\"><strong>Prochaine AC le mardi 13 d&eacute;cembre</strong></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>','2022-11-25 14:05:24',1,0,'uploads/blogarticle/6380c87493cf2.jpg'),(45,41,3,'CR de l\'AC du 13/12/2022','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous + Nicolas Bourgeois (Mazars)</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Philippe, Laurent, Arnold</div>\r\n\r\n<div class=\"ace-line\">Pouvoirs : aucun</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 20min&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp; &nbsp; DAD : 10min</div>\r\n\r\n<div class=\"ace-line\">&nbsp;&nbsp;&nbsp; CR COPIL : 15min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe :</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"moz-forward-container\">\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Indicateurs internes MAJ au 30/11/22</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\">Situation au 30/11/2022 :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 397 056&euro; (dont 95 348&euro; factur&eacute;s d&#39;avance)</li>\r\n	<li>Travaux r&eacute;alis&eacute;s sur l&#39;exercice, non factur&eacute;s au 30/11 : 101 020&euro;</li>\r\n	<li>Reste &agrave; faire sur commandes : 110 515&euro; sur l&#39;exercice</li>\r\n	<li>Devis &agrave; l&#39;&eacute;tude pond&eacute;r&eacute;s : 416 575&euro; sur l&#39;exercice</li>\r\n	<li>Fin exercice estim&eacute; : 1 025 166&euro; (Rappel &eacute;quilibre d&#39;apr&egrave;s budget pr&eacute;visionnel : 1 067 733&euro;)</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<p>A noter :</p>\r\n\r\n<ul>\r\n	<li>D&#39;une&nbsp; mani&egrave;re g&eacute;n&eacute;rale les pond&eacute;rations appliqu&eacute;es sont plut&ocirc;t prudentes.</li>\r\n	<li>MSE : quasi 70% de notre CA, refonte de l&#39;infra cette ann&eacute;e, le volume sera r&eacute;duit par la suite.</li>\r\n	<li>March&eacute; EOLE : suite au dernier COPIL, le p&ocirc;le nous annonce une baisse de leurs engagements significative. Pas de nouvelles commande avant mars, les commandes actuelles sont quasiment &eacute;puis&eacute;es. Le budget qui sera allou&eacute; &agrave; la MCO EOLE2 sera vraisemblablement faible en 2023. Pas d&#39;engagement ferme en ce qui concerne EOLE3.\r\n	<ul>\r\n		<li>Baisse du pr&eacute;visionnel -25 000&euro;</li>\r\n		<li>R&eacute;-affectation des ressources n&eacute;cessaire : une r&eacute;union d&#39;&eacute;quipe est pr&eacute;vue en janvier, &agrave; priori nous avons de quoi occuper tout le monde &agrave; court terme</li>\r\n	</ul>\r\n	</li>\r\n	<li>EFS : incertitudes sur Sheila : baisse de pond&eacute;ration</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">Le budget pr&eacute;visionnel (charges) sera r&eacute;-&eacute;valu&eacute; courant janvier apr&egrave;s r&eacute;alisation de la situation comptable au 31/12.</div>\r\n</div>\r\n\r\n<p><span style=\"font-size:22px\"><span style=\"color:#167594\"><strong>Point COPIL / Divers</strong></span></span></p>\r\n\r\n<div><strong>R&eacute;-affectation des ressources CSS suite baisse d&#39;activit&eacute; sur EOLE</strong></div>\r\n\r\n<div>-&gt; CSS a des pistes, une r&eacute;union sera r&eacute;alis&eacute;e en janvier</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>Recrutement Dev</strong></div>\r\n\r\n<div>-&gt; fin du contrat Atol le 20/12, nous allons faire un CDD de 6 mois (junior) &agrave; Valentin de fa&ccedil;on &agrave; pallier provisoirement au besoin de ressource</div>\r\n\r\n<div>-&gt; ouverture officielle du poste DEV budg&eacute;t&eacute; en d&eacute;but d&#39;ann&eacute;e, Valentin pourra candidater s&#39;il le souhaite</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>Subvention presta&#39;inno</strong></div>\r\n\r\n<div>-&gt; accord du financeur &agrave; hauteur de 2 300&euro; pour financer l&#39;&eacute;tude de march&eacute; de la BSB, mais en attente renouvellement carte d&#39;identit&eacute; de Laetitia</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>Libre Entreprise :</strong> Souhaite-t-on continuer &agrave; faire partie du mouvement LE, doublon avec Cooptech? (de nombreux membres de LE font partie de Cooptech), Si oui, il faudra un r&eacute;f&eacute;rent LE chez Cadoles.</div>\r\n\r\n<div>-&gt; BG va &eacute;tudier la question</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>Petits Dej de l&#39;innovation :</strong> 1&egrave;re &eacute;dition de d&eacute;cembre</div>\r\n\r\n<div>-&gt; format &agrave; am&eacute;liorer mais &agrave; conserver et &agrave; renouveler en janv/f&eacute;v</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>Ateliers RH :</strong></div>\r\n\r\n<div>-&gt; LF va mettre en place des &eacute;changes 1/4h sur divers sujets RH &agrave; partir de mars/avril</div>\r\n\r\n<p><strong>Article Hackathon</strong> : relay&eacute; sur Linkedin</p>\r\n\r\n<p><strong>Vid&eacute;o Cadoles </strong>: diffusion &agrave; faire sur le site Cooptech, puis sur site Cadoles (CR/ML)</p>\r\n<strong>KubeCon de la Linux fondation &agrave; Amterdam en avril 2023</strong>:\r\n\r\n<div>Souhaitent s&#39;y rendre : VF, PC, RM, CMS, ML, LS, WP</div>\r\n\r\n<div>Pr&eacute;paration du d&eacute;placement : Rudy se propose pour r&eacute;unir les infos et co&ucirc;ts de ce d&eacute;placement pour vote lors de la prochaine AC (DAD)</div>\r\n\r\n<div>-&gt; DAD &agrave; pr&eacute;parer pour la prochaine AC</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>Point sur le temps de travail et les plages dites obligatoires</strong> -&gt; plages recommand&eacute;es :</div>\r\n\r\n<div>LF fera une note de service + affichage</div>\r\n\r\n<p><strong>Participation :</strong> pour rappel un d&eacute;blocage exceptionnel est possible sur la participation aquise au 01/01/2022, dans la limite de 10 000&euro; dans le but d&#39;effectuer des achats de biens ou de prestation. Demandes &agrave; effectuer aupr&egrave;s de LF ou de CR avant le 31/12/22.</p>\r\n\r\n<p><strong>Litige ELiade :</strong> en attente des conclusions de la partie adverse (d&eacute;lai 31/12)</p>\r\n</div>\r\n\r\n<p><strong>Financement du Logiciel Libre</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div>-&gt; constitution d&#39;un groupe de travail (BB, RM et LG)</div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>Gestion de la participation</strong></div>\r\n\r\n<div>Aujourd&#39;hui la participation est plac&eacute;e en compte courants et r&eacute;mun&eacute;r&eacute;e par Cadoles &agrave; 2.5%. Le suivi et la gestion de la participation est r&eacute;alis&eacute;e sur un tableur. Le risque d&#39;erreur est important et le suivi fastidieux.</div>\r\n\r\n<div>CR va proposer prochainement deux alternatives (DAD en pr&eacute;paration) :</div>\r\n\r\n<ul>\r\n	<li>Externalisation avec un organisme financier</li>\r\n	<li>Utilisation d&#39;une appli de gestion en interne</li>\r\n</ul>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\" style=\"text-align:center\"><strong>Prochaine AC le mardi (&agrave; valider) janvier</strong></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>','2022-12-15 11:26:33',1,1,'uploads/blogarticle/639af83848a5f.jpg'),(46,41,3,'CR de l\'AC du 17/01/2023','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous + Nicolas Bourgeois (Mazars)</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Ludwig, Arnold</div>\r\n\r\n<div class=\"ace-line\">Pouvoirs : aucun</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 20min&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp; &nbsp; DAD : 10min</div>\r\n\r\n<div class=\"ace-line\">&nbsp;&nbsp;&nbsp; CR COPIL : 15min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe :</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"moz-forward-container\">\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Indicateurs internes MAJ au 31/12/22</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\"><strong>Situation au 31/12/2022 :</strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 530 890 (dont 67 220&euro; factur&eacute;s d&#39;avance)</li>\r\n	<li>Travaux r&eacute;alis&eacute;s sur l&#39;exercice, non factur&eacute;s au 31/12 : 43 190&euro;</li>\r\n	<li>Reste &agrave; faire sur commandes : 42 160&euro; sur l&#39;exercice</li>\r\n	<li>Devis &agrave; l&#39;&eacute;tude pond&eacute;r&eacute;s : 394 744&euro; sur l&#39;exercice</li>\r\n	<li>Fin exercice estim&eacute; : 1 010 985&euro; (Rappel &eacute;quilibre d&#39;apr&egrave;s budget pr&eacute;visionnel : 1 067 733&euro;)</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\"><strong>Situation comptable au 31/12/2022 :</strong></div>\r\n\r\n<div class=\"ace-line\">La situation comptable au 31/12 montre un r&eacute;sultat 19 500&euro;.</div>\r\n\r\n<div class=\"ace-line\">Les charges r&eacute;elles sont l&eacute;g&egrave;rement inf&eacute;rieures &agrave; ce que nous avions budgetis&eacute;.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">Le budget &eacute;quilibre (charges) va &ecirc;tre r&eacute;-&eacute;valu&eacute; en COPIL prochainement.</div>\r\n\r\n<div class=\"ace-line\">Si nous ne sommes pas inquiets pour cet exercice, il est &eacute;vident que nous devons trouver de nouveaux clients/march&eacute;s sous peine d&#39;impacter fortement le r&eacute;sultat de l&#39;exercice suivant.</div>\r\n\r\n<div class=\"ace-line\">Notre priorit&eacute; est de consolider&nbsp; l&#39;activit&eacute; historique de Cadoles.</div>\r\n\r\n<div class=\"ace-line\">En parrall&egrave;le nous allons profiter de la r&eacute;-organisation des ressources pour allouer du temps au plan de d&eacute;veloppement.</div>\r\n\r\n<p>A noter :</p>\r\n\r\n<ul>\r\n	<li>D&#39;une&nbsp; mani&egrave;re g&eacute;n&eacute;rale les pond&eacute;rations appliqu&eacute;es sont plut&ocirc;t prudentes.</li>\r\n	<li>MSE : quasi 70% de notre CA, refonte de l&#39;infra cette ann&eacute;e, le volume sera r&eacute;duit par la suite.</li>\r\n	<li>March&eacute; EOLE : suite au dernier COPIL, le p&ocirc;le nous annonce une baisse de leurs engagements significative. Pas de nouvelles commande avant mars, les commandes actuelles sont quasiment &eacute;puis&eacute;es. Le budget qui sera allou&eacute; &agrave; la MCO EOLE2 sera vraisemblablement faible en 2023. Pas d&#39;engagement ferme en ce qui concerne EOLE3.\r\n	<ul>\r\n		<li>Baisse du pr&eacute;visionnel -25 000&euro;</li>\r\n		<li>R&eacute;-affectation des ressources n&eacute;cessaire : une r&eacute;union d&#39;&eacute;quipe est pr&eacute;vue en janvier, &agrave; priori nous avons de quoi occuper tout le monde &agrave; court terme</li>\r\n	</ul>\r\n	</li>\r\n	<li>EFS : baisse significative de pond&eacute;ration (les commandes promises peinent &agrave; arriver)</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>DAD</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid13\">\r\n<div class=\"ace-line\" id=\"magicdomid13\"><strong>Cr&eacute;ation de la fonction Super Panda</strong></div>\r\n\r\n<div class=\"ace-line\">Vote &agrave; main lev&eacute; : adopt&eacute; &agrave; l&#39;unanimit&eacute;</div>\r\n\r\n<div class=\"ace-line\">Tirage au sort : Ludwig est nomm&eacute; &quot;super Panda&quot; jusqu&#39;&agrave; la prochaine AC</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\"><strong>Gestion de la participation</strong></div>\r\n\r\n<div class=\"ace-line\">Interne : 1</div>\r\n\r\n<div class=\"ace-line\">Externe : 12</div>\r\n\r\n<div class=\"ace-line\">=&gt; gestion de la particpation en externe (&eacute;tablissement bancaire) valid&eacute;, n&eacute;cessitera la modification de l&#39;accord de participation.</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n</div>\r\n\r\n<p><span style=\"font-size:22px\"><span style=\"color:#167594\"><strong>Point COPIL / Divers</strong></span></span></p>\r\n\r\n<div><strong>Entretiens individuels</strong></div>\r\n\r\n<div>-&gt; LF vous a envoy&eacute; par email vos convocations ainsi qu&#39;un questionnaire &agrave; remplir et &agrave; retourner &agrave; la co-g&eacute;rance au plus tard 24h avant la date de votre entretien.</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>AG Oralia </strong></div>\r\n\r\n<div>Rudy et Benjamin B ont assist&eacute; &agrave; l&#39;AG du syndic de copro de l&#39;immeuble,</div>\r\n\r\n<div>-&gt; ascenseur : d&eacute;but des travaux de r&eacute;fection le 06/03, immobilisation de l&#39;ascenseur &agrave; pr&eacute;voir, acc&egrave;s porte escalier &agrave; g&eacute;rer</div>\r\n\r\n<div>-&gt; sdb 1er &eacute;tage : le propri&eacute;taire du 1er &eacute;tage souhaitait modifier ses sanitaires pour ajouter une douche, l&#39;AG refuse la prise en charge des frais, mais autorise le propri&eacute;taire &agrave; le faire &agrave; ses frais s&#39;il le souhaite. Il est envisag&eacute; de r&eacute;aliser plut&ocirc;t une douche avec acc&egrave;s commun au RDC.</div>\r\n\r\n<div>-&gt; Changement du totem : refus&eacute;, sera rediscut&eacute; ult&eacute;rieurement</div>\r\n\r\n<div>-&gt; D&eacute;cret tertiaire : l&#39;AG valide le devis de Nexity pour les parties communes, Cadoles doit r&eacute;alis&eacute; les audits/inscriptions n&eacute;cessaires pour les parties privatives (nous sommes d&eacute;j&agrave; en retard) =&gt; le COPIL prend le sujet</div>\r\n\r\n<div>&nbsp;</div>\r\n&nbsp;\r\n\r\n<div><strong>Petits Dej de l&#39;innovation : prochain pr&eacute;vu le 21/02</strong></div>\r\n\r\n<div>-&gt; &agrave; organiser par le super Panda</div>\r\n\r\n<div>&nbsp;</div>\r\n<strong>KubeCon de la Linux fondation &agrave; Amterdam en avril 2023</strong>:\r\n\r\n<div>Souhaitent s&#39;y rendre : VF, PC, RM, CMS, ML, LS, WP</div>\r\n\r\n<div>RM a &eacute;valu&eacute; le co&ucirc;t, il est plus &eacute;lev&eacute; que pr&eacute;vu, nous allons devoir r&eacute;duire le nombre de participants.</div>\r\n\r\n<div>-&gt; DAD &agrave; pr&eacute;parer pour la prochaine AC</div>\r\n\r\n<div>&nbsp;</div>\r\n<strong>Litige ELiade :</strong> aucune modification dans les requ&ecirc;tes de M. Elliade en appel, ce qui est plut&ocirc;t positif pour nous.</div>\r\n\r\n<p>&nbsp;\r\n<p>&nbsp;\r\n<div>&nbsp;</div>\r\n</p>\r\n</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\" style=\"text-align:center\"><strong>Prochaine AC le mardi 14 f&eacute;vrier</strong></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>','2023-01-19 12:33:05',1,1,'uploads/blogarticle/63c92a6d84b9b.jpg'),(47,9,3,'CR DE L\'AC DU 14/02/2023','<h1>CR de l&#39;AC du 14/02/2023</h1>\r\n\r\n<div class=\"blogbody\">\r\n<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous ( saufs les axcus&eacute;s) + Anthony AZEVEDO (Mazars)</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Rudy, Arnold, C&eacute;line</div>\r\n\r\n<div class=\"ace-line\">Pouvoirs : Laetitia ( celui de C&eacute;line)</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 15min&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp; &nbsp; DAD : 30min</div>\r\n\r\n<div class=\"ace-line\">&nbsp;&nbsp;&nbsp; CR COPIL : 60min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 25 min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe :</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"moz-forward-container\">\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Indicateurs internes MAJ au 31/01/23</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par Philippe Caseiro</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\"><strong>Situation au 31/01/2023 :</strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Fin exercice estim&eacute; : 1 036 427&euro;&nbsp; (Rappel &eacute;quilibre d&#39;apr&egrave;s budget pr&eacute;visionnel : 1 043 654&euro;)</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n<span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>DAD</strong></span></span></div>\r\n\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">\r\n<div class=\"ace-line\" id=\"magicdomid13\"><strong>Cr&eacute;ation d&#39;un compte SymfonyCasts</strong></div>\r\n\r\n<div class=\"ace-line\">Vote &agrave; main lev&eacute; : adopt&eacute; &agrave; l&#39;unanimit&eacute;</div>\r\n\r\n<div class=\"ace-line\">Valentin prend en charge la cr&eacute;ation du compte et se rapprochera de C&eacute;line et Laetitia pour la mise en place compl&egrave;te.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\"><strong>Formation Udemy</strong></div>\r\n\r\n<div class=\"ace-line\">Vote &agrave; main lev&eacute; : majorit&eacute; de 11 personnes pour la solution &quot;ne rien faire&quot; et 1 personne pour la solution 2&nbsp;</div>\r\n&Agrave; potentiellement reproposer avec protocole de suivi/demande/impl&eacute;mentation</div>\r\n</div>\r\n</div>\r\n\r\n<p><span style=\"font-size:22px\"><span style=\"color:#167594\"><strong>Points COPIL </strong></span></span></p>\r\n\r\n<div>\r\n<div class=\"moz-text-html\" lang=\"x-unicode\"><span style=\"color:#167594\">Etude de march&eacute; : Arcad</span></div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">-&gt; restitution par le BSB le 24/01 &agrave; 13h30</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">Cible: bar et restaurant, &agrave; cave</div>\r\n\r\n<ul>\r\n	<li class=\"moz-text-html\" lang=\"x-unicode\">14% se disent pr&ecirc;ts &agrave; acheter la solution (sans m&ecirc;me la connaitre)</li>\r\n	<li class=\"moz-text-html\" lang=\"x-unicode\">Montant d&#39;achat propos&eacute; par les cibles: entre 70&euro; et 100&euro; par mois</li>\r\n	<li class=\"moz-text-html\" lang=\"x-unicode\">Utilisation: suivi et gestion des stocks ,&nbsp; prise de commande</li>\r\n	<li class=\"moz-text-html\" lang=\"x-unicode\">Proposition de 1&egrave;re mise sur le march&eacute; en juin</li>\r\n</ul>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">Tous les collaborateurs int&eacute;ress&eacute;s par ce projet sont invit&eacute;s &agrave; se manifester et &agrave; participer &agrave; ce travail.</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">\r\n<div class=\"moz-text-html\" lang=\"x-unicode\"><span style=\"color:#167594\">Strat&eacute;gie Communication/Marketing/Commerciale</span></div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">Rencontre de Gaelle Jouanne (Sp&eacute;cialis&eacute;e en Communication et Marketing) + d&eacute;mo Arcad le 07/02 avec la pr&eacute;sence de Guillaume Petitjean (Sp&eacute;cialis&eacute; en strat&eacute;gie commerciale)</div>\r\n\r\n<ul>\r\n	<li class=\"moz-text-html\" lang=\"x-unicode\">proposition commerciale de 10 jours &agrave; 12 000&euro;HT</li>\r\n	<li class=\"moz-text-html\" lang=\"x-unicode\">finalit&eacute; de cette PR: livrable =&nbsp; &eacute;tude et plan strat&eacute;gique complet&nbsp; Communcation/ Marketing / Commercial sur Cadoles et le projet Arcad</li>\r\n	<li class=\"moz-text-html\" lang=\"x-unicode\">Gaelle et Guillaume sont enthousiasm&eacute;s par ce projet qui a selon eux toutes ses chances</li>\r\n	<li class=\"moz-text-html\" lang=\"x-unicode\">Tout le monde est favorable &agrave; cet investissement</li>\r\n</ul>\r\n</div>\r\n</div>\r\n\r\n<div><span style=\"color:#167594\"><strong>PANDA du mois </strong></span><span style=\"color:#000000\">tir&eacute; au sort lors de cette AC : Laetitia</span></div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div>\r\n<div class=\"moz-text-html\" lang=\"x-unicode\"><span style=\"color:#167594\">2&egrave;me &eacute;dition des Petits Dej&#39; de l&#39;innovation chez Cadoles</span></div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">-&gt; 21/02/2023</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">Il y a deux propositions, c&#39;est parfait!</div>\r\n</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><span style=\"color:#167594\">Libre Entreprise + Financement du Logiciel Libre</span></div>\r\n\r\n<div>Ces deux sujets n&#39;ont pas pu &ecirc;tre vus lors du dernier COPIL qui n&#39;a pas pu avoir lieu faute de planning trop charg&eacute;. Mais ils seront bien &eacute;videmment trait&eacute;s lors du prochain COPIL et vous sera communiqu&eacute; par CR.</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div>\r\n<div class=\"moz-text-html\" lang=\"x-unicode\"><span style=\"color:#167594\">KubeCon du 17 au 21 avril &agrave; Amsterdam</span></div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\"><a class=\"moz-txt-link-freetext\" href=\"https://events.linuxfoundation.org/kubecon-cloudnativecon-europe/\">https://events.linuxfoundation.org/kubecon-cloudnativecon-europe/</a></div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">-&gt; D&#39;apr&egrave;s les recherches effectu&eacute;es par Rudy, le co&ucirc;t total pour 2 pers serait d&#39;environ 5 000&euro;, ce qui rentre dans le budget que nous avions pr&eacute;vu.</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">-&gt; Le COPIL propose PC et WP pour ce d&eacute;placement (au regard des crit&egrave;res suivants : connaissances techniques, niveau d&#39;anglais, ap&eacute;tence commerciale) - William se charge d&#39;acheter les places aujourd&#39;hui. Si l&#39;un des deux collaborateurs ne peut s&#39;y rendre, il sera alors remplac&eacute; par Matthieu.</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">\r\n<div class=\"moz-text-html\" lang=\"x-unicode\"><span style=\"color:#167594\">Developers Group Dijon</span></div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">Starter Lab Rust dans les locaux de la BPCE = Je cr&eacute;e mon 1er projet en RUST</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">Inscriptions obligatoires avant le 20 mars&nbsp;: <a class=\"moz-txt-link-freetext\" href=\"https://lnkd.in/ejnT3Xpp\">https://lnkd.in/ejnT3Xpp</a><br />\r\nNombre de place limit&eacute; &agrave; 50 personnes</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">Personne n&#39;est attir&eacute; par cet &eacute;v&egrave;nnement, mais il est primordiale pour la communication et l&#39;image CADOLES d&#39;y participer . Ainsi, soit Philippe, soit Vincent s&#39;y rendra, accompagn&eacute; d&#39;un autre collaborateur.</div>\r\n</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">\r\n<div class=\"moz-text-html\" lang=\"x-unicode\"><span style=\"color:#167594\">Hausse des prix du transport</span></div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">R&eacute;flexions sur les actions possibles pour &quot;contrer&quot; la hausse actuelle des prix du transport (sans parler des p&eacute;nuries), quelques pistes ont &eacute;t&eacute; &eacute;voqu&eacute;es:</div>\r\n\r\n<ul>\r\n	<li>V&eacute;hicule de service &eacute;lectrique</li>\r\n	<li>Pr&ecirc;ts &agrave; taux z&eacute;ro pour les salari&eacute;s souhaitant s&#39;&eacute;quiper d&#39;un v&eacute;hicule &eacute;lectrique ou hybride</li>\r\n	<li>Installation d&#39;une borne de recharge &agrave; disposition des salari&eacute;s</li>\r\n	<li>autres suggestions? ...</li>\r\n</ul>\r\n\r\n<p>-&gt; R&eacute;flexions &agrave; proposer en AC - il faut se renseigner sur la prime de transport ( propos&eacute; par Anthony AZEVEDO) et la prime de mobilit&eacute; ( Laetitia) -</p>\r\n</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\"><span style=\"font-size:22px\"><span style=\"color:#167594\"><strong>Questions diverses </strong></span></span></div>\r\n</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\"><strong>D&eacute;cret tertiaire (Benjamin Bohard)</strong></div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">Apr&egrave;s ses recherches et la r&eacute;colte des informations n&eacute;cessaires, il semble &agrave; Benjamin que cela (hors expertise obligatoire) peut &ecirc;tre trait&eacute; en interne dans le mois.</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">\r\n<div class=\"moz-text-html\" lang=\"x-unicode\"><strong>Activit&eacute; de Formation (Benjamin Bohard)</strong></div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">Le dossier avance bien. Benjamin ira voir les personnes qui ont r&eacute;pondu positivement au questionnaire. Se posent les questions suivantes:</div>\r\n\r\n<ul>\r\n	<li class=\"moz-text-html\" lang=\"x-unicode\">Certification Qualiopi?</li>\r\n	<li class=\"moz-text-html\" lang=\"x-unicode\">Contraintes des formations?</li>\r\n</ul>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\"><strong>Point QUID (Arnaud)</strong></div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">Il y a eu une perte de temps et financier sur les boxes et les propositions commerciales demand&eacute;es qui ne seront officiellement pas retenues par l&#39;EFS.</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">L&#39;EFS&nbsp; a une exclusivit&eacute; avec une entreprise priv&eacute;e COAXIA, pour tout ce qui est mobile/num&eacute;rique. L&#39;EFS propose donc que nous fassions de la sous-traitance avec ce groupe. Une 1&egrave;re prise de contact a &eacute;t&eacute; faite. Le contact &eacute;tant en vacances, on attend donc son retour pour un 1er entretien ( Arnaud et certainement Philippe).</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\" style=\"text-align:center\"><strong>Prochaine AC le mardi 14 mars</strong></div>\r\n\r\n<p>&nbsp;</p>\r\n</div>','2023-02-14 17:38:57',1,0,'uploads/blogarticle/63ebb505a6ca6.jpg'),(48,41,3,'CR de l\'Assemblée Collective Extraordinaire du 07/03/2023','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous&nbsp; sauf excus&eacute;s</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Benjamin B.</div>\r\n\r\n<div class=\"ace-line\">Pouvoirs :</div>\r\n\r\n<ul>\r\n	<li>William en TT -&gt; Matthieu</li>\r\n	<li>Benjamin G en TT -&gt; CHarles Maxime</li>\r\n	<li>Benjamin B -&gt; Matthieu</li>\r\n</ul>\r\n\r\n<div class=\"ace-line\" style=\"margin-left:40px\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4847\">&nbsp;&nbsp;&nbsp; DAD : 60min&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3057\">\r\n<p><strong>Embauche en CDI de Ludwig SEYS &agrave; l&#39;issue de son contrat d&#39;alternance &agrave; compter du 09/03/2023</strong></p>\r\n\r\n<p>Anciennet&eacute; reprise : 2 ans - Salaire junior</p>\r\n\r\n<ul>\r\n	<li>pour : 8</li>\r\n	<li>contre : 1</li>\r\n	<li>abstention : 1</li>\r\n</ul>\r\n</div>\r\n\r\n<p><strong>Info COPIL</strong></p>\r\n\r\n<p>Le COPIL r&eacute;fl&eacute;chit &agrave; un DAD pour proposer l&#39;embauche de Gaelle Jouanne en CDD 6 mois &agrave; mi-temps pour initier tous les travaux en mati&egrave;re de communication/marketing n&eacute;cessaires et pr&eacute;vus dans le plan de d&eacute;veloppement de Cadoles. (pas seulement Arcad)</p>\r\n\r\n<p>Nous devons encore travailler sur le budget et le financement de cette &eacute;ventuelle embauche.</p>','2023-03-09 14:42:34',1,0,'uploads/blogarticle/6409e3d5cc3d4.png'),(49,41,3,'CR de l\'AC du 14/03/2023','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous + Nicolas Bourgeois (Mazars)</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Philippe, William, Rudy, Arnold</div>\r\n\r\n<div class=\"ace-line\">Pouvoirs : William -&gt; Benjamin G - Rudy -&gt; Matthieu</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 20min&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp; &nbsp; DAD : 10min</div>\r\n\r\n<div class=\"ace-line\">&nbsp;&nbsp;&nbsp; CR COPIL : 15min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe :</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"moz-forward-container\">\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Indicateurs internes MAJ au 28/02/2023</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\"><strong>Situation au 28/02/2023 :</strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 727 586&euro; (dont 44 803&euro; factur&eacute;s d&#39;avance)</li>\r\n	<li>Travaux r&eacute;alis&eacute;s sur l&#39;exercice, non factur&eacute;s au 28/02 : 117 190&euro;</li>\r\n	<li>Reste &agrave; faire sur commandes : 90 640&euro; sur l&#39;exercice</li>\r\n	<li>Devis &agrave; l&#39;&eacute;tude pond&eacute;r&eacute;s : 216 493&euro; sur l&#39;exercice</li>\r\n	<li>Fin exercice estim&eacute; : 1 034 719&euro; (Rappel &eacute;quilibre d&#39;apr&egrave;s budget pr&eacute;visionnel : 1 034 719&euro;)</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\"><strong>Tr&eacute;sorerie au 28/02/2023 :</strong></div>\r\n\r\n<div class=\"ace-line\">En banque :\r\n<ul>\r\n	<li>Compte ch&egrave;que : 62 550.73&euro;</li>\r\n	<li>Compte Optipro : 450 000&euro;</li>\r\n</ul>\r\nDont\r\n\r\n<ul>\r\n	<li>Capital Social : 10 000&euro;</li>\r\n	<li>R&eacute;serve l&eacute;gale : 11 000&euro;</li>\r\n	<li>Participation des salari&eacute;s : 58 596.19&euro;</li>\r\n</ul>\r\n\r\n<p>A noter :</p>\r\n\r\n<ul>\r\n	<li>Factures clients &eacute;mises au 28/02 non r&eacute;gl&eacute;es : 15 390&euro; (dont facture &eacute;chue pour la Savoie de 3 840&euro;, relance pr&eacute;vue)</li>\r\n	<li>Factures fournisseur re&ccedil;ues au 28/02 non r&eacute;gl&eacute;es : 8 526.13&euro; (&agrave; r&eacute;gler sur mars pour la plupart)</li>\r\n</ul>\r\n</div>\r\n<span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>DAD</strong></span></span></div>\r\n\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">\r\n<div class=\"ace-line\" id=\"magicdomid13\"><strong>Cr&eacute;ation du r&ocirc;le de &quot;r&eacute;f&eacute;rent fili&egrave;re&quot;</strong></div>\r\n\r\n<div class=\"ace-line\">oui : 13</div>\r\n\r\n<div class=\"ace-line\">non : 0</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">Benjamin G. se propose pour tenir ce r&ocirc;le pour une dur&eacute;e d&#39;un an.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Panda du mois</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">Tirage au sort : Vincent</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n</div>\r\n</div>\r\n<span style=\"font-size:22px\"><span style=\"color:#167594\"><strong>Point COPIL / Divers</strong></span></span></div>\r\n</div>\r\n</div>\r\n\r\n<div><strong>Prochain petit Dej de l&#39;innovation</strong></div>\r\n\r\n<div>-&gt; mardi 21/02 &agrave; 9h - en attente de sujets</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>Formation URSCOP</strong></div>\r\n\r\n<div>-&gt; a lieu jeudi 16/03 pour 6 coop&eacute;rateurs</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>Developers Group</strong></div>\r\n\r\n<div>-&gt; &eacute;vennement Rust le 23/03 &agrave; 16h, participent : AF, ML, PC</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div>\r\n<div class=\"ace-line\" id=\"magicdomid12\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Questions diverses</strong></span></span></div>\r\n<strong>Financement du Logiciel libre</strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">-&gt; vos propositions de financement sont attendues pour la fin du mois de mars</div>\r\n\r\n<div class=\"ace-line\">-&gt; Benjamin pr&eacute;sentara un DAD le mois prochain pour Copie Publique (initiative visant &agrave; d&eacute;finir une r&egrave;gle de calcul sur le montant &agrave; allouer chaque ann&eacute;e et &agrave; communiquer sur nos dons)</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\"><strong>Chauffage</strong></div>\r\n\r\n<div class=\"ace-line\">-&gt; Pour limiter notre consommation, il est n&eacute;cessaire d&#39;optimiser nos utilisation du chauffage, Benjamin B. va effectuer un r&eacute;glage commun &agrave; toutes les clims sur la base de 19&deg;C la journ&eacute;e et 16&deg;C la nuit et le week-end.</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\" style=\"text-align:center\"><strong>Prochaine AC le mardi 11 avril</strong></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>','2023-03-16 16:01:45',1,0,'uploads/blogarticle/64132fc79430d.jpg'),(50,18,3,'CR de l\'AC du 11/04/23','<p><strong>- Pr&eacute;sentation financi&egrave;re autour des indicateurs</strong><br />\r\n<br />\r\n&gt; Perte de CA suite aux manques de commandes EFS.<br />\r\n&gt; Emploi des jours non travaill&eacute;s notamment sur le Projet Arcad.<br />\r\n&gt; Discussion autour de l&rsquo;&eacute;tat comptable et de l&rsquo;avenir de l&rsquo;EFS.<br />\r\n&gt; Attente des infos du comptable sur les solutions d&rsquo;immobilisation pour le Projet Arcad.</p>\r\n\r\n<p><strong>- Point COPIL</strong></p>\r\n\r\n<p>&gt; Pyxis et Envole &agrave; pr&eacute;voir.<br />\r\n&gt; Quelques pistes sur la route des potes et consorts.<br />\r\n&gt; Pr&eacute;f&eacute;rable de minimiser les cong&eacute;s sur le mois de juin.<br />\r\n&gt; Pr&eacute;sentation de la journ&eacute;e de Pentec&ocirc;te.<br />\r\n&gt; Discussion autour de notre implications autour de la Transition Ecologique.</p>\r\n\r\n<p><strong>- Point Fili&egrave;re avec Benjamin Gaud&eacute;</strong></p>\r\n\r\n<p>&gt; LE&nbsp;: Atelier le 27 avril en visio pour cr&eacute;er un sujet qui pr&eacute;sente notre mode de fonctionnement (scop, libre, &hellip;) pour communiquer autour et recruter de nouvelles entreprise.<br />\r\n&gt; LE&nbsp;: Cadoles devait organiser la journ&eacute;e LE, mais remis &agrave; plus tard pour cause de Covid. Il faut encore d&eacute;finir le budget en fonction du nombre de participants. Question de notre volont&eacute; de renouveller l&rsquo;organisation de cet &eacute;v&eacute;nement courant octobre ou novembre.<br />\r\n&gt; Scop du num&eacute;rique&nbsp;: R&eacute;union autour de la structuration de la fili&egrave;re Tech des Scop, pour pr&eacute;sentation &agrave; Direction G&eacute;n&eacute;rale des SCOP au mois de juin.</p>\r\n\r\n<p><strong>- DAD&nbsp;:</strong><br />\r\n&gt; Ch&egrave;ques d&eacute;jeuner / Carte UP</p>\r\n\r\n<p>Non obligation de prendre les Tickets Restaurant sans compensation financi&egrave;re.<br />\r\n10 Pour<br />\r\n2 Contre</p>\r\n\r\n<p>&gt; Mission Communication</p>\r\n\r\n<p>Accepter la prestation de Communication/Maketing de Gaelle pour Cadoles<br />\r\n11 Pour<br />\r\n1 Blanc</p>\r\n\r\n<p><strong>- Le mot du Panda</strong></p>\r\n\r\n<p>Chasse aux Oeufs au lendemain de P&acirc;ques<br />\r\nNouveau Panda&nbsp;: Arnold.</p>\r\n\r\n<p><strong>- Points Divers&nbsp;:</strong><br />\r\n&gt; Developpers Group Dijon&nbsp;: Retour sur la derni&egrave;re participation. ML continue de suivre le sujet.<br />\r\n&gt; Transition Ecologique&nbsp;: La route des potes est venu vers nous justement de part nos anciennes implication dans le domaines. C&rsquo;est un crit&egrave;re qui pourrait &ecirc;tre invalidant dans les futur projets publiques. Ludwig Seys prend en charge le sujet. Premier rendu &agrave; la prochaine AC.<br />\r\n&gt; Showroom de l&rsquo;innovation&nbsp;: Participation de Charles et peut &ecirc;tre Arnold.<br />\r\n&gt; Choix des projets Open Source &agrave; financer&nbsp;: document envoy&eacute; &agrave; tout le monde. Fin des votes vendredi 14. D&eacute;pouillement lundi le 17.<br />\r\n&gt; SISIRH&nbsp;: Rien de nouveau. Il faut recontacter l&rsquo;ADEME pour la marche &agrave; suivre.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>','2023-04-12 08:43:50',1,0,NULL),(51,41,3,'CR de l\'AC du 16/05/2023','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous + Nicolas Bourgeois (Mazars)</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Rudy, Arnold, Ludwig, Valentin</div>\r\n\r\n<div class=\"ace-line\">Pouvoirs :</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 20min&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp; &nbsp; DAD : 10min</div>\r\n\r\n<div class=\"ace-line\">&nbsp;&nbsp;&nbsp; CR COPIL : 15min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe :</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"moz-forward-container\">\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Indicateurs internes MAJ au 15/05/2023</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid14\"><strong>Situation comptable au 31/03/2023 : (documents envoy&eacute;s par email : SIG au 31/03 + pr&eacute;visionnel charges)</strong></div>\r\n\r\n<div class=\"ace-line\">Une situation comptable a &eacute;t&eacute; r&eacute;alis&eacute;e au bout de trois trimestres d&#39;exercice, soit au 31/03. La situ laisse apparaitre un r&eacute;sultat d&#39;exploitation de 13 605&euro;.</div>\r\n\r\n<div class=\"ace-line\">Les charges r&eacute;alis&eacute;es sont l&eacute;g&egrave;rement inf&eacute;rieures &agrave; celles escompt&eacute;es dans le pr&eacute;visionnel. (750 231&euro; r&eacute;alis&eacute; pour 783 201&euro; au budget)</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">Une projection des charges sur le dernier trimestre laisse &agrave; supposer total des charges estim&eacute; &agrave; 1 017 860&euro; en fin d&#39;exercice. (d&eacute;duction faite des subventions d&#39;exploitation).</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid293\"><strong>Situation au 15/05/2023 :</strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 833 961&euro; (dont 23 534&euro; factur&eacute;s d&#39;avance)</li>\r\n	<li>Travaux r&eacute;alis&eacute;s sur l&#39;exercice, non factur&eacute;s au 15/05 : 114 090&euro;</li>\r\n	<li>Reste &agrave; faire sur commandes : 12 090&euro; sur l&#39;exercice</li>\r\n	<li>Devis &agrave; l&#39;&eacute;tude pond&eacute;r&eacute;s : 68 036&euro; sur l&#39;exercice</li>\r\n	<li>Fin exercice estim&eacute; : 1 004 643&euro; (Rappel &eacute;quilibre d&#39;apr&egrave;s budget pr&eacute;visionnel : 1 043 654&euro;)</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">Un d&eacute;calage de facturation du MSE de mars li&eacute; &agrave; des formalit&eacute;s administratives (repuvellement march&eacute;), les prestations de mars ont &eacute;t&eacute; factur&eacute;es d&eacute;but mai avec avril.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\"><strong>Tr&eacute;sorerie au 30/04/2023 :</strong></div>\r\n\r\n<div class=\"ace-line\">En banque :\r\n<ul>\r\n	<li>Compte ch&egrave;que : 61 402.06&euro;</li>\r\n	<li>Compte Optipro : 380 231,13&euro; (d&eacute;calage tr&eacute;sorerie li&eacute; &agrave; la facturation MSE)</li>\r\n</ul>\r\nDont\r\n\r\n<ul>\r\n	<li>Capital Social : 10 000&euro;</li>\r\n	<li>R&eacute;serve l&eacute;gale : 11 000&euro;</li>\r\n	<li>Participation des salari&eacute;s : 58 596.19&euro;</li>\r\n</ul>\r\n\r\n<p>A noter :</p>\r\n\r\n<ul>\r\n	<li>Factures clients &eacute;mises au 30/04 non r&eacute;gl&eacute;es : 43 680&euro; (EFS)</li>\r\n	<li>Factures fournisseur re&ccedil;ues au 30/04 non r&eacute;gl&eacute;es : 3 240,79&euro; (&agrave; r&eacute;gler sur mai pour la plupart)</li>\r\n</ul>\r\n</div>\r\n<span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>DAD</strong></span></span></div>\r\n\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pas de DAD\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Panda du mois</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">Tirage au sort : Rudy</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n</div>\r\n</div>\r\n<span style=\"font-size:22px\"><span style=\"color:#167594\"><strong>Point COPIL / Divers</strong></span></span></div>\r\n</div>\r\n</div>\r\n\r\n<div>cf CR COPIL</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>Pr&eacute;sentation du plan communication/marketing de Ga&euml;lle</strong></div>\r\n\r\n<div>-&gt; cf pr&eacute;sentation qui sera envoy&eacute;e par e-mail</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>Petits Dej&#39; de l&#39;innovation chez Cadoles</strong>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">-&gt; prochaine &eacute;dition le<strong> mardi 23/05 &agrave; 9h15</strong> (organisation WP en l&#39;absence de Rudy)</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">Will : chat GPT &amp; co</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">Arnold : pr&eacute;sentation de son jeu</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\"><strong>Developers Group Dijon (ML)</strong>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&ldquo;Pitch Party&rdquo; mardi 27 juin 2023 &agrave; 16h dans les locaux d&rsquo;Alteca</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">-&gt; <strong>appel &agrave; id&eacute;es de pitch </strong>(5min) &agrave; proposer &agrave; Matthieu <strong>avant fin mai</strong></div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">-&gt; Suggestions PC/ML :&nbsp; Bouncer, Emissary ?</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">\r\n<div class=\"moz-text-html\" lang=\"x-unicode\"><strong>Lundi de Pentec&ocirc;te</strong></div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\"><strong>29/05/2023 :</strong> jour travaill&eacute; chez Cadoles, journ&eacute;e &agrave; organiser sur le m&ecirc;me mod&egrave;le que l&#39;ann&eacute;e derni&egrave;re (email &agrave; envoyer par la co-g&eacute;rance)</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">-&gt; Proposition :</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; Echange d&eacute;bat sur les &eacute;volutions r&eacute;centes de Cadoles</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; Pic-nic participatif</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; Initiation escalade / Balade / rallye photo &agrave; Bouilland</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\"><strong>Tickets Restaurant</strong></div>\r\nEvaluation d&#39;une augmentation de la valeur des TR &agrave; 11&euro; et &agrave; 13&euro; -&gt; DAD en juin (LF/CR)</div>\r\n</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;</div>\r\n</div>\r\n</div>\r\n\r\n<div>\r\n<div class=\"ace-line\" id=\"magicdomid12\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Questions diverses</strong></span></span></div>\r\n<strong>RAS</strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">-&gt; RAS</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"ace-line\" style=\"text-align:center\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\" style=\"text-align:center\"><strong>Prochaine AC le mardi 13 juin</strong></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>','2023-05-19 10:59:26',1,0,'uploads/blogarticle/646742035c599.jpg'),(52,41,3,'CR de l\'AC du 13/06/2023','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous + Anthony Azevedo (Mazars)</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Arnold, Ludwig</div>\r\n\r\n<div class=\"ace-line\">Pouvoirs :</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 20min&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp; &nbsp; DAD : 10min</div>\r\n\r\n<div class=\"ace-line\">&nbsp;&nbsp;&nbsp; CR COPIL : 15min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe :</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"moz-forward-container\">\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Indicateurs internes MAJ au 31/05/2023</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n<strong>Situation au 31/05/2023 :</strong>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 838 790&euro; (dont 27 375&euro; factur&eacute;s d&#39;avance)</li>\r\n	<li>Travaux r&eacute;alis&eacute;s sur l&#39;exercice, non factur&eacute;s au 31/05 : 86 648&euro;</li>\r\n	<li>Reste &agrave; faire sur commandes : 78 900&euro; sur l&#39;exercice</li>\r\n	<li>Devis &agrave; l&#39;&eacute;tude pond&eacute;r&eacute;s : 4 802&euro; sur l&#39;exercice</li>\r\n	<li>Fin exercice estim&eacute; : 995 117&euro; (Rappel &eacute;quilibre d&#39;apr&egrave;s situ au 31/03 : 1 017 860&euro;)</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<div class=\"ace-line\">\r\n<p><strong>Tr&eacute;sorerie au 31/05 :</strong></p>\r\n\r\n<p><em>Banque populaire :</em></p>\r\n\r\n<ul>\r\n	<li>Compte courant : 59 017,26&euro;</li>\r\n	<li>Opti pro : 185 231,13 &euro;</li>\r\n	<li>Compte &agrave; terme 12 mois : 2 x 10 000&euro; (issus de la conversion des parts sociales d&eacute;tenues &agrave; la Banque Populaire, taux nominal brut annuel 4%)</li>\r\n</ul>\r\n\r\n<p><em>Cr&eacute;dit Mutuel :</em></p>\r\n\r\n<ul>\r\n	<li>Compte &agrave; terme 12 mois : 250 000&euro; (taux nominal brut annuel 3,95%, 01/06/23 -&gt;01/06/24)</li>\r\n</ul>\r\n</div>\r\n<span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>DAD</strong></span></span></div>\r\n\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">\r\n<p>Augmentation de la valeur du ticket restaurant &agrave; 10.80&euro;</p>\r\n\r\n<p>Pour : 9<br />\r\nContre : 0<br />\r\nAbstention : 3</p>\r\n\r\n<p>-&gt; adopt&eacute;</p>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Panda du mois</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">Tirage au sort : Philippe</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n</div>\r\n</div>\r\n<span style=\"font-size:22px\"><span style=\"color:#167594\"><strong>Point COPIL / Divers</strong></span></span></div>\r\n</div>\r\n</div>\r\n\r\n<div>cf CR COPIL</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>Communication projet Quid</strong></div>\r\n\r\n<div>-&gt; de nombreux articles et interviews ces derniers jours !(France bleue, BP, Trace &eacute;crite, Journal du Palais, on Health...)</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>Discussion Pyxis</strong>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">-&gt; une pr&eacute;sentation de Pyxis avec Yann et Philippe a eu lieu le 09/06</div>\r\n&nbsp;\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\"><strong>Developers Group Dijon</strong>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&ldquo;Pitch Party&rdquo; mardi 27 juin 2023 &agrave; 16h dans les locaux d&rsquo;Alteca : PC pr&eacute;sentera Emissary</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\"><strong>Arcad</strong></div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">-&gt; Contact avec la Bourgogne tr&egrave;s positif, le CODIR de Soredis a manifest&eacute; de l&#39;int&eacute;r&ecirc;t pour le projet</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">-&gt; Rencontre avec Cominter pour la partie H&ocirc;tels notamment (room service et solution s&eacute;minaires)</div>\r\n</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;</div>\r\n</div>\r\n</div>\r\n\r\n<div>\r\n<div class=\"ace-line\" id=\"magicdomid12\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Questions diverses</strong></span></span></div>\r\n<strong>Fili&egrave;res</strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">-&gt; Open Source experience / osx en d&eacute;cembre, avec LE : pr&eacute;voir un pitch ?</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\"><strong>RH/Formations :</strong></div>\r\n\r\n<div class=\"ace-line\">-&gt; plan de formation en cours de finalisation avec les financements OPCO</div>\r\n\r\n<div class=\"ace-line\">-&gt; Fest : action de formation en situation de travail : &eacute;valuation des possibilit&eacute;s de financement de la formation en interne</div>\r\n\r\n<div class=\"ace-line\">-&gt; CSE : obligatoire d&egrave;s 11 salari&eacute;s, le processus &eacute;lectif sera mis en place prochainement</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\"><strong>Dons Logiciels libres</strong></div>\r\n\r\n<div class=\"ace-line\">-&gt; r&egrave;glements effectu&eacute;s, les frais bancaires ont &eacute;t&eacute; d&eacute;duits (frais sur virements internationaux)</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\"><strong>Communication :</strong></div>\r\n\r\n<div class=\"ace-line\">-&gt; Gaelle pr&eacute;sentera les r&eacute;sultats de son &eacute;tude lors de la prochaine AC</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"ace-line\" style=\"text-align:center\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\" style=\"text-align:center\"><strong>Prochaine AC le mardi 13 juillet</strong></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>','2023-06-19 11:13:47',1,1,'uploads/blogarticle/64901c78eeb1d.jpg'),(53,41,3,'CR de l\'AC du 11/07/2023','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous + Nicolas Bourgeois (Mazars)</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : William, Rudy, Charles-Maxime, Matthieu</div>\r\n\r\n<div class=\"ace-line\">Pouvoirs :</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 20min&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp; &nbsp; DAD : 10min</div>\r\n\r\n<div class=\"ace-line\">&nbsp;&nbsp;&nbsp; CR COPIL : 15min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe :</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"moz-forward-container\">\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Indicateurs internes MAJ au 30/06/2023</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n<strong>Situation au 30/06/2023 : fin exercice</strong>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 978 545.65&euro; (dont 16 963 &euro; factur&eacute;s d&#39;avance)</li>\r\n	<li>Travaux r&eacute;alis&eacute;s sur l&#39;exercice, non factur&eacute;s au 30/06 : 50 425 &euro;</li>\r\n	<li>Reste &agrave; faire sur commandes : 78 900&euro; sur l&#39;exercice</li>\r\n	<li>Devis &agrave; l&#39;&eacute;tude pond&eacute;r&eacute;s : 0 &euro; sur l&#39;exercice</li>\r\n	<li>Fin exercice estim&eacute; : 1 012 008&euro; (Rappel &eacute;quilibre d&#39;apr&egrave;s situ au 31/03 : 1 017 860&euro;)</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">A noter : les travaux de cl&ocirc;ture d&eacute;buteront deuxi&egrave;me 15aine de juillet. L&#39;objectif &eacute;tant d&#39;avoir un bilan provisoire &agrave; la fin juillet, bilan d&eacute;finitif &agrave; la rentr&eacute;e. (Le cabinet Mazars ferme pour CP d&eacute;but ao&ucirc;t)</div>\r\n\r\n<div class=\"ace-line\">\r\n<p><strong>Tr&eacute;sorerie au 30/06 :</strong></p>\r\n\r\n<p><em>Banque populaire :</em></p>\r\n\r\n<ul>\r\n	<li>Compte courant : 55 247.52&euro;</li>\r\n	<li>Opti pro : 172 231.13 &euro;</li>\r\n	<li>Compte &agrave; terme 12 mois : 2 x 10 000&euro; (issus de la conversion des parts sociales d&eacute;tenues &agrave; la Banque Populaire, taux nominal brut annuel 4%)</li>\r\n</ul>\r\n\r\n<p><em>Cr&eacute;dit Mutuel :</em></p>\r\n\r\n<ul>\r\n	<li>Compte courant : 22.50&euro;</li>\r\n	<li>Compte &agrave; terme 12 mois : 250 000&euro; (taux nominal brut annuel 3,95%, 01/06/23 -&gt;01/06/24)</li>\r\n</ul>\r\n</div>\r\n<span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>DAD</strong></span></span></div>\r\n\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">RAS\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Panda du mois</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">Tirage au sort : Laurent</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">Mot du Panda de juin : Philippe : mise en place prochaine d&#39;une biblioth&egrave;que participative</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n</div>\r\n</div>\r\n<span style=\"font-size:22px\"><span style=\"color:#167594\"><strong>Point COPIL / Divers</strong></span></span></div>\r\n</div>\r\n</div>\r\n\r\n<div>cf CR COPIL</div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div>\r\n<div><strong>Commercial</strong></div>\r\n\r\n<div>-&gt; Hausse de la d&eacute;pendence au CROUS : hausse du budget et du p&eacute;rim&egrave;tre sur la fin du march&eacute; et sur le nouveau march&eacute; pr&eacute;vu en d&eacute;but d&#39;ann&eacute;e</div>\r\n\r\n<div>&nbsp;</div>\r\n<strong>Communication</strong></div>\r\n\r\n<div>-&gt; article dans les &Eacute;chos</div>\r\n\r\n<div>&nbsp;</div>\r\n&nbsp;<strong>Developers Group Dijon</strong>\r\n\r\n<div>\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">Bar Camp Open Source le 21/09 : tout le monde devra y participer</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">Dev Fest 2023 le 08/12 : pr&eacute;voir conf&eacute;rence type Emissary</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\"><strong>Arcad</strong></div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">-&gt; la Bourgogne/Soredis : RDV le 19/07 pour r&eacute;cup&eacute;rer la base de donn&eacute;e produits</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">-&gt; Rencontre avec Cominter pour la partie H&ocirc;tels notamment (room service et solution s&eacute;minaires)</div>\r\n</div>\r\n\r\n<div class=\"moz-text-html\" lang=\"x-unicode\">&nbsp;</div>\r\n</div>\r\n</div>\r\n\r\n<div>\r\n<div class=\"ace-line\" id=\"magicdomid12\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Questions diverses</strong></span></span></div>\r\n<strong>Fili&egrave;res</strong></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">-&gt; Cooptech</div>\r\n\r\n<ul>\r\n	<li>suite &agrave; l&#39;AG : statu quo pour le moment, r&eacute;flexion sur la forme que doit prendre l&#39;association pour &eacute;voluer...</li>\r\n	<li>proposition des Tilleuls pour &ecirc;tre pr&eacute;sents sur un stand d&#39;API Platform Conference &agrave; Lille les 21 et 22/09 (Conf&eacute;rence internationale consacr&eacute;e au framework API Platform et &agrave; son &eacute;cosyst&egrave;me)</li>\r\n</ul>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\"><strong>RH/Formations :</strong></div>\r\n\r\n<div class=\"ace-line\">-&gt; plan de comp&eacute;tence (formation) en cours de finalisation avec les financements OPCO</div>\r\n\r\n<div class=\"ace-line\">-&gt; Fest : action de formation en situation de travail : &eacute;valuation des possibilit&eacute;s de financement de la formation en interne</div>\r\n\r\n<div class=\"ace-line\">-&gt; CSE : le processus &eacute;lectif&nbsp; en cours (cf note de service)</div>\r\n\r\n<div class=\"ace-line\">-&gt; Entretiens annuels d&egrave;s septembre (comp&eacute;tences, objectifs...)</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n&nbsp;\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"ace-line\" style=\"text-align:center\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3609\" style=\"text-align:center\"><strong>Prochaine AC le mardi 12 septembre</strong></div>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>','2023-07-13 11:56:20',1,0,'uploads/blogarticle/64afcac409b74.jpg'),(54,41,3,'CR de l\'AC du 12/09/2023','<div class=\"ace-line\" id=\"magicdomid182\">Pr&eacute;sents : tous + Nicolas Bourgeois et Thierry Bourgeois (Mazars)</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3087\">Excus&eacute;s : Laetitia, Benjamin B.</div>\r\n\r\n<div class=\"ace-line\">Pouvoirs : RAS</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3105\">Temps imparti :</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4846\">&nbsp;&nbsp;&nbsp; Suivi interne (financier et pr&eacute;visionnel) 20min&nbsp;</div>\r\n\r\n<div class=\"ace-line\">&nbsp; &nbsp; DAD : 10min</div>\r\n\r\n<div class=\"ace-line\">&nbsp;&nbsp;&nbsp; CR COPIL : 15min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid4848\">&nbsp;&nbsp;&nbsp; Questions diverses : 15 min</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid3230\">&nbsp;&nbsp;&nbsp; Travaux en groupe :</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"moz-forward-container\">\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Indicateurs internes MAJ au 07/09/2023</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid12\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">Pr&eacute;sent&eacute; par C&eacute;line R</div>\r\n<strong>Situation au 07/09/2023 :</strong>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid217\">\r\n<ul>\r\n	<li>Total factur&eacute; &agrave; date : 125 005&euro; (dont 9 261 &euro; factur&eacute;s d&#39;avance)</li>\r\n	<li>Travaux r&eacute;alis&eacute;s sur l&#39;exercice, non factur&eacute;s au 31/08/06 : 27 254 &euro;</li>\r\n	<li>Reste &agrave; faire sur commandes : 79 000&euro; sur l&#39;exercice</li>\r\n	<li>Devis &agrave; l&#39;&eacute;tude pond&eacute;r&eacute;s : 435 522 &euro; planifi&eacute;s sur l&#39;exercice et 40 593&euro; non planifi&eacute;s</li>\r\n	<li>Fin exercice estim&eacute; : 657 520 (Rappel &eacute;quilibre N-1 d&#39;apr&egrave;s situ au 31/03 : 1 017 860&euro;)</li>\r\n</ul>\r\n</div>\r\n\r\n<div class=\"ace-line\" id=\"magicdomid354\">Cet &eacute;tat des lieux est r&eacute;alis&eacute; en fonction des informations connues au moment de sa MAJ.</div>\r\n\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">A noter : RDV de trvail avec Mazars pour finaliser le bilan le 26/09/2023.</div>\r\n\r\n<div class=\"ace-line\">\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Tr&eacute;sorerie au 31/08 :</strong></p>\r\n\r\n<p><em>Banque populaire :</em></p>\r\n\r\n<ul>\r\n	<li>Compte courant : 43 010.35&euro;</li>\r\n	<li>Opti pro : 14 638.31 &euro;</li>\r\n</ul>\r\n\r\n<p>=&gt; la fragilisation de la tr&eacute;sorerie est en partie li&eacute;e au d&eacute;calage de facturation du MSE de juillet. (factur&eacute; avec MSE ao&ucirc;t d&eacute;but septembre) et au peu de facturation sur le 1er trimestre.</p>\r\n\r\n<ul>\r\n	<li>Compte &agrave; terme 12 mois : 2 x 10 000&euro; (issus de la conversion des parts sociales d&eacute;tenues &agrave; la Banque Populaire, taux nominal brut annuel 4%)</li>\r\n</ul>\r\n\r\n<p><em>Cr&eacute;dit Mutuel :</em></p>\r\n\r\n<ul>\r\n	<li>Compte courant : 315.63&euro;</li>\r\n	<li>Compte &agrave; terme 12 mois : 250 000&euro; (taux nominal brut annuel 3,95%, 01/06/23 -&gt;01/06/24)</li>\r\n</ul>\r\n</div>\r\n<span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>DAD</strong></span></span></div>\r\n\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid13\">RAS\r\n<div class=\"ace-line\">&nbsp;</div>\r\n\r\n<div class=\"ace-line\">\r\n<div class=\"ace-line\" id=\"magicdomid12\"><span style=\"color:#2980b9\"><span style=\"font-size:22px\"><strong>Panda du mois</strong></span></span></div>\r\n\r\n<div class=\"ace-line\" id=\"ma